# ============================================================
# UTILIDADES
# ============================================================

st.markdown(nexus_glass_styles_v713(), unsafe_allow_html=True)

def money(v: Any) -> str:
    try:
        value = float(v)
        return f"${value:,.2f}" if np.isfinite(value) else "N/D"
    except (TypeError, ValueError, OverflowError):
        return "N/D"


def integer(v: Any) -> str:
    try:
        return f"{int(round(float(v))):,}"
    except Exception:
        return "0"


def safe_float(v: Any, default: float = 0.0) -> float:
    try:
        x = float(v)
        return x if np.isfinite(x) else default
    except Exception:
        return default


def normalize_text(v: Any) -> str:
    x = str(v).strip().lower()
    x = re.sub(r"\s+", " ", x)
    return x



def normalize_key(v: Any) -> str:
    """Clave estable para búsquedas de proveedor/marca y comparaciones humanas."""
    x = normalize_text(v)
    x = unicodedata.normalize("NFKD", x)
    x = "".join(ch for ch in x if not unicodedata.combining(ch))
    x = re.sub(r"[^a-z0-9]+", " ", x)
    return re.sub(r"\s+", " ", x).strip()


def safe_slug(v: Any, fallback: str = "reporte") -> str:
    x = normalize_key(v).replace(" ", "_")
    return x[:80] or fallback


def supplier_matches(query: str, suppliers: list[str], limit: int = 12) -> list[str]:
    q = normalize_key(query)
    if not q:
        return suppliers[:limit]
    starts, contains = [], []
    for supplier in suppliers:
        k = normalize_key(supplier)
        if k.startswith(q):
            starts.append(supplier)
        elif q in k:
            contains.append(supplier)
    return (starts + contains)[:limit]


def parse_number(v: Any) -> float:
    if pd.isna(v):
        return 0.0
    if isinstance(v, (int, float, np.integer, np.floating)):
        return float(v)
    s = str(v).strip().replace("$", "").replace("€", "").replace(" ", "")
    if not s:
        return 0.0
    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        parts = s.split(",")
        if len(parts[-1]) in (1, 2):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    else:
        pass
    try:
        return float(s)
    except Exception:
        return 0.0


