        for _,file,row in others:
            by_desc.setdefault(_prep_description_key_v77(row['Descripción']),[]).append((file,row));by_code.setdefault(_a2_text(row['Código']),[]).append((file,row))
        for idx,row in data.iterrows():
            if int(row['Fila origen']) in item['manual_origins']:continue
            code,desc=_a2_text(row['Código']),_a2_text(row['Descripción'])
            matches=by_desc.get(_prep_description_key_v77(desc),[]) if not code else []
            codes={_a2_text(r['Código']) for _,r in matches}
            if len(codes)==1:
                chosen=next(iter(codes))
                # Avoid creating repeated inventory identities.
                if item['kind']!='inventario' or not data['Código'].eq(chosen).any():
                    data.at[idx,'Código']=chosen;code=chosen
                    _prep_events_v77(item,'Código recuperado','Descripción exacta y código único de la misma sede.',row,Nuevo=chosen,Evidencia=matches[0][0])
            if code and (not desc or normalize_key(desc)==normalize_key(code)):
                matches=by_code.get(code,[]);descs={_a2_text(r['Descripción']) for _,r in matches}
                if len(descs)==1:
                    chosen=next(iter(descs));data.at[idx,'Descripción']=chosen
                    _prep_events_v77(item,'Descripción recuperada','Código exacto y descripción única de la misma sede.',row,Nuevo=chosen,Evidencia=matches[0][0])
        repeated_description = data['Código'].map(_a2_text).ne('') & data['Descripción'].map(_prep_description_key_v77).eq(data['Código'].map(_prep_description_key_v77))
        for idx, row in data.loc[repeated_description].iterrows():
            _prep_events_v77(item, 'Descripción pendiente', 'El texto repetía el código y no se encontró una descripción confirmada. Se deja vacía la descripción; se conserva el código y toda la mercancía.', row, Anterior=_a2_text(row['Descripción']), Nuevo='')
            data.at[idx, 'Descripción'] = ''
        if item['supplier']:
            if 'Proveedor' not in data:data['Proveedor']=''
            empty=data['Proveedor'].fillna('').map(_a2_text).eq('')
            data.loc[empty,'Proveedor']=item['supplier']
            _prep_events_v77(item,'Proveedor asignado','Sólo completa proveedores vacíos; conserva los existentes.',Proveedor=item['supplier'],Filas=int(empty.sum()))
        duplicate=data['Código'].ne('') & data['Código'].duplicated(keep=False)
        if duplicate.any():
            item['duplicate_review']=data.loc[duplicate].to_dict('records')
            policy=item['options'].get('duplicates_policy','review')
            if policy=='remove_exact' and not item['options'].get('confirm_remove_exact'):
                item['errors'].append('Confirma que los renglones idénticos son copias antes de excluirlos; el total original puede incluirlos.')
            elif policy=='remove_exact':
                exact=_prep_exact_mask_v77(data)
                for r in data.loc[exact].to_dict('records'):_prep_events_v77(item,'Copia exacta excluida','El usuario confirmó que son copias, no movimientos distintos.',r,Unidades=r.get('Ventas',r.get('Existencia')))
                data=data.loc[~exact].copy()
            elif policy=='group' and item['kind']=='ventas':
                numeric=[c for c in ['Ventas','Monto bruto','Descuentos','IVA reportado','Costo de ventas','Utilidad A2','Importe neto'] if c in data]
                groups=[]
                for code,group in data.loc[data['Código'].ne('')].groupby('Código',sort=False):
                    explicit_fields=[c for c in ('Descripción','Proveedor','Marca','Departamento','Categoría') if c in group]
                    conflicts=[c for c in explicit_fields if group[c].map(_prep_description_key_v77).replace('',pd.NA).dropna().nunique()>1]
                    if len(group)>1 and conflicts:
                        item['errors'].append(f'{code}: información diferente en {", ".join(conflicts)}; revisa individualmente.');groups.extend(group.to_dict('records'));continue
                    r=group.iloc[0].to_dict()
