# NEXUS 7.10.2 · Exportación directa de los límites ya calculados por el motor.
# Fragmento integrado en el único script principal; no se ejecuta por separado.

def _direct_source_v712(data, site, assign_unlabelled=False, include_zero=False):
    """Filtra la sede antes de validar; nunca recalcula ni sustituye faltantes por cero."""
    x = data.copy().reset_index(drop=True)
    aliases = {
        'Código': ['codigo', 'cod', 'codigo producto', 'codigo de producto'],
        'Descripción': ['descripcion', 'producto', 'nombre del producto'],
        'Existencia': ['existencia', 'existencias', 'stock actual'],
        'Mínimo': ['stock minimo', 'minimo', 'min'],
        'Máximo': ['stock maximo', 'maximo', 'max'],
        'Sede': ['sede', 'sucursal'],
        'Ventas utilizadas': ['ventas utilizadas', 'ventas acumuladas', 'ventas', 'unidades vendidas'],
        'Meses utilizados': ['meses utilizados', 'meses del historial'],
    }
    for canonical, variants in aliases.items():
        if canonical not in x or canonical in {'Mínimo', 'Máximo'}:
            match = next((c for v in variants for c in x.columns if normalize_key(c) == v), None)
            if match is not None:
                x[canonical] = x[match]
    before = len(x)
    if 'Sede' in x:
        x = x.loc[x['Sede'].map(lambda v: normalize_key(_mm_text_v710(v))).eq(normalize_key(site))].copy()
    elif assign_unlabelled:
        x['Sede'] = site
    else:
        raise ValueError('La fuente no identifica la sede. Confirma a qué sede pertenece el archivo antes de exportar.')
    x.reset_index(drop=True, inplace=True)
    numeric = ['Existencia', 'Mínimo', 'Máximo', 'Ventas utilizadas', 'Meses utilizados']
    for c in ['Código', 'Descripción']:
        if c not in x:
            x[c] = ''
        x[c] = x[c].map(_mm_code_v710 if c == 'Código' else _mm_text_v710)
    for c in numeric:
        if c not in x:
            x[c] = np.nan
        x[c] = x[c].map(_mm_number_v710)
    manual = x.get('Política de stock', pd.Series('', index=x.index)).map(lambda v: normalize_key(_mm_text_v710(v))).eq('manual')
    reasons = pd.Series('', index=x.index, dtype=object)

    def flag(mask, message):
        mask = mask.fillna(False)
        reasons.loc[mask] = reasons.loc[mask].map(lambda s: s + '; ' if s else '') + message

    flag(x['Código'].eq(''), 'Falta código')
    flag(x['Código'].duplicated(keep=False) & x['Código'].ne(''), 'Código repetido dentro de esta sede')
    flag(x['Descripción'].eq(''), 'Falta descripción')
    flag(x['Código'].map(normalize_key).eq(x['Descripción'].map(normalize_key)) & x['Código'].ne(''), 'Código y descripción contienen el mismo texto: revisar producto')
    for c in ['Existencia', 'Mínimo', 'Máximo']:
        flag(x[c].isna(), f'{c}: falta un número válido')
        flag(x[c].lt(0), f'{c}: valor negativo pendiente')
    flag(x['Mínimo'].gt(x['Máximo']), 'El mínimo supera el máximo')
    flag(~manual & (x['Meses utilizados'].isna() | x['Meses utilizados'].le(0)), 'Falta historial válido de meses')
    flag(~manual & x['Ventas utilizadas'].isna(), 'Faltan las ventas utilizadas en el cálculo')
    flag(~manual & x['Ventas utilizadas'].lt(0), 'Ventas negativas: revisar devoluciones y período')
    if 'Historial de ventas' in x:
        history_state = x['Historial de ventas'].map(lambda v: normalize_key(_mm_text_v710(v)))
        flag(~manual & history_state.ne('') & history_state.ne('disponible'), 'El historial de ventas no está disponible o requiere revisión')
    for c in ['Revisión del cálculo', 'Revisión', 'Revisión Excel']:
        if c in x:
            benign = {'', 'sin cambios', 'sin observaciones', 'sin pendientes', 'ok', 'validado', 'no'}
            review = x[c].map(_mm_text_v710)
            # La exportación formulada añade esta nota informativa aunque el cálculo sea válido.
            meaningful = ~review.map(normalize_key).isin(benign)
            if c == 'Revisión Excel':
                meaningful &= ~review.map(normalize_key).str.startswith('simulacion revisar plan de traslados')
            for idx in x.index[meaningful]:
                reasons.loc[idx] += ('; ' if reasons.loc[idx] else '') + f'{c}: {review.loc[idx]}'
    if not include_zero:
        flag(x['Mínimo'].eq(0) | x['Máximo'].eq(0), 'Límites en cero: requiere revisión explícita')
    x['Motivo pendiente'] = reasons
    pending = x.loc[reasons.ne('')].copy()
    valid = x.loc[reasons.eq('')].copy()
    valid['A pedir'] = (valid['Máximo'] - valid['Existencia']).clip(lower=0)
    return valid, pending, {'Filas en fuente': before, 'Filas de esta sede': len(x),
                            'Filas de otras sedes o sin sede': before - len(x),
                            'Válidos': len(valid), 'Pendientes': len(pending)}


def _direct_filter_v712(data, query='', taxonomy=None, codes=None):
    """Filtros reales sobre el catálogo disponible, independientes del texto del encabezado."""
    x = data.copy()
    if query.strip():
        x = x.loc[x['Código'].str.contains(query.strip(), case=False, regex=False, na=False) |
                  x['Descripción'].str.contains(query.strip(), case=False, regex=False, na=False)]
    for col, values in (taxonomy or {}).items():
        if col in x and values:
            x = x.loc[x[col].map(_mm_text_v710).isin(values)]
    if codes is not None:
        x = x.loc[x['Código'].isin(codes)]
    return x.copy()


def _direct_fingerprint_v712(data, settings):
    digest = hashlib.sha256()
    digest.update(json.dumps(list(data.columns), ensure_ascii=False).encode())
    digest.update(pd.util.hash_pandas_object(data.astype(str), index=True).values.tobytes())
    digest.update(json.dumps(settings, sort_keys=True, ensure_ascii=False, default=str).encode())
    return digest.hexdigest()


def _direct_scope_v712(data, scope):
    """Recupera solo identidades seleccionadas, siempre desde los valores vivos."""
    if scope is None:
        return data.copy()
    if not {'Sede', 'Código'}.issubset(data.columns):
        raise ValueError('La selección recibida requiere las columnas Sede y Código en los datos vivos de NEXUS.')
    pairs = {(normalize_key(_mm_text_v710(r.get('Sede'))), _mm_code_v710(r.get('Código'))) for r in scope}
    live_pairs = list(zip(data['Sede'].map(lambda v: normalize_key(_mm_text_v710(v))), data['Código'].map(_mm_code_v710)))
    return data.loc[[p in pairs for p in live_pairs]].copy()


@st.fragment
def render_planilla_a2_v712(all_df):
    st.caption('1. Elige la sede y sus datos.  2. Selecciona productos y escribe el encabezado.  3. Descarga la misma planilla en PDF o Excel.')
    st.info('La plantilla de tu jefe ya está incorporada. Esta opción exporta los mínimos y máximos que NEXUS ya calculó; no necesitas volver a subir el PDF ni hacer una comparación.')
    if st.button('Ver cómo preparar esta planilla', key='v712_direct_help_button'):
        st.session_state['v712_direct_show_help'] = not st.session_state.get('v712_direct_show_help', False)
    if st.session_state.get('v712_direct_show_help', False):
        st.markdown('**Sede:** prepara una planilla por sucursal. **Datos:** usa el resultado guardado o un Excel NEXUS con su hoja Inventario. **Productos:** filtra por código/descripción o por las relaciones existentes. **Encabezado:** escribe marca, proveedor y grupo aunque todavía no estén en el catálogo. **Descarga:** el PDF conserva las seis columnas del formato original. Para cambiar las coberturas, ajusta el motor y vuelve a generar los datos antes de exportar.')
    st.subheader('1 · Sede y resultado NEXUS')
    available_sites = set(all_df['Sede'].map(_mm_text_v710)) if all_df is not None and not all_df.empty and 'Sede' in all_df else set()
    default_site = next((s for s in SEDES if s in available_sites), 'Matriz Makropetrol')
    site = st.selectbox('Sede de la planilla', list(SEDES), index=list(SEDES).index(default_site), key='v712_planilla_site')
    site_key = safe_slug(site)
    source_options = ['Resultado NEXUS guardado', 'Cargar Excel NEXUS / CSV']
    source = st.radio('Datos que se van a exportar', source_options, horizontal=True,
                      index=1 if all_df is None or all_df.empty else 0, key='v712_direct_source')
    assign_unlabelled = False
    try:
        if source == source_options[1]:
            uploaded = st.file_uploader('Excel NEXUS · hoja Inventario', type=['xlsx', 'xls', 'csv'], key='v712_direct_upload')
            if uploaded is None:
                st.info('Sube un reporte NEXUS que incluya existencia, mínimos, máximos e historial. Los archivos A2 de ventas sin calcular se cargan primero en Carga de datos.')
                return
            with st.spinner('Leyendo el resultado NEXUS…'):
                data, source_meta = read_minmax_source_v710(uploaded.getvalue(), uploaded.name, True)
            if not any(normalize_key(c) in {'sede', 'sucursal'} for c in data.columns):
                assign_unlabelled = st.checkbox(f'El archivo no trae columna Sede: confirmo que todas sus filas pertenecen a {site}.',
                                                key='v712_direct_assign_' + site_key + '_' + source_meta['SHA256'][:12])
                if not assign_unlabelled:
                    st.info('Confirma la sede real de este archivo para continuar.'); return
        else:
            data = all_df.copy() if all_df is not None else pd.DataFrame()
            source_meta = {'Archivo': 'Resultado NEXUS guardado'}
            if data.empty:
                st.info('Todavía no hay resultados guardados. Elige Cargar Excel NEXUS / CSV o carga inventario y ventas en Carga de datos.'); return
            scope = st.session_state.get('v712_planilla_scope')
            if scope is not None:
                data = _direct_scope_v712(data, scope)
                source_meta['Selección recibida'] = len(scope)
                st.caption('Se está usando la selección de productos que enviaste desde NEXUS, con sus valores actuales.')
                if st.button('Quitar selección anterior', key='v712_direct_clear_scope'):
                    st.session_state.pop('v712_planilla_scope', None)
                    st.rerun()
        review_zero = st.checkbox('Ya revisé los productos con límites en cero y quiero permitir su selección.', key='v712_direct_zero_' + site_key)
        valid, pending, audit = _direct_source_v712(data, site, assign_unlabelled, review_zero)
    except Exception as exc:
        st.error(f'No se pudieron preparar los productos: {exc}'); return
    cols = st.columns(3)
    cols[0].metric('Productos de esta sede', audit['Filas de esta sede'])
    cols[1].metric('Listos para seleccionar', len(valid))
    cols[2].metric('Pendientes de revisar', len(pending))
    if audit['Filas en fuente'] != audit['Filas de esta sede']:
        st.caption(f"Se omitieron {audit['Filas de otras sedes o sin sede']:,} filas de otras sedes o sin identificación de sede.")
    if not pending.empty:
        with st.expander(f'Ver {len(pending):,} productos pendientes · no entran en esta planilla'):
            st.dataframe(pending[[c for c in ['Código', 'Descripción', 'Existencia', 'Mínimo', 'Máximo', 'Ventas utilizadas', 'Meses utilizados', 'Motivo pendiente'] if c in pending]], hide_index=True, width='stretch')
            st.caption('Corrige la fuente o el historial indicado y vuelve a preparar la planilla. Los códigos repetidos se revisan dentro de la sede seleccionada; no se suman ni se completan con cero.')
    if valid.empty:
        st.warning('Esta sede no tiene productos listos para exportar con la fuente seleccionada. Revisa los pendientes o elige su reporte NEXUS.'); return
    st.subheader('2 · Productos y encabezado')
    query = st.text_input('Buscar código o descripción · texto literal', key='v712_direct_query_' + site_key,
                          help='Ejemplo: WEB. Escribir WEB en Marca del encabezado solo añade la etiqueta; usa este buscador para elegir los productos.')
    tax_filters = {}
    tax_columns = [c for c in ['Marca', 'Proveedor', 'Departamento', 'Categoría', 'Tipo de producto'] if c in valid]
    with st.expander('Filtrar por catálogo y elegir productos individuales · opcional'):
        has_taxonomy = False
        if tax_columns:
            for column in tax_columns:
                values = sorted({v for v in valid[column].map(_mm_text_v710) if v and normalize_key(v) not in {'sin asignar', 'n/d', 'none', 'nan'}})
                if values:
                    has_taxonomy = True
                    tax_filters[column] = st.multiselect('Filtrar ' + column.lower(), values, key='v712_direct_tax_' + site_key + '_' + safe_slug(column))
        if not has_taxonomy:
            st.caption('Esta fuente no tiene relaciones de marca o proveedor. Puedes buscar productos por código o descripción y escribir los datos del encabezado libremente.')
        filtered = _direct_filter_v712(valid, query, tax_filters)
        selection_context = _direct_fingerprint_v712(filtered, {'Sede': site, 'Origen': source, 'Fuente': source_meta, 'Ceros revisados': review_zero})[:16]
        select_all = st.checkbox(f'Incluir todos los productos filtrados ({len(filtered):,})', value=True, key='v713_direct_all_' + selection_context)
        codes = filtered['Código'].tolist() if select_all else st.multiselect('Productos incluidos', filtered['Código'].tolist(), default=[],
                               key='v712_direct_codes_' + selection_context,
                               help='Desmarca la selección total para elegir productos individuales.')
    chosen = _direct_filter_v712(filtered, codes=codes)
    header_title = st.text_input('Nombre de la sede en el encabezado', value='MAKROPETROL, C.A.' if site == 'Matriz Makropetrol' else site.upper(), key='v712_direct_title_' + site_key)
    department = st.text_input('Departamento / grupo que aparecerá en la planilla · obligatorio',
                                placeholder='Ejemplo: FILTROS WEB, ACEITES BOSS o PAÍLAS', key='v712_direct_department_' + site_key,
                                help='Este texto sustituye el grupo WEB del modelo original. Escribe el grupo real de los productos seleccionados.')
    c = st.columns(3)
    brand = c[0].text_input('Marca · texto libre', key='v712_direct_brand_' + site_key)
    supplier = c[1].text_input('Proveedor · texto libre', key='v712_direct_supplier_' + site_key)
    kind = c[2].text_input('Tipo de producto · texto libre', key='v712_direct_kind_' + site_key)
    st.caption('Marca, proveedor y tipo se imprimen como etiquetas. No modifican las relaciones guardadas ni cambian por sí solos los productos seleccionados.')
    address1 = address2 = phone = factor = ''
    with st.expander('Otro factor, dirección y teléfono · opcional'):
        factor = st.text_input('Otro factor para el encabezado', placeholder='Ejemplo: Propuesta septiembre / lote 01', key='v712_direct_factor_' + site_key)
        address1 = st.text_input('Dirección · línea 1', key='v712_direct_address1_' + site_key)
        address2 = st.text_input('Dirección · línea 2', key='v712_direct_address2_' + site_key)
        phone = st.text_input('Teléfono de la sede', key='v712_direct_phone_' + site_key)
        st.caption('En Matriz, dejar los contactos vacíos conserva el encabezado original. En otra sede se omiten los contactos de Matriz; escribe los reales si deseas incluirlos.')
    metadata = {'Versión NEXUS': APP_VERSION, 'Sede': site, 'Título encabezado': header_title,
                'Departamento encabezado': department, 'Marca': brand, 'Proveedor': supplier,
                'Tipo de producto': kind, 'Factor libre': factor, 'Dirección línea 1': address1,
                'Dirección línea 2': address2, 'Teléfono encabezado': phone,
                'Existencia para planilla': 'NEXUS', 'Fuente NEXUS': source_meta,
                'Ceros revisados': review_zero, 'Origen de los límites': 'Valores ya calculados en NEXUS; sin recálculo en la exportación'}
    st.subheader('3 · Revisar y descargar')
    preview_cols = ['Código', 'Descripción', 'Existencia', 'Mínimo', 'Máximo', 'A pedir', 'Ventas utilizadas', 'Meses utilizados', 'Período ventas', 'Cobertura mínima aplicada', 'Cobertura máxima aplicada', 'Política de stock']
    st.caption(f'{len(chosen):,} productos seleccionados de {site}. Los mínimos y máximos de esta vista son exactamente los que se imprimirán.')
    st.dataframe(chosen[[c for c in preview_cols if c in chosen]], hide_index=True, width='stretch', height=320)
    st.caption('A pedir = máximo − existencia, con límite inferior cero, como en la planilla A2. No descuenta órdenes en tránsito ni redistribuciones. El historial y las coberturas se muestran para revisar; el PDF lleva solo las seis columnas originales.')
    adjusted = st.checkbox('Ajustar los saltos de página para que se vean todos los productos', value=True, key='v712_direct_pagination')
    metadata['Ajustar paginación'] = adjusted
    if not adjusted:
        st.caption('Se conserva la distribución original cuando el conjunto coincide con el catálogo completo del modelo. Con otros productos o un subconjunto se mantienen sus columnas y diseño, ajustando el número de páginas.')
    plan = chosen.reindex(columns=['Código', 'Descripción', 'Existencia', 'Mínimo', 'Máximo', 'A pedir']).copy()
    fingerprint = _direct_fingerprint_v712(chosen, {'Metadatos': metadata, 'Consulta': query,
                                                  'Filtros': tax_filters, 'Códigos': codes, 'Sede confirmada': assign_unlabelled})
    for state_key in ['v712_direct_pdf_ready', 'v713_direct_excel_ready']:
        ready = st.session_state.get(state_key)
        if ready and ready.get('fingerprint') != fingerprint:
            st.session_state.pop(state_key, None)
    blocked = plan.empty or not department.strip() or not header_title.strip()
    if not department.strip():
        st.caption('Completa Departamento / grupo para habilitar la generación y evitar que aparezca WEB en una planilla de otro grupo.')
    if st.button('Preparar mi planilla A2 · PDF + Excel', type='primary', disabled=blocked, key='v712_direct_generate'):
        for state_key in ['v712_direct_pdf_ready', 'v713_direct_excel_ready']:
            st.session_state.pop(state_key, None)
        export_meta = dict(metadata)
        export_meta.update(_mm_generation_metadata_v711())
        filename = 'Planilla_A2_' + safe_slug(site) + '_' + safe_slug(department)[:65]
        failures = []
        with st.spinner('Preparando PDF y Excel con los mismos productos y valores…'):
            try:
                output = build_minmax_original_pdf_v710(builtin_a2_template_v712(), plan, export_meta)
                if not output:
                    raise ValueError('No se generó contenido PDF. Revisa las dependencias del entorno.')
                st.session_state['v712_direct_pdf_ready'] = {'fingerprint': fingerprint, 'bytes': output, 'metadata': export_meta, 'filename': filename + '.pdf'}
            except Exception as exc:
                failures.append('PDF')
                st.error(f'No se pudo generar la planilla PDF: {exc}')
            try:
                output = build_minmax_planilla_excel_v713(plan, export_meta, builtin_a2_template_v712())
                st.session_state['v713_direct_excel_ready'] = {'fingerprint': fingerprint, 'bytes': output, 'metadata': export_meta, 'filename': filename + '.xlsx'}
            except Exception as exc:
                failures.append('Excel')
                st.error(f'No se pudo generar la planilla Excel: {exc}')
        if not failures:
            st.success('Planilla lista en PDF y Excel. Elige el formato de descarga debajo.')
        elif len(failures) == 1:
            st.info('El otro formato está disponible debajo; no necesitas repetir los cálculos.')
    col_pdf, col_excel = st.columns(2)
    ready = st.session_state.get('v712_direct_pdf_ready')
    if ready and ready.get('fingerprint') == fingerprint:
        col_pdf.download_button('Descargar mi planilla A2 · PDF', ready['bytes'], ready['filename'], 'application/pdf',
                               type='primary', key='v712_direct_download', on_click='ignore', width='stretch')
        st.caption(f"{len(plan):,} productos · {site} · Generada el {ready['metadata']['Fecha generación']} a las {ready['metadata']['Hora generación']} (Venezuela). La generación no cambia las fechas de los datos ni registra movimientos en A2.")
    excel_ready = st.session_state.get('v713_direct_excel_ready')
    if excel_ready and excel_ready.get('fingerprint') == fingerprint:
        col_excel.download_button('Descargar mi planilla A2 · Excel', excel_ready['bytes'], excel_ready['filename'],
                                  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', key='v713_direct_download_excel', on_click='ignore', width='stretch')
    st.caption('PDF y Excel parten de la misma selección: seis columnas, mismos valores, sede, fecha y hora. El Excel adapta el diseño para editar e imprimir; no recalcula esta planilla ni modifica el PDF al editarlo.')


