def open_planilla_a2_v712(data=None):
    """Keep only selected identities so fresh engine values remain authoritative."""
    st.session_state['v712_planilla_route'] = 'Generar planilla con NEXUS'
    if data is not None and not data.empty and {'Sede', 'Código'}.issubset(data.columns):
        st.session_state['v712_direct_source'] = 'Resultado NEXUS guardado'
        scope = data[['Sede', 'Código']].drop_duplicates().astype(str)
        st.session_state['v712_planilla_scope'] = scope.to_dict('records')
        sites = scope['Sede'].unique().tolist()
        if len(sites) == 1 and sites[0] in SEDES:
            st.session_state['v712_planilla_site'] = sites[0]
    else:
        st.session_state.pop('v712_planilla_scope', None)
    st.session_state['nexus_view'] = 'Planilla A2'
    st.rerun()


def render_planilla_hub_v712(all_df):
    if st.button('Tengo la planilla A2 en PDF: revisar o pasar a Excel', key='v713_hub_review'):
        _navigation_v7('Revisar planilla A2')
    st.header('Planilla A2 · mínimos y máximos')
    if st.button('Tengo un ranking con ventas por mes y existencia · calcular sólo ese PDF', key='v714_from_planilla'):
        _navigation_v7('Ranking mensual A2')
    st.caption('Usa el PDF de tu jefe para comparar y proponer nuevos límites, o exporta directamente los límites que ya tienes guardados en NEXUS.')
    with st.expander('Guía rápida · qué opción elijo y qué recibo'):
        st.markdown('**Comparar con valores actuales A2:** sube el PDF de A2, elige los datos NEXUS de esa misma sede y confirma historial y coberturas. Para WEB: **4 meses de ventas, mínimo 1 mes y máximo 2 meses**. Pulsa **Comparar ahora**, revisa propuestas y pendientes, y usa **Preparar PDF + comparación Excel**.\n\n**Generar planilla con NEXUS:** exporta los límites efectivos que ya calculaste o ajustaste manualmente. No vuelve a calcularlos con otros parámetros.\n\n**Encabezado:** cambia sede, grupo, proveedor, marca o factor libre. Las etiquetas no inventan la clasificación de los productos; los filtros y la selección deciden qué filas salen.\n\n**Productos pendientes:** los códigos ausentes, duplicados o sin historial no reciben límites inventados. En comparación puedes conservar sus valores originales de A2 y revisarlos en Excel. Las propuestas con cero ventas requieren tu revisión explícita.\n\n**Entrega:** la planilla PDF conserva el diseño y seis columnas de A2; la comparación Excel explica los cambios. La fecha y hora del PDF corresponden a su generación en Venezuela. Ninguno de estos botones carga datos automáticamente en A2.')
    from importlib.util import find_spec
    missing_pdf = [package for module, package in [('pdfplumber', 'pdfplumber==0.11.8'), ('fitz', 'PyMuPDF==1.26.6')] if find_spec(module) is None]
    if missing_pdf:
        st.warning('Este Python todavía no tiene todas las librerías para leer y generar la planilla PDF. Instala los requisitos y reinicia NEXUS.')
        with st.expander('Ver el comando para este entorno'):
            import sys
            st.caption('En PowerShell, usa el mismo intérprete que está ejecutando esta aplicación:')
            st.code('& "' + sys.executable + '" -m pip install ' + ' '.join(missing_pdf), language='powershell')
    route = st.radio('¿Qué necesitas hacer con la planilla?',
                     ['Generar planilla con NEXUS', 'Comparar con valores actuales A2'],
                     horizontal=True, key='v712_planilla_route')
    if route == 'Generar planilla con NEXUS':
        render_planilla_a2_v712(all_df)
    else:
        render_minmax_comparison_v710(all_df)



# === RANKING MENSUAL A2: fuente independiente, sin datos guardados ===

def _ranking_descriptions_v7184(page, layout):
    groups=[];active=None
    for span in page.get_texttrace():
        chars=span.get('chars',())
        if not chars:continue
        text=''.join(chr(c[0]) for c in chars).strip()
        x=float(chars[0][2][0]);y=float(span['bbox'][1])
        if text and layout['description'][0]<=x<=layout['description'][0]+4 and y>layout['body_top']:
            if active is None:active=[y,[]];groups.append(active)
            active[1].append(text)
        else:active=None
    return [(g[0],' '.join(g[1])) for g in groups]

def _ranking_spans_v714(page):
    """Return visible text spans without relying on PDF stream reading order."""
    return [
        {"text": s["text"].strip(), "box": tuple(s["bbox"])}
        for block in page.get_text("dict").get("blocks", [])
        for line in block.get("lines", [])
        for s in line.get("spans", []) if s.get("text", "").strip()
    ]


def _ranking_number_v714(text):
    """A2 Spanish printed numeric notation. Missing or malformed stays NaN."""
    import re
    from decimal import Decimal, InvalidOperation
    text = str(text or "").strip().replace("\u00a0", "").replace("−", "-")
    if not re.fullmatch(r"[+-]?(?:\d{1,3}(?:\.\d{3})+|\d+)(?:,\d+)?", text):
        return float("nan")
    try:
        return float(Decimal(text.replace(".", "").replace(",", ".")))
    except InvalidOperation:
        return float("nan")


def _ranking_layout_v714(spans):
    """Derive month/metric coordinates from repeated comparative report headers."""
    import re
    import calendar
    from datetime import datetime
    import numpy as np
    exact = lambda t: [s for s in spans if s["text"].upper() == t]
    if not any("RANKING DE VENTAS POR PRODUCTOS COMPARATIVO" in s["text"].upper() for s in spans):
        raise ValueError("Este PDF no es un ranking A2 comparativo de ventas por producto y meses.")
    periods = sorted(
        [s for s in spans if re.fullmatch(r"PERIODO[_ ]\d+", s["text"], re.I)],
        key=lambda s: s["box"][0],
    )
    if len(periods) < 2:
        raise ValueError("Se necesitan al menos dos meses separados en las columnas del ranking PDF; un total acumulado no permite identificar los meses de mayor venta.")
    centers = [(s["box"][0] + s["box"][2]) / 2 for s in periods]
    spacing = float(np.median(np.diff(centers)))
    if spacing <= 0:
        raise ValueError("Los encabezados de meses del PDF están superpuestos.")
    months = []
    for i, period in enumerate(periods):
        center = centers[i]
        left = (centers[i - 1] + center) / 2 if i else center - spacing / 2
        right = (center + centers[i + 1]) / 2 if i < len(periods) - 1 else center + spacing / 2
        candidates = [s for s in spans if left <= (s["box"][0]+s["box"][2])/2 < right
                      and period["box"][1] < s["box"][1] < period["box"][1] + 40]
        dates = sorted([s for s in candidates if re.fullmatch(r"\d{1,2}/\d{1,2}/\d{4}", s["text"])], key=lambda s: s["box"][1])
        units = [s for s in candidates if s["text"].lower().rstrip(".") in {"unds", "unidades"}]
        money = [s for s in candidates if s["text"].lower() == "monto"]
        if len(dates) != 2 or len(units) != 1 or len(money) != 1:
            raise ValueError(f"No se pudo asociar inequívocamente fechas, unidades y monto a {period['text']}.")
        start, end = [datetime.strptime(s["text"], "%d/%m/%Y").date() for s in dates]
        if start > end or (start.year, start.month) != (end.year, end.month):
            raise ValueError(f"El bloque {period['text']} no representa un único mes válido.")
        mid = (units[0]["box"][2] + money[0]["box"][0]) / 2
        if not left < mid < right:
            raise ValueError("No se pueden separar las columnas de unidades y monto del PDF.")
        months.append({"period": start.strftime("%Y-%m"), "from": start.isoformat(), "to": end.isoformat(),
                       "full_month": start.day == 1 and end.day == calendar.monthrange(end.year, end.month)[1],
                       "source_id": period["text"], "left": left, "middle": mid, "right": right,
                       "header_bottom": max(units[0]["box"][3], money[0]["box"][3])})
    if len(set(m["period"] for m in months)) != len(months):
        raise ValueError("El ranking repite un mes; no se sumarán dos veces sus ventas.")
    required = {label: exact(label) for label in ("CODIGO", "DESCRIPCION DEL PRODUCTO", "CANT", "MONTO", "EXIST.", "NO.")}
    # MONTO appears once as the summary header and once for every monthly column.
    required["MONTO"] = [s for s in required["MONTO"] if s["box"][0] < months[0]["left"]]
    if any(len(items) != 1 for items in required.values()):
        raise ValueError("Faltan o se repiten encabezados principales: código, descripción, venta total o existencia.")
    code, desc, cant, monto, exist, rank = [required[label][0] for label in ("CODIGO", "DESCRIPCION DEL PRODUCTO", "CANT", "MONTO", "EXIST.", "NO.")]
    if not rank["box"][0] < code["box"][0] < desc["box"][0] < cant["box"][0] < monto["box"][0] < exist["box"][0] < months[0]["left"]:
        raise ValueError("El orden de las columnas del PDF es diferente del ranking comparativo reconocido.")
    # Numeric summary cells align to the right; boundaries follow complete stacked headers.
    summary = [s for s in spans if cant["box"][1]-1 <= s["box"][1] <= cant["box"][1]+20 and s["box"][0] < months[0]["left"]]
    center_cant = (cant["box"][0]+cant["box"][2])/2
    center_monto = (monto["box"][0]+monto["box"][2])/2
    cant_left = min(s["box"][0] for s in summary if abs((s["box"][0]+s["box"][2])/2-center_cant) < 3) - 1.5
    amount_left = min(s["box"][0] for s in summary if abs((s["box"][0]+s["box"][2])/2-center_monto) < 3) - 1.5
    pct = [s for s in summary if s["text"].upper() in {"PESO", "VENTA", "%"} and center_monto+15 < s["box"][0] < exist["box"][0]]
    if not pct:
        raise ValueError("No se pudo separar el total monetario de los porcentajes del ranking.")
    amount_right = min(s["box"][0] for s in pct) - 1.5
    previous_right = max(s["box"][2] for s in summary if amount_right < s["box"][0] < exist["box"][0])
    return {"months": months, "body_top": max(m["header_bottom"] for m in months),
            "rank": (rank["box"][0]-3, code["box"][0]-2),
            "code": (code["box"][0]-2, desc["box"][0]-2),
            "description": (desc["box"][0]-2, cant_left),
            "units_total": (cant_left, amount_left), "money_total": (amount_left, amount_right),
            "existence": ((previous_right+exist["box"][0])/2, months[0]["left"])}


def read_ranking_pdf_v714(raw, filename="ranking_A2.pdf"):
    """Isolated A2 ranking reader: no database, other uploads, or inferred zeros.

    Returned rows retain every rank, including invalid rows. Revisión lectura
    contains blocking extraction/identity errors. Observaciones fuente retains
    valid negative values for the calculation policy to review separately.
    Amounts are net sales as printed, never assumed to be inventory purchase costs.
    """
    import re
    import math
    import hashlib
    import unicodedata
    from datetime import datetime
    import pandas as pd
    import numpy as np
    try:
        import fitz
    except ImportError as exc:
        raise RuntimeError("Falta PyMuPDF para leer este PDF. Instala los requisitos de NEXUS en el mismo Python que ejecuta la app.") from exc
    if not isinstance(raw, (bytes, bytearray)) or not raw.startswith(b"%PDF"):
        raise ValueError("Sube un archivo PDF válido del ranking comparativo A2.")
    records, layouts, global_warnings, printed_money = [], [], [], []
    metadata = {"filename": filename, "sha256": hashlib.sha256(raw).hexdigest(), "source": "Solo PDF cargado", "database_used": False}
    with fitz.open(stream=raw, filetype="pdf") as doc:
        if doc.needs_pass:
            raise ValueError("El PDF está protegido con contraseña; exporta una copia legible desde A2.")
        if len(doc) > 1000:
            raise ValueError("El ranking supera 1000 páginas; divídelo por sede o proveedor.")
        metadata["pages"] = len(doc)
        for page_no, page in enumerate(doc, start=1):
            spans = _ranking_spans_v714(page)
            # A2 clips long code suffixes in its printed cell. Read their text
            # from the PDF without the clipping flag, ONLY in the code column.
            identity_spans = [s for b in page.get_text("dict", flags=fitz.TEXTFLAGS_DICT & ~fitz.TEXT_MEDIABOX_CLIP).get("blocks", [])
                              for line in b.get("lines", []) for s in line.get("spans", []) if s.get("text", "").strip()]
            identity_spans = [{"text": s["text"].strip(), "box": tuple(s["bbox"])} for s in identity_spans]
            if not spans:
                raise ValueError(f"La página {page_no} no contiene texto legible; exporta el PDF original de A2, no una imagen escaneada.")
            layout = _ranking_layout_v714(spans)
            full_descriptions=_ranking_descriptions_v7184(page,layout)
            layouts.append(layout)
            signature = [(m["period"], m["from"], m["to"]) for m in layout["months"]]
            if page_no > 1 and signature != [(m["period"], m["from"], m["to"]) for m in layouts[0]["months"]]:
                raise ValueError(f"La página {page_no} contiene otros meses o fechas. No mezcles rankings diferentes en un mismo PDF.")
            header_text = "\n".join(s["text"] for s in spans if s["box"][1] < layout["body_top"])
            def header_value(label):
                found = next((s for s in spans if s["text"].lower().startswith(label.lower()+":")), None)
                return found["text"].split(":", 1)[1].strip() if found else ""
            top_names = [s for s in spans if s["box"][0] < page.rect.width/2 and s["box"][1] < 60 and not re.match(r"(fecha|hora|pag)\b", s["text"], re.I)]
            company = " ".join(s["text"] for s in sorted(top_names, key=lambda s:(s["box"][1],s["box"][0])))
            department = next((s for s in spans if s["text"].lower().startswith("departamentos:")), None)
            group = [s for s in spans if department and s["box"][0] > department["box"][2] and abs(s["box"][1]-department["box"][1]) < 3 and s["box"][0] < page.rect.width/2]
            department_name = " ".join(s["text"] for s in sorted(group,key=lambda s:s["box"][0]))
            if page_no == 1:
                metadata["company"] = company
                metadata["report_date_text"] = header_value("Fecha")
                try: metadata["report_date"] = datetime.strptime(metadata["report_date_text"], "%d/%m/%Y").date().isoformat()
                except ValueError: metadata["report_date"] = None
                metadata["report_time"] = header_value("Hora")
                metadata["supplier"] = header_value("Proveedor")
                metadata["brand"] = header_value("Marca")
                metadata["warehouse"] = header_value("Depósito")
                metadata["department"] = department_name
                metadata["report_type"] = "Ranking de ventas por productos comparativo"
                metadata["currency_symbol"] = "$" if "VENTA EN $" in header_text else ""
            elif (company, department_name, header_value("Fecha"), header_value("Hora"), header_value("Depósito")) != (metadata["company"], metadata["department"], metadata["report_date_text"], metadata["report_time"], metadata["warehouse"]):
                raise ValueError(f"La página {page_no} pertenece a otra empresa, grupo, depósito o fecha de reporte. No mezcles rankings diferentes.")
            ranks = sorted([s for s in spans if s["box"][1] > layout["body_top"]
                            and layout["rank"][0] <= (s["box"][0]+s["box"][2])/2 < layout["rank"][1]
                            and re.fullmatch(r"\d+", s["text"])], key=lambda s:s["box"][1])
            if not ranks:
                global_warnings.append(f"Página {page_no}: no se detectaron filas de productos.")
                continue
            gaps = np.diff([s["box"][1] for s in ranks])
            row_step = float(np.median(gaps)) if len(gaps) else 10.0
            if row_step < 3:
                raise ValueError(f"Las filas de la página {page_no} están superpuestas.")
            for index, rank in enumerate(ranks):
                y = rank["box"][1]
                end = ranks[index+1]["box"][1]-0.75 if index+1 < len(ranks) else y+row_step-0.75
                row_spans = [s for s in spans if y-0.75 <= s["box"][1] < end]
                def cell(bounds, numeric=False):
                    parts = [s for s in row_spans if bounds[0] <= (s["box"][0]+s["box"][2])/2 < bounds[1]
                             and (not numeric or abs(s["box"][1]-y) <= 1.0)]
                    parts.sort(key=lambda s:(round(s["box"][1],1),s["box"][0]))
                    return " ".join(s["text"] for s in parts)
                visible_code = unicodedata.normalize("NFKC", cell(layout["code"])).strip()
                full_code_parts = [s for s in identity_spans if y-.75 <= s["box"][1] < end
                                   and layout["code"][0] <= (s["box"][0]+s["box"][2])/2 < layout["code"][1]]
                full_code_parts.sort(key=lambda s: (round(s["box"][1], 1), s["box"][0]))
                code_lines = []
                for part in full_code_parts:
                    if code_lines and abs(code_lines[-1][0] - part["box"][1]) < .5:
                        code_lines[-1][1].append(part["text"])
                    else:
                        code_lines.append([part["box"][1], [part["text"]]])
                code = unicodedata.normalize("NFKC", "".join(" ".join(line[1]) for line in code_lines)).strip() or visible_code
                description = next((text for yy,text in full_descriptions if abs(yy-y)<1.2),cell(layout["description"]))
                row = {"Código": code, "Código visible PDF": visible_code, "Descripción": description,
                       "Existencia": _ranking_number_v714(cell(layout["existence"], True)),
                       "Ventas total PDF": _ranking_number_v714(cell(layout["units_total"], True)),
                       "Monto total PDF": _ranking_number_v714(cell(layout["money_total"], True)),
                       "Página PDF": page_no, "Fila PDF": int(rank["text"]), "Fila en página": index+1,
                       "Revisión lectura": ""}
                for month in layout["months"]:
                    row["Unidades "+month["period"]] = _ranking_number_v714(cell((month["left"],month["middle"]),True))
                    row["Monto "+month["period"]] = _ranking_number_v714(cell((month["middle"],month["right"]),True))
                records.append(row)
            # Totals appear without rank, below last product. Never count as a product.
            footer = [s for s in spans if s["box"][1] > ranks[-1]["box"][1]+row_step-0.5
                      and math.isfinite(_ranking_number_v714(s["text"]))]
            if footer:
                totals = {"page":page_no}
                for name, bounds in [("total",layout["money_total"])] + [(m["period"],(m["middle"],m["right"])) for m in layout["months"]]:
                    values = [s for s in footer if bounds[0] <= (s["box"][0]+s["box"][2])/2 < bounds[1]]
                    if len(values) == 1: totals[name] = _ranking_number_v714(values[0]["text"])
                if "total" in totals: printed_money.append(totals)
        if not records:
            raise ValueError("El ranking no contiene filas de productos reconocibles.")
    frame = pd.DataFrame(records)
    periods = sorted(m["period"] for m in layouts[0]["months"])
    units_cols, amount_cols = ["Unidades "+m for m in periods], ["Monto "+m for m in periods]
    issues = [[] for _ in range(len(frame))]
    observations = [[] for _ in range(len(frame))]
    def flag(mask, reason):
        for pos in np.flatnonzero(np.asarray(mask)): issues[pos].append(reason)
    numeric_cols = ["Existencia","Ventas total PDF","Monto total PDF"] + units_cols + amount_cols
    flag(frame[numeric_cols].isna().any(axis=1), "Falta un número o su formato no es válido")
    flag(frame["Código"].eq(""), "Código vacío")
    flag(frame["Descripción"].eq(""), "Descripción vacía")
    flag(frame["Código"].str.upper().eq(frame["Descripción"].str.upper()), "Código igual a descripción")
    flag(frame["Código"].str.upper().duplicated(keep=False) & frame["Código"].ne(""), "Código repetido; no se fusionó")
    flag(frame["Fila PDF"].duplicated(keep=False), "Posición del ranking repetida")
    def observe(mask, reason):
        for pos in np.flatnonzero(np.asarray(mask)): observations[pos].append(reason)
    observe(frame["Existencia"].lt(0), "Existencia negativa")
    observe(frame[units_cols].lt(0).any(axis=1), "Ventas mensuales negativas; revisar devoluciones")
    observe(frame[amount_cols].lt(0).any(axis=1), "Montos mensuales negativos; revisar devoluciones/ajustes")
    frame["Suma unidades meses"] = frame[units_cols].sum(axis=1,min_count=len(periods))
    frame["Suma montos meses"] = frame[amount_cols].sum(axis=1,min_count=len(periods)).round(2)
    frame["Diferencia unidades PDF"] = frame["Suma unidades meses"] - frame["Ventas total PDF"]
    frame["Diferencia monto PDF"] = (frame["Suma montos meses"] - frame["Monto total PDF"]).round(2)
    flag(frame["Diferencia unidades PDF"].abs().gt(0.000001), "Las unidades mensuales no coinciden con el total impreso")
    # Each printed month may be rounded independently; 1 cent per month allowed.
    tolerance = max(0.01, len(periods)*0.005 + 0.005)
    flag(frame["Diferencia monto PDF"].abs().gt(tolerance+1e-9), "Los montos mensuales no coinciden con el total impreso")
    frame["Revisión lectura"] = ["; ".join(items) for items in issues]
    frame["Observaciones fuente"] = ["; ".join(items) for items in observations]
    ranks = frame["Fila PDF"].tolist()
    if ranks != list(range(1,len(frame)+1)):
        global_warnings.append("La numeración de productos no es continua desde 1: verifica páginas faltantes, duplicadas o filas no reconocidas.")
    month_meta = sorted([{k:v for k,v in m.items() if k in {"period","from","to","full_month","source_id"}} for m in layouts[0]["months"]],key=lambda m:m["period"])
    if not all(m["full_month"] for m in month_meta):
        global_warnings.append("Hay períodos parciales; no equivalen a meses completos de demanda.")
    month_ord = [int(m[:4])*12+int(m[5:]) for m in periods]
    if any(b-a != 1 for a,b in zip(month_ord,month_ord[1:])):
        global_warnings.append("Los meses del ranking no son consecutivos; verifica la ventana histórica.")
    total_units = float(frame["Ventas total PDF"].sum(min_count=len(frame)))
    total_amount = round(float(frame["Monto total PDF"].sum(min_count=len(frame))),2)
    monthly_totals = [{"period":m,"units":float(frame["Unidades "+m].sum(min_count=len(frame))),
                       "amount":round(float(frame["Monto "+m].sum(min_count=len(frame))),2)} for m in periods]
    if len(printed_money) == 1:
        printed = printed_money[0]
        difference = round(total_amount-printed["total"],2)
        if abs(difference) > 0.01+1e-9:
            global_warnings.append(f"La suma de montos por producto difiere del total general impreso en {difference:.2f}.")
        for month in monthly_totals:
            if month["period"] in printed:
                delta = round(month["amount"]-printed[month["period"]],2)
                month["printed_amount"] = printed[month["period"]]
                month["difference_printed_amount"] = delta
                if abs(delta) > 0.01+1e-9:
                    global_warnings.append(f"El monto de {month['period']} difiere del total mensual impreso en {delta:.2f}.")
    else:
        global_warnings.append("No se reconoció un único total general monetario al pie del ranking; los totales por fila sí se verifican.")
    metadata["recovered_codes"] = frame.loc[frame["Código"].ne(frame["Código visible PDF"]), ["Código visible PDF", "Código", "Página PDF", "Fila PDF"]].to_dict("records")
    metadata.update({"periods":periods,"months":month_meta,"months_count":len(periods),
                     "date_from":month_meta[0]["from"],"date_to":month_meta[-1]["to"],
                     "rows":len(frame),"unique_codes":int(frame["Código"].nunique()),
                     "review_rows":int(frame["Revisión lectura"].ne("").sum()),
                     "observation_rows":int(frame["Observaciones fuente"].ne("").sum()),
                     "negative_stock_rows":int(frame["Existencia"].lt(0).sum()),
                     "negative_units_rows":int(frame[units_cols].lt(0).any(axis=1).sum()),
                     "negative_amount_rows":int(frame[amount_cols].lt(0).any(axis=1).sum()),
                     "total_units":total_units,"total_amount":total_amount,"monthly_totals":monthly_totals,
                     "printed_totals":printed_money,"global_warnings":global_warnings,
                     "amount_rounding_tolerance":tolerance,
                     "description_note":"Se conserva la descripción impresa en el PDF; si A2 la recortó, no se completa desde otra base.",
                     "coverage_note":"El ranking puede mostrar solo productos con ventas; la ausencia de un código no equivale a demanda cero."})
    return {"data":frame,"metadata":metadata}


"""Políticas de stock aisladas para el ranking mensual A2 (sin base de datos)."""

import math
import re
import unicodedata
import numpy as np
import pandas as pd


RANKING_POLICIES_V714 = {
    "promedio_historico": "Promedio de todos los meses",
    "promedio_dos_mejores": "Promedio de los dos meses con más ventas",
    "suma_dos_mejores": "Suma de los dos meses con más ventas · criterio solicitado",
}


def _ranking_policy_number_v714(value):
    """Solo números ya normalizados por el lector; nunca adivina separadores."""
    try:
        if isinstance(value, (bool, np.bool_)):
            return np.nan
        result = float(value)
        return result if math.isfinite(result) else np.nan
    except (TypeError, ValueError, OverflowError):
        return np.nan


def _ranking_text_v714(value):
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except (ValueError, TypeError):
        return ""
    return unicodedata.normalize("NFKC", str(value)).strip()


def _ranking_ceil_v714(value):
    return float(math.ceil(round(float(value), 10))) if pd.notna(value) else np.nan


def _ranking_review_v714(value):
    text = _ranking_text_v714(value)
    return text if text.casefold() not in {"", "false", "no", "0", "none", "nan", "ok"} else ""


def ranking_months_v714(data, months=None):
    """Valida que haya dos o más meses distintos, consecutivos y presentes."""
    selected = list(months) if months is not None else [
        str(column)[9:] for column in data.columns
        if re.fullmatch(r"Unidades \d{4}-\d{2}", str(column))
    ]
    selected = [str(month) for month in selected]
    if len(selected) < 2:
        raise ValueError("Se necesitan al menos dos meses completos de ventas por producto.")
    if len(set(selected)) != len(selected):
        raise ValueError("Hay meses repetidos. Cada mes debe participar una sola vez.")
    if any(not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", month) for month in selected):
        raise ValueError("Los meses deben indicarse como AAAA-MM.")
    selected.sort()
    ordinal = [pd.Period(month, freq="M").ordinal for month in selected]
    if any(right - left != 1 for left, right in zip(ordinal, ordinal[1:])):
        raise ValueError("Faltan meses intermedios. No se sustituyen meses ausentes por ventas cero.")
    missing = [month for month in selected if f"Unidades {month}" not in data.columns]
    if missing:
        raise ValueError("Faltan las ventas mensuales de: " + ", ".join(missing))
    return selected


def evaluate_ranking_policies_v714(
    data,
    months=None,
    min_coverage=1.0,
    max_coverage=2.0,
    policy="suma_dos_mejores",
    review_returns=False,
    review_zero=False,
):
    """Compara tres escenarios por SKU, conservando íntegra la evidencia mensual.

    ``suma_dos_mejores`` reproduce literalmente (mes1 + mes2) * cobertura.
    ``promedio_dos_mejores`` usa ((mes1 + mes2) / 2) * cobertura.
    Los empates se resuelven eligiendo el mes más reciente primero.
    Los importes de ventas se conservan; nunca se convierten en costos de compra.
    Las filas pendientes tienen cálculos para revisión, pero ``Lista para planilla``
    es False; el generador debe exportar solo las filas explícitamente aptas.
    """
    if not isinstance(data, pd.DataFrame):
        raise TypeError("El ranking debe ser una tabla de pandas.")
    if data.columns.duplicated().any():
        raise ValueError("Hay columnas repetidas. Revisa el encabezado antes de calcular.")
    selected = ranking_months_v714(data, months)
    source_months = ranking_months_v714(data)
    compare_source_totals = selected == source_months
    min_cov, max_cov = _ranking_policy_number_v714(min_coverage), _ranking_policy_number_v714(max_coverage)
    if pd.isna(min_cov) or pd.isna(max_cov) or not (0 <= min_cov <= max_cov and max_cov > 0):
        raise ValueError("La cobertura mínima debe ser mayor o igual a cero y no superar la máxima; la máxima debe ser positiva.")
    if policy not in RANKING_POLICIES_V714:
        raise ValueError("Selecciona una política de cálculo válida.")
    missing = [col for col in ("Código", "Descripción", "Existencia") if col not in data.columns]
    if missing:
        raise ValueError("Faltan columnas: " + ", ".join(missing))
    result = data.copy(deep=True).reset_index(drop=True)
    codes = result["Código"].map(_ranking_text_v714).str.upper()
    duplicate = codes.duplicated(keep=False) & codes.ne("")
    derived_rows = []
    amount_columns = [f"Monto {month}" for month in selected]
    monthly_amounts_present = all(col in result.columns for col in amount_columns)
    for position, row in result.iterrows():
        reasons = []
        warnings = []
        quantities = [_ranking_policy_number_v714(row[f"Unidades {month}"]) for month in selected]
        complete = all(pd.notna(number) for number in quantities)
        stock = _ranking_policy_number_v714(row["Existencia"])
        code = codes.iloc[position]
        description = _ranking_text_v714(row["Descripción"])
        if not code:
            reasons.append("Código vacío")
        if not description:
            reasons.append("Descripción vacía")
        if code and code == description.upper():
            reasons.append("Código y descripción contienen el mismo texto")
        if bool(duplicate.iloc[position]):
            reasons.append("Código repetido: revisar las filas, no sumar automáticamente")
        if not complete:
            absent = [month for month, number in zip(selected, quantities) if pd.isna(number)]
            reasons.append("Ventas mensuales no informadas: " + ", ".join(absent))
        if pd.isna(stock):
            reasons.append("Existencia no informada")
        elif stock < 0:
            reasons.append("Existencia negativa: verificar inventario")
        reading_issue = _ranking_review_v714(row.get("Revisión lectura", ""))
        if reading_issue:
            reasons.append("Revisar lectura: " + reading_issue)
        has_returns = any(pd.notna(number) and number < 0 for number in quantities)
        if has_returns and not review_returns:
            reasons.append("Hay ventas netas negativas: revisar devoluciones")
        if has_returns and review_returns:
            warnings.append("Ventas negativas revisadas; se conservan sus signos")
        total = math.fsum(quantities) if complete else np.nan
        historical = total / len(selected) if complete else np.nan
        pdf_total = _ranking_policy_number_v714(row.get("Ventas total PDF", np.nan))
        if compare_source_totals and complete and pd.notna(pdf_total) and not math.isclose(total, pdf_total, rel_tol=1e-10, abs_tol=1e-6):
            reasons.append("La suma mensual no coincide con las ventas totales del PDF")
        if not compare_source_totals:
            warnings.append("Se usa un subconjunto de meses; el total PDF corresponde al período completo de origen")
        if complete:
            ranked = sorted(zip(selected, quantities), key=lambda pair: (pair[1], pair[0]), reverse=True)
            first_month, first_quantity = ranked[0]
            second_month, second_quantity = ranked[1]
            top_sum = first_quantity + second_quantity
            top_average = top_sum / 2.0
        else:
            first_month = second_month = ""
            first_quantity = second_quantity = top_sum = top_average = np.nan
        bases = {
            "promedio_historico": historical,
            "promedio_dos_mejores": top_average,
            "suma_dos_mejores": top_sum,
        }
        base = bases[policy]
        minimum = _ranking_ceil_v714(base * min_cov)
        maximum = _ranking_ceil_v714(base * max_cov)
        if pd.notna(base) and base < 0:
            reasons.append("La base de demanda es negativa: no es una propuesta de stock válida")
        elif pd.notna(base) and base == 0 and not review_zero:
            reasons.append("Sin demanda en la base seleccionada: confirmar límites cero")
        elif pd.notna(base) and base == 0 and review_zero:
            warnings.append("Límites cero revisados expresamente")
        amounts = [_ranking_policy_number_v714(row[col]) for col in amount_columns] if monthly_amounts_present else []
        amount_total = math.fsum(amounts) if amounts and all(pd.notna(number) for number in amounts) else np.nan
        pdf_amount = _ranking_policy_number_v714(row.get("Monto total PDF", np.nan))
        if monthly_amounts_present and pd.isna(amount_total):
            warnings.append("Hay importes mensuales no informados; no afectan la suma de unidades")
        if compare_source_totals and pd.notna(amount_total) and pd.notna(pdf_amount) and not math.isclose(amount_total, pdf_amount, rel_tol=1e-10, abs_tol=0.02):
            warnings.append("La suma de importes mensuales no coincide con el importe total del PDF")
        finite_plan = pd.notna(maximum) and maximum >= 0 and pd.notna(stock) and stock >= 0
        to_order = max(maximum - stock, 0.0) if finite_plan else np.nan
        triggered_order = to_order if finite_plan and stock < minimum else (0.0 if finite_plan else np.nan)
        overstock = max(stock - maximum, 0.0) if finite_plan else np.nan
        hist_min = _ranking_ceil_v714(historical * min_cov)
        hist_max = _ranking_ceil_v714(historical * max_cov)
        derived_rows.append({
            "Meses utilizados": len(selected),
            "Ventas meses calculadas": total,
            "Monto meses calculado": amount_total,
            "Demanda mensual promedio": historical,
            "Mes 1 mayor venta": first_month,
            "Unidades mes 1": first_quantity,
            "Mes 2 mayor venta": second_month,
            "Unidades mes 2": second_quantity,
            "Suma dos mejores meses": top_sum,
            "Promedio dos mejores meses": top_average,
            "Mínimo promedio histórico": hist_min,
            "Máximo promedio histórico": hist_max,
            "Mínimo promedio dos mejores": _ranking_ceil_v714(top_average * min_cov),
            "Máximo promedio dos mejores": _ranking_ceil_v714(top_average * max_cov),
            "Mínimo suma dos mejores": _ranking_ceil_v714(top_sum * min_cov),
            "Máximo suma dos mejores": _ranking_ceil_v714(top_sum * max_cov),
            "Política aplicada": RANKING_POLICIES_V714[policy],
            "Clave política": policy,
            "Base aplicada": base,
            "Cobertura mínima aplicada": min_cov,
            "Cobertura máxima aplicada": max_cov,
            "Stock Mínimo": minimum,
            "Stock Máximo": maximum,
            "Diferencia mínimo vs promedio": minimum - hist_min,
            "Diferencia máximo vs promedio": maximum - hist_max,
            "Variación máximo vs promedio (%)": (maximum / hist_max - 1) * 100 if pd.notna(hist_max) and hist_max > 0 else np.nan,
            "Máximo en meses al promedio histórico": maximum / historical if pd.notna(historical) and historical > 0 else np.nan,
            "A pedir": to_order,
            "Compra sugerida bajo mínimo": triggered_order,
            "Sobrestock": overstock,
            "Lista para planilla": not reasons,
            "Estado propuesta": "Lista" if not reasons else "Pendiente de revisión",
            "Motivo revisión": " · ".join(reasons),
            "Observaciones": " · ".join(warnings),
        })
    calculated = pd.DataFrame(derived_rows, index=result.index)
    for column in calculated.columns:
        result[column] = calculated[column]
    # Un lote vacío conserva el esquema de entrada y no crea filas ficticias.
    if result.empty:
        result["Lista para planilla"] = pd.Series(dtype=bool)
        result["Estado propuesta"] = pd.Series(dtype=str)
        result["Motivo revisión"] = pd.Series(dtype=str)
    result.attrs.update({
        "months": selected,
        "selected_months": selected,
        "source_months": source_months,
        "selected_month_count": len(selected),
        "source_month_count": len(source_months),
        "selected_years": sorted({int(month[:4]) for month in selected}),
        "source_years": sorted({int(month[:4]) for month in source_months}),
        "pdf_totals_reconciled_for_selected_window": compare_source_totals,
        "policy": policy,
        "min_coverage": min_cov,
        "max_coverage": max_cov,
        "review_returns": bool(review_returns),
        "review_zero": bool(review_zero),
        "source": "Solo el ranking cargado; no se consultó ni sumó la base NEXUS",
        "ranking_ties": "Mayor cantidad por producto; en empate, mes más reciente primero",
        "purchase_rule": "Compra sugerida bajo mínimo: completar al máximo solo si existencia < mínimo; A pedir completa al máximo",
        "cost_rule": "El monto vendido no se utiliza como costo de compra",
    })
    return result


def evaluate_ranking_backtest_v714(data, months=None):
    """Prueba retrospectiva orientativa: entrena sin usar los dos meses finales.

    Devuelve (resumen, detalle, metadata). Utiliza la misma cohorte completa,
    sin cantidades negativas, sin códigos duplicados ni lecturas pendientes.
    No exige existencia: esta prueba compara ventas, no propone una compra.
    """
    selected = ranking_months_v714(data, months)
    if len(selected) < 4:
        raise ValueError("La prueba retrospectiva necesita al menos cuatro meses completos.")
    train, test = selected[:-2], selected[-2:]
    codes = data["Código"].map(_ranking_text_v714).str.upper()
    duplicated = codes.duplicated(keep=False) & codes.ne("")
    details = []
    excluded = 0
    for position, (_, row) in enumerate(data.iterrows()):
        values = [_ranking_policy_number_v714(row[f"Unidades {month}"]) for month in selected]
        if (not codes.iloc[position] or bool(duplicated.iloc[position])
                or _ranking_review_v714(row.get("Revisión lectura", ""))
                or any(pd.isna(value) or value < 0 for value in values)):
            excluded += 1
            continue
        training, actual = values[:-2], math.fsum(values[-2:])
        top_sum = math.fsum(sorted(training, reverse=True)[:2])
        bases = {
            "promedio_historico": math.fsum(training) / len(train),
            "promedio_dos_mejores": top_sum / 2,
            "suma_dos_mejores": top_sum,
        }
        for key, base in bases.items():
            predicted = base * len(test)
            details.append({
                "Código": row["Código"], "Descripción": row.get("Descripción", ""),
                "Clave política": key, "Política": RANKING_POLICIES_V714[key],
                "Base sin meses de prueba": base,
                "Unidades previstas": predicted, "Unidades reales": actual,
                "Error unidades": predicted - actual,
                "Error absoluto unidades": abs(predicted - actual),
            })
    detail = pd.DataFrame(details, columns=[
        "Código", "Descripción", "Clave política", "Política", "Base sin meses de prueba",
        "Unidades previstas", "Unidades reales", "Error unidades", "Error absoluto unidades",
    ])
    summary = []
    for key, label in RANKING_POLICIES_V714.items():
        part = detail.loc[detail["Clave política"].eq(key)]
        actual = float(part["Unidades reales"].sum())
        predicted = float(part["Unidades previstas"].sum())
        absolute = float(part["Error absoluto unidades"].sum())
        summary.append({
            "Clave política": key, "Política": label,
            "Productos evaluados": len(part),
            "Ventas reales de prueba": actual,
            "Ventas previstas de prueba": predicted,
            "Error absoluto medio por producto": absolute / len(part) if len(part) else np.nan,
            "Sesgo total unidades": predicted - actual,
            "Sesgo total (%)": (predicted / actual - 1) * 100 if actual > 0 else np.nan,
            "Error absoluto ponderado (%)": absolute / actual * 100 if actual > 0 else np.nan,
        })
    return pd.DataFrame(summary), detail, {
        "train_months": train, "test_months": test,
        "source_months": ranking_months_v714(data),
        "selected_months": selected,
        "included_products": len(detail) // len(RANKING_POLICIES_V714),
        "excluded_products": excluded,
        "limitation": "Una sola ventana retrospectiva no determina la política óptima ni garantiza ventas futuras.",
        "no_leakage": "Los meses con más ventas se eligen únicamente dentro del período de entrenamiento.",
    }


"""Exportación Excel del ranking A2; integrada en el único script de NEXUS."""


def _ranking_excel_value_v714(cell, value):
    """Escribe textos literalmente, incluidos códigos que comiencen con = o +."""
    import math
    import pandas as pd
    import numpy as np
    if value is None:
        cell.value = None
    elif isinstance(value, (bool, np.bool_)):
        cell.value = bool(value)
    elif isinstance(value, (int, float, np.integer, np.floating)):
        cell.value = float(value) if math.isfinite(float(value)) else None
    else:
        try:
            if pd.isna(value):
                cell.value = None
                return
        except (ValueError, TypeError):
            pass
        cell.value = str(value)
        cell.data_type = "s"


def _ranking_excel_cache_v714(raw, cached):
    """Incluye resultados iniciales; Excel recalcula fórmulas al abrir o editar.

    openpyxl conserva las fórmulas pero no las calcula. Se guardan los resultados
    de la misma evaluación usada por NEXUS para las vistas previas del archivo.
    No se sustituye ninguna fórmula por un valor fijo.
    """
    import io
    import math
    import zipfile
    import xml.etree.ElementTree as ET
    ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    ET.register_namespace("", ns)
    output = io.BytesIO()
    with zipfile.ZipFile(io.BytesIO(raw)) as source, zipfile.ZipFile(output, "w", zipfile.ZIP_DEFLATED) as target:
        for item in source.infolist():
            data = source.read(item.filename)
            values = cached.get(item.filename)
            if values:
                root = ET.fromstring(data)
                for cell in root.iter("{"+ns+"}c"):
                    address = cell.get("r")
                    if address not in values or cell.find("{"+ns+"}f") is None:
                        continue
                    value = values[address]
                    old = cell.find("{"+ns+"}v")
                    if old is None:
                        old = ET.SubElement(cell, "{"+ns+"}v")
                    if isinstance(value, str) or value is None:
                        cell.set("t", "str")
                        old.text = "" if value is None else value
                    elif isinstance(value, bool):
                        cell.set("t", "b")
                        old.text = "1" if value else "0"
                    else:
                        try:
                            number = float(value)
                            if not math.isfinite(number):
                                cell.set("t", "str")
                                old.text = ""
                            else:
                                cell.set("t", "n")
                                old.text = repr(number)
                        except (TypeError, ValueError):
                            cell.set("t", "str")
                            old.text = str(value)
                data = ET.tostring(root, encoding="utf-8", xml_declaration=True)
            target.writestr(item, data)
    return output.getvalue()


def build_ranking_excel_v714(result, metadata, months):
    """Devuelve un XLSX formulado, aislado de la base de datos de NEXUS.

    ``result`` es la salida completa de ``evaluate_ranking_policies_v714``.
    Se preservan todas las filas, también las pendientes. ``metadata`` contiene
    la identidad del PDF y los parámetros confirmados. Los cambios en Excel son
    simulaciones: no modifican el PDF ya generado ni la base de datos.
    """
    import io
    import math
    import json
    import pandas as pd
    from datetime import datetime, timezone, timedelta
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.comments import Comment
    from openpyxl.utils import get_column_letter
    from openpyxl.worksheet.datavalidation import DataValidation
    from openpyxl.formatting.rule import FormulaRule
    from openpyxl.workbook.properties import CalcProperties

    if not isinstance(result, pd.DataFrame) or result.empty:
        raise ValueError("No hay filas evaluadas para preparar la comparación Excel.")
    months = ranking_months_v714(result, months)
    metadata = dict(metadata or {})
    attrs = dict(result.attrs)
    params = {**attrs, **metadata}
    policy = str(params.get("policy", "suma_dos_mejores"))
    if policy not in RANKING_POLICIES_V714:
        raise ValueError("La política seleccionada no es válida.")
    min_cov = float(params.get("min_coverage", 1.0))
    max_cov = float(params.get("max_coverage", 2.0))
    if not (math.isfinite(min_cov) and math.isfinite(max_cov) and 0 <= min_cov <= max_cov and max_cov > 0):
        raise ValueError("Revisa las coberturas antes de preparar el Excel.")
    # Revalidar asegura que resultados en caché y fórmulas correspondan exactamente
    # a los parámetros recibidos, incluso si un llamador entrega una tabla antigua.
    result = evaluate_ranking_policies_v714(
        result, months, min_cov, max_cov, policy,
        review_returns=bool(params.get("review_returns", False)),
        review_zero=bool(params.get("review_zero", False)),
    )
    wb = Workbook()
    ws = wb.active
    ws.title = "Comparación"
    source = wb.create_sheet("Fuente PDF")
    config = wb.create_sheet("Parámetros")
    wb.calculation = CalcProperties(calcId=191029, fullCalcOnLoad=True, forceFullCalc=True, calcMode="auto")
    wb.properties.title = "NEXUS · Ranking mensual y políticas de stock"
    wb.properties.subject = "Comparación por producto con evidencia mensual del PDF A2"
    wb.properties.creator = "Makropetrol NEXUS"
    navy, teal, blue, pale = "163641", "087F8C", "EAF4FF", "F2F6F8"
    white, ink, amber = "FFFFFF", "213547", "FFF3D6"
    border = Side(style="hair", color="DCE5E8")
    editable_fill = PatternFill("solid", fgColor=blue)
    calculated_fill = PatternFill("solid", fgColor=pale)
    cached = {}

    def literal(sheet, row, col, value):
        _ranking_excel_value_v714(sheet.cell(row, col), value)

    def title(sheet, heading, note, end=12):
        sheet.merge_cells(start_row=1, start_column=1, end_row=1, end_column=end)
        literal(sheet, 1, 1, heading)
        sheet.cell(1, 1).font = Font(name="Calibri", size=18, bold=True, color=white)
        sheet.cell(1, 1).fill = PatternFill("solid", fgColor=navy)
        sheet.cell(1, 1).alignment = Alignment(vertical="center")
        sheet.row_dimensions[1].height = 34
        sheet.merge_cells(start_row=2, start_column=1, end_row=3, end_column=end)
        literal(sheet, 2, 1, note)
        sheet.cell(2, 1).alignment = Alignment(wrap_text=True, vertical="center")
        sheet.cell(2, 1).font = Font(name="Calibri", size=11, color=ink)
        sheet.row_dimensions[2].height = 25
        sheet.row_dimensions[3].height = 20
        sheet.sheet_view.showGridLines = False

    def header(sheet, columns):
        for col, name in enumerate(columns, 1):
            literal(sheet, 5, col, name)
            cell = sheet.cell(5, col)
            cell.fill = PatternFill("solid", fgColor=teal)
            cell.font = Font(name="Calibri", bold=True, color=white)
            cell.alignment = Alignment(wrap_text=True, vertical="center")
            sheet.column_dimensions[get_column_letter(col)].width = 18
        sheet.row_dimensions[5].height = 44
        sheet.freeze_panes = "C6"

    title(config, "Parámetros del cálculo", "Edita las celdas azules para simular otra política o cobertura. El Excel recalcula al abrirse en Excel o LibreOffice; no cambia automáticamente el PDF, NEXUS ni A2.", 6)
    stamp = params.get("Generado ISO") or params.get("Generado") or params.get("generated_at") or params.get("generated_time") or datetime.now(timezone(timedelta(hours=-4))).isoformat(timespec="seconds")
    config_rows = [
        ("Método de cálculo", RANKING_POLICIES_V714[policy]),
        ("Cobertura mínima / factor", min_cov),
        ("Cobertura máxima / factor", max_cov),
        ("Devoluciones revisadas en NEXUS", "Sí" if params.get("review_returns", False) else "No"),
        ("Límites cero revisados en NEXUS", "Sí" if params.get("review_zero", False) else "No"),
        ("Sede", params.get("Sede") or params.get("site") or params.get("sede") or params.get("company") or "Pendiente de identificar"),
        ("Archivo fuente", params.get("filename", "Ranking A2 cargado")),
        ("Huella SHA-256 del PDF", params.get("sha256", "No informada")),
        ("Generado (hora de Venezuela)", str(stamp)),
        ("Meses analizados", ", ".join(months)),
        ("Origen de los datos", "Solo el ranking PDF cargado; no se sumó la base NEXUS"),
        ("Empates entre meses", "Misma cantidad: se escoge primero el mes más reciente"),
        ("Redondeo de mínimos y máximos", "Hacia arriba a la unidad, después de redondear el cálculo a 10 decimales"),
        ("A pedir", "Completar al máximo: MAX(máximo - existencia, 0). No descuenta tránsito, reservas ni traslados."),
        ("Compra sugerida bajo mínimo", "Completar al máximo solo cuando existencia < mínimo"),
        ("Costos", "El monto vendido no equivale a costo de compra; no se estiman costos con este ranking"),
        ("Alcance", "Los productos ausentes del ranking no se interpretan como ventas cero"),
        ("Control de edición", "Al cambiar unidades, existencia, método, coberturas o factores, la fila se marca SIMULACIÓN. Revisa los cambios en NEXUS antes de generar una nueva planilla."),
        ("Cobertura y factor", "En los dos métodos de promedio, la cobertura se expresa en meses. En suma de dos mejores, el factor multiplica un total de dos meses: no es una base mensual y da el doble que el promedio de esos dos meses."),
        ("Información de la fuente", json.dumps({key: value for key, value in metadata.items() if key not in {"raw", "data", "pdf_bytes"}}, ensure_ascii=False, default=str)[:30000]),
    ]
    # Las direcciones B4:B8 forman el contrato de las fórmulas siguientes.
    for row_no, (name, value) in enumerate(config_rows, 4):
        literal(config, row_no, 1, name)
        literal(config, row_no, 2, value)
        config.cell(row_no, 1).font = Font(bold=True, color=ink)
        config.cell(row_no, 2).alignment = Alignment(wrap_text=True, vertical="top")
        if row_no in (4, 5, 6):
            config.cell(row_no, 2).fill = editable_fill
        config.row_dimensions[row_no].height = 32 if row_no < 15 else 44
    config.column_dimensions["A"].width = 36
    config.column_dimensions["B"].width = 84
    for col in ("C", "D", "E"):
        config.column_dimensions[col].width = 3
    config.column_dimensions["F"].width = 24
    for row_no, label in enumerate(RANKING_POLICIES_V714.values(), 4):
        literal(config, row_no, 6, label)
    for row_no in range(4, 9):
        literal(config, row_no+6, 6, config.cell(row_no, 2).value)
    config.column_dimensions["F"].hidden = True
    choose = DataValidation(type="list", formula1="'Parámetros'!$F$4:$F$6")
    choose.errorTitle = "Método no reconocido"
    choose.error = "Selecciona uno de los tres métodos de la lista."
    choose.showErrorMessage = True
    choose.errorStyle = "stop"
    config.add_data_validation(choose)
    choose.add("B4")
    coverage = DataValidation(type="decimal", operator="between", formula1="0", formula2="12")
    coverage.error = "Indica un valor numérico entre 0 y 12; el máximo debe ser positivo y no menor que el mínimo."
    coverage.showErrorMessage = True
    config.add_data_validation(coverage)
    coverage.add("B5:B6")
    config.freeze_panes = "B4"

    derived = {
        "Meses utilizados", "Ventas meses calculadas", "Monto meses calculado", "Demanda mensual promedio",
        "Mes 1 mayor venta", "Unidades mes 1", "Mes 2 mayor venta", "Unidades mes 2",
        "Suma dos mejores meses", "Promedio dos mejores meses", "Mínimo promedio histórico", "Máximo promedio histórico",
        "Mínimo promedio dos mejores", "Máximo promedio dos mejores", "Mínimo suma dos mejores", "Máximo suma dos mejores",
        "Política aplicada", "Clave política", "Base aplicada", "Cobertura mínima aplicada", "Cobertura máxima aplicada",
        "Stock Mínimo", "Stock Máximo", "Diferencia mínimo vs promedio", "Diferencia máximo vs promedio",
        "Variación máximo vs promedio (%)", "Máximo en meses al promedio histórico", "A pedir", "Compra sugerida bajo mínimo",
        "Sobrestock", "Lista para planilla", "Estado propuesta", "Motivo revisión", "Observaciones", "Seleccionado para PDF",
    }
    source_cols = [str(col) for col in result.columns if col not in derived]
    title(source, "Fuente PDF · datos y revisión originales", "Evidencia de la lectura del ranking antes de editar la comparación. Incluye todas las filas, los montos, la página y las observaciones; no se fusionan códigos ni se rellenan meses ausentes con cero.", min(len(source_cols), 12))
    header(source, source_cols)
    source_map = {name: get_column_letter(col) for col, name in enumerate(source_cols, 1)}
    for row_no, row in enumerate(result.to_dict("records"), 6):
        for col, name in enumerate(source_cols, 1):
            literal(source, row_no, col, row.get(name))
            cell = source.cell(row_no, col)
            cell.number_format = "0.00" if "Monto" in name or "monto" in name else "0.##"
            if name in {"Código", "Descripción", "Revisión lectura"}:
                cell.number_format = "@"
    source.column_dimensions[source_map["Descripción"]].width = 48
    source.column_dimensions[source_map["Código"]].width = 22
    source.auto_filter.ref = f"A5:{get_column_letter(len(source_cols))}{len(result)+5}"

    columns = [
        "Código", "Descripción", "Existencia", *["Unidades "+m for m in months],
        "Total unidades", "Promedio mensual histórico", "Mes 1 mayor venta", "Unidades mes 1", "Mes 2 mayor venta", "Unidades mes 2",
        "Promedio dos mejores meses", "Suma dos mejores meses",
        "Mínimo promedio histórico", "Máximo promedio histórico", "Mínimo promedio dos mejores", "Máximo promedio dos mejores",
        "Mínimo suma dos mejores", "Máximo suma dos mejores", "Base seleccionada", "Mínimo seleccionado", "Máximo seleccionado",
        "A pedir", "Compra sugerida bajo mínimo", "Sobrestock", "Diferencia máximo vs histórico",
        "Máximo en meses al promedio histórico", "Validación en Excel", "Estado en NEXUS", "Seleccionado para PDF", "Motivo revisión original", "Observaciones originales",
        "Página PDF", "Fila PDF", *["Orden "+m for m in months],
    ]
    colno = {name: idx for idx, name in enumerate(columns, 1)}
    letters = {name: get_column_letter(idx) for name, idx in colno.items()}
    title(ws, "NEXUS · comparación de políticas por producto", "Azul: existencia y ventas mensuales editables. Cambia política y coberturas en Parámetros. La suma de los dos mejores meses es el doble de su promedio; cada producto elige sus propios meses. Las filas pendientes se conservan para revisión.", 12)
    header(ws, columns)
    ws.column_dimensions["A"].width = 22
    ws.column_dimensions["B"].width = 48
    for name in ("Motivo revisión original", "Observaciones originales", "Validación en Excel"):
        ws.column_dimensions[letters[name]].width = 42
    ws.column_dimensions[letters["Estado en NEXUS"]].width = 25
    for name in ("Mínimo seleccionado", "Máximo seleccionado", "A pedir", "Compra sugerida bajo mínimo"):
        ws.cell(5, colno[name]).fill = PatternFill("solid", fgColor=navy)
    for month in months:
        ws.column_dimensions[letters["Orden "+month]].hidden = True
    for name in ("Código", "Descripción", "Página PDF", "Fila PDF"):
        ws.cell(5, colno[name]).comment = Comment("Identificación conservada del ranking PDF cargado. No se completa con otra base.", "NEXUS")
    ws.cell(5, colno["Mínimo seleccionado"]).comment = Comment("Redondeo al entero superior: -INT(-ROUND(base × cobertura mínima, 10)).", "NEXUS")
    ws.cell(5, colno["Máximo seleccionado"]).comment = Comment("Redondeo al entero superior: -INT(-ROUND(base × cobertura máxima, 10)).", "NEXUS")
    ws.cell(5, colno["A pedir"]).comment = Comment("Completa al máximo. Es una diferencia de unidades, no una orden aprobada ni un costo de compra.", "NEXUS")
    ws.cell(5, colno["Validación en Excel"]).comment = Comment("Los cambios de unidades, existencia, método, coberturas o factores se marcan SIMULACIÓN. Las filas originalmente pendientes requieren revisión en NEXUS. Este archivo no actualiza el PDF previamente descargado.", "NEXUS")

    cached_sheet = {}
    method = "'Parámetros'!$B$4"
    minimum_cov = "'Parámetros'!$B$5"
    maximum_cov = "'Parámetros'!$B$6"
    labels = list(RANKING_POLICIES_V714.values())
    monthly_first, monthly_last = letters["Unidades "+months[0]], letters["Unidades "+months[-1]]
    rank_first, rank_last = letters["Orden "+months[0]], letters["Orden "+months[-1]]
    selected_codes = params.get("selected_codes")
    selected_codes = set(str(code) for code in selected_codes) if isinstance(selected_codes, (list, tuple, set)) else None
    def number(value):
        # Inputs used by Excel must be real numeric cells. The Fuente PDF sheet
        # retains original text even when a caller supplied a numeric string.
        try:
            if isinstance(value, bool) or type(value).__name__ == "bool_":
                return None
            normalized = float(value)
            return normalized if math.isfinite(normalized) else None
        except (TypeError, ValueError, OverflowError):
            return None
    for row_no, row in enumerate(result.to_dict("records"), 6):
        def ref(name):
            return f"{letters[name]}{row_no}"
        def formula(name, expression, value):
            cell = ws.cell(row_no, colno[name], "="+expression)
            cell.fill = calculated_fill
            cached_sheet[cell.coordinate] = value
        for name in ["Código", "Descripción", "Existencia", *["Unidades "+m for m in months], "Página PDF", "Fila PDF"]:
            if name == "Existencia" or name.startswith("Unidades ") and name[9:] in months:
                literal(ws, row_no, colno[name], number(row.get(name)))
                ws.cell(row_no, colno[name]).fill = editable_fill
            else:
                literal(ws, row_no, colno[name], row.get(name))
        literal(ws, row_no, colno["Estado en NEXUS"], row.get("Estado propuesta", "Pendiente de revisión"))
        selection = row.get("Seleccionado para PDF")
        if isinstance(selection, bool) or type(selection).__name__ == "bool_":
            selection = "Sí" if selection else "No"
        elif selected_codes is not None:
            selection = "Sí" if str(row.get("Código", "")) in selected_codes else "No"
        else:
            selection = "Sin selección informada"
        literal(ws, row_no, colno["Seleccionado para PDF"], selection)
        literal(ws, row_no, colno["Motivo revisión original"], row.get("Motivo revisión", ""))
        literal(ws, row_no, colno["Observaciones originales"], row.get("Observaciones", ""))
        monthly_range = f"{monthly_first}{row_no}:{monthly_last}{row_no}"
        ranks_range = f"{rank_first}{row_no}:{rank_last}{row_no}"
        complete = f"COUNT({monthly_range})={len(months)}"
        total = ref("Total unidades")
        hist = ref("Promedio mensual histórico")
        top_average = ref("Promedio dos mejores meses")
        top_sum = ref("Suma dos mejores meses")
        formula("Total unidades", f'IF({complete},SUM({monthly_range}),"")', row["Ventas meses calculadas"])
        formula("Promedio mensual histórico", f'IF({complete},{total}/{len(months)},"")', row["Demanda mensual promedio"])
        numbers = [number(row.get("Unidades "+m)) for m in months]
        stock_number = number(row.get("Existencia"))
        all_numbers = all(value is not None for value in numbers)
        ranked = sorted(range(len(months)), key=lambda i: (numbers[i], months[i]), reverse=True) if all_numbers else []
        for month_index, month in enumerate(months):
            item = ref("Unidades "+month)
            expr = f'IF({complete},RANK({item},{monthly_range},0)+COUNTIF({item}:{monthly_last}{row_no},{item})-1,"")'
            value = ranked.index(month_index)+1 if ranked else ""
            formula("Orden "+month, expr, value)
        for top in (1, 2):
            # Headers are literal dates; RIGHT extracts AAAA-MM, preserving month identity.
            formula(f"Mes {top} mayor venta", f'IF({complete},RIGHT(INDEX(${monthly_first}$5:${monthly_last}$5,1,MATCH({top},{ranks_range},0)),7),"")', row[f"Mes {top} mayor venta"])
            formula(f"Unidades mes {top}", f'IF({complete},LARGE({monthly_range},{top}),"")', row[f"Unidades mes {top}"])
        formula("Suma dos mejores meses", f'IF({complete},SUM({ref("Unidades mes 1")},{ref("Unidades mes 2")}),"")', row["Suma dos mejores meses"])
        formula("Promedio dos mejores meses", f'IF({complete},{top_sum}/2,"")', row["Promedio dos mejores meses"])
        config_valid = f'AND(COUNT(\'Parámetros\'!$B$5:$B$6)=2,{minimum_cov}>=0,{maximum_cov}>0,{maximum_cov}>={minimum_cov})'
        for suffix, base_name, original in [
            ("promedio histórico", hist, "promedio histórico"),
            ("promedio dos mejores", top_average, "promedio dos mejores"),
            ("suma dos mejores", top_sum, "suma dos mejores"),
        ]:
            for prefix, coverage_ref in [("Mínimo", minimum_cov), ("Máximo", maximum_cov)]:
                name = prefix+" "+suffix
                formula(name, f'IF(AND({complete},{config_valid}),-INT(-ROUND({base_name}*{coverage_ref},10)),"")', row[prefix+" "+original])
        base = ref("Base seleccionada")
        base_expression = f'IF({method}="{labels[0]}",{hist},IF({method}="{labels[1]}",{top_average},IF({method}="{labels[2]}",{top_sum},"")))'
        formula("Base seleccionada", f'IF({complete},{base_expression},"")', row["Base aplicada"])
        for name, coverage_ref, original in [("Mínimo seleccionado", minimum_cov, "Stock Mínimo"), ("Máximo seleccionado", maximum_cov, "Stock Máximo")]:
            formula(name, f'IF(AND(ISNUMBER({base}),{config_valid}),-INT(-ROUND({base}*{coverage_ref},10)),"")', row[original])
        stock, minimum, maximum = ref("Existencia"), ref("Mínimo seleccionado"), ref("Máximo seleccionado")
        plan_valid = f'AND(ISNUMBER({stock}),{stock}>=0,ISNUMBER({maximum}),{maximum}>=0)'
        formula("A pedir", f'IF({plan_valid},MAX({maximum}-{stock},0),"")', row["A pedir"])
        formula("Compra sugerida bajo mínimo", f'IF({plan_valid},IF({stock}<{minimum},{ref("A pedir")},0),"")', row["Compra sugerida bajo mínimo"])
        formula("Sobrestock", f'IF({plan_valid},MAX({stock}-{maximum},0),"")', row["Sobrestock"])
        formula("Diferencia máximo vs histórico", f'IF(AND(ISNUMBER({maximum}),ISNUMBER({ref("Máximo promedio histórico")})),{maximum}-{ref("Máximo promedio histórico")},"")', row["Diferencia máximo vs promedio"])
        formula("Máximo en meses al promedio histórico", f'IF(AND(ISNUMBER({maximum}),ISNUMBER({hist}),{hist}>0),{maximum}/{hist},"")', row["Máximo en meses al promedio histórico"])
        changed = [f'{stock}<>IFERROR(VALUE(\'Fuente PDF\'!{source_map["Existencia"]}{row_no}),"")'] + [f'{ref("Unidades "+m)}<>IFERROR(VALUE(\'Fuente PDF\'!{source_map["Unidades "+m]}{row_no}),"")' for m in months]
        changed += [f"'Parámetros'!$B${r}<>'Parámetros'!$F${r+6}" for r in range(4, 9)]
        method_valid = f'COUNTIF(\'Parámetros\'!$F$4:$F$6,{method})=1'
        validation = (
            f'IF(NOT(AND({config_valid},{method_valid})),"Revisar parámetros",'
            f'IF(NOT({complete}),"Faltan ventas mensuales",'
            f'IF(NOT(AND(ISNUMBER({stock}),{stock}>=0)),"Revisar existencia",'
            f'IF(AND(COUNTIF({monthly_range},"<0")>0,\'Parámetros\'!$B$7<>"Sí"),"Revisar devoluciones",'
            f'IF(OR({base}<0,AND({base}=0,\'Parámetros\'!$B$8<>"Sí")),"Revisar base o límites cero",'
            f'IF({ref("Estado en NEXUS")}<>"Lista","Pendiente en NEXUS",'
            f'IF(OR({",".join(changed)}),"SIMULACIÓN · revisar en NEXUS","Lista")))))))'
        )
        if not all_numbers:
            validation_value = "Faltan ventas mensuales"
        elif stock_number is None or stock_number < 0:
            validation_value = "Revisar existencia"
        elif min(numbers) < 0 and not params.get("review_returns", False):
            validation_value = "Revisar devoluciones"
        elif row["Base aplicada"] < 0 or row["Base aplicada"] == 0 and not params.get("review_zero", False):
            validation_value = "Revisar base o límites cero"
        else:
            validation_value = "Lista" if row["Lista para planilla"] else "Pendiente en NEXUS"
        formula("Validación en Excel", validation, validation_value)
        for col, name in enumerate(columns, 1):
            cell = ws.cell(row_no, col)
            cell.font = Font(name="Calibri", size=10, color=ink)
            cell.border = Border(bottom=border)
            cell.alignment = Alignment(vertical="center", wrap_text=name in {"Motivo revisión original", "Observaciones originales"})
            cell.number_format = "0.00" if "promedio" in name.lower() and not name.startswith(("Mínimo", "Máximo")) or name == "Máximo en meses al promedio histórico" else "0.##"
            if name in {"Código", "Descripción", "Mes 1 mayor venta", "Mes 2 mayor venta", "Validación en Excel", "Estado en NEXUS", "Motivo revisión original", "Observaciones originales"}:
                cell.number_format = "@"
        ws.row_dimensions[row_no].height = 30
    visible_end = colno["Fila PDF"]
    ws.auto_filter.ref = f"A5:{get_column_letter(visible_end)}{len(result)+5}"
    flag = letters["Validación en Excel"]
    ws.conditional_formatting.add(f"{flag}6:{flag}{len(result)+5}", FormulaRule(formula=[f'{flag}6<>"Lista"'], fill=PatternFill("solid", fgColor=amber)))
    ws.print_options.horizontalCentered = True
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    ws.page_setup.orientation = "landscape"
    ws.page_setup.paperSize = ws.PAPERSIZE_A3
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.print_title_rows = "1:5"
    ws.print_area = f"A1:{get_column_letter(visible_end)}{len(result)+5}"
    ws.oddFooter.center.text = "NEXUS · comparación de políticas · &P / &N"
    cached["xl/worksheets/sheet1.xml"] = cached_sheet
    raw = io.BytesIO()
    wb.save(raw)
    return _ranking_excel_cache_v714(raw.getvalue(), cached)


def ranking_signature_v714(value):
    import hashlib
    import json
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True, default=str).encode('utf-8')).hexdigest()


def ranking_month_label_v714(month):
    names = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre']
    return f'{names[int(month[5:7]) - 1]} {month[:4]}'


@st.cache_data(show_spinner=False, max_entries=8)
def cached_ranking_pdf_v714(raw, filename):
    return read_ranking_pdf_v714(raw, filename)


def ranking_plan_v714(result, codes):
    """Only reviewed, selected rows from this PDF; never use a saved inventory."""
    selected = result[result['Código'].isin(codes) & result['Lista para planilla'].eq(True)].copy()
    return selected.rename(columns={'Stock Mínimo': 'Mínimo', 'Stock Máximo': 'Máximo'}).reindex(
        columns=['Código', 'Descripción', 'Existencia', 'Mínimo', 'Máximo', 'A pedir'])


def ranking_selected_codes_v714(codes, eligible_codes):
    """Drop stale widget selections outside the current eligible search result."""
    eligible = set(eligible_codes)
    return list(dict.fromkeys(code for code in (codes or []) if code in eligible))


@st.fragment
def render_ranking_pdf_v714():
    st.header('Ranking mensual A2 · calcular desde un PDF')
    if st.button('Planificar con entrega, frecuencia de compra y reserva', key='v712r_from_ranking'):
        move_current_pdf_v713('v714_ranking_upload', 'Reposición por proveedor')
    st.caption('Sube el ranking con ventas separadas por mes y existencia. Todo este análisis usa ese archivo: no suma, completa ni guarda productos en la base NEXUS.')
    st.markdown('<div class="nexus-workflow"><div><b>01 · Subir ranking</b><span>Un PDF con sus meses y existencias</span></div><div><b>02 · Elegir fórmula</b><span>Histórico o dos mejores meses</span></div><div><b>03 · Comparar</b><span>Ver el cambio por producto</span></div><div><b>04 · Descargar</b><span>Planilla A2 + Excel formulado</span></div></div>', unsafe_allow_html=True)
    with st.expander('Entender las fórmulas · el ejemplo 462 y 329'):
        st.markdown('**462 + 329 × 2 = 1.120**: primero se multiplica 329.\n\n**(462 + 329) × 2 = 1.582**: primero se suman los dos meses.\n\n**((462 + 329) ÷ 2) × 2 = 791**: se obtiene su promedio mensual y se cubren dos meses.\n\nLa primera expresión es una regla distinta; no se aplica automáticamente como política de stock. Selecciona abajo la fórmula que hayas acordado. Para usar los dos meses como promedio de demanda, elige **Promedio de los dos meses con más ventas**.')
        st.caption('Los dos mejores meses se eligen por UNIDADES para cada código por separado. No se utilizan los montos de dinero ni se eligen dos meses iguales para toda la empresa. Los mínimos y máximos se redondean hacia arriba a unidades enteras.')
    st.info("Este recorrido histórico usa solo el PDF. Para incluir TODOS los códigos del proveedor, usa Proveedor completo · máximos y mínimos.")
    if st.button("Cruzar inventario completo, ventas y planilla anterior", key="v714_go_complete"):
        _navigation_v7("Proveedor completo · máximos y mínimos")
    upload = workflow_upload_v713('Subir ranking comparativo de ventas A2 · PDF', type=['pdf'], key='v714_ranking_upload')
    if upload is None:
        st.info('Empieza aquí: sube «ranking venta web 6 meses». Este recorrido no necesita inventario adicional ni CxC cuando el PDF ya incluye existencias.')
        st.session_state.pop('v714_ranking_calculation', None)
        st.session_state.pop('v714_ranking_exports', None)
        return
    raw = upload.getvalue()
    try:
        with st.spinner('Leyendo productos, meses y existencias del PDF…'):
            parsed = cached_ranking_pdf_v714(raw, upload.name)
    except Exception as exc:
        st.session_state.pop('v714_ranking_calculation', None)
        st.session_state.pop('v714_ranking_exports', None)
        st.error(f'No se pudo leer este ranking: {exc}')
        st.caption('Se requiere el ranking comparativo de A2 con columnas mensuales; un PDF escaneado o un total acumulado no permite recuperar ventas mensuales ausentes.')
        return
    data, source = parsed['data'], parsed['metadata']
    sid = source['sha256'][:14]
    periods = source['periods']
    k = lambda label: 'v714_' + label + '_' + sid
    st.subheader('1 · Fuente y parámetros')
    a, b, c = st.columns(3)
    a.metric('Productos en este PDF', f'{len(data):,}')
    b.metric('Meses disponibles', len(periods))
    c.metric('Unidades del historial completo', f"{source.get('total_units', 0):,.0f}")
    st.caption(f"Empresa impresa: {source.get('company', 'No indicada')} · Grupo: {source.get('department', 'No indicado')} · Emisión del reporte: {source.get('report_date_text', 'No indicada')} {source.get('report_time', '')}.")
    st.caption('Es un ranking de productos vendidos: no garantiza incluir productos sin ventas ni todo el catálogo. La existencia se toma tal como está impresa; la fecha de generación de la nueva planilla no actualiza ese inventario.')
    for warning in source.get('global_warnings', []):
        st.warning(str(warning))
    columns = st.columns([1, 2])
    suggested = SEDES.index('Matriz Makropetrol') if 'MAKROPETROL' in source.get('company', '').upper() else None
    site = columns[0].selectbox('Sede a la que pertenece este PDF', SEDES, index=suggested, placeholder='Selecciona la sede', key=k('site'))
    window = columns[1].select_slider('Meses del ranking que se usarán', options=periods,
                                     value=(periods[0], periods[-1]), format_func=ranking_month_label_v714, key=k('window'))
    months = [month for month in periods if window[0] <= month <= window[1]]
    from datetime import datetime, timezone, timedelta
    today_caracas = datetime.now(timezone(timedelta(hours=-4))).date().isoformat()
    selected_periods = [item for item in source.get('months', []) if item['period'] in months]
    incomplete = any(not item.get('full_month') for item in selected_periods)
    future = any(item.get('to', '') > today_caracas for item in selected_periods)
    if incomplete:
        st.error('El intervalo seleccionado incluye meses parciales. Elige meses completos o vuelve a exportar esos períodos de principio a fin.')
    if future:
        st.error('Hay fechas futuras en los meses seleccionados. Revisa el año y los períodos en A2; no se cambia la fecha del archivo automáticamente.')
    policy = st.selectbox('Fórmula que quieres aplicar', list(RANKING_POLICIES_V714), index=None,
                          format_func=lambda item: RANKING_POLICIES_V714[item], placeholder='Elige la regla acordada antes de calcular', key=k('policy'))
    formulas = {
        'promedio_historico': 'Base mensual = suma de unidades de los meses seleccionados ÷ número de meses.',
        'promedio_dos_mejores': 'Base mensual = (unidades del mejor mes + unidades del segundo mejor mes) ÷ 2.',
        'suma_dos_mejores': 'Base = unidades del mejor mes + unidades del segundo mejor mes. No se divide entre 2.',
    }
    if policy:
        st.info(formulas[policy])
    if policy == 'suma_dos_mejores':
        st.warning('Esta base contiene DOS meses de ventas. Multiplicarla por 2 equivale a cuatro meses al promedio de esos dos mejores meses. Los factores 1 y 2 duplican los límites de la política que usa su promedio, salvo redondeo.')
    c1, c2 = st.columns(2)
    factor_word = 'Factor' if policy == 'suma_dos_mejores' else 'Cobertura'
    low = c1.number_input(f'{factor_word} mínimo', min_value=0.0, max_value=12.0, value=1.0, step=0.5, key=k('low'))
    high = c2.number_input(f'{factor_word} máximo', min_value=0.5, max_value=12.0, value=2.0, step=0.5, key=k('high'))
    st.caption('Mínimo = base × valor mínimo. Máximo = base × valor máximo. La cobertura expresa meses cuando la base es un promedio mensual; con la suma se muestra como factor para no confundir ambas cosas.')
    with st.expander('Revisar ajustes del reporte y datos originales'):
        st.caption('Un valor negativo puede corresponder a devoluciones o ajustes en A2. No se elimina ni se convierte en cero. Una existencia negativa queda pendiente de corrección en el origen.')
        returns_reviewed = st.checkbox('Revisé las ventas netas negativas y quiero conservarlas en el cálculo', key=k('returns'))
        zero_reviewed = st.checkbox('Revisé los productos sin demanda y admito una propuesta de límites cero', key=k('zero'))
        st.dataframe(data, hide_index=True, width='stretch', height=280)
    config = {'source_sha256': source['sha256'], 'Sede': site, 'months': months, 'policy': policy,
              'min_coverage': low, 'max_coverage': high, 'review_returns': returns_reviewed, 'review_zero': zero_reviewed}
    signature = ranking_signature_v714(config)
    saved = st.session_state.get('v714_ranking_calculation')
    if saved and saved.get('signature') != signature:
        st.session_state.pop('v714_ranking_calculation', None)
        st.session_state.pop('v714_ranking_exports', None)
        saved = None
    invalid = not site or not policy or low > high or len(months) < 2 or incomplete or future
    if low > high:
        st.error('El mínimo no puede superar el máximo.')
    if len(months) < 2:
        st.info('Selecciona al menos dos meses completos consecutivos.')
    if st.button('Calcular y comparar las tres políticas', type='primary', key=k('calculate'), disabled=invalid):
        try:
            result = evaluate_ranking_policies_v714(data, months, low, high, policy, returns_reviewed, zero_reviewed)
            st.session_state['v714_ranking_calculation'] = {'signature': signature, 'result': result}
            st.session_state.pop('v714_ranking_exports', None)
            saved = st.session_state['v714_ranking_calculation']
        except Exception as exc:
            st.error(f'No se pudo calcular: {exc}')
            return
    if not saved or saved.get('signature') != signature:
        st.caption('Elige la fórmula y pulsa Calcular. Al cambiar el archivo, los meses, la sede o los parámetros, se retira el resultado anterior para evitar descargas desactualizadas.')
        return
    result = saved['result']
    st.subheader('2 · Revisar la propuesta')
    ready = result[result['Lista para planilla'].eq(True)]
    pending = result[~result['Lista para planilla'].eq(True)]
    m1, m2, m3 = st.columns(3)
    m1.metric('Listos para planilla', len(ready))
    m2.metric('Pendientes de revisión', len(pending))
    m3.metric('Meses usados por producto', len(months))
    st.caption(f"{RANKING_POLICIES_V714[policy]} · {ranking_month_label_v714(months[0])} a {ranking_month_label_v714(months[-1])} · mínimo {low:g} / máximo {high:g}. No se han agregado productos de otra fuente.")
    query = st.text_input('Buscar código o descripción para revisar o exportar un grupo', key=k('search'))
    mask = (result['Código'].astype(str).str.contains(query.strip(), case=False, regex=False, na=False)
            | result['Descripción'].astype(str).str.contains(query.strip(), case=False, regex=False, na=False))
    visible = result[mask].copy()
    table_cols = ['Código', 'Descripción', 'Existencia', 'Ventas meses calculadas', 'Demanda mensual promedio',
                  'Mes 1 mayor venta', 'Unidades mes 1', 'Mes 2 mayor venta', 'Unidades mes 2',
                  'Mínimo promedio histórico', 'Máximo promedio histórico', 'Mínimo promedio dos mejores', 'Máximo promedio dos mejores',
                  'Mínimo suma dos mejores', 'Máximo suma dos mejores', 'Stock Mínimo', 'Stock Máximo', 'A pedir', 'Estado propuesta']
    st.dataframe(visible[['Código', 'Descripción', 'Existencia', 'Stock Mínimo', 'Stock Máximo', 'A pedir', 'Estado propuesta']],
                 hide_index=True, width='stretch', height=350)
    with st.expander('Comparar las tres políticas y ver los dos meses elegidos por producto'):
        if not visible.empty:
            example_code = st.selectbox('Producto para explicar el cálculo', visible['Código'].tolist(), key=k('example'))
            sample = visible[visible['Código'].eq(example_code)].iloc[0]
            st.caption(f"{sample['Mes 1 mayor venta']}: {sample['Unidades mes 1']:g} unidades · {sample['Mes 2 mayor venta']}: {sample['Unidades mes 2']:g} unidades. Cada producto utiliza sus propios dos mejores meses.")
            example = pd.DataFrame([
                {'Método': 'Promedio de todos los meses', 'Base': sample['Demanda mensual promedio'], 'Mínimo': sample['Mínimo promedio histórico'], 'Máximo': sample['Máximo promedio histórico']},
                {'Método': 'Promedio de los dos mejores', 'Base': sample['Promedio dos mejores meses'], 'Mínimo': sample['Mínimo promedio dos mejores'], 'Máximo': sample['Máximo promedio dos mejores']},
                {'Método': 'Suma de los dos mejores', 'Base': sample['Suma dos mejores meses'], 'Mínimo': sample['Mínimo suma dos mejores'], 'Máximo': sample['Máximo suma dos mejores']},
            ])
            st.dataframe(example, hide_index=True, width='stretch', column_config={'Base': st.column_config.NumberColumn(format='%.2f')})
        st.dataframe(visible[table_cols], hide_index=True, width='stretch', height=280,
                     column_config={'Demanda mensual promedio': st.column_config.NumberColumn(format='%.2f')})
    st.caption('A pedir = máximo − existencia, sin valores negativos. Es completar al máximo; la compra por punto de reorden sólo se activa si la existencia está por debajo del mínimo. No se descuentan pedidos en tránsito ni traslados: el PDF no informa esos datos ni costos de compra.')
    if not pending.empty:
        with st.expander(f'{len(pending)} productos pendientes · se conservan en el Excel, fuera de la planilla de carga'):
            st.dataframe(pending[['Código', 'Descripción', 'Existencia', 'Motivo revisión']], hide_index=True, width='stretch')
    if len(months) >= 4:
        with st.expander('¿Qué regla se acercó más a los últimos meses? · prueba orientativa'):
            summary, detail, retrospective = evaluate_ranking_backtest_v714(data, months)
            st.caption('Se calculan las bases con todos los meses seleccionados excepto los dos últimos. Se estiman esos dos últimos y se comparan con sus ventas reales; no se usan para elegir los mejores meses del entrenamiento.')
            st.dataframe(summary, hide_index=True, width='stretch',
                         column_config={col: st.column_config.NumberColumn(format='%.2f') for col in summary.select_dtypes(include='number').columns})
            st.caption('Esta única ventana compara unidades vendidas, no demuestra qué política minimiza faltantes, costo o sobrestock. Las ventas pueden estar limitadas por falta de mercancía; para decidir también hacen falta disponibilidad, tiempos de entrega y nivel de servicio. La suma es una reserva elegida, no un promedio mensual.')
            st.caption(f"Meses para calcular: {', '.join(months[:-2])}. Meses para comprobar: {', '.join(months[-2:])}.")
    st.subheader('3 · Elegir productos y descargar')
    eligible = visible[visible['Lista para planilla'].eq(True)]
    select_all = st.checkbox('Incluir todos los productos listos de la búsqueda actual', value=True, key=k('all'))
    eligible_codes = eligible['Código'].tolist()
    if select_all:
        codes = eligible_codes
    else:
        code_key = k('codes')
        if code_key in st.session_state:
            st.session_state[code_key] = ranking_selected_codes_v714(st.session_state[code_key], eligible_codes)
        codes = st.multiselect('Códigos para la planilla', eligible_codes, key=code_key)
        codes = ranking_selected_codes_v714(codes, eligible_codes)
    plan = ranking_plan_v714(result, codes)
    with st.expander('Encabezado de la planilla · sede, grupo y etiquetas', expanded=False):
        title = st.text_input('Nombre de la sede en el encabezado', value=source.get('company', '') if site == 'Matriz Makropetrol' else site,
                              key=k('title_' + str(site)))
        department = st.text_input('Departamento / grupo', value=source.get('department', ''), key=k('department'))
        a, b, c = st.columns(3)
        brand = a.text_input('Marca · etiqueta opcional', key=k('brand'))
        supplier = b.text_input('Proveedor · etiqueta opcional', key=k('supplier'))
        kind = c.text_input('Tipo de producto · etiqueta opcional', key=k('kind'))
        factor = st.text_input('Otro factor para el encabezado', key=k('factor'))
        st.caption('Estas etiquetas sólo cambian el encabezado. Para escoger los productos utiliza la búsqueda o los códigos de arriba. No se completa proveedor ni marca con datos inventados.')
    st.caption(f'{len(plan)} productos seleccionados para la planilla PDF y Excel de {site}. La comparación Excel incluye los {len(result)} productos del ranking, sus cálculos, pendientes y fuente; identifica cuáles elegiste para la planilla.')
    export_meta = {**source, **config, 'Versión NEXUS': APP_VERSION, 'Título encabezado': title,
                   'Departamento encabezado': department, 'Marca': brand, 'Proveedor': supplier, 'Tipo de producto': kind,
                   'Factor libre': factor or (RANKING_POLICIES_V714[policy] + f' · {low:g}/{high:g}'),
                   'Ajustar paginación': True, 'selected_codes': list(codes), 'database_used': False,
                   'source': 'Solo PDF cargado', 'Origen de los límites': RANKING_POLICIES_V714[policy]}
    export_signature = ranking_signature_v714({'calculation': signature, 'metadata': export_meta, 'codes': codes})
    exports = st.session_state.get('v714_ranking_exports')
    if exports and exports.get('signature') != export_signature:
        st.session_state.pop('v714_ranking_exports', None)
        exports = None
    if st.button('Preparar planilla PDF + Excel y comparación', type='primary', key=k('prepare'), disabled=not title.strip() or not department.strip()):
        export_meta.update(_mm_generation_metadata_v711())
        package = {'signature': export_signature, 'metadata': export_meta, 'errors': []}
        output = result.copy()
        output.attrs.update(result.attrs)
        output['Seleccionado para PDF'] = output['Código'].isin(codes) & output['Lista para planilla'].eq(True)
        with st.spinner('Preparando las descargas…'):
            try:
                package['excel'] = build_ranking_excel_v714(output, export_meta, months)
            except Exception as exc:
                package['errors'].append('Excel: ' + str(exc))
            if not plan.empty:
                try:
                    package['pdf'] = build_minmax_original_pdf_v710(builtin_a2_template_v712(), plan, export_meta)
                except Exception as exc:
                    package['errors'].append('PDF: ' + str(exc))
                try:
                    package['planilla_excel'] = build_minmax_planilla_excel_v713(plan, export_meta, builtin_a2_template_v712())
                except Exception as exc:
                    package['errors'].append('Planilla Excel: ' + str(exc))
        st.session_state['v714_ranking_exports'] = package
        exports = package
    if exports and exports.get('signature') == export_signature:
        for error in exports.get('errors', []):
            st.error(error)
        a, planilla_column, b = st.columns(3)
        stem = 'Ranking_NEXUS_' + safe_slug(site) + '_' + str(months[0]) + '_' + str(months[-1])
        if exports.get('pdf'):
            a.download_button('Descargar planilla A2 · PDF', exports['pdf'], stem + '_planilla.pdf', 'application/pdf', key=k('download_pdf'), on_click='ignore', width='stretch')
        if exports.get('excel'):
            b.download_button('Descargar comparación · Excel formulado', exports['excel'], stem + '_comparacion.xlsx', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', key=k('download_excel'), on_click='ignore', width='stretch')
        if exports.get('planilla_excel'):
            planilla_column.download_button('Descargar planilla A2 · Excel', exports['planilla_excel'], stem + '_planilla.xlsx', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', key=k('download_planilla_excel'), on_click='ignore', width='stretch')
        if plan.empty:
            st.info('La comparación Excel sigue disponible. Selecciona al menos un producto listo para generar la planilla en PDF y Excel.')
        st.caption('Planilla A2: seis columnas y mismos valores en PDF y Excel, con diseño adaptado para imprimir desde Excel. Comparación: fórmulas para revisar escenarios. Editar cualquiera de los Excel no actualiza el PDF ni la base NEXUS. Ninguna descarga registra movimientos en A2.')


def replenishment_config_v712(config):
    """Validate explicit assumptions; never retrieve inventory or supplier data."""
    import math
    defaults = dict(method='promedio', lead_days=7, cycle_days=60, buffer_days=7,
                    safety_mode='dias', service_level=95.0, adjustment=1.0,
                    order_mode='programada', review_returns=False, review_zero=False)
    c = {**defaults, **dict(config)}
    for name, low, high in [('lead_days', 0, 365), ('cycle_days', 1, 365), ('buffer_days', 0, 180),
                            ('service_level', 50.01, 99.9), ('adjustment', 0, 5)]:
        try:
            n = float(c[name])
        except (TypeError, ValueError):
            raise ValueError('Completa el parámetro: ' + name)
        if not math.isfinite(n) or not low <= n <= high:
            raise ValueError(f'{name}: valor fuera de rango ({low} a {high}).')
        c[name] = n
    if c['method'] not in {'promedio', 'ponderado'}:
        raise ValueError('Método de demanda no reconocido.')
    if c['safety_mode'] not in {'dias', 'estadistica'} or c['order_mode'] not in {'programada', 'minimo'}:
        raise ValueError('Política de seguridad o compra no reconocida.')
    if c['safety_mode'] == 'estadistica' and (c['method'] != 'promedio' or c['adjustment'] != 1):
        raise ValueError('La aproximación estadística requiere promedio simple sin factor; con tendencia o campañas usa una reserva explícita en días.')
    return c


def evaluate_replenishment_v712(data, months, config, excluded_months=None):
    """Periodic order-up-to target S plus a lead-time reorder alert r.

    In scheduled mode Q reaches S at each review. In minimum mode Q is triggered
    only when inventory position <= r. Monthly-to-daily convention: 30 days.
    Statistical buffers assume stationary independent monthly demand, fixed lead
    time and normal aggregation; service % is a model input, never a guarantee.
    """
    import math
    from statistics import NormalDist
    import numpy as np
    import pandas as pd
    c = replenishment_config_v712(config)
    months = ranking_months_v714(data, months)
    excluded = set(excluded_months or [])
    if not excluded.issubset(set(months)):
        raise ValueError('Se intentó excluir un mes que no pertenece al intervalo.')
    used = [m for m in months if m not in excluded]
    if len(used) < 2:
        raise ValueError('Conserva al menos dos meses completos; excluir un mes no equivale a ventas cero.')
    if c['safety_mode'] == 'estadistica' and len(used) < 12:
        raise ValueError('Para esta aproximación estadística se requieren al menos 12 meses; con seis meses utiliza reserva en días.')
    # Reuse source identity and reconciliation checks over the whole chosen range.
    checked = evaluate_ranking_policies_v714(data, months, 1, 2, 'promedio_historico',
                                             bool(c['review_returns']), bool(c['review_zero']))
    out = checked.copy(deep=True)
    values = []
    for _, row in out.iterrows():
        reasons = [str(row['Motivo revisión'])] if row['Motivo revisión'] else []
        notes = []
        q = np.array([_ranking_policy_number_v714(row['Unidades ' + m]) for m in used], dtype=float)
        complete = np.isfinite(q).all()
        base = float(np.average(q, weights=range(1, len(q)+1))) if complete and c['method'] == 'ponderado' else (float(q.mean()) if complete else np.nan)
        demand = base * c['adjustment']
        daily = demand / 30
        sigma = float(np.std(q, ddof=1)) if complete else np.nan
        if np.isfinite(demand) and demand < 0:
            reasons.append('Demanda ajustada negativa')
        if np.isfinite(demand) and demand == 0 and not c['review_zero']:
            reasons.append('Demanda ajustada cero: revisar límites')
        if any(q == 0):
            notes.append('Hay meses con cero ventas: revisar falta de stock o demanda intermitente')
        if c['safety_mode'] == 'estadistica':
            if (q < 0).any():
                reasons.append('Ventas negativas incompatibles con esta aproximación estadística')
            z = NormalDist().inv_cdf(c['service_level'] / 100)
            safety_min = z * sigma * math.sqrt(c['lead_days'] / 30)
            safety_max = z * sigma * math.sqrt((c['lead_days'] + c['cycle_days']) / 30)
            notes.append('Nivel de servicio aproximado bajo demanda estacionaria, períodos independientes y plazo fijo; no garantiza disponibilidad')
        else:
            safety_min = safety_max = daily * c['buffer_days']
        minimum = _ranking_ceil_v714(daily * c['lead_days'] + safety_min)
        maximum = _ranking_ceil_v714(daily * (c['lead_days'] + c['cycle_days']) + safety_max)
        stock = _ranking_policy_number_v714(row['Existencia'])
        inputs = {}
        for column, default in [('En tránsito', 0), ('Comprometido', 0), ('Lote compra', 1), ('Mínimo proveedor', 0)]:
            v = _ranking_policy_number_v714(row.get(column, default))
            if not np.isfinite(v) or v < 0 or (column == 'Lote compra' and (v < 1 or v != int(v))):
                reasons.append('Revisar ' + column)
            inputs[column] = v
        position = stock + inputs['En tránsito'] - inputs['Comprometido']
        valid = all(np.isfinite(v) for v in [minimum, maximum, position, *inputs.values()]) and minimum >= 0 and maximum >= minimum and stock >= 0 and inputs['Lote compra'] >= 1
        gap = max(maximum - position, 0) if valid else np.nan
        triggered = c['order_mode'] == 'programada' or (valid and position <= minimum)
        raw_order = gap if triggered else (0.0 if valid else np.nan)
        order = (_ranking_ceil_v714(max(raw_order, inputs['Mínimo proveedor']) / inputs['Lote compra']) * inputs['Lote compra']
                 if valid and raw_order > 0 else (0.0 if valid else np.nan))
        reasons = list(dict.fromkeys(reasons))
        values.append({**inputs, 'Base mensual': base, 'Demanda ajustada mensual': demand, 'Demanda diaria planificada': daily,
                       'Desviación mensual': sigma, 'Reserva al pedir': safety_min, 'Reserva objetivo': safety_max,
                       'Mínimo anterior cobertura 1 mes': row['Stock Mínimo'], 'Máximo anterior cobertura 2 meses': row['Stock Máximo'],
                       'Stock Mínimo': minimum, 'Stock Máximo': maximum, 'Punto de pedido': minimum,
                       'Posición inventario': position, 'Necesidad hasta objetivo': gap, 'A pedir': order,
                       'Exceso por lote': max(order-gap, 0) if valid else np.nan,
                       'Estado propuesta': 'Pendiente de revisión' if reasons else 'Lista',
                       'Lista para planilla': not reasons, 'Motivo revisión': ' · '.join(reasons), 'Notas reposición': ' · '.join(notes)})
    for column in values[0] if values else []:
        out[column] = [r[column] for r in values]
    out.attrs.update(dict(replenishment_config=c, months=months, used_months=used, excluded_months=sorted(excluded),
                          source='Solo PDF y datos operativos introducidos en esta pantalla', database_used=False))
    return out


def build_replenishment_excel_v712(result, source, metadata):
    """Live monthly/input formulas plus immutable original source and initial values."""
    import io
    import json
    import pandas as pd
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter as letter
    from openpyxl.workbook.properties import CalcProperties
    c = replenishment_config_v712(result.attrs['replenishment_config'])
    used = result.attrs['used_months']
    wb = Workbook()
    ws = wb.active
    ws.title = 'Reposición'
    settings = wb.create_sheet('Parámetros')
    original = wb.create_sheet('Fuente PDF')
    initial = wb.create_sheet('Propuesta original')
    wb.calculation = CalcProperties(calcMode='auto', fullCalcOnLoad=True, forceFullCalc=True)
    def put(sheet, r, col, value):
        _ranking_excel_value_v714(sheet.cell(r, col), value)
    params = [('Método (promedio/ponderado)', c['method']), ('Entrega proveedor (días)', c['lead_days']),
              ('Frecuencia de compra (días)', c['cycle_days']), ('Reserva manual (días)', c['buffer_days']),
              ('Seguridad (dias/estadistica)', c['safety_mode']), ('Servicio objetivo (%)', c['service_level']),
              ('Factor de demanda', c['adjustment']), ('Compra (programada/minimo)', c['order_mode'])]
    for r, (label, value) in enumerate(params, 2):
        put(settings, r, 1, label); put(settings, r, 2, value)
        settings.cell(r, 2).fill = PatternFill('solid', fgColor='DBEAFE')
    from openpyxl.worksheet.datavalidation import DataValidation
    for cell,options in [('B2','promedio,ponderado'),('B6','dias,estadistica'),('B9','programada,minimo')]:
        validation=DataValidation(type='list',formula1='"'+options+'"')
        validation.showErrorMessage=True;validation.error='Elige una opción de la lista.';validation.errorStyle='stop'
        settings.add_data_validation(validation);validation.add(cell)
    extra = [('Sede', metadata.get('Sede', '')), ('Proveedor/grupo', metadata.get('Proveedor', '')),
             ('Meses usados', ', '.join(used)), ('Meses excluidos', ', '.join(result.attrs['excluded_months'])),
             ('Fecha generación', metadata.get('Generado ISO', '')), ('Fuente', metadata.get('filename', '')),
             ('Supuestos', 'Mes=30 días. Plazo fijo. Mínimo=punto de pedido. Máximo=objetivo de posición, incluye entrega + ciclo + reserva.'),
             ('Servicio', 'Probabilidad de ciclo aproximada, no fill rate ni garantía. Estadística requiere >=12 meses, promedio sin factor.'),
             ('Límites del historial', 'Ventas pueden subestimar demanda durante quiebres. Seis meses no prueban estacionalidad anual.'),
             ('Edición', 'Cambiar datos o parámetros recalcula Excel; revisar como simulación. No modifica PDF, NEXUS o A2.'),
             ('Metadatos', json.dumps(metadata, ensure_ascii=False, default=str)[:30000])]
    for r, (label, value) in enumerate(extra, 12):
        put(settings, r, 1, label); put(settings, r, 2, value)
    settings.column_dimensions['A'].width=36
    settings.column_dimensions['B'].width=100
    for row in settings:
        for cell in row: cell.alignment=Alignment(wrap_text=True, vertical='top')
    cols = ['Código','Descripción','Existencia','En tránsito','Comprometido','Lote compra','Mínimo proveedor',
            *['Unidades '+m for m in used], 'Base mensual','Demanda ajustada mensual','Desviación mensual','Reserva al pedir','Reserva objetivo',
            'Stock Mínimo','Stock Máximo','Posición inventario','Necesidad hasta objetivo','A pedir','Exceso por lote',
            'Mínimo anterior cobertura 1 mes','Máximo anterior cobertura 2 meses','Estado original','Revisión / simulación']
    idx={name:letter(i) for i,name in enumerate(cols,1)}
    for i,col in enumerate(cols,1): put(ws,1,i,col)
    cached={}
    param='\'Parámetros\'!'
    p=lambda row:f'{param}$B${row}'
    config_ok=f'AND(OR({p(2)}="promedio",{p(2)}="ponderado"),COUNT({p(3)}:{p(5)})=3,{p(3)}>=0,{p(3)}<=365,{p(4)}>=1,{p(4)}<=365,{p(5)}>=0,{p(5)}<=180,ISNUMBER({p(7)}),{p(7)}>50,{p(7)}<100,ISNUMBER({p(8)}),{p(8)}>=0,{p(8)}<=5,OR({p(6)}="dias",AND({p(6)}="estadistica",{len(used)}>=12,{p(2)}="promedio",{p(8)}=1)),OR({p(9)}="programada",{p(9)}="minimo"))'
    for r, row in enumerate(result.to_dict('records'),2):
        ref=lambda name:idx[name]+str(r)
        inputs=[ref('Unidades '+m) for m in used]
        rng=inputs[0]+':'+inputs[-1]
        complete=f'COUNT({rng})={len(used)}'
        positive=f'MIN({rng})>=0'
        weighted='+'.join(f'{i}*{value}' for i,value in enumerate(inputs,1))
        formulas={
            'Base mensual':f'IF({p(2)}="ponderado",({weighted})/{len(used)*(len(used)+1)/2},AVERAGE({rng}))',
            'Demanda ajustada mensual':f'{ref("Base mensual")}*{p(8)}',
            'Desviación mensual':f'STDEV({rng})',
            'Reserva al pedir':f'IF({p(6)}="dias",{ref("Demanda ajustada mensual")}/30*{p(5)},NORMSINV({p(7)}/100)*{ref("Desviación mensual")}*SQRT({p(3)}/30))',
            'Reserva objetivo':f'IF({p(6)}="dias",{ref("Reserva al pedir")},NORMSINV({p(7)}/100)*{ref("Desviación mensual")}*SQRT(({p(3)}+{p(4)})/30))',
            'Stock Mínimo':f'ROUNDUP(ROUND({ref("Demanda ajustada mensual")}/30*{p(3)}+{ref("Reserva al pedir")},10),0)',
            'Stock Máximo':f'ROUNDUP(ROUND({ref("Demanda ajustada mensual")}/30*({p(3)}+{p(4)})+{ref("Reserva objetivo")},10),0)',
            'Posición inventario':f'{ref("Existencia")}+{ref("En tránsito")}-{ref("Comprometido")}',
            'Necesidad hasta objetivo':f'MAX({ref("Stock Máximo")}-{ref("Posición inventario")},0)',
            'A pedir':f'IF(OR({p(9)}="programada",{ref("Posición inventario")}<={ref("Stock Mínimo")}),IF({ref("Necesidad hasta objetivo")}>0,ROUNDUP(ROUND(MAX({ref("Necesidad hasta objetivo")},{ref("Mínimo proveedor")})/{ref("Lote compra")},10),0)*{ref("Lote compra")},0),0)',
            'Exceso por lote':f'MAX({ref("A pedir")}-{ref("Necesidad hasta objetivo")},0)',
        }
        all_ok=f'AND({config_ok},{complete},IF({p(2)}="ponderado",({weighted})/{len(used)*(len(used)+1)/2},AVERAGE({rng}))>=0,COUNT(C{r}:G{r})=5,C{r}>=0,D{r}>=0,E{r}>=0,F{r}>=1,MOD(F{r},1)=0,G{r}>=0,OR({p(6)}="dias",{positive}))'
        numeric=lambda v: isinstance(v,(int,float)) and pd.notna(v)
        cache_ok=(all(numeric(row.get('Unidades '+m)) for m in used)
                  and all(numeric(row.get(col)) and row[col]>=0 for col in ['Existencia','En tránsito','Comprometido','Lote compra','Mínimo proveedor'])
                  and row['Lote compra']>=1 and float(row['Lote compra']).is_integer()
                  and numeric(row.get('Base mensual')) and row['Base mensual']>=0
                  and (c['safety_mode']=='dias' or all(row['Unidades '+m]>=0 for m in used)))
        for i,col in enumerate(cols,1):
            cell=ws.cell(r,i)
            if col in formulas:
                cell.value=f'=IFERROR(IF({all_ok},{formulas[col]},"REVISAR"),"REVISAR")'
                cached[cell.coordinate]=row.get(col) if cache_ok else 'REVISAR'
            elif col=='Estado original': put(ws,r,i,row.get('Estado propuesta'))
            elif col=='Revisión / simulación':
                put(ws,r,i,'SIMULACIÓN al editar. '+str(row.get('Motivo revisión') or 'Propuesta original lista; confirmar datos operativos.'))
            else: put(ws,r,i,row.get(col))
            cell.number_format='0.00' if col in {'Base mensual','Demanda ajustada mensual','Desviación mensual','Reserva al pedir','Reserva objetivo'} else '0.##'
            if 3<=i<=7+len(used):cell.fill=PatternFill('solid',fgColor='DBEAFE')
    for sheet,frame in [(original,source),(initial,result)]:
        for i,col in enumerate(frame.columns,1):put(sheet,1,i,col)
        for r,record in enumerate(frame.to_dict('records'),2):
            for i,col in enumerate(frame.columns,1):put(sheet,r,i,record.get(col))
    for sheet in [ws,original,initial]:
        sheet.freeze_panes='C2'
        sheet.auto_filter.ref=sheet.dimensions
        sheet.sheet_view.showGridLines=False
        sheet.row_dimensions[1].height=42
        for cell in sheet[1]:
            cell.fill=PatternFill('solid',fgColor='147D78');cell.font=Font(color='FFFFFF',bold=True);cell.alignment=Alignment(wrap_text=True)
            sheet.column_dimensions[cell.column_letter].width=19
        sheet.column_dimensions['B'].width=46
    stream=io.BytesIO();wb.save(stream)
    return _ranking_excel_cache_v714(stream.getvalue(),{'xl/worksheets/sheet1.xml':cached})


def load_replenishment_profiles_v712(path):
    import json
    from pathlib import Path
    p=Path(path)
    if not p.exists():return {}
    value=json.loads(p.read_text(encoding='utf-8'))
    if not isinstance(value,dict):raise ValueError('Archivo de perfiles inválido.')
    return value


def save_replenishment_profile_v712(path, name, config):
    import json, os, tempfile
    from pathlib import Path
    if not str(name).strip():raise ValueError('Escribe un nombre para guardar el perfil.')
    c=replenishment_config_v712(config)
    p=Path(path)
    profiles=load_replenishment_profiles_v712(p)
    profiles[str(name).strip()]=c
    fd,temp=tempfile.mkstemp(prefix='nexus_reposicion_',suffix='.tmp',dir=p.parent)
    try:
        with os.fdopen(fd,'w',encoding='utf-8') as f:json.dump(profiles,f,ensure_ascii=False,indent=2)
        os.replace(temp,p)
    finally:
        if os.path.exists(temp):os.unlink(temp)


@st.fragment
def render_replenishment_v712():
    st.header('Reposición por proveedor')
    st.caption('Planifica cuándo pedir y cuánto comprar con el ranking mensual A2. Esta sección usa sólo el PDF cargado y los datos operativos que introduzcas; no mezcla inventarios guardados.')
    with st.expander('Guía · mínimo, máximo y seguridad son cosas diferentes', expanded=False):
        st.markdown('**Stock de seguridad:** reserva para incertidumbre.\n\n**Mínimo / punto de pedido:** demanda durante la entrega + reserva de ese plazo.\n\n**Máximo / objetivo de posición:** demanda durante entrega + intervalo entre compras + reserva correspondiente. La posición es existencia + pedidos confirmados en tránsito − unidades comprometidas.\n\n**Compra programada:** completar ese objetivo en la fecha de compra. **Sólo bajo mínimo:** proponer compra cuando la posición llega al punto de pedido. El mínimo sirve de alerta entre revisiones; no es una orden de esperar si hoy corresponde una compra programada.')
        st.info('Ejemplo: demanda 20 unidades/mes, proveedor 15 días, compras cada 60 días y reserva de 15 días. Reserva = 10; mínimo = 20; máximo = 60. El máximo incluye plazo y reserva, por eso no equivale sólo a 2 meses de ventas.')
        st.caption('La conversión operativa utiliza meses de 30 días. Las fórmulas describen una política, no garantizan evitar todo faltante o sobrante. La planilla A2 conserva sus seis columnas; en este modo A pedir ya descuenta tránsito y comprometidos, y respeta el lote mínimo.')
        st.markdown('**Estacionalidad:** comparar el mismo mes del año anterior es una alternativa, no una obligación. Con seis meses no se puede comprobar un ciclo anual. Para productos nuevos se requiere una estimación externa; este módulo no inventa su demanda. Los meses sin existencias pueden ocultar ventas perdidas: no se corrigen sin datos de disponibilidad.')
    st.markdown('<div class="nexus-workflow"><div><b>1 · Fuente</b><span>Ranking mensual y sede</span></div><div><b>2 · Política</b><span>Entrega, compras y reserva</span></div><div><b>3 · Revisar</b><span>Tránsito y cantidades</span></div><div><b>4 · Descargar</b><span>Planilla + Excel con fórmulas</span></div></div>',unsafe_allow_html=True)
    upload=workflow_upload_v713('Ranking mensual A2 con existencias',type=['pdf'],key='v712r_upload')
    if upload is None:
        st.session_state.pop('v712r_result',None);st.session_state.pop('v712r_exports',None)
        st.info('Sube el ranking. Puedes analizar todos los productos de un proveedor/grupo o filtrar códigos. Los ajustes de esta sección no sustituyen automáticamente las reglas guardadas del resto de NEXUS.')
        return
    try:
        parsed=cached_ranking_pdf_v714(upload.getvalue(),upload.name)
    except Exception as exc:
        st.session_state.pop('v712r_result',None);st.session_state.pop('v712r_exports',None)
        st.error(f'No se pudo leer el ranking: {exc}');return
    source=parsed['data'];meta=parsed['metadata'];sid=meta['sha256'][:12]
    k=lambda name:'v712r_'+name+'_'+sid
    for warning in meta.get('global_warnings',[]):st.caption('Aviso de fuente: '+str(warning))
    st.caption(f"{len(source)} productos · {', '.join(meta['periods'])} · empresa impresa: {meta.get('company','')} · existencia según reporte {meta.get('report_date_text','')}. Ranking de vendidos, no catálogo completo.")
    site=st.selectbox('Sede del ranking',SEDES,index=SEDES.index('Matriz Makropetrol') if 'MAKROPETROL' in meta.get('company','').upper() else None,key=k('site'))
    group=st.text_input('Proveedor o grupo para este lote',value=meta.get('department',''),key=k('group'))
    st.caption('El proveedor/grupo es una etiqueta confirmada por ti. No asigna automáticamente un proveedor a todos los códigos de A2.')
    profile_path=Path(__file__).with_name('nexus_reposicion_perfiles.json')
    try:profiles=load_replenishment_profiles_v712(profile_path)
    except Exception as exc:profiles={};st.warning(f'No se pueden leer los perfiles: {exc}')
    for name,value in {'cycle_days':60,'buffer_days':7,'service_level':95.0,'adjustment':1.0}.items():
        if 'v712r_cfg_'+name not in st.session_state:st.session_state['v712r_cfg_'+name]=value
    with st.expander('Guardar o reutilizar parámetros por proveedor'):
        selected_profile=st.selectbox('Perfil guardado',['Selecciona…']+list(profiles),key='v712r_profile_select')
        if st.button('Usar parámetros del perfil',key='v712r_profile_load',disabled=selected_profile=='Selecciona…'):
            for name,value in profiles[selected_profile].items():
                st.session_state['v712r_cfg_'+name]=int(value) if name in {'lead_days','cycle_days','buffer_days'} else value
            st.session_state.pop('v712r_result',None);st.session_state.pop('v712r_exports',None)
    st.subheader('Política de demanda y reposición')
    months=meta['periods']
    excluded=st.multiselect('Excluir meses excepcionales · sólo si sabes por qué',months,format_func=ranking_month_label_v714,key=k('exclude'))
    reason=st.text_input('Motivo de la exclusión',placeholder='Ejemplo: promoción puntual que no se repetirá',key=k('exclude_reason')) if excluded else ''
    method=st.selectbox('Cómo estimar la demanda', ['promedio','ponderado'],format_func=lambda v:{'promedio':'Promedio de los meses incluidos','ponderado':'Promedio ponderado · más peso a meses recientes'}[v],key='v712r_cfg_method')
    st.caption('Ponderado: pesos 1, 2, 3… en orden cronológico. No elige automáticamente el método más conveniente ni elimina picos por su cuenta.')
    a,b,c=st.columns(3)
    lead=a.number_input('Entrega del proveedor · días',min_value=0,max_value=365,value=None,step=1,key='v712r_cfg_lead_days',placeholder='Introduce el plazo real')
    cycle=b.number_input('Cada cuántos días compras',min_value=1,max_value=365,value=None,step=1,key='v712r_cfg_cycle_days')
    safety=c.selectbox('Cómo definir la reserva',['dias','estadistica'],format_func=lambda v:'Días de demanda' if v=='dias' else 'Servicio objetivo · aproximación estadística',key='v712r_cfg_safety_mode')
    a,b=st.columns(2)
    buffer_days=a.number_input('Días adicionales de reserva',min_value=0,max_value=180,value=None,step=1,key='v712r_cfg_buffer_days',disabled=safety!='dias')
    service=b.number_input('Servicio objetivo de ciclo · %',min_value=50.1,max_value=99.9,value=None,step=0.5,key='v712r_cfg_service_level',disabled=safety!='estadistica')
    if safety=='estadistica':
        st.warning('Aproximación normal con demanda mensual estacionaria, períodos independientes y plazo fijo. Requiere al menos 12 meses incluidos, promedio simple y factor 1. No estima retrasos variables ni garantiza el porcentaje de disponibilidad.')
        st.caption('Reserva = z × desviación mensual × raíz(plazo de protección / 30). Para el mínimo se protege la entrega; para el máximo, entrega + ciclo. Un porcentaje mayor aumenta la reserva estimada, no necesariamente el mínimo por encima de un mes de ventas.')
    with st.expander('Ajuste comercial y excepciones del historial'):
        adjustment=st.number_input('Factor de demanda previsto',min_value=0.0,max_value=5.0,value=None,step=0.1,key='v712r_cfg_adjustment')
        adjustment_reason=st.text_input('Motivo del factor si es distinto de 1',placeholder='Campaña prevista, cambio de clientela…',key=k('adjustment_reason'))
        st.caption('1 conserva la estimación; 1,2 añade 20 %. Es una hipótesis manual, no estacionalidad detectada. Aplicarla a un lote afecta a todos sus productos; filtra un grupo homogéneo.')
        returns_reviewed=st.checkbox('Revisé las ventas netas negativas del reporte',key='v712r_cfg_review_returns')
        zero_reviewed=st.checkbox('Revisé y admito propuestas con demanda cero',key='v712r_cfg_review_zero')
    order_mode=st.radio('Qué compra necesitas preparar',['programada','minimo'],format_func=lambda v:'Hoy corresponde compra programada' if v=='programada' else 'Sólo productos que llegaron al mínimo',horizontal=True,key='v712r_cfg_order_mode')
    config=dict(method=method,lead_days=lead,cycle_days=cycle,buffer_days=buffer_days,safety_mode=safety,service_level=service,adjustment=adjustment,
                order_mode=order_mode,review_returns=returns_reviewed,review_zero=zero_reviewed)
    profile_name=st.text_input('Nombre del perfil para reutilizar estos parámetros',placeholder='WEB · Matriz · entrega 15 / compra 60',key='v712r_profile_name')
    if st.button('Guardar perfil de parámetros',key='v712r_profile_save'):
        try:save_replenishment_profile_v712(profile_path,profile_name,config);st.success('Perfil guardado. Sólo conserva parámetros; no guarda ni mezcla este inventario.')
        except Exception as exc:st.error(str(exc))
    st.subheader('Productos y compromisos')
    query=st.text_input('Filtrar por código o descripción',key=k('query'))
    mask=source['Código'].astype(str).str.contains(query,case=False,regex=False,na=False)|source['Descripción'].astype(str).str.contains(query,case=False,regex=False,na=False)
    data=source[mask].copy().reset_index(drop=True)
    edit=pd.DataFrame({'Código':data['Código'],'Descripción':data['Descripción'],'En tránsito':0.0,'Comprometido':0.0,'Lote compra':1,'Mínimo proveedor':0.0})
    with st.expander('Pedidos confirmados, compromisos y lotes · opcional'):
        st.caption('Sólo tránsito que llegará dentro del plazo y compromisos firmes pendientes. No dupliques reservas ya descontadas de la existencia. Los ceros son la hipótesis de esta propuesta, no información obtenida de otra base. Filtrar cambia el lote y reinicia esta tabla.')
        entries=st.data_editor(edit,disabled=['Código','Descripción'],hide_index=True,width='stretch',key=k('editor')+'_'+ranking_signature_v714(data['Código'].tolist())[:10],
                              column_config={col:st.column_config.NumberColumn(min_value=1 if col=='Lote compra' else 0,step=1 if col=='Lote compra' else 1.0) for col in ['En tránsito','Comprometido','Lote compra','Mínimo proveedor']})
    for col in ['En tránsito','Comprometido','Lote compra','Mínimo proveedor']:data[col]=entries[col].to_numpy()
    metadata={**meta,'Sede':site,'Proveedor':group,'Departamento encabezado':group,'Título encabezado':meta.get('company') if site=='Matriz Makropetrol' else site,
              'Ajustar paginación':True,'Factor libre':f'Reposición · entrega {lead}d / compra {cycle}d / reserva {safety}',
              'Meses excluidos':excluded,'Motivo exclusión':reason,'Motivo ajuste':adjustment_reason,'database_used':False,
              'Supuesto tránsito': 'Ceros no editados significan sin tránsito/compromisos incluidos; no fueron consultados en A2.'}
    signature=ranking_signature_v714({'source':sid,'config':config,'metadata':metadata,'rows':data.to_dict('records')})
    state=st.session_state.get('v712r_result')
    if state and state['signature']!=signature:
        st.session_state.pop('v712r_result',None);st.session_state.pop('v712r_exports',None);state=None
    from datetime import datetime,timezone,timedelta
    today=datetime.now(timezone(timedelta(hours=-4))).date().isoformat()
    used=[m for m in months if m not in excluded]
    bad_period=any((not m['full_month'] or m['to']>today) for m in meta['months'] if m['period'] in used)
    invalid=not site or not group.strip() or data.empty or lead is None or (excluded and not reason.strip()) or (adjustment!=1 and not adjustment_reason.strip()) or bad_period
    if bad_period:st.error('Selecciona meses completos y no futuros. No se cambian las fechas del origen.')
    if st.button('Calcular reposición',type='primary',disabled=bool(invalid),key='v712r_calculate'):
        try:
            result=evaluate_replenishment_v712(data,months,config,excluded)
            state={'signature':signature,'result':result}
            st.session_state['v712r_result']=state;st.session_state.pop('v712r_exports',None)
        except Exception as exc:st.error(str(exc));return
    if not state:return
    result=state['result'];ready=result[result['Lista para planilla'].eq(True)]
    a,b,c=st.columns(3)
    a.metric('Productos listos',len(ready));b.metric('Pendientes',len(result)-len(ready));c.metric('Compra propuesta · unidades',f"{ready['A pedir'].sum():,.0f}")
    st.dataframe(result[['Código','Descripción','Existencia','Posición inventario','Punto de pedido','Stock Máximo','A pedir','Estado propuesta']],hide_index=True,width='stretch',height=330)
    with st.expander('Detalle del cálculo y comparación con cobertura 1 / 2'):
        st.caption('La referencia 1/2 usa el promedio del intervalo original. La nueva propuesta utiliza las exclusiones y ajustes indicados. La diferencia no demuestra por sí sola que un método sea mejor.')
        st.dataframe(result[['Código','Base mensual','Demanda ajustada mensual','Reserva al pedir','Reserva objetivo','Stock Mínimo','Stock Máximo','Mínimo anterior cobertura 1 mes','Máximo anterior cobertura 2 meses','Exceso por lote','Motivo revisión','Notas reposición']],hide_index=True,width='stretch')
    st.caption('Revisa los pendientes y el exceso causado por lotes mínimos. El máximo es un objetivo de posición de inventario; la cantidad física al recibir puede ser menor por las ventas durante la espera.')
    if st.button('Preparar planilla PDF + Excel y análisis de reposición',type='primary',key='v712r_prepare'):
        metadata.update(_mm_generation_metadata_v711())
        package={'signature':signature,'metadata':metadata,'errors':[]}
        try:package['excel']=build_replenishment_excel_v712(result,source,metadata)
        except Exception as exc:package['errors'].append('Excel: '+str(exc))
        if not ready.empty:
            try:plan=ranking_plan_v714(result,ready['Código'].tolist())
            except Exception as exc:plan=pd.DataFrame();package['errors'].append('Planilla: '+str(exc))
            if not plan.empty:
                try:package['pdf']=build_minmax_original_pdf_v710(builtin_a2_template_v712(),plan,metadata)
                except Exception as exc:package['errors'].append('PDF: '+str(exc))
                try:package['planilla_excel']=build_minmax_planilla_excel_v713(plan,metadata,builtin_a2_template_v712())
                except Exception as exc:package['errors'].append('Planilla Excel: '+str(exc))
        st.session_state['v712r_exports']=package
    package=st.session_state.get('v712r_exports')
    if package and package['signature']==signature:
        for error in package['errors']:st.error(error)
        a,planilla_column,b=st.columns(3);name='Reposicion_'+safe_slug(site)+'_'+safe_slug(group)[:35]
        if package.get('pdf'):a.download_button('Descargar planilla A2 · PDF',package['pdf'],name+'.pdf','application/pdf',on_click='ignore',key='v712r_download_pdf')
        if package.get('planilla_excel'):planilla_column.download_button('Descargar planilla A2 · Excel',package['planilla_excel'],name+'_planilla.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',on_click='ignore',key='v713r_download_planilla_excel')
        if package.get('excel'):b.download_button('Descargar Excel formulado',package['excel'],name+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',on_click='ignore',key='v712r_download_excel')
        if ready.empty:st.info('El análisis Excel incluye los pendientes. Para descargar la planilla PDF y Excel hace falta al menos un producto listo.')
        st.caption('La planilla PDF y Excel lleva los mismos valores, incluido A pedir ajustado por tránsito, compromisos y lotes. El Excel formulado de reposición permite simulaciones separadas: no actualiza el PDF ni registra movimientos en A2. Fuente PDF conserva las filas originales y Propuesta original conserva el cálculo emitido.')


def build_minmax_planilla_excel_v713(plan, metadata, template_pdf=None):
    """Export the SAME approved six-column A2 proposal as an editable workbook.

    This is a print layout adapted to Excel, not a raster copy of the source PDF.
    In particular, A pedir is the approved value supplied by the caller: it must
    not be recalculated from stock because other flows account for transit/lots.
    The detailed comparison workbook remains the place for live calculations.
    ``metadata`` uses exactly the keys consumed by build_minmax_original_pdf_v710.
    ``template_pdf`` is used for optional header/logo appearance only, never data.
    """
    import io
    import math
    from datetime import datetime, timezone, timedelta
    from openpyxl import Workbook
    from openpyxl.drawing.image import Image as ExcelImage
    from openpyxl.styles import Alignment, Border, Font, PatternFill, Side
    from openpyxl.worksheet.page import PageMargins

    columns = ['Código', 'Descripción', 'Existencia', 'Mínimo', 'Máximo', 'A pedir']
    metadata = dict(metadata or {})

    def text(value):
        if value is None:
            return ''
        value = str(value).strip()
        return '' if value.casefold() in {'nan', 'none', '<na>', 'nat'} else value

    def numeric(value, field, code):
        try:
            result = float(value)
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError(f'{code}: {field} no es un número válido.') from exc
        if not math.isfinite(result):
            raise ValueError(f'{code}: falta {field}; no se puede completar con cero.')
        if field != 'Existencia' and result < 0:
            raise ValueError(f'{code}: {field} no puede ser negativo.')
        return result

    if plan is None or plan.empty:
        raise ValueError('Selecciona al menos un producto para descargar la planilla Excel.')
    missing = [column for column in columns if column not in plan.columns]
    if missing:
        raise ValueError('Faltan columnas para la planilla Excel: ' + ', '.join(missing))
    wanted, seen = [], set()
    for raw_row in plan[columns].to_dict('records'):
        code = text(raw_row['Código'])
        if not code or code in seen:
            raise ValueError('La planilla contiene códigos vacíos o repetidos. Revísalos antes de exportar.')
        seen.add(code)
        row = {'Código': code, 'Descripción': text(raw_row['Descripción'])}
        if not row['Descripción']:
            raise ValueError(f'{code}: falta la descripción del producto.')
        for column in columns[2:]:
            row[column] = numeric(raw_row[column], column, code)
        if row['Mínimo'] > row['Máximo']:
            raise ValueError(f'{code}: el mínimo supera el máximo.')
        wanted.append(row)

    # Read only the source header. Product records from the template are never
    # inspected or joined to the approved plan, so no old SKU enters the export.
    template_fields, logo = {}, None
    if template_pdf:
        try:
            import fitz
            with fitz.open(stream=bytes(template_pdf), filetype='pdf') as source:
                if source.is_encrypted:
                    raise ValueError('La plantilla PDF está protegida; usa una copia sin contraseña.')
                spans = [span for block in source[0].get_text('dict')['blocks'] if block['type'] == 0
                         for line in block['lines'] for span in line['spans']]
                for field, baseline in [('Dirección línea 1', 49.68), ('Dirección línea 2', 63.18), ('Teléfono encabezado', 77.46)]:
                    found = next((span for span in spans if abs(span['origin'][1] - baseline) < .3
                                  and 70 < span['origin'][0] < 90), None)
                    if found:
                        template_fields[field] = text(found['text'])
                for prefix in ['Departamento', 'Clasificación', 'Activo']:
                    found = next((span for span in spans if text(span['text']).startswith(prefix)), None)
                    if found:
                        template_fields[prefix] = text(found['text'])
                for info in source[0].get_images(full=True):
                    boxes = source[0].get_image_rects(info[0])
                    if not any(box.x0 < 78 and box.y0 < 80 and box.width < 100 and box.height < 100 for box in boxes):
                        continue
                    pix = fitz.Pixmap(source, info[0])
                    if pix.n - pix.alpha > 3:
                        pix = fitz.Pixmap(fitz.csRGB, pix)
                    logo = pix.tobytes('png')
                    break
        except ImportError:
            # Header fields provided by the caller remain available if PDF
            # support was not installed. The numerical workbook still works.
            pass
        except ValueError:
            raise
        except Exception:
            # An optional logo must not prevent a valid approved plan export.
            logo = None

    current_dt = datetime.now(timezone(timedelta(hours=-4)))
    generated = text(metadata.get('Generado ISO') or metadata.get('Generado'))
    if generated:
        try:
            parsed = datetime.fromisoformat(generated.replace('Z', '+00:00'))
            current_dt = parsed.replace(tzinfo=timezone(timedelta(hours=-4))) if parsed.tzinfo is None else parsed.astimezone(timezone(timedelta(hours=-4)))
        except ValueError as exc:
            raise ValueError('La fecha de generación no es válida.') from exc
    date_text = text(metadata.get('Fecha generación') or metadata.get('Fecha')) or current_dt.strftime('%d/%m/%Y')
    hour = current_dt.hour % 12 or 12
    time_text = text(metadata.get('Hora generación') or metadata.get('Hora')) or f'{hour}:{current_dt.minute:02d} ' + ('a. m.' if current_dt.hour < 12 else 'p. m.')
    site = text(metadata.get('Sede'))
    is_matriz = not site or 'matriz' in site.casefold() or site.casefold() in {'makropetrol', 'makropetrol, c.a.'}
    title = text(metadata.get('Título encabezado') or metadata.get('Nombre encabezado')) or ('MAKROPETROL, C.A.' if is_matriz else site.upper())
    addresses = [text(metadata.get(field)) or (template_fields.get(field, '') if is_matriz else '')
                 for field in ['Dirección línea 1', 'Dirección línea 2', 'Teléfono encabezado']]
    brand, provider = text(metadata.get('Marca')), text(metadata.get('Proveedor'))
    kind, factor = text(metadata.get('Tipo de producto')), text(metadata.get('Factor libre'))
    classification = ' | '.join(value for value in [('Marca: ' + brand) if brand else '', ('Tipo: ' + kind) if kind else ''] if value)
    active = ' | '.join(value for value in [('Proveedor: ' + provider) if provider else '', ('Factor: ' + factor) if factor else ''] if value)
    classification = classification or template_fields.get('Clasificación', 'Clasificación :  Productos,Ensamblados')
    active = active or template_fields.get('Activo', 'Activo  :  Todos')
    department = text(metadata.get('Departamento encabezado'))
    if department:
        department = department if department.lower().startswith('departamento') else 'Departamento  :  ' + department
    else:
        department = template_fields.get('Departamento', 'Departamento  :  Todos')

    workbook = Workbook()
    sheet = workbook.active
    sheet.title = 'Planilla A2'
    sheet.sheet_view.showGridLines = False
    workbook.properties.title = f'Reposición de Inventario - {site or title}'
    workbook.properties.subject = 'Planilla A2 de seis columnas; valores aprobados sin recálculo'
    workbook.properties.creator = 'Makropetrol NEXUS'
    workbook.properties.description = f'{title} | {date_text} | {time_text} | {department}'
    workbook.properties.keywords = 'NEXUS_A2_PLANILLA_SIX_COLUMNS_V1;NEXUS_A2_NUMERIC_EN_US_V1'
    workbook.properties.created = current_dt.replace(tzinfo=None)
    workbook.properties.modified = current_dt.replace(tzinfo=None)
    regular = Font(name='Arial', size=9, color='000000')
    header_font = Font(name='Arial', size=9, bold=True, color='000000')
    rule = Side(style='thin', color='7F7F7F')

    def literal(cell, value):
        # A code such as =123 or a description starting with + is data, not an
        # Excel formula. Text format preserves leading zeros and internal spaces.
        cell.value = value
        cell.data_type = 's'
        cell.number_format = '@'

    def merged(row, first, last, value, *, bold=False, size=10, height=None):
        sheet.merge_cells(start_row=row, start_column=first, end_row=row, end_column=last)
        cell = sheet.cell(row, first)
        literal(cell, value)
        cell.font = Font(name='Arial', size=size, bold=bold, color='000000')
        cell.alignment = Alignment(vertical='center', wrap_text=True)
        if height:
            sheet.row_dimensions[row].height = height
        return cell

    sheet.column_dimensions['A'].width = 18
    sheet.column_dimensions['B'].width = 66
    for column in ['C', 'D', 'E', 'F']:
        sheet.column_dimensions[column].width = 13
    merged(1, 2, 4, title, bold=True, size=13, height=24)
    merged(2, 2, 4, addresses[0], height=max(18, 14 * math.ceil(len(addresses[0]) / 95)))
    merged(3, 2, 4, addresses[1], height=max(18, 14 * math.ceil(len(addresses[1]) / 95)))
    merged(4, 2, 4, addresses[2], height=18)
    for row, label, value in [(1, 'Fecha :', date_text), (2, 'Hora :', time_text), (3, 'Sede :', site or title)]:
        literal(sheet.cell(row, 5), label)
        sheet.cell(row, 5).font = header_font
        literal(sheet.cell(row, 6), value)
        sheet.cell(row, 6).font = Font(name='Arial', size=9)
        sheet.cell(row, 6).alignment = Alignment(horizontal='right', vertical='center', wrap_text=True)
    # A long site name is given a separate full-width line rather than shrinking
    # a tiny right-hand cell into unreadable text.
    if len(site or title) > 16:
        sheet.row_dimensions[3].height = max(sheet.row_dimensions[3].height or 18, 30)
    merged(5, 1, 6, 'Reposición de Inventario', bold=True, size=12, height=23)
    merged(6, 1, 6, classification, height=max(18, 13 * math.ceil(len(classification) / 135)))
    merged(7, 1, 6, active, height=max(18, 13 * math.ceil(len(active) / 135)))
    merged(8, 1, 6, department, height=max(18, 13 * math.ceil(len(department) / 135)))
    if logo:
        picture = ExcelImage(io.BytesIO(logo))
        picture.width = 80
        picture.height = 80
        sheet.add_image(picture, 'A1')

    for index, column in enumerate(columns, 1):
        cell = sheet.cell(9, index)
        literal(cell, column)
        cell.font = header_font
        cell.fill = PatternFill('solid', fgColor='C0C0C0')
        cell.border = Border(top=rule, bottom=rule)
        cell.alignment = Alignment(vertical='center', wrap_text=True)
    sheet.row_dimensions[9].height = 22
    for row_index, item in enumerate(wanted, 10):
        for column_index, column in enumerate(columns, 1):
            cell = sheet.cell(row_index, column_index)
            cell.font = regular
            if column_index <= 2:
                literal(cell, item[column])
                cell.alignment = Alignment(vertical='center', wrap_text=column_index == 2,
                                           shrink_to_fit=column_index == 1)
            else:
                cell.value = item[column]
                cell.number_format = '#,##0' if abs(item[column] - round(item[column])) < 1e-9 else '#,##0.######'
                cell.alignment = Alignment(horizontal='right', vertical='center')
        # Excel does not auto-size a wrapped row on every viewer. An explicit
        # height keeps long A2 descriptions visible in print and basic readers.
        lines = max(1, math.ceil(len(item['Descripción']) / 75))
        sheet.row_dimensions[row_index].height = max(15, 12 * lines)

    last_data_row = 9 + len(wanted)
    footer_row = last_data_row + 2
    merged(footer_row, 1, 4, 'Total Registros :', size=9, height=19)
    sheet.cell(footer_row, 5, len(wanted)).font = header_font
    for cell in sheet[footer_row]:
        cell.border = Border(top=rule)
    sheet.freeze_panes = 'C10'
    sheet.auto_filter.ref = f'A9:F{last_data_row}'
    sheet.print_area = f'A1:F{footer_row}'
    sheet.print_title_rows = '1:9'
    sheet.sheet_properties.pageSetUpPr.fitToPage = True
    sheet.page_setup.orientation = 'portrait'
    sheet.page_setup.paperSize = sheet.PAPERSIZE_A4
    sheet.page_setup.fitToWidth = 1
    sheet.page_setup.fitToHeight = 0
    sheet.page_margins = PageMargins(left=.25, right=.25, top=.3, bottom=.45, header=.1, footer=.15)
    sheet.print_options.horizontalCentered = True
    sheet.oddFooter.left.text = 'Reposición de Inventario'
    sheet.oddFooter.right.text = 'Pág. &P de &N'
    sheet.oddFooter.left.size = sheet.oddFooter.right.size = 8
    output = io.BytesIO()
    workbook.save(output)
    return output.getvalue()


# NEXUS 7.13: clasificación rápida por contenido, sin cálculos ni base guardada.
def _source_pdf_text_v713(value):
    import re
    import unicodedata
    value = unicodedata.normalize("NFKD", str(value or ""))
    value = "".join(ch for ch in value if not unicodedata.combining(ch))
    return re.sub(r"\s+", " ", value).strip().lower()


def _source_pdf_headers_v713(page):
    """Recognize a table header on one line; body prose is never a header."""
    lines = []
    for word in sorted(page.get_text("words"), key=lambda w: (w[1], w[0])):
        if not lines or abs(lines[-1][0][1] - word[1]) > 2:
            lines.append([word])
        else:
            lines[-1].append(word)
    candidates = []
    aliases = {"codigo": "code", "cod.": "code", "descripcion": "description",
               "existencia": "stock", "existencias": "stock", "stock": "stock",
               "minimo": "minimum", "min.": "minimum", "maximo": "maximum", "max.": "maximum"}
    for line in lines:
        line.sort(key=lambda w: w[0])
        fields = [aliases.get(_source_pdf_text_v713(w[4]).rstrip(":")) for w in line]
        fields = [field for field in fields if field]
        if len(fields) == len(set(fields)) and {"code", "description", "stock"}.issubset(fields):
            # Known A2 order; text in another report containing these words is not sufficient.
            required = ["code", "description", "stock"]
            if {"minimum", "maximum"}.issubset(fields):
                required += ["minimum", "maximum"]
            if [fields.index(field) for field in required] == sorted(fields.index(field) for field in required):
                candidates.append(set(fields))
    return max(candidates, key=len) if candidates else set()


def classify_nexus_pdf_v713(raw, filename="reporte_A2.pdf"):
    """Classify supported PDF structure, not the truth or readiness of its values.

    Filenames are labels only. No saved inventory, sales or database is accessed.
    The selected reader still validates values, identities and printed totals.
    ``row_count`` is a printed count when available, not a parsed-row claim.
    ``can_calculate_without_history`` means no *additional* history upload is
    needed: a monthly ranking already contains its own sales history.
    """
    import hashlib
    import re
    try:
        import fitz
    except ImportError as exc:
        raise RuntimeError("Falta PyMuPDF para identificar el PDF. Instala los requisitos de NEXUS en este Python.") from exc
    if not isinstance(raw, (bytes, bytearray)) or not bytes(raw).lstrip()[:5] == b"%PDF-":
        raise ValueError("El archivo no contiene un PDF válido. Exporta el documento original de A2.")
    result = {
        "kind": "otro", "label": "PDF sin formato reconocido", "filename": str(filename),
        "sha256": hashlib.sha256(raw).hexdigest(), "pages": 0, "row_count": None,
        "row_count_source": "", "month_count": 0, "months": [],
        "has_monthly_sales": False, "has_stock": False, "has_current_minmax": False,
        "can_calculate_without_history": False, "can_export_existing_limits": False,
        "requires_value_validation": True, "database_used": False,
        "supported": False, "destination": None, "requires": [], "warnings": [],
        "message": "No se reconoce una planilla de mínimos/máximos ni un ranking mensual A2."
    }
    try:
        doc = fitz.open(stream=raw, filetype="pdf")
    except Exception as exc:
        raise ValueError("El PDF está dañado o no se puede abrir; vuelve a exportarlo desde A2.") from exc
    with doc:
        if doc.needs_pass:
            raise ValueError("El PDF está protegido con contraseña. Exporta una copia legible desde A2.")
        if len(doc) == 0 or len(doc) > 1000:
            raise ValueError("Usa un PDF de 1 a 1000 páginas; puedes separarlo por sede o proveedor.")
        result["pages"] = len(doc)
        kinds, signatures, counts, ranking_errors, observed_ranks = [], [], [], [], []
        for page_no, page in enumerate(doc, 1):
            text = page.get_text()
            normalized = _source_pdf_text_v713(text)
            if not normalized:
                kinds.append("sin_texto")
                continue
            if page_no == 1:
                dates = re.findall(r"\b\d{1,2}/\d{1,2}/\d{4}\b", text)
                result["report_date_text"] = dates[0] if dates else ""
                company = next((line.strip() for line in text.splitlines()
                                if "makropetrol" in _source_pdf_text_v713(line)), "")
                result["company"] = company
                department = re.search(r"departamentos?\s*:\s*([^\r\n]+)", text, re.I)
                result["department"] = department.group(1).strip() if department else ""
            printed = re.findall(r"total\s+registros\s*:\s*([\d.,]+)", text, re.I)
            for value in printed:
                # Record counts are integers; don't infer a numeric locale from them.
                if value.isdigit():
                    counts.append(int(value))
            if "ranking de ventas por productos comparativo" in normalized:
                try:
                    spans = _ranking_spans_v714(page)
                    layout = _ranking_layout_v714(spans)
                    signatures.append(tuple((m["period"], m["from"], m["to"], m["full_month"]) for m in layout["months"]))
                    observed_ranks.extend(int(s["text"]) for s in spans
                                          if s["box"][1] > layout["body_top"]
                                          and layout["rank"][0] <= (s["box"][0] + s["box"][2])/2 < layout["rank"][1]
                                          and re.fullmatch(r"\d+", s["text"]))
                    if page_no == 1:
                        department = next((s for s in spans if _source_pdf_text_v713(s["text"]).startswith("departamentos:")), None)
                        group = [s for s in spans if department and s["box"][0] > department["box"][2]
                                 and abs(s["box"][1] - department["box"][1]) < 3
                                 and s["box"][0] < page.rect.width/2]
                        result["department"] = " ".join(s["text"] for s in sorted(group, key=lambda s: s["box"][0]))
                    kinds.append("ranking_mensual")
                except ValueError as exc:
                    kinds.append("ranking_incompleto")
                    ranking_errors.append("Página " + str(page_no) + ": " + str(exc))
                continue
            headers = _source_pdf_headers_v713(page)
            if {"code", "description", "stock", "minimum", "maximum"}.issubset(headers):
                kinds.append("planilla_minmax")
            elif {"code", "description", "stock"}.issubset(headers):
                kinds.append("inventario_pdf")
            else:
                kinds.append("otro")
        distinct = set(kinds)
        if "sin_texto" in distinct:
            result.update(kind="sin_texto", label="PDF con páginas sin texto legible",
                          requires=["PDF original exportado de A2 o tabla Excel"],
                          message="Hay páginas sin texto legible. No se adivinarán códigos ni cantidades de una imagen escaneada.")
            return result
        if len(distinct) > 1:
            result.update(kind="mixto", label="PDF con formatos diferentes",
                          requires=["Separar los documentos de distinto tipo"],
                          message="Este PDF mezcla páginas con estructuras diferentes. Separa la planilla y el ranking para revisar cada fuente completa.")
            result["warnings"].extend(ranking_errors)
            return result
        kind = kinds[0]
        if kind == "ranking_incompleto":
            result.update(kind=kind, label="Ranking mensual pendiente de lectura",
                          requires=["Columnas completas con fechas, unidades, monto y existencia"],
                          message="Se detectó el título de un ranking comparativo, pero su estructura mensual no se puede validar.")
            result["warnings"] = ranking_errors
            return result
        if kind == "ranking_mensual":
            if len(set(signatures)) != 1:
                result.update(kind="mixto", label="Ranking con períodos diferentes",
                              requires=["Un ranking con los mismos meses en todas sus páginas"],
                              message="Los meses cambian entre páginas. No se combinarán períodos diferentes automáticamente.")
                return result
            signature = signatures[0]
            months = sorted(month[0] for month in signature)
            complete = all(month[3] for month in signature)
            result.update(kind=kind, label="Ranking A2 con ventas por mes y existencias",
                          month_count=len(months), months=months, has_monthly_sales=True, has_stock=True,
                          row_count=len(observed_ranks), row_count_source="Filas numeradas detectadas; pendiente de validar cantidades y totales",
                          can_calculate_without_history=complete, supported=True,
                          destination="Ranking mensual A2",
                          message="Este archivo incluye las ventas separadas por mes y las existencias. Puedes calcular usando únicamente este PDF.")
            if not complete:
                result["requires"] = ["Revisar períodos parciales antes de calcular coberturas mensuales"]
                result["message"] = "Se identificaron ventas mensuales, pero hay períodos parciales; revisa sus fechas antes de calcular."
            result["warnings"].append("Un ranking de más vendidos puede excluir productos sin ventas; no equivale automáticamente a todo el inventario.")
            if observed_ranks and sorted(observed_ranks) != list(range(1, len(observed_ranks) + 1)):
                result["warnings"].append("La numeración del ranking contiene saltos o repetidos; el lector debe revisar la integridad del archivo.")
        elif kind == "planilla_minmax":
            if counts:
                result["row_count"] = counts[-1]
                result["row_count_source"] = "Total de registros impreso en el PDF; pendiente de conciliación por el lector"
            result.update(kind=kind, label="Planilla A2 con mínimos y máximos actuales",
                          has_stock=True, has_current_minmax=True, can_export_existing_limits=True,
                          supported=True, destination="Revisar planilla A2",
                          requires=["Ventas e intervalo del historial para proponer nuevos mínimos y máximos"],
                          message="Esta planilla trae existencia, mínimo, máximo y A pedir; no trae ventas ni meses. Puedes revisarla o pasar sus valores a Excel. Para recalcular por demanda necesitas un ranking mensual o historial de ventas.")
        elif kind == "inventario_pdf":
            result.update(kind=kind, label="Inventario PDF sin historial de ventas",
                          has_stock=True, destination="Carga de datos",
                          requires=["Inventario exportado a XLS/XLSX/CSV", "Historial de ventas con sus fechas"],
                          message="Se detectó una tabla de inventario, pero no mínimos/máximos ni ventas mensuales. Para el motor general, exporta el inventario a Excel y acompáñalo de las ventas.")
        else:
            result["requires"] = ["Ranking mensual A2 o planilla de mínimos y máximos con encabezados completos"]
    return result


# Navigation and source hand-off. These helpers do not run the stock engine.
