@st.cache_data(show_spinner=False, max_entries=8)
def cached_classify_nexus_pdf_v713(raw, filename):
    return classify_nexus_pdf_v713(raw, filename)


def forward_pdf_v713(raw, filename, target, site=None):
    keys = {'Ranking mensual A2': 'v714_ranking_upload', 'Reposición por proveedor': 'v712r_upload',
            'Revisar planilla A2': 'v713_review_upload', 'Planilla A2': 'v710_mm_a2'}
    if target not in keys:
        raise ValueError('Destino de archivo no válido.')
    # No writes to uploader widget state. A forwarded file is a separate source.
    key = keys[target]
    st.session_state['v713_forward_' + key] = {'raw': bytes(raw), 'name': str(filename)}
    if target == 'Planilla A2':
        st.session_state['v712_planilla_route'] = 'Comparar con valores actuales A2'
        st.session_state['v710_mm_confirm'] = False
        if site in SEDES:
            st.session_state['v710_mm_site'] = site
    _navigation_v7(target)


def workflow_upload_v713(label, *, type=None, key, **kwargs):
    forwarded = st.session_state.get('v713_forward_' + key)
    if forwarded:
        from types import SimpleNamespace
        st.info('Archivo recibido: ' + forwarded['name'])
        if st.button('Cambiar archivo', key='v713_change_' + key):
            st.session_state.pop('v713_forward_' + key, None)
            st.session_state['v713_upload_epoch_' + key] = st.session_state.get('v713_upload_epoch_' + key, 0) + 1
            # Existing calculation signatures handle new files. Hide old output
            # immediately even if the replacement has not been selected yet.
            owned_states = {
                'v714_ranking_upload': ['v714_ranking_calculation', 'v714_ranking_exports'],
                'v712r_upload': ['v712r_result', 'v712r_exports'],
                'v713_review_upload': ['v713_review_exports'],
                'v710_mm_a2': ['v710_mm_result', 'v711_mm_pdf_ready', 'v711_mm_excel_ready', 'v713_mm_planilla_excel_ready'],
            }
            for state_key in owned_states.get(key, []):
                st.session_state.pop(state_key, None)
            if key == 'v710_mm_a2':
                st.session_state['v710_mm_confirm'] = False
            st.rerun()
        return SimpleNamespace(name=forwarded['name'], getvalue=lambda: forwarded['raw'])
    epoch = st.session_state.get('v713_upload_epoch_' + key, 0)
    actual_key = key if not epoch else key + '_file_' + str(epoch)
    return st.file_uploader(label, type=type, key=actual_key, **kwargs)


def move_current_pdf_v713(key, target):
    forwarded = st.session_state.get('v713_forward_' + key)
    if forwarded:
        forward_pdf_v713(forwarded['raw'], forwarded['name'], target)
    epoch = st.session_state.get('v713_upload_epoch_' + key, 0)
    current = st.session_state.get(key if not epoch else key + '_file_' + str(epoch))
    if current is not None and hasattr(current, 'getvalue'):
        forward_pdf_v713(current.getvalue(), current.name, target)
    _navigation_v7(target)


def render_file_gateway_v713():
    st.subheader('¿Tienes un PDF de A2?')
    st.caption('La app reconoce el tipo de documento y abre el recorrido adecuado con el mismo archivo.')
    file = st.file_uploader('Sube la planilla o el ranking mensual', type=['pdf'], key='v713_gateway_upload')
    if not file:
        return
    try:
        with st.spinner('Identificando el documento…'):
            info = cached_classify_nexus_pdf_v713(file.getvalue(), file.name)
    except Exception as exc:
        st.error(str(exc)); return
    st.markdown('**' + info['label'] + '**')
    st.write(info['message'])
    if info.get('row_count'):
        st.caption(f"{info['row_count']:,} registros detectados · {info['pages']} páginas" +
                   (f" · {info['month_count']} meses" if info.get('month_count') else ''))
    if info.get('warnings'):
        with st.expander('Qué conviene revisar en esta fuente'):
            for warning in info['warnings']:
                st.write(warning)
    if info['supported']:
        label = 'Abrir cálculo desde este ranking' if info['kind'] == 'ranking_mensual' else 'Revisar esta planilla y sus descargas'
        if st.button(label, type='primary', key='v713_gateway_open'):
            forward_pdf_v713(file.getvalue(), file.name, info['destination'])
    else:
        st.info(' · '.join(info.get('requires', [])) or 'Solicita el archivo original exportado de A2.')


