V714_PLAN_COLUMNS = ['Código', 'Descripción', 'Existencia', 'Mínimo', 'Máximo', 'A pedir']
V714_COMPLETE_VIEW = 'Proveedor completo · máximos y mínimos'


def pending_mask_v714(frame):
    if frame is None or frame.empty:
        return pd.Series(False, index=frame.index if frame is not None else [])
    state = frame.get('Estado', pd.Series('', index=frame.index)).astype(str)
    result = state.str.startswith('PENDIENTE')
    if 'Historial de ventas' in frame:
        result |= frame['Historial de ventas'].astype(str).eq('Pendiente de cargar')
    if {'Stock Mínimo', 'Stock Máximo'}.issubset(frame):
        result |= frame[['Stock Mínimo', 'Stock Máximo']].isna().any(axis=1)
    return result


def score_text_v714(score):
    try:
        return f'{float(score):.0f}/100' if np.isfinite(float(score)) else 'N/D'
    except (TypeError, ValueError):
        return 'N/D'


def safe_export_text_v714(value):
    if isinstance(value, str) and value.lstrip().startswith(('=', '+', '-', '@', '\t', '\r')):
        return "'" + value
    return value


def document_currency_v714(frame):
    if frame is None or frame.empty:
        return 'Sin moneda'
    col = next((c for c in ['Moneda inventario', 'Moneda destino', 'Moneda'] if c in frame), None)
    if col is None:
        return 'Sin moneda'
    values = frame[col].fillna('').astype(str).str.strip().str.upper()
    if not values.isin(FIN_CURRENCIES).all():
        return 'Sin moneda'
    return str(values.iloc[0]) if values.nunique() == 1 else 'Varias monedas'


def monetary_frame_total_v714(frame, value_column):
    """Legacy dollar cards only show a complete total with USD confirmed."""
    if frame is None or frame.empty:
        return float('nan')
    if document_currency_v714(frame) != 'USD' or value_column not in frame:
        return float('nan')
    values = pd.to_numeric(frame[value_column], errors='coerce').replace([np.inf, -np.inf], np.nan)
    return float(values.sum()) if values.notna().all() else float('nan')


def currency_summary_v714(frame):
    columns = ['Sede', 'Moneda', 'Productos', 'Valor conocido', 'Sin valorar', 'Cobertura']
    if frame is None or frame.empty:
        return pd.DataFrame(columns=columns)
    x = frame.copy()
    x['Moneda'] = x.get('Moneda inventario', pd.Series('', index=x.index)).fillna('Sin moneda')
    x['Moneda'] = x['Moneda'].where(x['Moneda'].isin(FIN_CURRENCIES), 'Sin moneda')
    x['Sede'] = x.get('Sede', pd.Series('Selección', index=x.index))
    rows = []
    for (site, currency), part in x.groupby(['Sede', 'Moneda'], dropna=False, observed=True):
        values = pd.to_numeric(part.get('Valor Inventario ($)', pd.Series(np.nan, index=part.index)), errors='coerce')
        missing = int(values.isna().sum())
        rows.append({'Sede': site, 'Moneda': currency, 'Productos': len(part),
                     'Valor conocido': float(values.sum(min_count=1)) if currency in FIN_CURRENCIES else np.nan,
                     'Sin valorar': missing,
                     'Cobertura': 'Moneda pendiente' if currency not in FIN_CURRENCIES else f'PARCIAL: {missing} sin dato' if missing else 'Completa'})
    return pd.DataFrame(rows, columns=columns)


def attach_transfer_currency_v714(transfers, site_results):
    x = transfers.copy()
    if x.empty:
        x['Moneda destino'] = pd.Series(dtype=str)
        return x
    lookup = {}
    for site, part in site_results.items():
        for rec in part.to_dict('records'):
            lookup[(site, str(rec['Código']))] = rec.get('Moneda inventario', 'Sin moneda')
    x['Moneda destino'] = [lookup.get((r['Destino'], str(r['Código'])), 'Sin moneda') for r in x.to_dict('records')]
    return x


def _doc_amount_v714(value, decimals=2):
    try:
        value=float(value)
        return f'{value:,.{decimals}f}' if np.isfinite(value) else 'N/D'
    except (TypeError,ValueError,OverflowError):
        return 'N/D'


def make_operational_pdf_v714():
    """FPDF with a system Unicode font, or a documented printable fallback."""
    from pathlib import Path
    import os
    class SafeOperationalPDF(FPDF):
        _unicode_ready = False
        def set_font(self, family=None, style='', size=0, **kwargs):
            family = family or 'Helvetica'
            if self._unicode_ready and str(family).lower() in {'helvetica', 'arial', 'times', 'courier'}:
                family = 'NexusUnicode'
                if 'B' in style:
                    style = 'B'
                else:
                    style = ''
            return super().set_font(family, style, size, **kwargs)
        def normalize_text(self, text):
            text = str(text)
            if not self._unicode_ready:
                for a, b in [('—','-'), ('–','-'), ('−','-'), ('→','>'), ('…','...'), ('“','"'), ('”','"'), ('’',"'")]:
                    text = text.replace(a,b)
                text = text.encode('latin-1', errors='replace').decode('latin-1')
            return super().normalize_text(text)
    pdf = SafeOperationalPDF()
    windir = Path(os.environ.get('WINDIR', 'C:/Windows')) / 'Fonts'
    pairs = [(windir/'arial.ttf',windir/'arialbd.ttf'),
             (Path('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'),Path('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'))]
    for regular,bold in pairs:
        if regular.is_file() and bold.is_file():
            try:
                pdf.add_font('NexusUnicode','',str(regular),uni=True)
                pdf.add_font('NexusUnicode','B',str(bold),uni=True)
                pdf._unicode_ready = True
                break
            except Exception:
                continue
    return pdf


def pdf_output_bytes_v714(pdf):
    raw = pdf.output(dest='S')
    return raw.encode('latin-1') if isinstance(raw, str) else bytes(raw)


def init_v714_db():
    """Additive, idempotent migration; unverified historic currencies stay blank."""
    with db() as con:
        ready = con.execute("SELECT value FROM v7_meta WHERE key='migration_v714'").fetchone()
    if ready:
        return
    with db() as con:
        has_data = bool(con.execute('SELECT 1 FROM inventory_snapshots UNION ALL SELECT 1 FROM supplier_inventory_snapshots LIMIT 1').fetchone())
    if has_data:
        dest = DB_PATH.with_name(f'nexus_respaldo_antes_v714_{datetime.now():%Y%m%d_%H%M%S_%f}.db')
        dest.write_bytes(backup_database_bytes())
    with db() as con:
        for table in ['inventory_snapshots', 'supplier_inventory_snapshots']:
            cols = {r[1] for r in con.execute(f'PRAGMA table_info({table})')}
            if 'inventory_currency' not in cols:
                con.execute(f"ALTER TABLE {table} ADD COLUMN inventory_currency TEXT NOT NULL DEFAULT ''")
        con.execute('''CREATE TABLE IF NOT EXISTS v714_supplier_runs (
            run_id TEXT PRIMARY KEY, created_at TEXT NOT NULL, site TEXT NOT NULL,
            supplier TEXT NOT NULL, source_hash TEXT NOT NULL, payload TEXT NOT NULL)''')
        con.execute("INSERT OR REPLACE INTO v7_meta VALUES('migration_v714','1')")
        touch_v7(con)


def snapshot_currency_v714(site, cutoff, scope=''):
    if not cutoff:
        return 'Sin moneda'
    table = 'supplier_inventory_snapshots' if scope else 'inventory_snapshots'
    where = 'site=? AND snapshot_date=?' + (' AND supplier_key=?' if scope else '')
    params = [site, cutoff] + ([normalize_key(scope)] if scope else [])
    with db() as con:
        columns = {r[1] for r in con.execute(f'PRAGMA table_info({table})')}
        if 'inventory_currency' not in columns:
            return 'Sin moneda'
        rows = con.execute(f'SELECT DISTINCT inventory_currency FROM {table} WHERE {where}', params).fetchall()
    values = {str(r[0] or '').strip().upper() for r in rows}
    return next(iter(values)) if len(values)==1 and values.issubset(set(FIN_CURRENCIES)) else 'Sin moneda'


def confirm_snapshot_currency_v714(site, cutoffs, currency, scope=''):
    if site not in SEDES or currency not in FIN_CURRENCIES or not cutoffs:
        raise ValueError('Selecciona sede, fechas y moneda válidas.')
    table = 'supplier_inventory_snapshots' if scope else 'inventory_snapshots'
    backup = DB_PATH.with_name(f'nexus_respaldo_moneda_{datetime.now():%Y%m%d_%H%M%S_%f}.db')
    backup.write_bytes(backup_database_bytes())
    with db() as con:
        for cutoff in cutoffs:
            where = 'site=? AND snapshot_date=?' + (' AND supplier_key=?' if scope else '')
            params = [currency, site, cutoff] + ([normalize_key(scope)] if scope else [])
            con.execute(f'UPDATE {table} SET inventory_currency=? WHERE {where}', params)
        con.execute('INSERT INTO v7_import_log(saved_at,site,kind,filename,sha256,metadata) VALUES(?,?,?,?,?,?)',
                    (datetime.now().isoformat(),site,'Confirmación moneda por corte','Confirmación del operador','',
                     json.dumps({'fechas':list(cutoffs),'moneda':currency,'scope':scope,'respaldo':backup.name},ensure_ascii=False)))
        touch_v7(con)
    st.cache_data.clear()


