# ============================================================================
# 7.18.4 · Identidad de producto ANTES del cálculo. No reescribe ventas ni A2.
# Coincidencia exacta -> variante de espacios única y descripción compatible ->
# equivalencia confirmada. Las similitudes sólo proponen; nunca inventan ceros.
# ============================================================================
V7184_IDENTITY_VERSION = '2026-09-19.1'


def compact_code_v7184(value):
    """Quita sólo espacios de comparación, no letras, dígitos, ceros ni guiones."""
    return ''.join(c for c in code_key_v714(value) if not c.isspace() and c not in '\u200b\ufeff')


def identity_description_v7184(value):
    text=unicodedata.normalize('NFKD',str(value or '')).upper()
    text=''.join(c for c in text if not unicodedata.combining(c))
    return ' '.join(re.findall(r'[A-Z0-9]+',text))


def description_check_v7184(left, right):
    """Corroboración, NO clave de unión. Descripciones cortas no prueban identidad."""
    from difflib import SequenceMatcher
    a=identity_description_v7184(left); b=identity_description_v7184(right)
    if not a or not b:return False, 'Falta descripción para corroborar la variante', 0.0
    ta=set(a.split());tb=set(b.split())
    def role(tokens):
        found=set()
        if tokens & {'SEC','SECUND','SECUNDARIO','SECUNDARIA'}:found.add('secundario')
        if tokens & {'PRIM','PRIMARIO','PRIMARIA'}:found.add('primario')
        return found
    ra,rb=role(ta),role(tb)
    if ra and rb and ra.isdisjoint(rb):return False,'Primario y secundario no son el mismo producto',0.0
    kinds={'AIRE','ACEITE','COMBUSTIBLE','REFRIGERANTE'}
    ka,kb=ta&kinds,tb&kinds
    if ka and kb and not ka&kb:return False,'Descripciones de tipos de producto diferentes',0.0
    if ('KIT' in ta)!=('KIT' in tb):return False,'Kit y pieza individual requieren confirmación',0.0
    ua=re.findall(r'\b(\d+(?:[.,]\d+)?)\s*(ML|CC|L|LT|LTS|LITROS|GAL|GL|GALONES|KG)\b',str(left).upper())
    ub=re.findall(r'\b(\d+(?:[.,]\d+)?)\s*(ML|CC|L|LT|LTS|LITROS|GAL|GL|GALONES|KG)\b',str(right).upper())
    if ua and ub and set(ua).isdisjoint(ub):return False,'Presentaciones/capacidades diferentes',0.0
    stop={'FILTRO','FILTROS','DE','DEL','LA','EL','PARA','Y','CON','SIN','TIPO'}
    aa=ta-stop;bb=tb-stop;overlap=len(aa&bb)/max(1,min(len(aa),len(bb)))
    similarity=SequenceMatcher(None,a,b,autojunk=False).ratio()
    prefix=(a.startswith(b+' ') or b.startswith(a+' ')) and min(len(a),len(b))>=18
    short_description=(min(len(aa),len(bb))<=3 and len(aa&bb)>=2 and bool((aa&bb)-kinds) and overlap>=2/3)
    supported=(a==b and len(aa)>=2) or (prefix and len(aa&bb)>=2) or (len(aa&bb)>=3 and (similarity>=.72 or overlap>=.75)) or short_description
    return supported, ('Descripción compatible' if supported else 'Descripción insuficiente o distinta; revisar'),round(max(similarity,overlap if len(aa&bb)>=3 else 0),4)


