def identity_store_v7184(site):
    """Una lectura; ni crea una base en lectura ni toca los códigos originales."""
    if not DB_PATH.exists():return {}
    with db() as con:
        if not con.execute("SELECT 1 FROM sqlite_master WHERE name='v7184_code_links'").fetchone():return {}
        rows=con.execute('SELECT source_code,target_code,source_description,target_description FROM v7184_code_links WHERE site=?',(site,)).fetchall()
    return {r[0]:{'target':r[1],'source_description':r[2],'target_description':r[3]} for r in rows}



def rejected_identity_links_v7184(site):
    if not DB_PATH.exists():return {}
    with db() as con:
        if not con.execute("SELECT 1 FROM sqlite_master WHERE name='v7184_rejected_links'").fetchone():return {}
        rows=con.execute('SELECT source_code,target_code,source_description,target_description FROM v7184_rejected_links WHERE site=?',(site,)).fetchall()
    return {(r[0],r[1]):(identity_description_v7184(r[2]),identity_description_v7184(r[3])) for r in rows}


def serialize_identity_plan_v7184(plan):
    plain=dict(plan)
    for key in ['report','candidates']:plain[key]=plan[key].to_dict('records')
    return json.dumps(plain,ensure_ascii=False,default=str)


def deserialize_identity_plan_v7184(raw):
    if not raw:return None
    plain=json.loads(raw)
    for key in ['report','candidates']:plain[key]=pd.DataFrame(plain[key])
    return plain


def identity_context_v7184(inv, sources, site):
    payload=[V7184_IDENTITY_VERSION,site,
             sorted((code_key_v714(r.get('Código')),identity_description_v7184(r.get('Descripción'))) for r in inv.to_dict('records')),
             sorted((str(r.get('Mes','')),code_key_v714(r.get('Código')),str(r.get('Ventas')),identity_description_v7184(r.get('Descripción')),
                     str(r.get('Fuente identidad',''))) for r in sources)]
    return hashlib.sha256(json.dumps(payload,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()


def identity_absences_v7184(site,context):
    if not DB_PATH.exists():return set()
    with db() as con:
        if not con.execute("SELECT 1 FROM sqlite_master WHERE name='v7184_absence_reviews'").fetchone():return set()
        return {r[0] for r in con.execute('SELECT code FROM v7184_absence_reviews WHERE site=? AND context_key=?',(site,context))}


def resolve_product_codes_v7184(inv, sources, site='', *, links=None, checked_absences=None):
    """Plan de unión reversible. Cada fila fuente se puede atribuir a UN producto.

    sources: registros Código, Descripción, Ventas, Mes (período o mes), Fuente identidad.
    Las variantes simultáneas del mismo mes permanecen pendientes: confirmar una
    equivalencia NO confirma que dos renglones deban sumarse o descartarse.
    No se decide identidad por precio, stock o cantidad vendida.
    """
    from collections import defaultdict
    from difflib import SequenceMatcher
    products=inv.to_dict('records'); sources=[dict(r) for r in sources]
    codes=[code_key_v714(r.get('Código')) for r in products]
    if any(not c for c in codes) or len(codes)!=len(set(codes)):
        raise ValueError('Corrige los códigos vacíos/repetidos del catálogo antes del cruce de identidad.')
    invmap={c:r for c,r in zip(codes,products)}; srcmap=defaultdict(list)
    for r in sources:
        r['Código']=code_key_v714(r.get('Código'))
        if r['Código']:srcmap[r['Código']].append(r)
    inv_compact=defaultdict(set);sale_compact=defaultdict(set);numbers=defaultdict(set);descriptions=defaultdict(set);deletions=defaultdict(set)
    for c in codes:inv_compact[compact_code_v7184(c)].add(c)
    for c,rows in srcmap.items():
        compact=compact_code_v7184(c)
        sale_compact[compact].add(c)
        if len(compact)<=64:
            for position in range(len(compact)):deletions[compact[:position]+compact[position+1:]].add(c)
        numbers[tuple(re.findall(r'\d+',c))].add(c)
        for r in rows:descriptions[identity_description_v7184(r.get('Descripción'))].add(c)
    links=identity_store_v7184(site) if links is None else links
    context=identity_context_v7184(inv,sources,site)
    checked_absences=identity_absences_v7184(site,context) if checked_absences is None else set(checked_absences)
    rejected=rejected_identity_links_v7184(site)
    def is_rejected(sc,tc):
        saved=rejected.get((sc,tc))
        return bool(saved and saved[1]==identity_description_v7184(invmap[tc].get('Descripción')) and
                    all(identity_description_v7184(r.get('Descripción'))==saved[0] for r in srcmap[sc]))
    mapping={};methods={};pending=defaultdict(list);candidates=defaultdict(set)
    # Exactitud antes de cualquier normalización; las dos referencias co-existentes
    # en el catálogo no se fusionan sólo por su aspecto.
    for sc in srcmap:
        if sc in invmap:mapping[sc]=sc;methods[sc]='Código exacto'
    for sc,record in links.items():
        tc=code_key_v714(record.get('target'))
        if sc not in srcmap or tc not in invmap:continue
        if sc in invmap and sc!=tc:
            pending[tc].append('Equivalencia incompatible: el código fuente existe como otro producto del catálogo')
            candidates[tc].add(sc);continue
        # Una equivalencia guardada no se hereda si cambia la identidad descriptiva.
        a=identity_description_v7184(record.get('target_description'))
        b=identity_description_v7184(invmap[tc].get('Descripción'))
        src_desc={identity_description_v7184(r.get('Descripción')) for r in srcmap[sc]}
        if a!=b or any(d!=identity_description_v7184(record.get('source_description')) for d in src_desc):
            pending[tc].append('Cambió la descripción de una equivalencia guardada; confirmar de nuevo')
            candidates[tc].add(sc);continue
        mapping[sc]=tc;methods[sc]='Equivalencia confirmada en esta sede'
    for sc,rows in srcmap.items():
        if sc in mapping:continue
        poss=inv_compact.get(compact_code_v7184(sc),set())
        if not poss:continue
        if len(poss)!=1:
            for tc in poss:pending[tc].append('Dos códigos del catálogo se confunden al retirar espacios');candidates[tc].add(sc)
            continue
        tc=next(iter(poss))
        if is_rejected(sc,tc):continue
        checks=[description_check_v7184(invmap[tc].get('Descripción'),r.get('Descripción')) for r in rows]
        if all(ok for ok,_,_ in checks):mapping[sc]=tc;methods[sc]='Espacios · única y descripción compatible'
        else:
            pending[tc].append(' / '.join(sorted({reason for ok,reason,_ in checks if not ok})));candidates[tc].add(sc)
    by_target=defaultdict(set)
    for sc,tc in mapping.items():by_target[tc].add(sc)
    for tc,assigned in by_target.items():
        month_codes=defaultdict(set)
        for sc in assigned:
            for r in srcmap[sc]:month_codes[str(r.get('Mes',''))].add(sc)
        overlap=[m for m,values in month_codes.items() if len(values)>1]
        if overlap:
            pending[tc].append('Variantes de código coexisten en '+', '.join(sorted(overlap))+': revisar duplicación antes de sumar')
            candidates[tc].update(assigned)
    # Sólo los NO encontrados solicitan similitudes. Índices por componentes
    # numéricos/descripcion: evita el cruce exhaustivo catálogo x filas mensuales.
    all_periods={str(r.get('Mes','')) for r in sources}
    for tc in codes:
        applied=by_target.get(tc,set())
        seen_months={str(r.get('Mes','')) for sc in applied for r in srcmap[sc]}
        gaps=all_periods-seen_months
        if applied and not gaps:continue
        dc=identity_description_v7184(invmap[tc].get('Descripción'));compact=compact_code_v7184(tc)
        pool=set(sale_compact.get(compact,set())) | set(numbers.get(tuple(re.findall(r'\d+',tc)),set())) | descriptions.get(dc,set())
        pool.update(deletions.get(compact,set()))
        if len(compact)<=64:
            for position in range(len(compact)):
                key=compact[:position]+compact[position+1:]
                pool.update(sale_compact.get(key,set()));pool.update(deletions.get(key,set()))
        for sc in sorted(pool):
            if is_rejected(sc,tc):continue
            if applied and (sc in mapping or not any(str(r.get('Mes','')) in gaps for r in srcmap[sc])):continue
            support,reason,score=description_check_v7184(invmap[tc].get('Descripción'),srcmap[sc][0].get('Descripción'))
            ratio=SequenceMatcher(None,compact,compact_code_v7184(sc),autojunk=False).ratio()
            if compact==compact_code_v7184(sc) or (support and (ratio>=.72 or identity_description_v7184(srcmap[sc][0].get('Descripción'))==dc)):
                candidates[tc].add(sc)
        if candidates[tc]:pending[tc].append('Hay posibles equivalencias en meses sin registro: confirmar o descartar antes de certificar límites')
        elif not applied and tc not in checked_absences:pending[tc].append('Código no encontrado en estas ventas; NO se considera un cero confirmado')
    # Una descripción de ventas SIN código nunca se atribuye automáticamente.
    target_desc=defaultdict(set)
    for tc in codes:target_desc[identity_description_v7184(invmap[tc].get('Descripción'))].add(tc)
    for r in sources:
        if not r['Código']:
            for tc in target_desc.get(identity_description_v7184(r.get('Descripción')),set()):
                pending[tc].append('Hay venta sin código con esta descripción; completar su identidad')
    report=[]
    for tc in codes:
        applied=sorted(by_target.get(tc,set()));issues=list(dict.fromkeys(pending.get(tc,[])))
        if issues:state='IDENTIDAD PENDIENTE'
        elif not applied:state='SIN REGISTROS · REVISADO EN ESTAS FUENTES'
        elif any(methods[c]!='Código exacto' for c in applied):state='RELACIONADO'
        else:state='EXACTO'
        report.append({'Código inventario':tc,'Descripción inventario':str(invmap[tc].get('Descripción','')),
                       'Códigos ventas aplicados':' | '.join(applied),'Coincidencia':state,
                       'Método':' | '.join(sorted({methods[c] for c in applied})),
                       'Candidatos':' | '.join(sorted(candidates.get(tc,set()))),'Motivo':' | '.join(issues),
                       'Identidad pendiente':bool(issues)})
    cand=[]
    for tc,choices in candidates.items():
        for sc in sorted(choices):
            ok,reason,score=description_check_v7184(invmap[tc].get('Descripción'),srcmap[sc][0].get('Descripción'))
            cand.append({'Código inventario':tc,'Descripción inventario':str(invmap[tc].get('Descripción','')),
                         'Código ventas':sc,'Descripción ventas':str(srcmap[sc][0].get('Descripción','')),
                         'Comprobación descripción':reason,'Similitud descripción':score,
                         'Ya atribuido a':mapping.get(sc,''),'Confirmar equivalencia':False,'Son productos distintos':False})
    safe_map={sc:tc for sc,tc in mapping.items() if tc not in pending}
    return {'mapping':safe_map,'proposed_mapping':mapping,'pending':dict(pending),
            'report':pd.DataFrame(report),'candidates':pd.DataFrame(cand), 'context':context,
            'site':site,'source_records':sources,'checked_absences':sorted(checked_absences),
            'source_count':len(sources),'source_codes':len(srcmap),'version':V7184_IDENTITY_VERSION}


def save_identity_review_v7184(plan, candidates, absence_codes=(), *, confirm=False):
    if not confirm:raise ValueError('Confirma que revisaste identidad y fuentes antes de guardar equivalencias.')
    if not plan.get('site'):raise ValueError('Falta la sede de esta revisión.')
    allowed={(r['Código inventario'],r['Código ventas']):r for r in plan['candidates'].to_dict('records')}
    chosen=[];rejected=[];claimed={}
    for r in candidates:
        if not bool(r.get('Confirmar equivalencia')) and not bool(r.get('Son productos distintos')):continue
        if bool(r.get('Confirmar equivalencia')) and bool(r.get('Son productos distintos')):raise ValueError('Una pareja no puede ser igual y distinta a la vez.')
        key=(code_key_v714(r.get('Código inventario')),code_key_v714(r.get('Código ventas')))
        if key not in allowed:raise ValueError('Cambió la fuente: vuelve a calcular antes de confirmar.')
        row=allowed[key];tc,sc=key
        if bool(r.get('Son productos distintos')):
            if sc==tc:raise ValueError('No descartes un código idéntico sin corregir su identidad en el origen.')
            rejected.append(row);continue
        if row['Ya atribuido a'] and row['Ya atribuido a']!=tc:raise ValueError('Una venta no se puede atribuir a dos productos: '+sc)
        if sc in claimed and claimed[sc]!=tc:raise ValueError('Seleccionaste la misma referencia para dos productos: '+sc)
        claimed[sc]=tc;chosen.append(row)
    report=plan['report'].set_index('Código inventario');absence_codes={code_key_v714(c) for c in absence_codes}
    for tc in absence_codes:
        if tc not in report.index or report.at[tc,'Códigos ventas aplicados'] or report.at[tc,'Candidatos'] or 'Hay venta sin código' in report.at[tc,'Motivo']:
            raise ValueError('No puedes certificar ausencia si hay ventas o equivalencias pendientes: '+tc)
    init_code_links_v7184();stamp=datetime.now().isoformat(timespec='microseconds')
    with db() as con:
        for row in rejected:
            sc=row['Código ventas'];tc=row['Código inventario']
            con.execute('INSERT OR REPLACE INTO v7184_rejected_links VALUES (?,?,?,?,?,?)',
                        (plan['site'],sc,tc,row['Descripción ventas'],row['Descripción inventario'],stamp))
            con.execute('DELETE FROM v7184_code_links WHERE site=? AND source_code=? AND target_code=?',(plan['site'],sc,tc))
            con.execute('INSERT INTO v7184_identity_audit(site,source_code,target_code,action,details,created_at) VALUES (?,?,?,?,?,?)',
                        (plan['site'],sc,tc,'PRODUCTOS DISTINTOS',json.dumps(row,ensure_ascii=False),stamp))
        for row in chosen:
            sc=row['Código ventas'];tc=row['Código inventario']
            con.execute('DELETE FROM v7184_rejected_links WHERE site=? AND source_code=? AND target_code=?',(plan['site'],sc,tc))
            con.execute('INSERT INTO v7184_code_links VALUES (?,?,?,?,?,?) ON CONFLICT(site,source_code) DO UPDATE SET target_code=excluded.target_code,source_description=excluded.source_description,target_description=excluded.target_description,updated_at=excluded.updated_at',
                        (plan['site'],sc,tc,row['Descripción ventas'],row['Descripción inventario'],stamp))
            con.execute('INSERT INTO v7184_identity_audit(site,source_code,target_code,action,details,created_at) VALUES (?,?,?,?,?,?)',
                        (plan['site'],sc,tc,'CONFIRMAR EQUIVALENCIA',json.dumps(row,ensure_ascii=False),stamp))
        for tc in absence_codes:
            con.execute('INSERT OR REPLACE INTO v7184_absence_reviews VALUES (?,?,?,?)',(plan['site'],plan['context'],tc,stamp))
            con.execute('INSERT INTO v7184_identity_audit(site,target_code,action,details,created_at) VALUES (?,?,?,?,?)',
                        (plan['site'],tc,'REVISAR AUSENCIA',plan['context'],stamp))
        if con.execute("SELECT 1 FROM sqlite_master WHERE name='v7_meta'").fetchone():touch_v7(con)
    return {'equivalencias':len(chosen),'distintos':len(rejected),'ausencias_revisadas':len(absence_codes)}


def revoke_identity_link_v7184(site, source_code):
    init_code_links_v7184();sc=code_key_v714(source_code)
    with db() as con:
        before=con.execute('SELECT target_code FROM v7184_code_links WHERE site=? AND source_code=?',(site,sc)).fetchone()
        con.execute('DELETE FROM v7184_code_links WHERE site=? AND source_code=?',(site,sc))
        con.execute('INSERT INTO v7184_identity_audit(site,source_code,target_code,action,details,created_at) VALUES (?,?,?,?,?,?)',
                    (site,sc,before[0] if before else '', 'REVOCAR','Usuario revocó la equivalencia',datetime.now().isoformat(timespec='microseconds')))
        if con.execute("SELECT 1 FROM sqlite_master WHERE name='v7_meta'").fetchone():touch_v7(con)


def identity_version_v7184():
    if not DB_PATH.exists():return V7184_IDENTITY_VERSION
    with db() as con:
        if not con.execute("SELECT 1 FROM sqlite_master WHERE name='v7184_identity_audit'").fetchone():return V7184_IDENTITY_VERSION
        r=con.execute('SELECT COALESCE(MAX(id),0) FROM v7184_identity_audit').fetchone()
    return V7184_IDENTITY_VERSION+':'+str(r[0])


def render_identity_review_v7184(plan, key):
    if not plan or plan['report'].empty:return
    report=plan['report'];pending=int(report['Identidad pendiente'].sum());related=int(report['Coincidencia'].eq('RELACIONADO').sum())
    st.caption(f'CRUCE DE CÓDIGOS · {related} relacionados por variantes/equivalencias · {pending} identidades pendientes. Un pendiente nunca se presenta como venta cero.')
    with st.expander('Coincidencias de códigos · ver y resolver sólo las excepciones',expanded=False):
        exceptions = report.loc[~report['Coincidencia'].eq('EXACTO')]
        st.dataframe(exceptions.head(250),hide_index=True,width='stretch')
        if len(exceptions)>250:st.caption('Vista de las primeras 250 excepciones; la descarga conserva toda la auditoría.')
        st.caption('La referencia de inventario no se cambia. Las cantidades originales de ventas permanecen registradas. Parecido en letras, sufijos o descripción exige confirmación.')
        candidates=plan['candidates'];edited=[];absence=[]
        with st.form(key+'_form_'+plan['context'][:16]):
            if not candidates.empty:
                edit=st.data_editor(candidates,hide_index=True,width='stretch',num_rows='fixed',
                     disabled=[c for c in candidates.columns if c not in {'Confirmar equivalencia','Son productos distintos'}],
                     key=key+'_editor_'+plan['context'][:16])
                edited=edit.to_dict('records')
            no_candidates=report.loc[report['Códigos ventas aplicados'].eq('')&report['Candidatos'].eq(''),'Código inventario'].tolist()
            if no_candidates:
                absence=st.multiselect('Sólo tras revisar A2: confirmar SIN REGISTROS en estas fuentes',no_candidates,key=key+'_absence_'+plan['context'][:16])
                st.caption('Esta confirmación se limita a los archivos y meses actuales; no se hereda a ventas nuevas. No sustituye una fila ilegible ni un mes faltante.')
            confirmed=st.checkbox('Verifiqué las referencias seleccionadas y sus descripciones',key=key+'_confirm_'+plan['context'][:16])
            submit=st.form_submit_button('Guardar revisión de coincidencias',type='primary')
        if submit:
            try:
                save_identity_review_v7184(plan,edited,absence,confirm=confirmed)
                st.session_state['v7184_review_saved'] = True
                for name in ['v715_calculation','v715_full_exports','v715_selected_exports','v714_full_result','v714_full_exports']:st.session_state.pop(name,None)
                st.rerun()
            except ValueError as exc:st.error(str(exc))
        links=identity_store_v7184(plan['site'])
        if links:
            selection=st.selectbox('Equivalencia guardada que deseas revocar',['']+sorted(links),key=key+'_revoke_code')
            if st.button('Revocar equivalencia seleccionada',disabled=not selection,key=key+'_revoke'):
                revoke_identity_link_v7184(plan['site'],selection)
                for name in ['v715_calculation','v715_full_exports','v715_selected_exports','v714_full_result','v714_full_exports']:st.session_state.pop(name,None)
                st.rerun()
        st.download_button('Descargar auditoría del cruce',export_csv_bytes(report),'Cruce_codigos_'+safe_slug(plan['site'])+'.csv','text/csv',key=key+'_download',on_click='ignore')


def relate_period_sales_v7184(inv, sales, site):
    if sales.empty:
        records=[]
    else:
        records=[dict(r,Mes='PERIODO',**{'Fuente identidad':'Período agregado'}) for r in sales.to_dict('records')]
    plan=resolve_product_codes_v7184(inv,records,site)
    related=sales.copy()
    if 'Código' not in related:related['Código']=pd.Series(dtype=str)
    related['Código original ventas']=related['Código']
    related['Código']=related['Código'].map(lambda c:plan['mapping'].get(code_key_v714(c),code_key_v714(c)))
    # Coexistencias quedan pendientes, por lo tanto la selección segura no duplica.
    return related,plan


def protect_period_identity_v7184(result,plan):
    info=plan['report'].set_index('Código inventario');out=result.copy()
    out['Coincidencia código']=out['Código'].map(info['Coincidencia'])
    out['Códigos de ventas relacionados']=out['Código'].map(info['Códigos ventas aplicados'])
    bad=out['Código'].isin(plan['pending'])
    out['Identidad pendiente']=bad
    for col in ['Ventas','Ventas utilizadas','Demanda Mensual','Stock Mínimo','Stock Máximo','Mínimo automático','Máximo automático','Punto de Reorden']:
        if col in out:out[col]=pd.to_numeric(out[col],errors='coerce').astype(float);out.loc[bad,col]=np.nan
    for col in ['Compra Sugerida','Retiro Almacén','Capital Inmovilizado ($)','Costo Compra Estimada ($)']:
        if col in out:out.loc[bad,col]=0.0
    for col,text in [('Estado','PENDIENTE — IDENTIDAD'),('Acción','REVISAR COINCIDENCIA DE CÓDIGO'),('Sin movimiento','No evaluable')]:
        out[col]=out[col].astype(object);out.loc[bad,col]=text
    for col in ['Revisión del cálculo','Bloqueo operativo']:
        if col not in out:out[col]=''
        out.loc[bad,col]=out.loc[bad,'Código'].map(info['Motivo'])
    out.attrs['v7184_identity_plan']=serialize_identity_plan_v7184(plan)
    return out


def validate_monthly_limits_v7184(result):
    """Invariante previa a PDF/Excel/A2: no emite un cero falso ni otro cálculo."""
    import math
    errors=[];months=result['months'];rounding=result['summary']['redondeo']
    for r in result['data'].to_dict('records'):
        code=str(r['Código']);values=[numeric_v714(r.get('Unidades '+m)) for m in months]
        mx=numeric_v714(r.get('Máximo'));mn=numeric_v714(r.get('Mínimo'))
        if r.get('Identidad pendiente'):
            if np.isfinite(mx) or np.isfinite(mn) or r.get('Lista para A2'):errors.append(code+': identidad pendiente con límites/selección')
            continue
        if not all(np.isfinite(v) for v in values):
            if np.isfinite(mx):errors.append(code+': máximo con meses incompletos')
            continue
        top=sorted(values,reverse=True)[:2];expected=sum(top)
        if np.isfinite(mx):
            if abs(mx-expected)>1e-8:errors.append(code+': máximo no corresponde a los dos mayores meses')
            half=mx*.5;minimum=half if rounding=='exact' else math.ceil(round(half,10))
            if not np.isfinite(mn) or abs(mn-minimum)>1e-8:errors.append(code+': mínimo no corresponde a 50%')
            if mx==0 and any(v>0 for v in values):errors.append(code+': cero con actividad positiva/ajustes requiere revisión')
    if errors:raise ValueError('Exportación bloqueada por verificación: '+'; '.join(errors[:12]))
    return True


@st.cache_data(show_spinner=False,max_entries=12)
def cached_monthly_sources_v7184(site, keys, data_version):
    return load_monthly_sources_v715(site,list(keys))


def render_catalog_inventory_v7184(file,key):
    """El mismo revisor del cargador, ahora también en el comparativo por marca."""
    raw=file.getvalue()
    try:return cached_supplier_master_v714(raw,file.name)
    except ValueError:
        parsed=parse_a2_report(raw,file.name,'inventario')
        reasons=parsed.get('metadata',{}).get('blocking_reasons',[])
        if any(r in reasons for r in ['missing_codes','miss_codes','duplicate_codes']):
            parsed=_render_inventory_cleanup_v75(parsed,key)
            if parsed['metadata'].get('blocking_reasons'):
                detail=parsed['data'].loc[parsed['data']['Código'].eq('')|parsed['data']['Código'].duplicated(keep=False)]
                st.dataframe(detail,hide_index=True,width='stretch')
                raise ValueError('Hay productos sin código o repetidos. Corrige las filas visibles y pulsa Aplicar revisión a esta carga.')
            return {'data':parsed['data'],'metadata':parsed['metadata']}
        md=parsed.get('metadata',{})
        st.dataframe(pd.DataFrame(md.get('rejected_rows',[])),hide_index=True,width='stretch') if md.get('rejected_rows') else None
        labels={'total_mismatch':'Los totales no concilian con el original','unreadable_rows':'Hay cantidades ilegibles'}
        raise ValueError('; '.join(labels.get(r,r) for r in reasons) or 'La lectura no concilia; revisa el archivo original')
# FIN 7.18.4


def code_key_v714(value):
    if value is None or (not isinstance(value, str) and pd.isna(value)):
        return ''
    # Internal spaces, punctuation and leading zeros are significant. Never use
    # a fuzzy match or remove all hyphens to merge two distinct product codes.
    return unicodedata.normalize('NFKC',str(value)).strip().upper()


def numeric_v714(value):
    if value is None or value is pd.NA:
        return np.nan
    if isinstance(value,(bool,np.bool_)):
        return np.nan
    if isinstance(value,(int,float,np.number)):
        return float(value) if np.isfinite(value) else np.nan
    text=str(value).strip()
    if not text:
        return np.nan
    if ',' in text:
        return _ranking_number_v714(text)
    try:
        val=float(text)
        return val if np.isfinite(val) else np.nan
    except (TypeError,ValueError):
        return np.nan


def read_supplier_master_v714(raw, filename):
    parsed = parse_a2_report(raw, filename, 'inventario')
    if parsed.get('kind') != 'inventario':
        raise ValueError('El catálogo base debe ser el inventario completo del proveedor, no un ranking de ventas.')
    meta = dict(parsed['metadata'])
    if meta.get('blocking_reasons') or meta.get('reconciled') is False:
        raise ValueError('Revisa la lectura del inventario: ' + '; '.join(meta.get('blocking_reasons',[]) or ['No concilia con los totales impresos']))
    frame = parsed['data'].copy()
    # Preserve the FULL universe for reconciliation. The generic preparator may
    # set aside zero-balance ELIMINAR records; they remain visible here.
    restored=[]
    for item in meta.get('cleanup_v75',{}).get('changes',[]):
        if item.get('Acción')=='Apartado automático':
            restored.append({'Código':item.get('Código original',''), 'Descripción':item.get('Descripción',''),
                             'Existencia':item.get('Existencia',np.nan), 'Costo':np.nan,
                             'Valor inventario A2':item.get('Valor inventario A2',np.nan),
                             'Fila origen':item.get('Fila origen'), 'Revisión catálogo':'Marcado ELIMINAR; conservar en auditoría, no enviar a A2'})
    if restored:
        frame = pd.concat([frame,pd.DataFrame(restored)],ignore_index=True)
    if 'Fila origen' in frame:
        frame=frame.sort_values('Fila origen',kind='stable').reset_index(drop=True)
    frame['Código'] = frame['Código'].map(code_key_v714)
    if frame['Código'].eq('').any() or frame['Código'].duplicated().any():
        raise ValueError('El inventario contiene códigos vacíos o repetidos. No se fusionaron automáticamente.')
    frame['Archivo inventario'] = filename
    frame['Fecha inventario'] = meta.get('snapshot_date') or meta.get('report_date') or ''
    frame['Revisión catálogo'] = frame.get('Revisión catálogo',pd.Series('',index=frame.index)).fillna('')
    if len(frame)>30000:
        raise ValueError('Divide el catálogo por proveedor; este cruce admite hasta 30.000 productos.')
    meta.update(filename=filename,sha256=hashlib.sha256(raw).hexdigest(),row_count_full=len(frame),restored_catalog_rows=len(restored))
    return {'data':frame,'metadata':meta,'warnings':parsed.get('warnings',[])}


def read_previous_plan_v714(raw, filename):
    if not raw:
        return pd.DataFrame(columns=V714_PLAN_COLUMNS+['Fila original'])
    data = _read_excel_fast(io.BytesIO(raw),header=None,dtype=object)
    wanted={normalize_key(x):x for x in V714_PLAN_COLUMNS}
    aliases={'stock minimo':'Mínimo','stock maximo':'Máximo','existencias':'Existencia','codigo producto':'Código'}
    located=None
    for i,row in data.head(80).iterrows():
        mapping={}
        for j,value in enumerate(row):
            key=normalize_key(value)
            dest=wanted.get(key) or aliases.get(key)
            if dest and dest not in mapping:
                mapping[dest]=j
        if {'Código','Mínimo','Máximo'}.issubset(mapping):
            located=(i,mapping);break
    if located is None:
        raise ValueError('La planilla anterior debe contener Código, Mínimo y Máximo. No se detectó su encabezado.')
    header,mapping=located
    records=[]
    for i,row in data.iloc[header+1:].iterrows():
        code=code_key_v714(row.iloc[mapping['Código']])
        if not code or normalize_key(code).startswith(('total registros','total items','codigo')):
            continue
        record={'Código':code,'Fila original':int(i)+1}
        for name in V714_PLAN_COLUMNS[1:]:
            value=row.iloc[mapping[name]] if name in mapping else None
            record[name]=str(value or '').strip() if name=='Descripción' else numeric_v714(value)
        if all(pd.isna(record[c]) for c in ['Mínimo','Máximo','Existencia']):
            continue
        records.append(record)
    result=pd.DataFrame(records)
    if not result.empty and result['Código'].duplicated().any():
        raise ValueError('Hay códigos repetidos en la planilla anterior; revisa cuál corresponde antes de comparar.')
    return result


def monthly_entry_v714(parsed, name=None):
    """Accept a genuine complete calendar month, never split a six-month total."""
    import calendar
    meta=dict(parsed['metadata']);start=meta.get('period_start');end=meta.get('period_end')
    try:
        first,last=date.fromisoformat(start),date.fromisoformat(end)
    except (TypeError,ValueError) as exc:
        raise ValueError('El reporte mensual no tiene fechas verificables: '+str(name or meta.get('filename',''))) from exc
    if first.day!=1 or first.year!=last.year or first.month!=last.month or last.day!=calendar.monthrange(last.year,last.month)[1]:
        raise ValueError(f'{name}: se necesita UN mes completo por archivo. Un acumulado de varios meses no se reparte artificialmente.')
    if last>date.today():
        raise ValueError('El archivo tiene ventas futuras; revisa las fechas del reporte.')
    if meta.get('blocking_reasons') or meta.get('reconciled') is False:
        raise ValueError(f'{name}: existen incidencias de lectura o conciliación.')
    frame=parsed['data'].copy()
    if not {'Código','Ventas'}.issubset(frame):
        raise ValueError(f'{name}: falta el detalle de código y unidades vendidas.')
    frame['Código']=frame['Código'].map(code_key_v714)
    if frame['Código'].eq('').any() or frame['Código'].duplicated().any():
        raise ValueError(f'{name}: hay códigos pendientes/repetidos; deben revisarse antes del cruce.')
    meta['filename']=name or meta.get('filename','Archivo mensual')
    return {'data':frame,'metadata':meta,'month':first.strftime('%Y-%m')}


def saved_monthly_entries_v714(site, batch_ids):
    entries=[]
    with db() as con:
        for bid in dict.fromkeys(int(v) for v in batch_ids):
            b=pd.read_sql_query('SELECT * FROM v7_sales_batches WHERE id=? AND site=?',con,params=(bid,site))
            if b.empty:
                raise ValueError('Cambió un reporte guardado. Vuelve a seleccionar los archivos de la base.')
            rec=b.iloc[0].to_dict()
            frame=pd.read_sql_query('SELECT code AS Código, description AS Descripción, units AS Ventas, row_no AS "Fila origen" FROM v7_sales_items WHERE batch_id=? ORDER BY row_no',con,params=(bid,))
            if frame['Código'].duplicated().any():
                # Detail can have several lines per SKU; explicitly sum them
                # within ONE source only. Never add overlapping sources.
                frame=frame.groupby('Código',as_index=False,dropna=False).agg({'Descripción':'first','Ventas':lambda v:v.sum(min_count=len(v)),'Fila origen':'min'})
            meta={'period_start':rec['start_date'],'period_end':rec['end_date'],'site':site,
                  'currency':rec['currency'],'filename':rec['file_name'],'sha256':rec['sha256'],
                  'batch_id':bid,'scope':rec['scope'],'source':'Base NEXUS local'}
            entries.append(monthly_entry_v714({'data':frame,'metadata':meta},rec['file_name']))
    return entries


def reconcile_supplier_v714(master, rankings, monthly_entries, previous, months,
                             rounding='up', review_returns=False, confirmed_complete_months=()):
    """Full catalogue left join + provenance; no absent month defaults to zero.

    Independent reports are alternatives, not addends. Equal overlapping values
    are corroboration. Different overlapping values block that SKU for review.
    Zero imputation only follows the explicit complete-month confirmation.
    """
    import calendar,math
    months=[str(m) for m in months]
    if len(set(months)) != len(months):
        raise ValueError('Hay meses repetidos. Cada mes debe participar una sola vez.')
    months=sorted(months)
    if len(months)<2 or any(not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])',m) for m in months):
        raise ValueError('Selecciona por lo menos dos meses completos, distintos y consecutivos.')
    ords=[int(m[:4])*12+int(m[5:]) for m in months]
    if any(b-a!=1 for a,b in zip(ords,ords[1:])):
        raise ValueError('Faltan meses intermedios; no se reemplazan por ceros.')
    if any(date(int(m[:4]),int(m[5:]),calendar.monthrange(int(m[:4]),int(m[5:]))[1])>date.today() for m in months):
        raise ValueError('El análisis incluye un mes que todavía no ha cerrado.')
    if rounding not in {'up','exact'}:
        raise ValueError('Regla de redondeo no válida.')
    inv=master['data'].copy();meta=dict(master.get('metadata',{}))
    if inv.empty or not {'Código','Descripción','Existencia'}.issubset(inv):
        raise ValueError('El catálogo debe contener productos, códigos, descripciones y existencias.')
    inv['Código']=inv['Código'].map(code_key_v714)
    if inv['Código'].eq('').any() or inv['Código'].duplicated().any():
        raise ValueError('No se puede reconciliar un catálogo con códigos vacíos o duplicados.')
    keys=set(inv['Código']);evidence={};source_info=[];reading_issues={};visible_alias={};pdf_rows={}
    def add(code,month,quantity,source,location,description=''):
        evidence.setdefault((code,month),[]).append({'code':code,'month':month,'quantity':numeric_v714(quantity),
                                                   'source':source,'location':location,'description':description})
    for parsed in rankings:
        frame=parsed['data'];md=parsed['metadata'];name=md.get('filename','Ranking PDF')
        if any(not m.get('full_month') for m in md.get('months',[]) if m.get('period') in months):
            raise ValueError(name+': contiene meses parciales.')
        source_info.append({'Archivo':name,'Tipo':'Ranking mensual PDF','SHA256':md.get('sha256',''),
                            'Desde':md.get('date_from',''),'Hasta':md.get('date_to',''),
                            'Fecha emisión':md.get('report_date',''),'Filas':len(frame),'Departamento':md.get('department',''),
                            'Proveedor filtro':md.get('supplier',''),'Advertencias':' | '.join(md.get('global_warnings',[]))})
        if frame['Código'].map(code_key_v714).duplicated().any():
            raise ValueError(name+': códigos repetidos en el ranking; no se fusionaron.')
        for r in frame.to_dict('records'):
            code=code_key_v714(r['Código']);visible=code_key_v714(r.get('Código visible PDF',code))
            if visible!=code:
                visible_alias.setdefault(visible,set()).add(code)
            pdf_rows.setdefault(code,[]).append(dict(r,archivo=name))
            if str(r.get('Revisión lectura','') or '').strip():
                reading_issues.setdefault(code,[]).append(name+': '+str(r['Revisión lectura']))
            for month in months:
                if 'Unidades '+month in r:
                    add(code,month,r['Unidades '+month],name,f"pág. {r.get('Página PDF','?')}, fila {r.get('Fila PDF','?')}",r.get('Descripción',''))
    explicit_months=set()
    for entry in monthly_entries:
        frame=entry['data'];md=entry['metadata'];month=entry['month'];name=md.get('filename','Ventas mensuales')
        if month not in months:
            continue
        explicit_months.add(month)
        source_info.append({'Archivo':name,'Tipo':'Mes completo · '+md.get('source','archivo'),
                            'SHA256':md.get('sha256',''),'Desde':md.get('period_start',''),'Hasta':md.get('period_end',''),
                            'Fecha emisión':md.get('report_date',''),'Filas':len(frame),'Departamento':md.get('department',''),
                            'Proveedor filtro':md.get('scope',''),'Advertencias':''})
        for r in frame.to_dict('records'):
            add(code_key_v714(r['Código']),month,r['Ventas'],name,f"fila {r.get('Fila origen','?')}",r.get('Descripción',''))
    identity_sources=[{'Código':code,'Descripción':e.get('description',''),'Ventas':e['quantity'],'Mes':month,'Fuente identidad':e['source']}
                      for (code,month),items in evidence.items() for e in items]
    identity_plan=resolve_product_codes_v7184(inv,identity_sources,meta.get('site',''))
    remapped={}
    for (sc,month),items in evidence.items():
        tc=identity_plan['mapping'].get(sc,sc)
        remapped.setdefault((tc,month),[]).extend(items)
    evidence=remapped
    for sc,tc in identity_plan['mapping'].items():
        if sc!=tc and sc in pdf_rows:pdf_rows[tc]=pdf_rows[sc]
        if sc!=tc and sc in reading_issues:reading_issues.setdefault(tc,[]).extend(reading_issues[sc])
    for tc,issues in identity_plan['pending'].items():reading_issues.setdefault(tc,[]).extend(issues)
    zero_months=set(confirmed_complete_months)&explicit_months&set(months)
    for code in keys:
        for month in zero_months:
            if (code,month) not in evidence:
                add(code,month,0,'Confirmación del operador: reporte mensual completo','Ausente en el mes completo; cero confirmado')
    old={};old_original={};old_map_notes={}
    if previous is not None and not previous.empty:
        for r in previous.to_dict('records'):
            original=code_key_v714(r['Código']);code=original
            if code not in keys and len(visible_alias.get(code,set()))==1:
                candidate=next(iter(visible_alias[code]))
                if candidate in keys:
                    code=candidate;old_map_notes[code]=f'Código recortado en planilla anterior: {original} → {code}; recuperado del texto del PDF'
            if code in old:
                raise ValueError('Dos filas anteriores se relacionan con el mismo código: '+code)
            old[code]=r;old_original[code]=original
    rows=[];trace=[]
    for r in inv.to_dict('records'):
        code=r['Código'];oldrow=old.get(code,{});candidates=pdf_rows.get(code,[])
        output={'Código':code,'Descripción':str(r.get('Descripción','') or ''),'Existencia':numeric_v714(r.get('Existencia')),
                'Fecha inventario':r.get('Fecha inventario') or meta.get('snapshot_date') or meta.get('report_date',''),
                'Fila inventario':r.get('Fila origen',r.get('Fila inventario')),
                'En planilla anterior':'Sí' if oldrow else 'No',
                'Código anterior':old_original.get(code,''),
                'Fila anterior':oldrow.get('Fila original'),
                'Mínimo anterior':numeric_v714(oldrow.get('Mínimo')),'Máximo anterior':numeric_v714(oldrow.get('Máximo')),
                'Existencia anterior':numeric_v714(oldrow.get('Existencia')),
                'Existencia ranking':numeric_v714(candidates[0].get('Existencia')) if candidates else np.nan,
                'Código visible PDF':code_key_v714(candidates[0].get('Código visible PDF',code)) if candidates else '',
                'Página PDF':candidates[0].get('Página PDF') if candidates else None,
                'Fila PDF':candidates[0].get('Fila PDF') if candidates else None}
        blockers=list(reading_issues.get(code,[]));notes=[];quantities=[];unavailable=[];conflicts=[]
        for month in months:
            ev=evidence.get((code,month),[])
            values=[e['quantity'] for e in ev]
            if not values or not all(np.isfinite(v) for v in values):
                value=np.nan;unavailable.append(month)
            elif max(values)-min(values)>1e-8:
                value=np.nan;conflicts.append(month)
            else:
                value=values[0]
            quantities.append(value);output['Unidades '+month]=value
            for e in ev:
                trace.append({'Código':code,'Mes':month,'Unidades':e['quantity'],'Archivo':e['source'],
                              'Ubicación':e['location'],'Estado':'Conflicto' if month in conflicts else 'No numérico' if not np.isfinite(e['quantity']) else 'Leído'})
        output['Meses con dato']=sum(np.isfinite(v) for v in quantities)
        if unavailable:
            blockers.append('Sin evidencia mensual: '+', '.join(unavailable))
        if conflicts:
            blockers.append('Fuentes con cantidades diferentes: '+', '.join(conflicts))
        valid_sales=all(np.isfinite(v) for v in quantities) and not reading_issues.get(code)
        maximum=minimum=half=total=np.nan;best=[]
        if valid_sales:
            total=sum(quantities)
            best=sorted(zip(months,quantities),key=lambda x:(x[1],x[0]),reverse=True)[:2]
            maximum=best[0][1]+best[1][1]
            if maximum<0:
                maximum=np.nan;blockers.append('Los dos meses mayores suman ventas negativas; revisar ajustes')
            else:
                half=maximum*0.5
                minimum=float(math.ceil(round(half,10))) if rounding=='up' else half
            if any(q<0 for q in quantities):
                notes.append('Se conservan ventas netas negativas; no se convirtieron en cero')
                if not review_returns:
                    blockers.append('Revisar devoluciones/ventas negativas antes de usar la planilla')
        if not np.isfinite(output['Existencia']):
            blockers.append('Existencia no informada')
        elif output['Existencia']<0:
            blockers.append('Existencia negativa: límites calculables, pedido bloqueado hasta revisar saldo')
        retired=str(r.get('Revisión catálogo','') or '').strip()
        if normalize_key(output['Descripción']) in {'eliminar','elminar'}:
            retired='Catálogo marcado ELIMINAR: confirmar baja; no enviar límites a A2'
        if retired:
            blockers.append(retired)
        if code in old_map_notes:notes.append(old_map_notes[code])
        if pd.notna(output['Existencia anterior']) and output['Existencia anterior']!=output['Existencia']:
            notes.append('Cambió la existencia entre fuentes/cortes; se usa el inventario del catálogo')
        if valid_sales and maximum==0:
            blockers.append('Demanda neta nula: confirmar política de límites cero')
        theoretical_order=max(maximum-output['Existencia'],0) if np.isfinite(maximum) and np.isfinite(output['Existencia']) and output['Existencia']>=0 else np.nan
        output.update({'Datos mensuales válidos':valid_sales,'Ventas seis meses':total,'Mes mayor 1':best[0][0] if best else '',
                       'Unidades mayor 1':best[0][1] if best else np.nan,'Mes mayor 2':best[1][0] if best else '',
                       'Unidades mayor 2':best[1][1] if best else np.nan,'Mínimo 50% exacto':half,
                       'Mínimo':minimum,'Máximo':maximum,'A pedir':theoretical_order,
                       'Regla redondeo':'Hacia arriba a unidad entera' if rounding=='up' else '50% exacto',
                       'Lista para A2':not blockers,
                       'Estado':'PENDIENTE' if blockers else 'CALCULADO · REVISABLE',
                       'Motivo':' | '.join(dict.fromkeys(blockers)),
                       'Observaciones':' | '.join(notes)})
        rows.append(output)
    result=pd.DataFrame(rows)
    result['Diferencia mínimo']=result['Mínimo']-result['Mínimo anterior']
    result['Diferencia máximo']=result['Máximo']-result['Máximo anterior']
    result['Diferencia existencia']=result['Existencia']-result['Existencia anterior']
    raw_old=set(previous['Código'].map(code_key_v714)) if previous is not None and not previous.empty else set()
    result['Falta código literal anterior']=~result['Código'].isin(raw_old)
    outside=sorted({c for c,m in evidence if c not in keys}|{c for c in old if c not in keys})
    extras=pd.DataFrame([{'Código':c,'Motivo':'Aparece en ventas/planilla, pero NO en el catálogo cargado. No se atribuye a este proveedor sin confirmar.'} for c in outside],columns=['Código','Motivo'])
    sources=pd.DataFrame([{'Archivo':meta.get('filename','Inventario guardado'),'Tipo':'Catálogo completo','SHA256':meta.get('sha256',''),
                           'Fecha emisión':meta.get('snapshot_date') or meta.get('report_date',''),'Filas':len(inv)}]+source_info)
    summary={'productos_catalogo':len(result),'productos_planilla_anterior':len(previous) if previous is not None else 0,
             'ausentes_codigo_literal':int(result['Falta código literal anterior'].sum()),
             'codigos_recuperados':len(old_map_notes),'productos_con_calculo':int(result['Máximo'].notna().sum()),
             'productos_sin_calculo':int(result['Máximo'].isna().sum()),
             'nuevos_con_calculo':int((result['En planilla anterior'].eq('No')&result['Máximo'].notna()).sum()),
             'listos_para_a2':int(result['Lista para A2'].sum()),'pendientes_revision':int((~result['Lista para A2']).sum()),
             'existencias_distintas':int(result['Diferencia existencia'].fillna(0).ne(0).sum()),
             'fuera_catalogo':len(extras),'meses':months,'redondeo':rounding,
             'devoluciones_revisadas':bool(review_returns),'meses_ausencias_cero_confirmadas':sorted(zero_months)}
    return {'data':result,'faltantes':result.loc[result['Falta código literal anterior']].copy(),
            'evidence':pd.DataFrame(trace),'extras':extras,'sources':sources,'summary':summary,'months':months,'identity_plan':identity_plan,
            'metadata':{'inventory':meta,'policy':'Máximo = suma de los dos meses de mayor venta por producto; mínimo = 50% del máximo',
                        'rankings':[p['metadata'] for p in rankings], 'rounding':rounding,'note':'A pedir completa al máximo; no descuenta tránsito ni comprometidos. No es una orden ejecutada.'}}


def reconciliation_fingerprint_v714(parts):
    def default(value):
        if isinstance(value,(date,datetime)):
            return value.isoformat()
        if isinstance(value,np.generic):
            return value.item()
        return str(value)
    return hashlib.sha256(json.dumps(parts,sort_keys=True,ensure_ascii=False,default=default).encode()).hexdigest()


def save_supplier_run_v714(result, site, supplier, fingerprint):
    payload={'summary':result['summary'],'metadata':result['metadata'],'months':result['months'],
             'tables':{k:json.loads(result[k].to_json(orient='records',force_ascii=False)) for k in ['data','faltantes','evidence','extras','sources']}}
    run_id=str(uuid.uuid4())
    with db() as con:
        con.execute('INSERT INTO v714_supplier_runs VALUES(?,?,?,?,?,?)',
                    (run_id,datetime.now().isoformat(timespec='seconds'),site,supplier,fingerprint,json.dumps(payload,ensure_ascii=False,allow_nan=False)))
    return run_id


def supplier_plan_metadata_v714(result,site,supplier):
    meta=result['metadata']['inventory']
    return {'Sede':site,'Título encabezado':'MAKROPETROL, C.A.' if site=='Matriz Makropetrol' else site,
            'Dirección línea 1':'CTRA ANTIGUA BARCELONA ARAGUITA, PROLONGACI' if site=='Matriz Makropetrol' else '',
            'Dirección línea 2':'N SAN CARLOS LOCAL NRO. 2, SECTOR LA ADUANA' if site=='Matriz Makropetrol' else '',
            'Teléfono encabezado':'0281-271.86.68' if site=='Matriz Makropetrol' else '',
            'Departamento encabezado':supplier,
            'Factor libre':'Máximo = suma de 2 mejores meses; mínimo 50%' + (' redondeado arriba' if result['summary']['redondeo']=='up' else ' exacto'),
            'Origen':'Catálogo + ventas mensuales verificadas','Ajustar texto a celda':True,
            'Período ventas':result['months'][0]+' a '+result['months'][-1],
            'Fecha inventario':meta.get('snapshot_date') or meta.get('report_date','')}


def build_supplier_audit_excel_v714(result,site,supplier):
    """Standalone runtime export: full six-column review + auditable formulas.

    Keeps the original A2 presentation distinct from its audit sheets. Unknown
    sales remain blank. No empty catalogue rows are silently removed.
    """
    from openpyxl import Workbook
    from openpyxl.styles import Font,PatternFill,Alignment
    from openpyxl.comments import Comment
    from openpyxl.utils import get_column_letter
    from openpyxl.workbook.properties import CalcProperties
    from openpyxl.worksheet.page import PageMargins
    wb=Workbook();plan=wb.active;plan.title='Planilla A2'
    audit=wb.create_sheet('Cálculo y revisión');summary=wb.create_sheet('LEER PRIMERO')
    # Fixed explanatory inputs; formulas reference them, not hidden magic numbers.
    summary.append(['REVISIÓN COMPLETA · NO CARGAR FILAS PENDIENTES EN A2'])
    summary.append(['Proveedor / grupo',supplier]);summary.append(['Sede',site])
    summary.append(['Factor mínimo',.5]);summary.append(['Redondear arriba',1 if result['summary']['redondeo']=='up' else 0])
    summary.append(['Meses seleccionados',', '.join(result['months'])])
    summary.append(['Regla','Máximo: suma de las 2 mayores cantidades mensuales por código. Mínimo: 50%.'])
    summary.append(['N/D o celda vacía','No significa cero: falta evidencia o existe una incidencia.'])
    summary.append(['A pedir','Máximo − existencia, mínimo cero. Saldo negativo: pedido pendiente. No descuenta tránsito.'])
    summary.append(['Existencias','Del inventario completo cargado; no se actualizan por la fecha de impresión.'])
    summary.append(['Uso','Planilla A2 es revisión del catálogo entero; para importar usa la descarga de selección validada desde la app.'])
    names={'productos_catalogo':'Productos en catálogo','productos_planilla_anterior':'Productos de planilla anterior','ausentes_codigo_literal':'Sin coincidencia literal en planilla','codigos_recuperados':'Códigos recortados recuperados','productos_con_calculo':'Productos con límites calculados','productos_sin_calculo':'Productos sin evidencia suficiente','nuevos_con_calculo':'Productos omitidos recuperados con cálculo','listos_para_a2':'Disponibles para revisar A2','pendientes_revision':'Pendientes de revisión','existencias_distintas':'Cambios de existencia','fuera_catalogo':'Fuera del catálogo','meses':'Meses usados','redondeo':'Regla de redondeo','devoluciones_revisadas':'Devoluciones revisadas','meses_ausencias_cero_confirmadas':'Meses con ausencia = cero confirmada'}
    for key,value in result['summary'].items():
        summary.append([names.get(key,key),json.dumps(value,ensure_ascii=False) if isinstance(value,(list,dict)) else value])
    rows=result['data'].to_dict('records');months=result['months']
    headers=['Código','Descripción','Existencia']+['Unidades '+m for m in months]+['Ventas seis meses','Máximo','Mínimo 50% exacto','Mínimo','A pedir','Estado','Motivo','En planilla anterior','Código anterior','Mínimo anterior','Máximo anterior','Existencia anterior','Diferencia mínimo','Diferencia máximo','Diferencia existencia','Mes mayor 1','Unidades mayor 1','Mes mayor 2','Unidades mayor 2','Página PDF','Fila PDF','Fila inventario','Observaciones','Datos mensuales válidos']
    audit.append(headers);columns={name:i+1 for i,name in enumerate(headers)}
    cached={}
    def literal(cell,value):
        if value is None or (not isinstance(value,(str,list,dict)) and pd.isna(value)):
            cell.value=None
        elif isinstance(value,str):
            cell.value=value;cell.data_type='s'
        elif isinstance(value,np.generic):cell.value=value.item()
        else:cell.value=value
    def formula(sheet,row,column,expression,value):
        cell=sheet.cell(row,column);cell.value=expression
        cached[f'{sheet.title}!{cell.coordinate}']=value if value is not None and (isinstance(value,str) or pd.notna(value)) else ''
    for i,r in enumerate(rows,2):
        for j,name in enumerate(headers,1):literal(audit.cell(i,j),r.get(name))
        span=f'D{i}:{get_column_letter(3+len(months))}{i}'
        def ref(name):return f'{get_column_letter(columns[name])}{i}'
        sales_gate=f'AND(COUNT({span})={len(months)},{ref("Datos mensuales válidos")}=TRUE)'
        formula(audit,i,columns['Ventas seis meses'],f'=IF({sales_gate},SUM({span}),"")',r.get('Ventas seis meses'))
        formula(audit,i,columns['Máximo'],f'=IF({sales_gate},IF(LARGE({span},1)+LARGE({span},2)>=0,LARGE({span},1)+LARGE({span},2),""),"")',r.get('Máximo'))
        formula(audit,i,columns['Mínimo 50% exacto'],f'=IF(ISNUMBER({ref("Máximo")}),{ref("Máximo")}*\'LEER PRIMERO\'!$B$4,"")',r.get('Mínimo 50% exacto'))
        formula(audit,i,columns['Mínimo'],f'=IF(ISNUMBER({ref("Mínimo 50% exacto")}),IF(\'LEER PRIMERO\'!$B$5=1,ROUNDUP({ref("Mínimo 50% exacto")},0),{ref("Mínimo 50% exacto")}),"")',r.get('Mínimo'))
        formula(audit,i,columns['A pedir'],f'=IF(AND(ISNUMBER({ref("Máximo")}),ISNUMBER(C{i}),C{i}>=0),MAX({ref("Máximo")}-C{i},0),"")',r.get('A pedir'))
        for dest,left,right in [('Diferencia mínimo','Mínimo','Mínimo anterior'),('Diferencia máximo','Máximo','Máximo anterior'),('Diferencia existencia','Existencia','Existencia anterior')]:
            formula(audit,i,columns[dest],f'=IF(AND(ISNUMBER({ref(left)}),ISNUMBER({ref(right)})),{ref(left)}-{ref(right)},"")',r.get(dest))
    # Six-column print contract matches the uploaded planilla (headers at row 9).
    meta=supplier_plan_metadata_v714(result,site,supplier)
    for n,val in [(1,meta['Título encabezado']),(2,meta['Dirección línea 1']),(3,meta['Dirección línea 2']),(4,meta['Teléfono encabezado'])]:
        plan.merge_cells(start_row=n,start_column=2,end_row=n,end_column=4);plan.cell(n,2,val)
    plan['E1']='Generado:';plan['F1']=datetime.now().strftime('%d/%m/%Y')
    plan['E2']='Inventario:';plan['F2']=meta['Fecha inventario'];plan['E3']='Sede:';plan['F3']=site
    for n,val in [(5,'Reposición de Inventario · REVISIÓN COMPLETA'),(6,'Vacíos = pendientes. No asignar cero ni cargar esas filas en A2.'),(7,meta['Factor libre']),(8,'Departamento / grupo: '+supplier+' · '+meta['Período ventas'])]:
        plan.merge_cells(start_row=n,start_column=1,end_row=n,end_column=6);plan.cell(n,1,val)
    for j,name in enumerate(V714_PLAN_COLUMNS,1):plan.cell(9,j,name)
    for i,r in enumerate(rows,10):
        ar=i-8
        literal(plan.cell(i,1),r['Código']);literal(plan.cell(i,2),r['Descripción'])
        for j,name in enumerate(V714_PLAN_COLUMNS[2:],3):
            acol=get_column_letter(columns[name]);formula(plan,i,j,f'=IF(ISNUMBER(\'Cálculo y revisión\'!{acol}{ar}),\'Cálculo y revisión\'!{acol}{ar},"")',r.get(name))
        plan.cell(i,1).comment=Comment(r.get('Motivo') or 'Datos calculados; revisar alcance y aprobar antes de cargar.','NEXUS')
        if not r.get('Lista para A2'):
            for cell in plan[i]:cell.fill=PatternFill('solid',fgColor='FFF2CC')
        plan.row_dimensions[i].height=28 if len(r['Descripción'])>75 else 18
    for name,key in [('Códigos faltantes','faltantes'),('Fuentes','sources'),('Evidencia mensual','evidence'),('Fuera del catálogo','extras')]:
        ws=wb.create_sheet(name);frame=result[key]
        if not len(frame.columns):ws.append(['Sin registros']);continue
        ws.append(list(frame.columns))
        for i,r in enumerate(frame.to_dict('records'),2):
            for j,col in enumerate(frame.columns,1):literal(ws.cell(i,j),r.get(col))
    for ws in wb.worksheets:
        ws.sheet_view.showGridLines=False
        head=9 if ws==plan else 1
        for cell in ws[head]:
            cell.font=Font(bold=True,color='000000' if ws==plan else 'FFFFFF')
            cell.fill=PatternFill('solid',fgColor='C0C0C0' if ws==plan else '176B68')
            cell.alignment=Alignment(wrap_text=True,vertical='center')
        ws.freeze_panes='C10' if ws==plan else 'D2'
        for col in range(1,ws.max_column+1):ws.column_dimensions[get_column_letter(col)].width=18
        ws.column_dimensions['A'].width=20;ws.column_dimensions['B'].width=66 if ws==plan else 45
        for line in ws.iter_rows(min_row=head+1):
            for cell in line:
                cell.alignment=Alignment(vertical='center',wrap_text=cell.column==2)
                if isinstance(cell.value,(int,float)) or cell.data_type=='f':cell.number_format='#,##0.########'
        if ws.max_row>head:ws.auto_filter.ref=f'A{head}:{get_column_letter(ws.max_column)}{ws.max_row}'
    summary.column_dimensions['A'].width=43
    summary.column_dimensions['B'].width=98
    summary.freeze_panes='B4'
    for i in range(1,summary.max_row+1):
        summary.row_dimensions[i].height=32 if i>=7 and i<=11 else 23
        summary.cell(i,2).alignment=Alignment(wrap_text=True,vertical='center')
    plan.print_title_rows='1:9';plan.print_area=f'A1:F{9+len(rows)}'
    plan.sheet_properties.pageSetUpPr.fitToPage=True;plan.page_setup.fitToWidth=1;plan.page_setup.fitToHeight=0
    plan.page_setup.paperSize=plan.PAPERSIZE_A4
    plan.page_margins=PageMargins(left=.25,right=.25,top=.3,bottom=.4)
    for col in ['C','D','E','F']:plan.column_dimensions[col].width=13
    plan.row_dimensions[3].height=30;plan.row_dimensions[6].height=25;plan.row_dimensions[7].height=28
    for cell in [plan['B1'],plan['A5']]:cell.font=Font(name='Arial',bold=True,size=13)
    for r in [6,7,8]:plan.cell(r,1).alignment=Alignment(wrap_text=True)
    for i in range(2,len(rows)+2):
        for j in range(3,4+len(months)):
            audit.cell(i,j).font=Font(color='0000FF')
    wb.calculation=CalcProperties(calcId=191029,fullCalcOnLoad=True)
    output=io.BytesIO();wb.save(output)
    # The existing helper embeds cached numeric values for viewers that do not
    # recalculate. The formula source remains intact for Microsoft Excel.
    return cache_xlsx_values_v714(output.getvalue(),cached)


def cache_xlsx_values_v714(raw, cached):
    from xml.etree import ElementTree as ET
    ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    relns={'r':'http://schemas.openxmlformats.org/package/2006/relationships'}
    mainns=ns['m'];ridns='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
    out=io.BytesIO()
    with zipfile.ZipFile(io.BytesIO(raw)) as src:
        workbook=ET.fromstring(src.read('xl/workbook.xml'));rels=ET.fromstring(src.read('xl/_rels/workbook.xml.rels'))
        target={r.attrib['Id']:r.attrib['Target'] for r in rels}
        sheets={}
        for sh in workbook.find('m:sheets',ns):
            path=target[sh.attrib['{'+ridns+'}id']]
            path=path.lstrip('/') if path.startswith('/') else 'xl/'+path
            sheets[path]=sh.attrib['name']
        with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as dst:
            for info in src.infolist():
                data=src.read(info.filename)
                if info.filename in sheets:
                    root=ET.fromstring(data);sheet=sheets[info.filename]
                    for cell in root.findall('.//m:sheetData/m:row/m:c',ns):
                        key=sheet+'!'+cell.attrib.get('r','')
                        if key not in cached or cell.find('m:f',ns) is None:continue
                        val=cached[key];v=cell.find('m:v',ns)
                        if v is None:v=ET.SubElement(cell,'{'+mainns+'}v')
                        if isinstance(val,str):cell.set('t','str');v.text=val
                        else:cell.attrib.pop('t',None);v.text=str(float(val))
                    data=ET.tostring(root,encoding='utf-8',xml_declaration=True)
                dst.writestr(info,data)
    return out.getvalue()


