    result=state['result'];data=result['data'];s=result['summary']
    render_identity_review_v7184(result.get('identity_plan'),'v7184_supplier')
    st.subheader('4 · Resultado completo: ningún código queda oculto')
    c1,c2,c3,c4=st.columns(4)
