    query=st.text_input('Buscar código o descripción (solo filtra la vista; el informe completo conserva TODOS)',key='v714_full_search')
    if query:view=view[view['Código'].str.contains(query,case=False,regex=False)|view['Descripción'].str.contains(query,case=False,regex=False)]
