# ============================================================================
# NEXUS 7.15 · COMPARATIVO MENSUAL: DOS MEJORES MESES POR CÓDIGO
# No sustituye las políticas de cobertura del motor general ni escribe en A2.
# ============================================================================

V715_VIEW = 'Comparativo mensual · dos mejores meses'
V715_MONTH_NAMES = ('Enero','Febrero','Marzo','Abril','Mayo','Junio',
                    'Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre')


def month_label_v715(month):
    return V715_MONTH_NAMES[int(str(month)[5:7])-1] + ' ' + str(month)[:4]


def monthly_entry_v715(parsed, filename=None):
    """Validate one complete calendar month, keeping unidentified rows in audit.

    A missing code must not block unrelated, identified products. It must not be
    guessed, discarded, or silently included in another product either.
    """
    import calendar
    md = dict(parsed.get('metadata', {}))
    name = filename or md.get('filename', 'Reporte mensual')
    if parsed.get('kind', 'ventas') != 'ventas':
        raise ValueError(name + ': se requiere un reporte de ventas, no inventario.')
    try:
        first = date.fromisoformat(str(md.get('period_start', '')))
        last = date.fromisoformat(str(md.get('period_end', '')))
    except ValueError as exc:
        raise ValueError(name + ': faltan fechas verificables en el encabezado.') from exc
    if (first.day != 1 or first.year != last.year or first.month != last.month
            or last.day != calendar.monthrange(first.year, first.month)[1]):
        raise ValueError(name + ': debe abarcar un mes calendario completo. No se divide un acumulado.')
    if last > date.today():
        raise ValueError(name + ': el mes todavía no ha cerrado.')
    blockers = set(md.get('blocking_reasons') or []) - {'missing_codes'}
    if blockers or md.get('reconciled') is False or md.get('rejected_rows'):
        raise ValueError(name + ': revisar lectura/conciliación: ' + ', '.join(sorted(blockers) or ['totales o filas rechazadas']))
    frame = parsed['data'].copy()
    if not {'Código', 'Descripción', 'Ventas'}.issubset(frame):
        raise ValueError(name + ': se requieren Código, Descripción y unidades vendidas.')
    frame['Código'] = frame['Código'].map(code_key_v714)
    frame['Descripción'] = frame['Descripción'].fillna('').astype(str).str.strip()
    frame['Ventas'] = pd.to_numeric(frame['Ventas'], errors='coerce')
    if frame.empty or not np.isfinite(frame['Ventas'].to_numpy(dtype=float)).all():
        raise ValueError(name + ': no hay detalle válido o existen cantidades no numéricas.')
    known = frame[frame['Código'].ne('')]
    if known['Código'].duplicated().any():
        raise ValueError(name + ': hay códigos repetidos. Revisar el origen, no sumar filas repetidas a ciegas.')
    if 'Fila origen' not in frame:
        frame['Fila origen'] = np.arange(1, len(frame)+1)
    md.update(filename=name, period_start=first.isoformat(), period_end=last.isoformat(),
              row_count=len(frame), identified_count=len(known),
              unidentified_count=int(frame['Código'].eq('').sum()),
              original_units=float(frame['Ventas'].sum()))
    return {'month':first.strftime('%Y-%m'), 'data':frame, 'metadata':md}


@st.cache_data(show_spinner=False, max_entries=18)
def cached_monthly_v715(raw, filename):
    if len(raw) > 32 * 1024 * 1024:
        raise ValueError('Un archivo mensual supera 32 MB.')
    parsed = parse_a2_report(raw, filename, 'ventas')
    parsed['metadata']['sha256'] = hashlib.sha256(raw).hexdigest()
    # The company is evidence from the heading, not inferred from the filename.
    grid = read_a2_grid(raw, filename)
    first_lines = [' '.join(_a2_text(v) for v in row if _a2_text(v)) for row in grid.head(12).values.tolist()]
    parsed['metadata']['company_heading'] = first_lines[0] if first_lines else ''
    return monthly_entry_v715(parsed, filename)


def init_monthly_store_v715():
    """Additive local archive. Original v7 sales tables remain untouched."""
    with db() as con:
        exists = con.execute("SELECT value FROM v7_meta WHERE key='migration_v715'").fetchone()
    if exists:
        return
    with db() as con:
        populated = con.execute('SELECT 1 FROM inventory_snapshots UNION ALL SELECT 1 FROM v7_sales_batches LIMIT 1').fetchone()
    if populated:
        dest = DB_PATH.with_name(f'nexus_respaldo_antes_v715_{datetime.now():%Y%m%d_%H%M%S_%f}.db')
        dest.write_bytes(backup_database_bytes())
    with db() as con:
        con.execute('''CREATE TABLE IF NOT EXISTS v715_monthly_sources (
          id INTEGER PRIMARY KEY AUTOINCREMENT, site TEXT NOT NULL, scope TEXT NOT NULL,
          month TEXT NOT NULL, sha256 TEXT NOT NULL, filename TEXT NOT NULL,
          stored_at TEXT NOT NULL, metadata TEXT NOT NULL, payload TEXT NOT NULL,
          UNIQUE(site, scope, sha256))''')
        con.execute('CREATE INDEX IF NOT EXISTS idx_v715_months ON v715_monthly_sources(site,month)')
        con.execute("INSERT OR REPLACE INTO v7_meta(key,value) VALUES('migration_v715','1')")
        touch_v7(con)


def save_monthly_sources_v715(entries, site, scope):
    if site not in SEDES or not str(scope).strip():
        raise ValueError('Confirma sede y alcance antes de guardar los meses.')
    saved = duplicates = 0
    with db() as con:
        for entry in entries:
            md = dict(entry['metadata']); digest = md.get('sha256')
            if not digest:
                raise ValueError('Falta la huella del archivo; vuelve a cargarlo.')
            md['site'] = site; md['declared_scope'] = str(scope).strip()
            # JSON preserves numeric nulls and code strings, including leading zeros.
            payload = entry['data'].to_json(orient='records', force_ascii=False, double_precision=15)
            cur = con.execute('''INSERT OR IGNORE INTO v715_monthly_sources
                (site,scope,month,sha256,filename,stored_at,metadata,payload) VALUES(?,?,?,?,?,?,?,?)''',
                (site,str(scope).strip(),entry['month'],digest,md['filename'],datetime.now().isoformat(timespec='seconds'),
                 json.dumps(md,ensure_ascii=False,default=str,allow_nan=False),payload))
            saved += cur.rowcount; duplicates += int(cur.rowcount == 0)
        if saved:
            touch_v7(con)
    return {'guardados':saved,'ya_existían':duplicates}


def list_monthly_sources_v715(site):
    import calendar
    result = []
    with db() as con:
        for row in con.execute('SELECT id,month,scope,filename FROM v715_monthly_sources WHERE site=? ORDER BY month DESC,id DESC',(site,)):
            result.append({'key':'nuevo:'+str(row[0]),'month':row[1],'scope':row[2], 'name':row[3],'source':'Comparativo guardado'})
        rows = con.execute('SELECT id,start_date,end_date,scope,file_name FROM v7_sales_batches WHERE site=? ORDER BY start_date DESC,id DESC',(site,)).fetchall()
    for bid,first,last,scope,name in rows:
        try:
            f,l = date.fromisoformat(first),date.fromisoformat(last)
            if f.day == 1 and (f.year,f.month) == (l.year,l.month) and l.day == calendar.monthrange(l.year,l.month)[1]:
                result.append({'key':'anterior:'+str(bid),'month':first[:7], 'scope':scope or 'Sede completa', 'name':name,'source':'Base anterior'})
        except (ValueError,TypeError):
            continue
    return result


def load_monthly_sources_v715(site, keys):
    entries=[]
    with db() as con:
        for key in dict.fromkeys(keys):
            kind,number = str(key).split(':',1); bid=int(number)
            if kind == 'nuevo':
                row = con.execute('SELECT metadata,payload FROM v715_monthly_sources WHERE id=? AND site=?',(bid,site)).fetchone()
                if not row:
                    raise ValueError('Cambió un archivo guardado. Selecciona los meses de nuevo.')
                md=json.loads(row[0]); frame=pd.DataFrame(json.loads(row[1]))
                entries.append(monthly_entry_v715({'data':frame,'metadata':md}))
            elif kind == 'anterior':
                row=con.execute('SELECT start_date,end_date,scope,file_name,sha256,currency FROM v7_sales_batches WHERE id=? AND site=?',(bid,site)).fetchone()
                if not row:
                    raise ValueError('El lote anterior ya no existe en esta sede.')
                frame=pd.read_sql_query('SELECT code AS Código,description AS Descripción,units AS Ventas,row_no AS "Fila origen",net_sales AS "Importe neto",cogs AS "Costo de ventas",gross_sales AS "Monto bruto",discounts AS Descuentos,tax AS "IVA reportado" FROM v7_sales_items WHERE batch_id=? ORDER BY row_no',con,params=(bid,))
                md={'period_start':row[0],'period_end':row[1],'declared_scope':row[2] or 'Sede completa',
                    'filename':row[3],'sha256':row[4],'currency':row[5],'site':site,'source':'Base anterior',
                    'reconciled':True}
                entries.append(monthly_entry_v715({'data':frame,'metadata':md}))
            else:
                raise ValueError('Tipo de archivo guardado no reconocido.')
    return entries


# ============================================================================
# NEXUS 7.18.3 · Criterio mensual persistente y exportación honesta de pendientes
# No altera ventas, existencias, límites manuales ni aprobaciones de A2.
# ============================================================================


def init_monthly_coverage_v7183():
    """Registra declaraciones por fuente exacta; no presume completa la base antigua."""
    with db() as con:
        con.execute('''CREATE TABLE IF NOT EXISTS v7183_monthly_coverage (
            site TEXT NOT NULL, source_key TEXT NOT NULL, month TEXT NOT NULL,
            scope TEXT NOT NULL, filename TEXT NOT NULL,
            mode TEXT NOT NULL CHECK(mode IN ('complete','partial')),
            confirmed_at TEXT NOT NULL, version TEXT NOT NULL,
            PRIMARY KEY(site, source_key))''')
        con.execute('''CREATE TABLE IF NOT EXISTS v7183_coverage_audit (
            id INTEGER PRIMARY KEY AUTOINCREMENT, site TEXT NOT NULL,
            source_key TEXT NOT NULL, month TEXT NOT NULL, scope TEXT NOT NULL,
            previous_mode TEXT, new_mode TEXT NOT NULL, confirmed_at TEXT NOT NULL)''')


def monthly_coverage_key_v7183(entry, site):
    """Incluye datos leídos, período y alcance: una revisión cambia la identidad."""
    md = entry['metadata']
    # El orden físico y los rótulos de procedencia no modifican las ventas,
    # pero sí un cambio de cantidad, código o descripción.
    rows = [[code_key_v714(r['Código']), str(r['Descripción']), float(r['Ventas'])]
            for r in entry['data'].to_dict('records')]
    rows.sort(key=lambda r: (r[0], r[1], r[2]))
    payload = [site, entry['month'], md.get('period_start'), md.get('period_end'),
               normalize_key(md.get('declared_scope', '')), md.get('sha256', ''), rows]
    return hashlib.sha256(json.dumps(payload, ensure_ascii=False, allow_nan=False,
                                     separators=(',', ':')).encode('utf-8')).hexdigest()


def coverage_sources_v7183(entries, months, site):
    """Valida archivos cerrados y contiguos; no completa meses o lecturas ausentes."""
    if site not in SEDES:
        raise ValueError('Selecciona una sede válida para confirmar el historial.')
    chosen = sorted(set(months or []))
    if len(chosen) < 2 or len(chosen) > 12 or len(chosen) != len(months or []):
        raise ValueError('Selecciona de 2 a 12 meses distintos; el recorrido habitual utiliza seis.')
    if any(not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])', str(m)) for m in chosen):
        raise ValueError('Hay un mes no válido en la selección.')
    ordinals = [int(m[:4])*12 + int(m[5:]) for m in chosen]
    if any(b-a != 1 for a,b in zip(ordinals, ordinals[1:])):
        raise ValueError('Falta un mes intermedio. Carga ese reporte; no se sustituye por cero.')
    sources = {}
    for entry in entries:
        if entry.get('month') not in chosen:
            continue
        validated = monthly_entry_v715({'metadata': entry['metadata'], 'data': entry['data']})
        md = validated['metadata']
        if md.get('site') and normalize_key(md['site']) != normalize_key(site):
            raise ValueError(md['filename'] + ': pertenece a otra sede.')
        if not str(md.get('declared_scope') or '').strip():
            raise ValueError(md['filename'] + ': falta confirmar el alcance de ventas.')
        key = monthly_coverage_key_v7183(validated, site)
        month = validated['month']
        if month in sources and sources[month]['key'] != key:
            raise ValueError('Hay fuentes distintas para ' + month_label_v715(month) +
                             '. Elige una; no se suman meses superpuestos.')
        sources[month] = {'key': key, 'entry': validated}
    if set(sources) != set(chosen):
        missing = sorted(set(chosen)-set(sources))
        raise ValueError('Falta el archivo mensual de: ' + ', '.join(missing) + '.')
    scopes = {normalize_key(s['entry']['metadata']['declared_scope']) for s in sources.values()}
    if len(scopes) != 1:
        raise ValueError('Los reportes mensuales tienen alcances diferentes. No se certifican como un mismo historial.')
    return [sources[m] for m in chosen]


def monthly_coverage_status_v7183(entries, months, site):
    sources = coverage_sources_v7183(entries, months, site)
    init_monthly_coverage_v7183()
    with db() as con:
        stored = dict(con.execute('SELECT source_key, mode FROM v7183_monthly_coverage WHERE site=?', (site,)))
    modes = [stored.get(source['key'], '') for source in sources]
    mode = modes[0] if modes and all(m == modes[0] and m for m in modes) else ''
    return {'sources': sources, 'mode': mode, 'confirmed': sum(bool(m) for m in modes),
            'count': len(sources), 'token': reconciliation_fingerprint_v714([site, [s['key'] for s in sources]]),
            'modes': modes}


def save_monthly_coverage_v7183(entries, months, site, mode):
    """Declaración del operador sobre fuentes exactas; no escribe ventas ni A2."""
    if mode not in {'complete', 'partial'}:
        raise ValueError('Selecciona reportes completos o análisis parcial.')
    sources = coverage_sources_v7183(entries, months, site)
    init_monthly_coverage_v7183()
    stamp = datetime.now().isoformat(timespec='microseconds')
    with db() as con:
        for source in sources:
            entry = source['entry']; md = entry['metadata']; key = source['key']
            previous = con.execute('SELECT mode FROM v7183_monthly_coverage WHERE site=? AND source_key=?',
                                   (site,key)).fetchone()
            con.execute('''INSERT INTO v7183_monthly_coverage VALUES (?,?,?,?,?,?,?,?)
                ON CONFLICT(site,source_key) DO UPDATE SET mode=excluded.mode,
                confirmed_at=excluded.confirmed_at,version=excluded.version''',
                (site,key,entry['month'],md['declared_scope'],md['filename'],mode,stamp,APP_VERSION))
            if not previous or previous[0] != mode:
                con.execute('''INSERT INTO v7183_coverage_audit
                    (site,source_key,month,scope,previous_mode,new_mode,confirmed_at) VALUES (?,?,?,?,?,?,?)''',
                    (site,key,entry['month'],md['declared_scope'],previous[0] if previous else None,mode,stamp))
    return len(sources)


def render_monthly_coverage_v7183(entries, months, site, has_errors=False):
    """Una decisión explícita guardada por fuentes, no dos casillas intercambiables."""
    pending = {'ready': False, 'complete': False, 'token': '', 'mode': ''}
    st.markdown('**Tratamiento de los códigos que no aparecen en un mes**')
    st.caption('El criterio se guarda con la sede y estos reportes. Puedes reutilizarlo para otras marcas sin volver a marcarlo. '
               'Tener seis archivos no demuestra por sí solo que el alcance sea completo.')
    if has_errors or not entries or len(months or []) < 2:
        st.info('Primero selecciona los meses y resuelve las lecturas indicadas arriba.')
        return pending
    try:
        status = monthly_coverage_status_v7183(entries, months, site)
    except Exception as exc:
        st.error('Historial pendiente: ' + str(exc))
        return pending
    choices = {'': 'Selecciona el alcance real de estos reportes',
               'complete': 'REPORTES COMPLETOS · un código omitido representa cero registros identificados',
               'partial': 'REPORTES PARCIALES / NO CONFIRMADOS · sólo generar un borrador de revisión'}
    mode = status['mode']
    selected = st.selectbox('¿Estos reportes incluyen todas las ventas del alcance elegido?', list(choices),
                            index=list(choices).index(mode), format_func=lambda k: choices[k],
                            key='v7183_coverage_choice_'+status['token'][:20]+'_'+(mode or 'pending'))
    dirty = selected != mode
    if st.button('Guardar criterio de estos meses', key='v7183_save_coverage_'+status['token'][:20],
                 disabled=not selected or (not dirty and bool(mode))):
        try:
            save_monthly_coverage_v7183(entries, months, site, selected)
            st.rerun()
        except Exception as exc:
            st.error('No se guardó el criterio: ' + str(exc))
            return pending
    if not mode or dirty:
        st.warning('Falta guardar el criterio de estos reportes. No se genera una planilla final con esa decisión pendiente.')
        return dict(pending, token=status['token'])
    if mode == 'complete':
        st.success(f"Criterio guardado: {status['count']} meses de {site}. Ausencia por código = 0 identificado. "
                   'Esto no autoriza cargar límites cero en A2.')
    else:
        st.warning('Modo parcial confirmado: los datos desconocidos permanecen pendientes. La descarga se identificará como BORRADOR PARCIAL.')
    return {'ready': True, 'complete': mode == 'complete', 'token': status['token'], 'mode': mode}


def monthly_quality_v7183(result):
    """Una misma cobertura gobierna pantalla, Excel y PDF, incluso tras filtrar."""
    data = result['data']
    low = pd.to_numeric(data['Mínimo'], errors='coerce')
    high = pd.to_numeric(data['Máximo'], errors='coerce')
    valid = np.isfinite(low) & np.isfinite(high) & low.ge(0) & high.ge(low)
    complete_policy = bool(result['summary'].get('ausencias_completas_cero'))
    pending = ~valid
    label = 'CÁLCULO COMPLETO' if complete_policy and not pending.any() and len(data) else 'BORRADOR PARCIAL'
    return {'total': len(data), 'calculated': int(valid.sum()), 'pending': int(pending.sum()),
            'zero': int((valid & high.eq(0)).sum()), 'positive': int((valid & high.gt(0)).sum()),
            'ready_a2': int(data.get('Lista para A2', pd.Series(False,index=data.index)).fillna(False).sum()) if complete_policy else 0,
            'complete_policy': complete_policy, 'partial': label == 'BORRADOR PARCIAL', 'label': label,
            'pending_data': data.loc[pending].copy()}


def monthly_row_status_v7183(row):
    if bool(row.get('Identidad pendiente')):
        return 'ID PENDIENTE'
    if not np.isfinite(numeric_v714(row.get('Máximo'))) or not np.isfinite(numeric_v714(row.get('Mínimo'))):
        return 'DATOS PENDIENTES'
    if bool(row.get('Sin registro')):
        return 'SIN REGISTRO'
    if bool(row.get('Ventas negativas')):
        return 'DEVOLUCIONES'
    if np.isfinite(numeric_v714(row.get('Existencia'))) and numeric_v714(row.get('Existencia')) < 0:
        return 'REVISAR SALDO'
    return 'CALCULADO'


def refresh_monthly_summary_v7183(result):
    data = result['data']; summary = dict(result['summary'])
    summary.update(productos=len(data), con_limites=int(pd.to_numeric(data['Máximo'],errors='coerce').notna().sum()),
                   sin_registro=int(data['Sin registro'].sum()), con_negativas=int(data['Ventas negativas'].sum()),
                   identidades_pendientes=int(data['Identidad pendiente'].sum()),
                   listos_para_a2=int(data['Lista para A2'].sum()))
    result['summary'] = summary
    return result


def render_monthly_delivery_v7183(result, site, label, comparison, signature):
    quality = monthly_quality_v7183(result)
    st.subheader('4 · Descargar resultados y revisar cobertura')
    st.write(f"**{quality['label']} · {quality['calculated']} de {quality['total']} códigos con mínimos y máximos. "
             f"Pendientes de cálculo: {quality['pending']}. Límites cero calculados: {quality['zero']}.**")
    allow = True
    if quality['partial']:
        st.error('Este resultado no es un reporte final completo. Los espacios vacíos son datos pendientes, no ventas cero. '
                 'Revisa el criterio del historial arriba o utiliza solamente el borrador de diagnóstico.')
        if quality['pending']:
            columns = ['Código','Descripción','Meses sin registro','Estado','Motivo revisión']
            with st.expander('Ver cuáles códigos siguen sin cálculo', expanded=True):
                st.dataframe(quality['pending_data'][columns],hide_index=True,width='stretch')
        allow = st.checkbox('Descargar sólo un BORRADOR PARCIAL; no usarlo para cargar límites a A2',
                            key='v7183_allow_partial_'+signature[:20])
    else:
        st.success('Los límites de todos los códigos son numéricos. La revisión de ceros, devoluciones y saldos para A2 se mantiene separada.')
    exports = st.session_state.setdefault('v715_full_exports', {'signature':signature})
    if exports.get('signature') != signature:
        exports = {'signature':signature}; st.session_state['v715_full_exports'] = exports
    prefix = 'BORRADOR_PARCIAL_' if quality['partial'] else ''
    qualifier = 'borrador parcial' if quality['partial'] else 'informe de cálculo'
    a,b = st.columns(2)
    if a.button('Preparar Excel · '+qualifier, key='v715_prepare_excel',type='primary',disabled=not allow):
        try:
            exports['xlsx'] = build_monthly_excel_v715(result,site,label,comparison)
        except Exception as exc:
            st.error('No se generó el Excel: '+str(exc))
    if allow and exports.get('xlsx'):
        a.download_button('Descargar Excel · '+qualifier,exports['xlsx'],prefix+'NEXUS_'+safe_slug(label)+'_comparativo_mensual.xlsx',
                          DOC_MIME_XLSX,key='v715_download_excel',on_click='ignore')
    if b.button('Preparar PDF · '+qualifier,key='v715_prepare_pdf',disabled=not allow):
        try:
            exports['pdf'] = build_monthly_pdf_v715(result,site,label)
        except Exception as exc:
            st.error('No se generó el PDF: '+str(exc))
    if allow and exports.get('pdf'):
        b.download_button('Descargar PDF · '+qualifier,exports['pdf'],prefix+'NEXUS_'+safe_slug(label)+'_comparativo_mensual.pdf',
                          DOC_MIME_PDF,key='v715_download_pdf',on_click='ignore')
    return quality

# FIN 7.18.3


def monthly_source_signature_v715(entries):
    return reconciliation_fingerprint_v714([(e['month'], e['metadata'].get('sha256'),
                e['metadata'].get('site'), e['metadata'].get('declared_scope'),
                e['data'].to_json(orient='split',force_ascii=False,double_precision=15)) for e in entries])


def build_monthly_matrix_v715(entries, master=None, months=None, complete_reports=False,
                               rounding='exact', review_returns=False, approve_zero=False,
                               site='Matriz Makropetrol'):
    """Compare calendar months separately; top two are selected per SKU.

    Zero means absence in a user-confirmed full monthly report, never an absent
    month. Unidentified source rows stay in an independent, reconcilable table.
    Exact-description matches are only REVIEW candidates and never joins.
    """
    import calendar
    if rounding not in {'exact','up'}:
        raise ValueError('Redondeo no válido.')
    unique={}; duplicates=[]
    for e in entries:
        validated=monthly_entry_v715({'metadata':e['metadata'],'data':e['data']})
        md=validated['metadata'];month=validated['month']
        if md.get('site') and normalize_key(md['site']) != normalize_key(site):
            raise ValueError('El archivo '+md['filename']+' pertenece a otra sede.')
        if month in unique:
            a=unique[month]
            if (md.get('sha256') and md.get('sha256') == a['metadata'].get('sha256')
                    and monthly_coverage_key_v7183(validated,site) == monthly_coverage_key_v7183(a,site)):
                duplicates.append(md['filename']);continue
            raise ValueError('Hay DOS fuentes para '+month_label_v715(month)+'. Elige una: no se suman meses superpuestos. El PDF es comparación aparte.')
        unique[month]=validated
    months=sorted(list(months) if months is not None else unique)
    if len(set(months)) != len(months) or len(months)<2 or len(months)>12:
        raise ValueError('Selecciona entre 2 y 12 meses distintos; para tu regla habitual elige seis.')
    if any(not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])',str(m)) for m in months):
        raise ValueError('Los meses deben indicarse como AAAA-MM.')
    ordinal=[int(m[:4])*12+int(m[5:]) for m in months]
    if any(b-a!=1 for a,b in zip(ordinal,ordinal[1:])):
        raise ValueError('Falta un mes intermedio. No se reemplazan meses completos ausentes por cero.')
    if any(m not in unique for m in months):
        raise ValueError('No hay archivo para todos los meses seleccionados.')
    for m in months:
        if date(int(m[:4]),int(m[5:]),calendar.monthrange(int(m[:4]),int(m[5:]))[1]) > date.today():
            raise ValueError('Hay meses futuros o todavía abiertos.')
    selected=[unique[m] for m in months]
    scopes={normalize_key(e['metadata'].get('declared_scope','')) for e in selected if e['metadata'].get('declared_scope')}
    if len(scopes)>1:
        raise ValueError('Los meses guardados tienen alcances diferentes. Selecciona el mismo alcance antes de comparar.')
    known_map={};unidentified=[];evidence=[];source_rows=[];desc_codes={};master_info={}
    for e in selected:
        m=e['month'];md=e['metadata'];frame=e['data'];known=frame[frame['Código'].ne('')]
        unknown=frame[frame['Código'].eq('')]
        known_map[m]={r['Código']:r for r in known.to_dict('records')}
        for r in known.to_dict('records'):
            desc_codes.setdefault(normalize_key(r['Descripción']),set()).add(r['Código'])
            evidence.append({'Código':r['Código'],'Descripción':r['Descripción'],'Mes':m,'Unidades':float(r['Ventas']),
                'Archivo':md['filename'],'Hoja':md.get('sheet','Base local'),'Fila origen':r.get('Fila origen'),
                'SHA256':md.get('sha256','')})
        for r in unknown.to_dict('records'):
            unidentified.append({'Mes':m,'Código':'','Descripción':r['Descripción'],'Unidades':float(r['Ventas']),
                'Archivo':md['filename'],'Fila origen':r.get('Fila origen'),'SHA256':md.get('sha256','')})
        source_rows.append({'Mes':m,'Archivo':md['filename'],'Empresa encabezado':md.get('company_heading',''),
            'Desde':md['period_start'],'Hasta':md['period_end'],'Emisión':md.get('report_date',''),
            'Filas fuente':len(frame),'Códigos identificados':len(known),'Filas sin código':len(unknown),
            'Unidades identificadas':float(known['Ventas'].sum()),'Unidades sin código':float(unknown['Ventas'].sum()),
            'Total unidades fuente':float(frame['Ventas'].sum()),'SHA256':md.get('sha256',''),
            'Lectura':md.get('reader',md.get('source','Base local'))})
    if master is not None:
        inv=master['data'].copy();master_info=dict(master.get('metadata',{}))
        if not {'Código','Descripción','Existencia'}.issubset(inv):
            raise ValueError('El inventario debe contener Código, Descripción y Existencia.')
        inv['Código']=inv['Código'].map(code_key_v714)
        if inv.empty or inv['Código'].eq('').any() or inv['Código'].duplicated().any():
            raise ValueError('El catálogo está vacío o tiene códigos vacíos/duplicados.')
        if len(inv)>30000:
            raise ValueError('Este recorrido admite hasta 30.000 códigos; divide el catálogo.')
        for r in inv.to_dict('records'):
            desc_codes.setdefault(normalize_key(r['Descripción']),set()).add(r['Código'])
        base=inv.to_dict('records')
    else:
        allcodes=sorted({code for month in known_map.values() for code in month})
        base=[]
        for code in allcodes:
            last=next(known_map[m][code] for m in reversed(months) if code in known_map[m])
            base.append({'Código':code,'Descripción':last['Descripción'],'Existencia':np.nan})
    identity_sources=[dict(r,Mes=e['month'],**{'Fuente identidad':e['metadata'].get('sha256','')+'|'+e['metadata'].get('filename','')})
                      for e in selected for r in e['data'].to_dict('records')]
    identity_plan=resolve_product_codes_v7184(pd.DataFrame(base),identity_sources,site) if master is not None else None
    if identity_plan:
        inverse={}
        for source_code,target_code in identity_plan['mapping'].items():inverse.setdefault(target_code,set()).add(source_code)
        original_maps=known_map
        known_map={}
        for month,source_rows_map in original_maps.items():
            remapped={}
            for target_code,source_codes in inverse.items():
                found=[source_rows_map[sc] for sc in source_codes if sc in source_rows_map]
                if len(found)>1:raise ValueError('Dos códigos fuente pretenden alimentar el mismo mes/producto: '+target_code)
                if found:remapped[target_code]=dict(found[0],**{'Código':target_code})
            # En identidades pendientes mostrar sólo la evidencia exacta, NO cero ni sumas conjeturales.
            for target_code in identity_plan['pending']:
                if target_code in source_rows_map:remapped[target_code]=source_rows_map[target_code]
            known_map[month]=remapped
        for row in evidence:
            row['Código original ventas']=row['Código']
            row['Código inventario relacionado']=identity_plan['mapping'].get(row['Código'],'')
        identity_lookup=identity_plan['report'].set_index('Código inventario')
    affected={};unknown_no_match=[]
    for row in unidentified:
        candidates=sorted(desc_codes.get(normalize_key(row['Descripción']),set()))
        row['Posibles códigos · NO asignados']=' | '.join(candidates)
        row['Revisión']='Sin código en origen. No se asignó por descripción.'
        if not candidates:unknown_no_match.append(row)
        for code in candidates:affected.setdefault(code,[]).append(row['Mes'])
    records=[]
    for item in base:
        code=code_key_v714(item['Código']);values=[];absent=[];present=[]
        row={'Código':code,'Descripción':str(item.get('Descripción','') or ''),
             'Existencia':numeric_v714(item.get('Existencia'))}
        for m in months:
            found=known_map[m].get(code)
            if found is not None:
                q=float(found['Ventas']);present.append(m)
            else:
                q=0.0 if complete_reports and not (identity_plan and code in identity_plan['pending']) else np.nan;absent.append(m)
            row['Unidades '+m]=q;values.append(q)
        complete=all(np.isfinite(v) for v in values)
        ambiguous=code in affected or bool(identity_plan and code in identity_plan['pending'])
        gate=complete and not ambiguous
        total=sum(values) if complete else np.nan
        best=sorted(zip(months,values),key=lambda pair:(pair[1],pair[0]),reverse=True)[:2] if complete else []
        top_sum=best[0][1]+best[1][1] if best else np.nan
        adjustment_zero=complete and top_sum==0 and any(v>0 for v in values)
        gate=gate and not adjustment_zero
        maximum=top_sum if gate and top_sum>=0 else np.nan
        half=maximum*0.5;integer_min=float(math.ceil(round(half,10))) if np.isfinite(half) else np.nan
        minimum=half if rounding=='exact' else integer_min
        stock=row['Existencia'];order=max(maximum-stock,0.0) if np.isfinite(maximum) and np.isfinite(stock) and stock>=0 else np.nan
        negative=any(np.isfinite(v) and v<0 for v in values)
        no_record=len(present)==0
        zero=complete and all(v==0 for v in values)
        blockers=[];notes=[]
        if not complete:blockers.append('Identidad pendiente: los meses no relacionados se conservan sin dato, no como ceros.' if ambiguous else 'Meses sin registro: no se confirmó que ausencia signifique cero.')
        if code in affected:blockers.append('Hay filas sin código con esta misma descripción en '+', '.join(sorted(set(affected[code])))+'. No se asignaron ni se certifican límites.')
        if identity_plan and code in identity_plan['pending']:blockers.extend(identity_plan['pending'][code])
        if adjustment_zero:blockers.append('Hay actividad positiva y ajustes que anulan los dos mayores meses: revisar, no certificar sin ventas.')
        if gate and top_sum<0:blockers.append('Los dos meses mayores suman un valor negativo; revisar ajustes.')
        if not np.isfinite(stock):blockers.append('Sin inventario de este código: A pedir no disponible.')
        elif stock<0:blockers.append('Existencia negativa: revisar saldo antes de pedir.')
        if negative and not review_returns:blockers.append('Revisar ventas netas negativas/devoluciones.')
        if np.isfinite(maximum) and maximum==0 and not approve_zero:blockers.append('Límites cero calculados; aprobar expresamente antes de sustituir límites vigentes en A2.')
        retired=str(item.get('Revisión catálogo','') or '')
        if normalize_key(row['Descripción']) in {'eliminar','elminar'}:retired='Marcado ELIMINAR; revisar baja, no cargar a A2.'
        if retired:blockers.append(retired)
        if absent and complete_reports:notes.append('Cero por ausencia en reporte mensual completo declarado, no una transacción de venta cero.')
        if negative:notes.append('Unidades netas negativas conservadas; no se sustituyeron por cero.')
        if best and not zero and best[0][1]==best[1][1]:notes.append('Empate: se muestran primero los meses más recientes. Se usan dos meses diferentes.')
        status=('REVISAR IDENTIDAD' if ambiguous else 'DATOS INCOMPLETOS' if not complete else
                'SIN REGISTRO EN LOS 6 MESES' if no_record and len(months)==6 else
                'SIN REGISTRO EN LOS MESES' if no_record else 'VENTAS NETAS CERO' if zero else
                'REVISAR DEVOLUCIONES' if negative and not review_returns else 'CALCULADO')
        row.update({'Total meses':total,'Mes mayor 1':best[0][0] if best and not zero else '',
            'Unidades mayor 1':best[0][1] if best and not zero else (0.0 if zero else np.nan),
            'Mes mayor 2':best[1][0] if best and not zero else '',
            'Unidades mayor 2':best[1][1] if best and not zero else (0.0 if zero else np.nan),
            'Máximo':maximum,'Mínimo 50% exacto':half,'Mínimo entero':integer_min,'Mínimo':minimum,'A pedir':order,
            'Estado':status,'Observaciones':' | '.join(notes),'Motivo revisión':' | '.join(blockers),
            'Meses sin registro':', '.join(absent),'Meses con registro':len(present),'Sin registro':no_record,
            'Calcular límites':gate,'Identidad pendiente':ambiguous,'Ventas negativas':negative,'Lista para A2':not blockers,
            'Fecha inventario':item.get('Fecha inventario') or master_info.get('snapshot_date') or master_info.get('report_date','')})
        if identity_plan:
            info=identity_lookup.loc[code]
            row['Coincidencia código']=info['Coincidencia'];row['Códigos de ventas relacionados']=info['Códigos ventas aplicados']
            row['Método de coincidencia']=info['Método']
            if ambiguous:
                row['Estado']='IDENTIDAD PENDIENTE'
                row['Observaciones']+=' | No encontrado no significa cero. Ventas exactas conocidas se conservan en los meses y en la evidencia.'
        if adjustment_zero:row['Estado']='REVISAR AJUSTES';row['Lista para A2']=False
        records.append(row)
    data=pd.DataFrame(records)
    if data.empty:raise ValueError('No se encontraron códigos identificados para comparar.')
    summary={'productos':len(data),'con_limites':int(data['Máximo'].notna().sum()),
        'sin_registro':int(data['Sin registro'].sum()),'con_negativas':int(data['Ventas negativas'].sum()),
        'identidades_pendientes':int(data['Identidad pendiente'].sum()),
        'filas_sin_codigo':len(unidentified),'unidades_sin_codigo':sum(r['Unidades'] for r in unidentified),
        'listos_para_a2':int(data['Lista para A2'].sum()),'meses':len(months),
        'ausencias_completas_cero':bool(complete_reports),'redondeo':rounding,
        'devoluciones_revisadas':bool(review_returns),'ceros_aprobados':bool(approve_zero),
        'duplicados_ignorados':duplicates}
    return {'data':data,'months':months,'sources':pd.DataFrame(source_rows),
            'unidentified':pd.DataFrame(unidentified,columns=['Mes','Código','Descripción','Unidades','Archivo','Fila origen','SHA256','Posibles códigos · NO asignados','Revisión']),
            'evidence':pd.DataFrame(evidence),'summary':summary,'inventory_metadata':master_info,'identity_plan':identity_plan,
            'site':site,'scope':'Catálogo aportado' if master is not None else 'Códigos identificados en ventas'}


def compare_monthly_pdf_v715(result, parsed_pdf):
    """Reference only. Never add PDF units a second time or replace input months."""
    frame=result['data'].set_index('Código');records=[]
    for r in parsed_pdf['data'].to_dict('records'):
        code=code_key_v714(r['Código'])
        for m in result['months']:
            col='Unidades '+m
            if col not in r:continue
            raw=r[col];value=frame.at[code,col] if code in frame.index else np.nan
            diff=value-raw if np.isfinite(value) and np.isfinite(raw) else np.nan
            records.append({'Código':code,'Mes':m,'Unidades PDF':raw,'Unidades mensual':value,'Diferencia':diff,
                            'Estado':'COINCIDE' if pd.notna(diff) and abs(diff)<1e-8 else 'SIN COMPARACIÓN' if pd.isna(diff) else 'DIFERENTE',
                            'Página PDF':r.get('Página PDF'), 'Fuente PDF':parsed_pdf['metadata'].get('filename','Ranking PDF')})
    return pd.DataFrame(records)


def excel_col_v715(n):
    out=''
    while n:
        n,mod=divmod(n-1,26);out=chr(65+mod)+out
    return out


def monthly_workbook_spec_v715(result, site, label, pdf_comparison=None):
    """Shared workbook specification: same formulas in the app and delivery."""
    import math
    validate_monthly_limits_v7184(result)
    months=result['months'];data=result['data'];count=len(data);n=len(months)
    quality=monthly_quality_v7183(result)
    specs=[];cache={}
    def clean(value):
        if value is None:return None
        if isinstance(value,np.generic):value=value.item()
        if not isinstance(value,(str,bool,list,dict)) and pd.isna(value):return None
        if isinstance(value,(list,dict)):return json.dumps(value,ensure_ascii=False)
        return value
    def make(name,headers,rows,start=1):
        spec={'name':name,'headers':list(headers),'rows':[[clean(v) for v in row] for row in rows],
              'header_row':start,'formulas':{},'notes':{},'widths':{},'merges':[],'intro':{}}
        specs.append(spec);return spec
    def f(spec,cell,formula,value):
        spec['formulas'][cell]=formula;cache[spec['name']+'!'+cell]=clean(value) if clean(value) is not None else ''
    head=['Código','Descripción','Existencia']+[month_label_v715(m) for m in months]+[
        'Total meses','Mes mayor 1','Unidades mayor 1','Mes mayor 2','Unidades mayor 2','Stock máximo',
        'Mínimo 50% exacto','Mínimo entero','Mínimo aplicado','A pedir','Estado','Motivo revisión',
        'Meses sin registro','Observaciones','Calcular límites']
    cols={v:i+1 for i,v in enumerate(head)}
    rows=[]
    for row in data.to_dict('records'):
        rows.append([row['Código'],row['Descripción'],row['Existencia']]+[row['Unidades '+m] for m in months]+
                    [row['Total meses'],month_label_v715(row['Mes mayor 1']) if row['Mes mayor 1'] else '',row['Unidades mayor 1'],
                     month_label_v715(row['Mes mayor 2']) if row['Mes mayor 2'] else '',row['Unidades mayor 2'],
                     row['Máximo'],row['Mínimo 50% exacto'],row['Mínimo entero'],row['Mínimo'],row['A pedir'],
                     row['Estado'],row['Motivo revisión'],row['Meses sin registro'],row['Observaciones'],row['Calcular límites']])
    comp=make('Comparativo mensual',head,rows,7)
    comp['intro']={'A1':'NEXUS · '+quality['label']+' · COMPARATIVO MENSUAL POR PRODUCTO',
       'A2':label+' · '+site+' · '+month_label_v715(months[0])+' a '+month_label_v715(months[-1]),
       'A3':'Máximo = suma de los DOS meses con más unidades de cada código. Mínimo = 50% del máximo.',
       'A4':'Verde = mejor mes; azul = segundo mejor. Empate: mes más reciente. Los meses son distintos.',
       'A5':f"{quality['calculated']}/{quality['total']} códigos calculados; {quality['pending']} pendientes. " + ('Ausencia por código = cero identificado, según criterio confirmado.' if quality['complete_policy'] else 'Historial no confirmado completo: documento parcial, no para cargar a A2.'),
       'A6':'Entradas de meses y existencia en azul. Al editar Excel se recalculan fórmulas; la aprobación en NEXUS/A2 no se modifica.'}
    comp['merges']=[f'A{i}:{excel_col_v715(len(head))}{i}' for i in [1,2,4,5,6]]
    comp['merges']+=['A3:C3','E3:F3']
    comp['intro'].update(A3='Factor mínimo (50%)',D3=.5,E3='Mínimo aplicado',G3='Exacto' if result['summary']['redondeo']=='exact' else 'Entero superior')
    comp['widths']={1:22,2:64,3:13,**{i:15 for i in range(4,4+n)}}
    for name in ['Mes mayor 1','Mes mayor 2']:comp['widths'][cols[name]]=21
    for name in ['Estado','Motivo revisión','Meses sin registro','Observaciones']:comp['widths'][cols[name]]=46 if name!='Estado' else 33
    comp['widths'][cols['Calcular límites']]=14
    comp['hide_columns']=[cols['Calcular límites']]
    comp['month_columns']=(4,3+n);comp['best_columns']=(cols['Mes mayor 1'],cols['Mes mayor 2'])
    comp['num_columns']=[3]+list(range(4,4+n))+[cols[x] for x in ['Total meses','Unidades mayor 1','Unidades mayor 2','Stock máximo','Mínimo 50% exacto','Mínimo entero','Mínimo aplicado','A pedir']]
    for i,row in enumerate(data.to_dict('records'),8):
        span=f'$D{i}:${excel_col_v715(3+n)}{i}';hdr=f'$D$7:${excel_col_v715(3+n)}$7'
        valid=f'AND(COUNT({span})={n},{excel_col_v715(cols["Calcular límites"])}{i}=TRUE)'
        numeric_gate=f'COUNT({span})={n}'
        def ref(key):return excel_col_v715(cols[key])+str(i)
        def ff(key,expression,value):f(comp,ref(key),expression,value)
        ff('Total meses',f'=IF({numeric_gate},SUM({span}),"")',row['Total meses'])
        ff('Unidades mayor 1',f'=IF({numeric_gate},LARGE({span},1),"")',row['Unidades mayor 1'])
        ff('Unidades mayor 2',f'=IF({numeric_gate},LARGE({span},2),"")',row['Unidades mayor 2'])
        # Last matching month wins; the second index explicitly excludes the first.
        idx1='1'
        for j in range(1,n):
            col=excel_col_v715(4+j)
            idx1=f'IF({col}{i}=MAX({span}),{j+1},{idx1})'
        name1=f'INDEX({hdr},1,{idx1})'
        idx2='1'
        for j in range(0,n):
            col=excel_col_v715(4+j)
            idx2=f'IF(AND({col}{i}=LARGE({span},2),{col}$7<>{ref("Mes mayor 1")}),{j+1},{idx2})'
        for key,expr,value in [('Mes mayor 1',name1,month_label_v715(row['Mes mayor 1']) if row['Mes mayor 1'] else ''),
                               ('Mes mayor 2',f'INDEX({hdr},1,{idx2})',month_label_v715(row['Mes mayor 2']) if row['Mes mayor 2'] else '')]:
            ff(key,f'=IF({numeric_gate},IF(COUNTIF({span},"<>0")=0,"",{expr}),"")',value)
        ff('Stock máximo',f'=IF({valid},IF({ref("Unidades mayor 1")}+{ref("Unidades mayor 2")}>=0,{ref("Unidades mayor 1")}+{ref("Unidades mayor 2")},""),"")',row['Máximo'])
        ff('Mínimo 50% exacto',f'=IF(ISNUMBER({ref("Stock máximo")}),{ref("Stock máximo")}*$D$3,"")',row['Mínimo 50% exacto'])
        ff('Mínimo entero',f'=IF(ISNUMBER({ref("Mínimo 50% exacto")}),ROUNDUP(ROUND({ref("Mínimo 50% exacto")},10),0),"")',row['Mínimo entero'])
        ff('Mínimo aplicado',f'=IF(ISNUMBER({ref("Mínimo 50% exacto")}),IF($G$3="Exacto",{ref("Mínimo 50% exacto")},{ref("Mínimo entero")}),"")',row['Mínimo'])
        ff('A pedir',f'=IF(AND(ISNUMBER({ref("Stock máximo")}),ISNUMBER(C{i}),C{i}>=0),MAX({ref("Stock máximo")}-C{i},0),"")',row['A pedir'])
        comp['notes'][f'A{i}']=row['Motivo revisión'] or 'Datos de los reportes mensuales. Revisar selección antes de cargar a A2.'
    plan=make('Planilla A2',V714_PLAN_COLUMNS,[[r[c] for c in V714_PLAN_COLUMNS] for r in data.to_dict('records')],9)
    plan['intro']={'A1':'MAKROPETROL, C.A.','A2':site+' · '+label,
        'A3':'Inventario: '+str(result['inventory_metadata'].get('snapshot_date') or result['inventory_metadata'].get('report_date') or 'no aportado'),
        'A4':'Ventas: '+month_label_v715(months[0])+' a '+month_label_v715(months[-1]),
        'A5':('BORRADOR PARCIAL · NO CARGAR DIRECTAMENTE A A2' if quality['partial'] else 'REPOSICIÓN DE INVENTARIO · REVISIÓN DE TODOS LOS CÓDIGOS'),
        'A6':'Máximo = suma de 2 mejores meses. Mínimo '+('50% exacto' if result['summary']['redondeo']=='exact' else '50% redondeado arriba')+'.',
        'A7':f"{quality['calculated']}/{quality['total']} con límites; {quality['pending']} pendientes; {quality['zero']} con máximo cero. Revisar antes de cargar a A2.",
        'A8':'Vacío = historial/límites pendientes, identidad no resuelta o saldo negativo/no informado; no equivale a cero.'}
    plan['merges']=[f'A{i}:F{i}' for i in range(1,9)]
    plan['widths']={1:22,2:68,3:14,4:14,5:14,6:14};plan['num_columns']=[3,4,5,6]
    plan['review_rows']=[]
    for pi,row in enumerate(data.to_dict('records'),10):
        ri=pi-2
        for j,key in [(3,'Existencia'),(4,'Mínimo aplicado'),(5,'Stock máximo'),(6,'A pedir')]:
            cell=f'{excel_col_v715(cols[key])}{ri}'
            value=row[{'Mínimo aplicado':'Mínimo','Stock máximo':'Máximo'}.get(key,key)]
            f(plan,f'{excel_col_v715(j)}{pi}',f'=IF(ISNUMBER(\'Comparativo mensual\'!{cell}),\'Comparativo mensual\'!{cell},"")',value)
        plan['notes'][f'A{pi}']=row['Motivo revisión'] or row['Estado']
        if not row['Lista para A2']:plan['review_rows'].append(pi)
    s=result['summary']
    info_rows=[['Proveedor / grupo',label],['Sede',site],['Factor mínimo',.5],
       ['Mínimo aplicado','Exacto' if s['redondeo']=='exact' else 'Entero superior'],
       ['Meses',', '.join(month_label_v715(m) for m in months)],
       ['Política','Para cada producto se eligen DOS meses diferentes con las mayores unidades netas. Máximo = suma; mínimo = 50%.'],
       ['Empates','Se muestran primero los meses más recientes; el máximo no cambia si las unidades son iguales.'],
       ['Cero por ausencia','Solo cuando los reportes mensuales fueron declarados completos. No significa una fila de venta cero en A2.'],
       ['Productos sin registro','Código no encontrado no significa cero. Identidades pendientes se conservan sin límites hasta resolver; ausencias certificadas se limitan a estas fuentes.'],
       ['Filas sin código','Se conservan completas aparte. No se asignan por parecido. Coincidencias exactas de descripción son solo candidatos para revisión.'],
       ['Inventario','Las existencias pertenecen al corte aportado; la fecha de generación NO las actualiza.'],
       ['A pedir','Completar al máximo: MAX(máximo − existencia, 0). No descuenta tránsito ni comprometidos. No se calcula con saldo negativo.'],
       ['PDF de referencia','Comparación independiente: nunca se suma de nuevo a los seis meses.'],
       ['Colores','Verde: primer mes. Azul claro: segundo. Rojo: cantidades negativas. Amarillo: fila pendiente en planilla.'],
       ['Edición','Entradas azules modificables. Fórmulas actualizan números y meses seleccionados. Estados y aprobaciones requieren revisión nueva en la app.'],
       ['Unidades de productos','No usar una suma global de unidades heterogéneas como demanda de un producto. Los cálculos se hacen por código.'],
       ['Alcance','Esta planilla de revisión no escribe cambios ni pedidos directamente en A2.'],
       ['Productos',s['productos']],['Con límites calculables',s['con_limites']],['Sin registro en los meses',s['sin_registro']],
       ['Productos con ventas netas negativas',s['con_negativas']],['Identidades pendientes',s['identidades_pendientes']],
       ['Filas sin código en fuentes',s['filas_sin_codigo']],['Unidades sin código, no repartidas',s['unidades_sin_codigo']],
       ['Ausencias consideradas cero',s['ausencias_completas_cero']],['Ceros aprobados para A2',s['ceros_aprobados']],
       ['Inventario fuente',result['inventory_metadata'].get('filename','No aportado')],
       ['Huella inventario',result['inventory_metadata'].get('sha256','')],
       ['Estado de este informe',quality['label']],['Códigos con límites pendientes',quality['pending']],
       ['Límites cero calculados',quality['zero']],['Versión generadora',APP_VERSION]]
    info=make('LEER PRIMERO',['Campo','Detalle'],info_rows)
    # rows: header1, provider2, site3, factor4, rounding5 (formula contract).
    info['widths']={1:42,2:110};info['row_height']=33
    sources=make('Fuentes',list(result['sources'].columns),result['sources'].values.tolist())
    sources['widths']={1:15,2:49,3:32,13:72}
    source_names={e['Mes']:e['Archivo'] for e in result['sources'].to_dict('records')}
    for i,row in enumerate(data.to_dict('records'),8):
        for j,m in enumerate(months,4):
            absent = m in row['Meses sin registro']
            explanation = (' · sin registro por código; cero según criterio confirmado' if quality['complete_policy'] else ' · sin registro por código; pendiente, NO se interpreta como cero') if absent else ' · unidades leídas por código'
            comp['notes'][f'{excel_col_v715(j)}{i}']=source_names[m]+explanation
    u=result['unidentified']
    unknown=make('Filas sin codigo',list(u.columns),u.values.tolist());unknown['widths']={1:15,2:16,3:46,4:14,5:48,7:70,8:46,9:60}
    ev=result['evidence']
    # Limit evidence to the selected catalog; source summary still reconciles all source rows.
    ev=ev[ev['Código'].isin(set(data['Código'])) | ev.get('Código inventario relacionado',pd.Series('',index=ev.index)).isin(set(data['Código']))]
    evidence_spec=make('Evidencia mensual',list(ev.columns),ev.values.tolist());evidence_spec['widths']={1:22,2:57,3:16,4:16,5:47,8:70}
    zero_rows=data[data['Sin registro']]
    zero_spec=make('Sin registro en meses',['Código','Descripción','Existencia','Stock máximo','Stock mínimo','Estado'],
        [[r['Código'],r['Descripción'],r['Existencia'],r['Máximo'],r['Mínimo'],r['Motivo revisión']] for r in zero_rows.to_dict('records')])
    zero_spec['widths']={1:22,2:68,3:16,4:16,5:16,6:95};zero_spec['num_columns']=[3,4,5]
    pos={code:i+8 for i,code in enumerate(data['Código'])}
    for zi,row in enumerate(zero_rows.to_dict('records'),2):
        ci=pos[row['Código']]
        for j,key,val in [(3,'Existencia',row['Existencia']),(4,'Stock máximo',row['Máximo']),(5,'Mínimo aplicado',row['Mínimo'])]:
            ref=f"'Comparativo mensual'!{excel_col_v715(cols[key])}{ci}"
            f(zero_spec,f'{excel_col_v715(j)}{zi}',f'=IF(ISNUMBER({ref}),{ref},"")',val)
    if result.get('identity_plan'):
        ip=result['identity_plan'];ir=ip['report']
        cr=make('Cruce de codigos',list(ir.columns),ir.values.tolist());cr['widths']={1:23,2:65,3:35,4:32,5:45,6:45,7:85}
        if not ip['candidates'].empty:
            ca=ip['candidates'];cx=make('Equivalencias pendientes',list(ca.columns),ca.values.tolist());cx['widths']={1:23,2:65,3:23,4:65,5:65}
    if pdf_comparison is not None and not pdf_comparison.empty:
        pc=make('Comparacion PDF',list(pdf_comparison.columns),pdf_comparison.values.tolist());pc['widths']={1:22,2:16,6:25,8:48}
    if quality['pending']:
        pending_cols=['Código','Descripción','Estado','Meses sin registro','Motivo revisión']
        pend=make('Pendientes de calculo',pending_cols,quality['pending_data'][pending_cols].values.tolist())
        pend['widths']={1:22,2:55,3:28,4:38,5:90};pend['row_height']=42
    return {'sheets':specs,'cache':cache,'columns':cols,'summary':s}


def build_monthly_excel_v715(result, site, label, pdf_comparison=None):
    """Portable runtime exporter (existing application dependency: openpyxl)."""
    from openpyxl import Workbook
    from openpyxl.styles import Font,PatternFill,Alignment
    from openpyxl.comments import Comment
    from openpyxl.formatting.rule import FormulaRule
    from openpyxl.worksheet.page import PageMargins
    from openpyxl.workbook.properties import CalcProperties
    spec=monthly_workbook_spec_v715(result,site,label,pdf_comparison)
    wb=Workbook();wb.remove(wb.active)
    for item in spec['sheets']:
        ws=wb.create_sheet(item['name']);hr=item['header_row'];last=hr+len(item['rows']);nc=len(item['headers'])
        for j,name in enumerate(item['headers'],1):ws.cell(hr,j,name)
        for i,row in enumerate(item['rows'],hr+1):
            for j,value in enumerate(row,1):
                cell=ws.cell(i,j,value)
                if isinstance(value,str):cell.data_type='s'
        for cell,value in item['intro'].items():ws[cell]=value
        for area in item['merges']:ws.merge_cells(area)
        for cell,formula in item['formulas'].items():ws[cell]=formula
        for cell,comment in item['notes'].items():ws[cell].comment=Comment(str(comment),'NEXUS · fuentes')
        ws.sheet_view.showGridLines=False;ws.freeze_panes=f'D{hr+1}' if item['name']=='Comparativo mensual' else f'C{hr+1}'
        for j in range(1,nc+1):ws.column_dimensions[excel_col_v715(j)].width=item['widths'].get(j,18)
        for j in item.get('hide_columns',[]):ws.column_dimensions[excel_col_v715(j)].hidden=True
        for cell in ws[hr]:
            cell.fill=PatternFill('solid',fgColor='C0C0C0' if item['name']=='Planilla A2' else '176B68')
            cell.font=Font(name='Arial',bold=True,color='000000' if item['name']=='Planilla A2' else 'FFFFFF',size=10)
            cell.alignment=Alignment(wrap_text=True,vertical='center')
        ws.row_dimensions[hr].height=32
        for i,line in enumerate(ws.iter_rows(min_row=hr+1,max_row=last,max_col=nc),hr+1):
            ws.row_dimensions[i].height=item.get('row_height',30 if item['name'] in {'Comparativo mensual','Planilla A2'} else 27)
            for cell in line:
                cell.alignment=Alignment(vertical='center',wrap_text=cell.column==2 or item['name']=='LEER PRIMERO')
                cell.font=Font(name='Arial',size=10)
                if isinstance(cell.value,(int,float)) or cell.data_type=='f':cell.number_format='General'
        for ri in item.get('review_rows',[]):
            for j in range(1,nc+1):ws.cell(ri,j).fill=PatternFill('solid',fgColor='FFF2CC')
        for ri in range(1,hr):
            ws.row_dimensions[ri].height=24
            ws.cell(ri,1).alignment=Alignment(wrap_text=True,vertical='center')
        if item['intro']:
            ws['A1'].font=Font(name='Arial',bold=True,color='176B68',size=16)
            ws.row_dimensions[1].height=30
        if last>hr:
            ws.auto_filter.ref=f'A{hr}:{excel_col_v715(nc)}{last}'
        if item['name']=='Comparativo mensual':
            lo,hi=item['month_columns'];b1,b2=item['best_columns']
            area=f'{excel_col_v715(lo)}{hr+1}:{excel_col_v715(hi)}{last}'
            ws.conditional_formatting.add(area,FormulaRule(formula=[f'AND(D$7=${excel_col_v715(b1)}8,ISNUMBER(D8))'],fill=PatternFill('solid',fgColor='B7E1CD')))
            ws.conditional_formatting.add(area,FormulaRule(formula=[f'AND(D$7=${excel_col_v715(b2)}8,ISNUMBER(D8))'],fill=PatternFill('solid',fgColor='CFE2F3')))
            ws.conditional_formatting.add(area,FormulaRule(formula=['AND(ISNUMBER(D8),D8<0)'],font=Font(color='C00000',bold=True)))
            for row in ws.iter_rows(min_row=8,max_row=last,min_col=3,max_col=hi):
                for cell in row:cell.font=Font(name='Arial',size=10,color='0000FF')
        ws.print_title_rows=f'1:{hr}';ws.print_area=f'A1:{excel_col_v715(nc)}{max(last,hr)}'
        ws.page_setup.orientation='landscape' if nc>6 else 'portrait'
        ws.page_setup.paperSize=ws.PAPERSIZE_A3 if nc>6 else ws.PAPERSIZE_A4
        ws.page_setup.fitToWidth=1;ws.page_setup.fitToHeight=0;ws.sheet_properties.pageSetUpPr.fitToPage=True
        ws.page_margins=PageMargins(left=.25,right=.25,top=.3,bottom=.35)
    wb.calculation=CalcProperties(fullCalcOnLoad=True)
    out=io.BytesIO();wb.save(out)
    return cache_xlsx_values_v714(out.getvalue(),spec['cache'])


def build_monthly_pdf_v715(result, site, label):
    validate_monthly_limits_v7184(result)
    """Readable monthly comparison, with the top two cells highlighted per row."""
    if not HAS_PDF:
        raise ValueError('Instala fpdf2 para habilitar el PDF comparativo.')
    pdf=make_operational_pdf_v714();pdf.set_auto_page_break(False)
    pdf.set_title('Comparativo mensual · '+label);pdf.alias_nb_pages()
    months=result['months']; n=len(months)
    quality=monthly_quality_v7183(result)
    titles=['Código','Descripción','Exist.']+[month_label_v715(m) for m in months]+['Total','Mes mayor 1','Mes mayor 2','Máximo','Mínimo','A pedir','Revisión']
    widths=[24,94,16]+[124/n]*n+[18,22,22,18,18,18,26]
    # Sum of widths is 400 mm on A3 landscape, with 10 mm margins.
    def linewrap(text,width):
        words=str(text or '').replace('\n',' ').split();lines=[];line=''
        for word in words:
            test=(line+' '+word).strip()
            if pdf.get_string_width(test)<=width-2:
                line=test
            else:
                if line:lines.append(line)
                while pdf.get_string_width(word)>width-2 and len(word)>1:
                    cut=len(word)-1
                    while cut>1 and pdf.get_string_width(word[:cut])>width-2:cut-=1
                    lines.append(word[:cut]);word=word[cut:]
                line=word
        if line:lines.append(line)
        return lines or ['']
    def footer():
        pdf.set_font('Helvetica','',7);pdf.set_text_color(85,100,108);pdf.set_xy(10,285)
        pdf.cell(300,5,'NEXUS '+APP_VERSION+' · Unidades por código. Fuente de existencias: inventario aportado, no fecha de impresión.')
        pdf.set_xy(364,285);pdf.cell(46,5,'Página '+str(pdf.page_no())+'/{nb}',align='R')
    def page():
        pdf.add_page(orientation='L',format='A3');pdf.set_text_color(23,75,72)
        pdf.set_font('Helvetica','B',15);pdf.set_xy(10,8);pdf.cell(390,8,'NEXUS · '+quality['label']+' · COMPARATIVO DE VENTAS')
        pdf.set_font('Helvetica','',10);pdf.set_xy(10,18);pdf.cell(390,6,label+' | '+site+' | '+month_label_v715(months[0])+' a '+month_label_v715(months[-1]))
        pdf.set_font('Helvetica','',8);pdf.set_xy(10,25)
        pdf.cell(390,5,'Máximo: suma de los 2 mejores meses de cada código. Mínimo: 50% '+('exacto.' if result['summary']['redondeo']=='exact' else 'redondeado arriba.'))
        pdf.set_xy(10,31);pdf.cell(390,5,'Verde: mejor mes. Azul: segundo. '+('Cero por ausencia: criterio confirmado de reportes completos.' if quality['complete_policy'] else 'Historial parcial: dato pendiente NO significa cero.'))
        pdf.set_xy(10,37);pdf.cell(390,5,f"{quality['calculated']}/{quality['total']} códigos con límites; {quality['pending']} pendientes. Filas sin código: {result['summary']['filas_sin_codigo']}. No es autorización de carga en A2.")
        x=10;y=45;pdf.set_font('Helvetica','B',8)
        for title,w in zip(titles,widths):
            pdf.set_fill_color(23,107,104);pdf.rect(x,y,w,12,'F');pdf.set_text_color(255,255,255)
            for li,line in enumerate(linewrap(title,w)):
                pdf.set_xy(x+1,y+1+li*3.5);pdf.cell(w-2,3.5,line,align='L' if title in {'Código','Descripción'} else 'C')
            x+=w
        pdf.set_text_color(30,45,50);return 57
    y=page()
    for index,row in enumerate(result['data'].to_dict('records')):
        pdf.set_font('Helvetica','',7.2)
        state=monthly_row_status_v7183(row)
        def num(v):
            if v is None or pd.isna(v):return 'N/D'
            return f'{float(v):,.8f}'.rstrip('0').rstrip('.') if float(v)%1 else f'{int(v):,}'
        def mlabel(m):return V715_MONTH_NAMES[int(m[5:])-1][:3]+' '+m[:4] if m else '-'
        vals=[row['Código'],row['Descripción'],num(row['Existencia'])]+[num(row['Unidades '+m]) for m in months]+[
            num(row['Total meses']),mlabel(row['Mes mayor 1']),mlabel(row['Mes mayor 2']),num(row['Máximo']),num(row['Mínimo']),num(row['A pedir']),state]
        wrapped=[linewrap(v,w) for v,w in zip(vals,widths)];height=max(8, max(len(v) for v in wrapped)*3.2+2)
        if y+height>281:
            footer();y=page();pdf.set_font('Helvetica','',7.2)
        x=10
        for j,(lines,w) in enumerate(zip(wrapped,widths)):
            fill=(248,250,250) if index%2==0 else (255,255,255)
            if 3<=j<3+n:
                month=months[j-3]
                if month==row['Mes mayor 1']:fill=(183,225,205)
                elif month==row['Mes mayor 2']:fill=(207,226,243)
            if row['Sin registro'] and j>=3+n:fill=(255,244,218)
            pdf.set_fill_color(*fill);pdf.rect(x,y,w,height,'F')
            pdf.set_text_color(175,25,25) if 3<=j<3+n and row['Unidades '+months[j-3]]<0 else pdf.set_text_color(30,45,50)
            for li,line in enumerate(lines):
                pdf.set_xy(x+1,y+1+li*3.2);pdf.cell(w-2,3.2,line,align='L' if j in {0,1,len(widths)-1} else 'R')
            pdf.set_draw_color(221,231,234);pdf.line(x,y+height,x+w,y+height);x+=w
        y+=height
    footer();return pdf_output_bytes_v714(pdf)


def subset_monthly_result_v715(result, codes):
    copied=dict(result); copied['data']=result['data'][result['data']['Código'].isin(set(codes))].copy()
    copied['summary']=dict(result['summary'])
    return refresh_monthly_summary_v7183(copied)


