V716_LOAD_ROUTE = 'Todas las sedes · inventario + meses'


def assign_file_group_v716(rows, indices, site, currency=''):
    """Asigna sólo las filas elegidas; no copia cantidades ni modifica fechas."""
    if site not in SEDES:
        raise ValueError('Selecciona la sede del grupo de archivos.')
    if currency and currency not in FIN_CURRENCIES:
        raise ValueError('Selecciona una moneda válida; no se convierte el dinero.')
    out = [dict(row) for row in rows]
    for i in set(indices):
        if not isinstance(i, int) or i < 0 or i >= len(out):
            raise ValueError('Cambió la selección de archivos. Selecciona el grupo de nuevo.')
        out[i]['Sede'] = site
        if currency:
            out[i]['Moneda'] = currency
    return out


def render_file_group_v716(defaults, key):
    """Asignación de 7 archivos por sede sin repetir 7 veces los selectores."""
    base = st.session_state.get(key+'_last_table', st.session_state.get(key+'_table_base', defaults))
    with st.expander('Asignar varios archivos a una sede de una vez', expanded=True):
        st.caption('Por ejemplo, elige el inventario y los seis meses de Barcelona, selecciona Barcelona y aplica. Repite para las demás sedes. Después revisa la tabla completa.')
        indices = st.multiselect('Archivos del grupo', list(range(len(defaults))),
                                format_func=lambda i: defaults[i]['Archivo'], key=key+'_group_files')
        left, right = st.columns(2)
        site = left.selectbox('Sede para ese grupo', ['']+list(SEDES),
                              format_func=lambda x: x or 'Selecciona la sede',key=key+'_group_site')
        currency = right.selectbox('Moneda de ese grupo', ['']+list(FIN_CURRENCIES),
                                    format_func=lambda x:x or 'No cambiar las monedas de la tabla',key=key+'_group_currency')
        if st.button('Aplicar sede y moneda al grupo',key=key+'_group_apply',disabled=not indices or not site):
            current = st.session_state.get(key+'_last_table',base)
            st.session_state[key+'_table_base'] = assign_file_group_v716(current, indices, site, currency)
            st.session_state[key+'_last_table'] = st.session_state[key+'_table_base']
            st.session_state[key+'_table_version'] = st.session_state.get(key+'_table_version',0)+1
            st.rerun()
    return base, str(st.session_state.get(key+'_table_version',0))


def period_covered_by_spans_v716(first, last, spans):
    """True sólo si la unión de intervalos cubre cada día del período anterior."""
    try:
        cursor, final = date.fromisoformat(first), date.fromisoformat(last)
        if cursor > final:
            return False
        for begin, end in sorted(spans):
            begin, end = date.fromisoformat(begin), date.fromisoformat(end)
            if end < begin:
                return False
            if end < cursor:
                continue
            if begin > cursor:
                return False
            if end >= final:
                return True
            cursor = end + timedelta(days=1)
    except (ValueError, TypeError, OverflowError):
        return False
    return False


def preflight_monthly_periods_v716(bundles):
    """Puede sustituir un acumulado por TODOS sus meses, nunca por una parte."""
    problems, replace_sites = [], set()
    with db() as con:
        for bundle in bundles:
            spans = sorted((p['metadata'].get('period_start',''),p['metadata'].get('period_end','')) for p in bundle.get('sales_reports',[]))
            if not spans or any(not a or not b for a,b in spans):
                continue
            olds = con.execute('SELECT start_date,end_date FROM v7_sales_batches WHERE site=? AND scope=? AND start_date<=? AND end_date>=?',
                               (bundle['site'],bundle.get('scope',''),max(b for a,b in spans),min(a for a,b in spans))).fetchall()
            for first,last in olds:
                if not any(a<=last and b>=first for a,b in spans):
                    continue
                if not period_covered_by_spans_v716(first,last,spans):
                    problems.append(f"{bundle['site']}: falta parte de {first} a {last}, ya guardado. Para sustituir un acumulado carga todos sus meses completos; no se recorta ni se reparte el período anterior.")
                elif (first,last) not in spans:
                    replace_sites.add(bundle['site'])
    return list(dict.fromkeys(problems)), replace_sites


def archive_sales_batch_v716(con, prior):
    """Archiva y elimina dentro de la transacción ABIERTA de la sede."""
    stored = pd.read_sql_query('SELECT i.*,c.supplier,c.brand,c.department,c.category FROM v7_sales_items i LEFT JOIN v77_sales_classification c ON c.batch_id=i.batch_id AND c.row_no=i.row_no WHERE i.batch_id=?',con,params=(int(prior['id']),))
    con.execute('INSERT INTO v7_import_archive(archived_at,batch_metadata,items_json) VALUES(?,?,?)',
                (datetime.now().isoformat(),prior.to_json(force_ascii=False),stored.to_json(orient='records',force_ascii=False)))
    con.execute('DELETE FROM v77_sales_classification WHERE batch_id=?',(int(prior['id']),))
    con.execute('DELETE FROM v7_sales_items WHERE batch_id=?',(int(prior['id']),))
    con.execute('DELETE FROM v7_sales_batches WHERE id=?',(int(prior['id']),))


def multisite_inventory_cuts_v716(rows):
    """Un corte por sede; las ventas heredan ese corte, no el de otra sede."""
    cuts = {}
    for row in rows:
        if row.get('Tipo') == 'Inventario' and row.get('Sede') in SEDES:
            cut = _upload_date_v71(row.get('Corte'))
            if cut:
                cuts[row['Sede']] = cut
    return cuts


def validate_monthly_bundles_v716(bundles):
    """La nueva ruta guarda cada mes; no disfraza acumulados como meses."""
    errors = []
    for bundle in bundles:
        for parsed in bundle.get('sales_reports', []):
            try:
                monthly_entry_v715(parsed)
            except (ValueError, KeyError, TypeError) as exc:
                errors.append(f"{bundle['site']}: {exc}")
    return list(dict.fromkeys(errors))


def multisite_replacements_v716(bundles):
    """Hace visible incluso la sustitución de un período EXACTAMENTE igual."""
    rows = []
    with db() as con:
        for bundle in bundles:
            site, scope, cut = bundle['site'], bundle.get('scope', ''), bundle['cutoff']
            if bundle.get('inventory') is not None:
                if scope:
                    exists = con.execute('SELECT 1 FROM supplier_inventory_snapshots WHERE site=? AND snapshot_date=? AND supplier_key=? LIMIT 1',
                                         (site, cut, normalize_key(scope))).fetchone()
                else:
                    exists = con.execute('SELECT 1 FROM inventory_snapshots WHERE site=? AND snapshot_date=? LIMIT 1', (site, cut)).fetchone()
                if exists:
                    rows.append({'Sede': site, 'Tipo': 'Inventario', 'Período/corte': cut,
                                 'Acción': 'Sustituir fotografía de la misma fecha; respaldo previo'})
            for p in bundle.get('sales_reports', []):
                md = p['metadata']
                olds = con.execute('SELECT start_date,end_date FROM v7_sales_batches WHERE site=? AND scope=? AND start_date<=? AND end_date>=?',
                                   (site, scope, md['period_end'], md['period_start'])).fetchall()
                for first, last in olds:
                    rows.append({'Sede': site, 'Tipo': 'Ventas', 'Período/corte': first + ' a ' + last,
                                 'Acción': 'Sustituir período; conservar versión anterior en archivo de auditoría'})
    return pd.DataFrame(rows, columns=['Sede', 'Tipo', 'Período/corte', 'Acción']).drop_duplicates(ignore_index=True)


def registered_multisite_v716():
    """Registro por sede/mes, sin confundir fuentes del comparativo con el motor."""
    import calendar
    inventory_rows, details, monthly = [], [], []
    with db() as con:
        for site in SEDES:
            cuts = con.execute('SELECT snapshot_date,COUNT(*) FROM inventory_snapshots WHERE site=? GROUP BY snapshot_date ORDER BY snapshot_date DESC', (site,)).fetchall()
            for cut, count in cuts:
                details.append({'Sede': site, 'Fecha del inventario': cut, 'Productos': count})
            inventory_rows.append({'Sede': site, 'Último inventario': cuts[0][0] if cuts else 'Sin inventario',
                                   'Productos del último corte': cuts[0][1] if cuts else None, 'Cortes conservados': len(cuts)})
        for bid, site, first, last, scope, name in con.execute('SELECT id,site,start_date,end_date,scope,file_name FROM v7_sales_batches ORDER BY site,start_date'):
            try:
                begin, end = date.fromisoformat(first), date.fromisoformat(last)
                full = (begin.day == 1 and (begin.year, begin.month) == (end.year, end.month)
                        and end.day == calendar.monthrange(end.year, end.month)[1])
            except (ValueError, TypeError):
                full = False
            monthly.append({'Sede': site, 'Mes': first[:7] if full else '', 'Desde': first, 'Hasta': last,
                            'Alcance': scope or 'Sede completa', 'Uso': 'Motor + comparativo' if full else 'Motor · período no mensual', 'Archivo': name})
        if con.execute("SELECT 1 FROM sqlite_master WHERE name='v715_monthly_sources'").fetchone():
            for site, month, scope, name in con.execute('SELECT site,month,scope,filename FROM v715_monthly_sources ORDER BY site,month'):
                monthly.append({'Sede': site, 'Mes': month, 'Desde': '', 'Hasta': '', 'Alcance': scope,
                                'Uso': 'Solo comparativo', 'Archivo': name})
    return (pd.DataFrame(inventory_rows), pd.DataFrame(monthly, columns=['Sede','Mes','Desde','Hasta','Alcance','Uso','Archivo']),
            pd.DataFrame(details, columns=['Sede','Fecha del inventario','Productos']))


def render_registered_multisite_v716():
    inventory, months, cuts = registered_multisite_v716()
    with st.expander('Ver inventarios y meses que YA están guardados', expanded=True):
        st.caption('Este registro consulta tu base NEXUS. Inventario = fotografía en una fecha; ventas = períodos separados. Cerrar la app no borra estos registros.')
        st.dataframe(inventory, hide_index=True, width='stretch')
        observed = sorted(set(months.loc[months['Mes'].ne(''), 'Mes'])) if not months.empty else []
        # Show calendar gaps even when NO branch has loaded the missing month.
        options = [str(period) for period in pd.period_range(observed[0], observed[-1], freq='M')] if observed else []
        selected = st.multiselect('Meses a comprobar en todas las sedes', options, default=options[-6:], key='v716_registry_months')
        if selected:
            rows = []
            for site in SEDES:
                row = {'Sede': site}
                for month in selected:
                    found = months[(months['Sede']==site) & (months['Mes']==month)]
                    main = found[found['Alcance'].eq('Sede completa')]
                    motor = main['Uso'].eq('Motor + comparativo').any()
                    comparison = main['Uso'].eq('Solo comparativo').any()
                    row[month_label_v715(month)] = ('Guardado · motor y comparativo' if motor else 'Solo comparativo' if comparison
                                                  else 'Solo alcance limitado' if not found.empty else 'Sin cargar')
                rows.append(row)
            st.dataframe(pd.DataFrame(rows), hide_index=True, width='stretch')
        elif months.empty:
            st.info('Todavía no hay meses guardados. Carga los archivos de las sedes abajo.')
        else:
            st.info('Hay períodos acumulados o no mensuales. No equivalen a meses separados para elegir los dos mejores.')
        if not months.empty:
            st.caption('Motor y comparativo: una carga sirve para ambos. Solo comparativo: fuente guardada desde esa herramienta; no actualiza por sí sola el motor de compras.')
            st.dataframe(months, hide_index=True, width='stretch', height=220)
        if not cuts.empty:
            st.caption('Fotografías de inventario conservadas (no se suman entre fechas).')
            st.dataframe(cuts, hide_index=True, width='stretch', height=180)


def render_multisite_load_v716():
    st.title('Cargar todas las sedes · inventario + meses')
    st.write('Sube juntos los inventarios y las ventas mensuales de Matriz y las sucursales. Asigna cada archivo a su sede y guarda el lote con un solo botón.')
    st.info('Ejemplo: 5 inventarios + 6 meses por cada sede = 35 archivos. Cada mes se guarda por separado, sin convertir los seis meses en un único acumulado.')
