def init_workspace_v717():
    """Configuración adicional; los datos de inventario y ventas no se migran."""
    with db() as con:
        con.execute('''CREATE TABLE IF NOT EXISTS v717_workspace_settings (
            name TEXT PRIMARY KEY, config_json TEXT NOT NULL, updated_at TEXT NOT NULL)''')


def _config_defaults_v717():
    return {'sites': [s for s in SEDES if latest_snapshot_date(s)], 'mode': 'periodo',
            'policy': 'cobertura', 'months': [], 'sources': {}, 'scopes': {}, 'cuts': {},
            'supplier': '', 'complete_reports': False, 'review_returns': False,
            'approve_zero': False, 'rounding': 'exact', 'respect_manual': True,
            'months_history': 3, 'min_coverage': 0.5, 'max_coverage': 1.0,
            'lead_time_days': 7, 'safety_days': 3, 'abc_basis': 'Movimiento',
            'sales_mode': 'periodo'}


def workspace_config_v717():
    current = st.session_state.get('v717_active_config')
    if current is None:
        with db() as con:
            row = con.execute("SELECT config_json FROM v717_workspace_settings WHERE name='principal'").fetchone()
        try:
            current = json.loads(row[0]) if row else {}
        except (ValueError, TypeError):
            current = {}
        current = dict(_config_defaults_v717(), **current)
        current['sites'] = [s for s in current['sites'] if s in SEDES]
        st.session_state['v717_active_config'] = current
    # No devolver el diccionario compartido para que los controles no lo muten.
    return json.loads(json.dumps(current, ensure_ascii=False))


def validate_workspace_config_v717(config):
    c = dict(config)
    if not c.get('sites') or len(c['sites']) != len(set(c['sites'])) or any(s not in SEDES for s in c['sites']):
        raise ValueError('Selecciona al menos una sede válida, sin repetirla.')
    if c.get('mode') not in V717_SOURCE_MODES or c.get('policy') not in V717_RULES:
        raise ValueError('Origen del historial o regla de stock no reconocido.')
    if c['policy'] == 'dos_mejores' and c['mode'] != 'mensual':
        raise ValueError('Los dos mejores meses requieren ventas separadas por mes; no sirve un único acumulado.')
    if c.get('rounding') not in ('exact', 'up'):
        raise ValueError('Elige el redondeo del mínimo.')
    lo, hi = float(c['min_coverage']), float(c['max_coverage'])
    if not (0 < lo <= hi <= 24):
        raise ValueError('La cobertura mínima debe ser positiva y no superar la máxima.')
    for field, maximum in [('lead_time_days',180), ('safety_days',90), ('months_history',36)]:
        number = int(c[field])
        if number < (1 if field == 'months_history' else 0) or number > maximum:
            raise ValueError('Parámetro fuera de rango: '+field)
    if c['mode'] == 'mensual':
        months = sorted(c.get('months', []))
        if not 2 <= len(months) <= 12 or len(months) != len(set(months)):
            raise ValueError('Elige de 2 a 12 meses completos distintos; tu comparación habitual usa seis.')
        if any(not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])', m) for m in months):
            raise ValueError('Mes no válido.')
        ords = [pd.Period(m, freq='M').ordinal for m in months]
        if any(b-a != 1 for a,b in zip(ords,ords[1:])):
            raise ValueError('Hay meses intermedios sin seleccionar. No se reemplazan por cero.')
        import calendar
        if any(date(int(m[:4]),int(m[5:]),calendar.monthrange(int(m[:4]),int(m[5:]))[1]) > date.today() for m in months):
            raise ValueError('No puedes evaluar meses abiertos o futuros como meses completos.')
        c['months'] = months
    return c


def save_workspace_config_v717(config):
    c = validate_workspace_config_v717(config)
    with db() as con:
        con.execute('''INSERT INTO v717_workspace_settings VALUES (?,?,?)
                    ON CONFLICT(name) DO UPDATE SET config_json=excluded.config_json,updated_at=excluded.updated_at''',
                    ('principal', json.dumps(c,ensure_ascii=False,allow_nan=False), datetime.now().isoformat()))
    st.session_state['v717_active_config'] = c
    st.session_state.pop('v717_export_ready', None)
    return c


def _blank_scope_v717(scope):
    return normalize_key(scope or '') in ('', 'sede completa', 'todos', 'toda la sede')


def eligible_monthly_sources_v717(site, scope=''):
    """Con un catálogo dedicado se admite su alcance o el de la sede completa."""
    items = list_monthly_sources_v715(site)
    return [r for r in items if _blank_scope_v717(r['scope']) or
            (scope and normalize_key(r['scope']) == normalize_key(scope))]


def choose_monthly_keys_v717(site, months, choices=None, scope=''):
    """Una fuente por mes. Copias alternativas no se suman ni se eligen a ciegas."""
    items = eligible_monthly_sources_v717(site, scope)
    selected, issues = [], []
    choices = choices or {}
    for month in months:
        candidates = [x for x in items if x['month'] == month]
        # La sede completa no se reemplaza por un alcance dedicado más estrecho.
        full = [x for x in candidates if _blank_scope_v717(x['scope'])]
        # El motor es la base prioritaria; el archivo de comparativos es un respaldo opcional.
        primary = [x for x in (full or candidates) if x['key'].startswith('anterior:')]
        preferred = primary or (full or candidates)
        key = choices.get(month)
        if key:
            match = next((x for x in candidates if x['key'] == key), None)
            if not match:
                issues.append(month+': la fuente elegida ya no existe o no pertenece al alcance.')
            else:
                selected.append(key)
        elif len(preferred) == 1:
            selected.append(preferred[0]['key'])
        elif not preferred:
            issues.append(month+': no hay un reporte mensual completo guardado.')
        else:
            issues.append(month+': hay varias fuentes; elige expresamente cuál usar.')
    return selected, issues


def _inventory_source_v717(site, config):
    scope = str(config.get('scopes', {}).get(site, '') or '')
    cut = config.get('cuts', {}).get(site) or (latest_supplier_snapshot_date(site,scope) if scope else latest_snapshot_date(site))
    if not cut:
        return None, '', scope
    if date.fromisoformat(cut) > date.today():
        raise ValueError('La fecha de inventario es futura.')
    frame = (load_supplier_snapshot(site,scope,cut) if scope else load_snapshot(site,cut))[0]
    frame = enrich_dimensions_v7(frame)
    supplier = str(config.get('supplier','') or '').strip()
    if supplier and not scope:
        frame = frame.loc[frame.get('Proveedor',pd.Series('',index=frame.index)).map(normalize_key).eq(normalize_key(supplier))].copy()
    if frame.empty:
        return None, cut, scope
    if frame['Código'].duplicated().any() or frame['Código'].astype(str).str.strip().eq('').any():
        raise ValueError('El inventario contiene códigos vacíos o repetidos.')
    return frame, cut, scope


def _pending_inventory_v717(inv, site, cut, message, config, scope=''):
    sales = pd.DataFrame({'Código':inv['Código'], 'Ventas':0.0})
    result = calculate_site(inv, sales, pd.DataFrame(columns=['Código','Ventas']),
        config['months_history'], config['min_coverage'], config['max_coverage'],
        config['lead_time_days'], config['safety_days'],config['abc_basis'],'periodo',30,
        average_months=float(config['months_history']))
    result = result.astype({c:object for c in ('Estado','Acción','Sin movimiento','Política de stock')})
    for col in ['Stock Mínimo','Stock Máximo','Punto de Reorden','Mínimo automático','Máximo automático','Ventas','Demanda Mensual']:
        result[col] = np.nan
    for col in ['Compra Sugerida','Retiro Almacén','Costo Compra Estimada ($)','Capital Inmovilizado ($)']:
        result[col] = 0.0
    result['Historial de ventas']='Pendiente de cargar'; result['Sin movimiento']='No evaluable'
    result['Estado']='PENDIENTE — REVISAR VENTAS';result['Acción']='REVISAR BASE DEL CÁLCULO'
    result['Revisión del cálculo']=message;result['Bloqueo operativo']=message
    result['Fecha del inventario']=cut;result['Moneda inventario']=snapshot_currency_v714(site,cut,scope)
    result['Período ventas']='No evaluable';result['Política de stock']='Pendiente'
    return _restore_optional_costs_v71(result,inv,config['abc_basis'])


def calculate_monthly_site_v717(inv, entries, site, cut, scope, config):
    """Mismos datos por código -> una regla activa -> compras, retiros y traslados."""
    c = config; months = c['months']
    master={'data':inv, 'metadata':{'snapshot_date':cut,'filename':'Inventario guardado · '+site}}
    monthly = build_monthly_matrix_v715(entries,master,months, c['complete_reports'],c['rounding'],
                                        c['review_returns'],c['approve_zero'],site)
    m = monthly['data'].set_index('Código')
    augmented = apply_stock_settings_v7(inv.copy(),site) if c['respect_manual'] else inv.copy()
    original_min = pd.to_numeric(augmented.get('Mínimo manual',pd.Series(np.nan,index=augmented.index)),errors='coerce')
    original_max = pd.to_numeric(augmented.get('Máximo manual',pd.Series(np.nan,index=augmented.index)),errors='coerce')
    manual = original_min.notna() & original_max.notna() & original_min.ge(0) & original_max.ge(original_min)
    manual_codes=set(augmented.loc[manual,'Código'])
    if c['policy'] == 'dos_mejores':
        # Se reutiliza la regla de abastecer bajo mínimo sin alterar los valores de ventas.
        augmented['Mínimo manual'] = augmented['Código'].map(m['Mínimo']).where(~manual,original_min)
        augmented['Máximo manual'] = augmented['Código'].map(m['Máximo']).where(~manual,original_max)
    sales=pd.DataFrame({'Código':m.index, 'Ventas':m['Total meses'].to_numpy()})
    result=calculate_site(augmented,sales,pd.DataFrame(columns=['Código','Ventas']),len(months),
            c['min_coverage'],c['max_coverage'],c['lead_time_days'] if c['policy']=='cobertura' else 0,
            c['safety_days'] if c['policy']=='cobertura' else 0,c['abc_basis'],'periodo',30,
            period_days=(pd.Period(months[-1]).end_time.date()-pd.Period(months[0]).start_time.date()).days+1,
            average_months=float(len(months)))
    result=result.astype({name:object for name in ('Estado','Acción','Política de stock','Sin movimiento')})
    for field in ['Unidades '+x for x in months]+['Mes mayor 1','Mes mayor 2','Unidades mayor 1','Unidades mayor 2',
            'Ventas negativas','Identidad pendiente','Motivo revisión','Lista para A2','Sin registro','Meses sin registro','Coincidencia código','Códigos de ventas relacionados','Método de coincidencia']:
        result[field]=result['Código'].map(m[field])
    valid_months=result['Código'].map(m['Calcular límites']).fillna(False)
    if c['policy']=='dos_mejores':
        not_manual=~result['Código'].isin(manual_codes)
        result.loc[not_manual,'Política de stock']='Dos mejores meses'
        for dest,src in [('Mínimo automático','Mínimo'),('Máximo automático','Máximo'),('Stock Mínimo','Mínimo'),('Stock Máximo','Máximo'),('Punto de Reorden','Mínimo')]:
            result[dest]=pd.to_numeric(result[dest],errors='coerce').astype(float)
            result.loc[not_manual,dest]=result.loc[not_manual,'Código'].map(m[src])
    result['Redondeo mínimo']=c['rounding']
    result['Fecha del inventario']=cut;result['Moneda inventario']=snapshot_currency_v714(site,cut,scope)
    result['Historial de ventas']='Disponible';result['Período ventas']=months[0]+' a '+months[-1]
    result['Días del historial']=(pd.Period(months[-1]).end_time.date()-pd.Period(months[0]).start_time.date()).days+1
    result['Corte desactualizado']='Sí' if pd.Period(months[-1]).end_time.date().isoformat()>cut else 'No'
    result['Ventas sin código del historial']=monthly['summary']['unidades_sin_codigo']
    result['Revisión del cálculo']='';result['Bloqueo operativo']=''
    # Una cifra desconocida no se convierte en cero ni en producto sin rotación.
    for field in ['Ventas','Ventas utilizadas','Demanda Mensual']:
        result.loc[~valid_months,field]=np.nan
    for field in ['Stock Mínimo','Stock Máximo','Punto de Reorden','Mínimo automático','Máximo automático']:
        result.loc[~valid_months,field]=np.nan
    for idx,row in result.iterrows():
        reasons=[]
        if not valid_months.loc[idx]:reasons.append(str(m.at[row['Código'],'Motivo revisión']) or 'Historial incompleto o identidad pendiente')
        if bool(row['Ventas negativas']) and not c['review_returns']:reasons.append('Revisar devoluciones/ventas netas negativas')
        if not np.isfinite(row['Existencia']) or row['Existencia']<0:reasons.append('Revisar saldo de inventario')
        if result.at[idx,'Corte desactualizado']=='Sí':reasons.append('Inventario anterior al fin de las ventas seleccionadas')
        if not np.isfinite(row['Stock Máximo']) or row['Stock Máximo']<0:reasons.append('Límites pendientes')
        elif row['Stock Máximo']==0 and not c['approve_zero']:reasons.append('Aprobar límites cero antes de retirar o cargar a A2')
        if normalize_key(str(row['Descripción'])) in {'eliminar','elminar'}:reasons.append('Código marcado ELIMINAR')
        result.at[idx,'Bloqueo operativo']=' | '.join(dict.fromkeys(reasons))
        result.at[idx,'Revisión del cálculo']=result.at[idx,'Bloqueo operativo']
    blocked=result['Bloqueo operativo'].ne('')
    result.loc[blocked,['Compra Sugerida','Retiro Almacén','Capital Inmovilizado ($)','Costo Compra Estimada ($)']]=0.0
    result.loc[blocked,'Estado']='PENDIENTE — REVISIÓN OPERATIVA';result.loc[blocked,'Acción']='REVISAR ANTES DE EJECUTAR'
    # Neto cero en meses positivos y negativos NO equivale a ausencia de ventas.
    units=result[['Unidades '+x for x in months]].apply(pd.to_numeric,errors='coerce')
    no_net=units.notna().all(axis=1)&units.eq(0).all(axis=1)&valid_months&result['Existencia'].gt(0)
    result['Sin movimiento']=np.where(no_net,'Sí',np.where(~valid_months,'No evaluable','No'))
    result['Lectura rotación']=np.where(no_net,'Sin ventas netas en los meses · validar movimientos',
                                       np.where(~valid_months,'Datos insuficientes','Con actividad neta'))
    result['A pedir']=np.where(result['Existencia'].ge(0)&result['Stock Máximo'].notna(),
                               (result['Stock Máximo']-result['Existencia']).clip(lower=0),np.nan)
    result=_restore_optional_costs_v71(result,inv,c['abc_basis'])
    return result, monthly


def _postprocess_workspace_v717(frames, config):
    """Un solo plan de transferencias; los bloqueados no donan ni reciben."""
    eligible={s:f.loc[f.get('Bloqueo operativo',pd.Series('',index=f.index)).fillna('').eq('')].copy() for s,f in frames.items()}
    moves=attach_transfer_currency_v714(build_redistribution(eligible),frames)
    adjusted=apply_redistribution_to_results(frames,moves)
    for site,frame in adjusted.items():
        blocked=frame.get('Bloqueo operativo',pd.Series('',index=frame.index)).fillna('').ne('')
        frame['Acción']=frame['Acción'].astype(object)
        frame.loc[blocked,'Acción']='REVISAR ANTES DE EJECUTAR'
        frame.loc[blocked,['Compra Sugerida','Compra Ajustada','Retiro Almacén']]=0.0
        frame['Retiro neto']=(frame['Retiro Almacén']-frame['Transferencias Enviadas']).clip(lower=0)
    all_data=combine_sites(adjusted) if adjusted else pd.DataFrame()
    return all_data,moves,adjusted


@st.cache_data(show_spinner=False,max_entries=4)
def calculate_workspace_v717(data_version, config_json):
    c=validate_workspace_config_v717(json.loads(config_json))
    frames={};comparisons={};dates_used={};statuses=[];sales_ledger=[]
    for site in c['sites']:
        scope=c.get('scopes',{}).get(site,'')
        inv,cut,scope=_inventory_source_v717(site,c)
        if inv is None:
            statuses.append({'Sede':site,'Inventario':cut or 'Sin inventario','Historial':'No evaluable','Detalle':'Sin inventario del alcance elegido','Productos':0})
            continue
        dates_used[site]=cut
        if c['mode']=='periodo':
            # Mantener los divisores y ventanas antiguas: no repartir un acumulado.
            frame=calculate_loaded_site_v7(site,cut,scope,c['months_history'],c['min_coverage'],c['max_coverage'],
                      c['lead_time_days'],c['safety_days'],c['abc_basis'],c['sales_mode'],30)
            frame=frame.loc[frame['Código'].isin(inv['Código'])].copy()
            frame['Bloqueo operativo']=frame.get('Revisión del cálculo',pd.Series('',index=frame.index)).fillna('')
            negative=frame['Existencia'].lt(0)
            frame.loc[negative,'Bloqueo operativo']='Revisar saldo negativo'
            zeros=frame['Stock Máximo'].eq(0)
            if not c['approve_zero']:frame.loc[zeros,'Bloqueo operativo']='Aprobar límites cero antes de retirar o cargar a A2'
            stale=frame.get('Corte desactualizado',pd.Series('No',index=frame.index)).eq('Sí')
            frame.loc[stale,'Bloqueo operativo']='Inventario anterior al final del historial de ventas'
            blocked=frame['Bloqueo operativo'].ne('')
            frame['Estado']=frame['Estado'].astype(object);frame['Acción']=frame['Acción'].astype(object)
            frame.loc[blocked,['Compra Sugerida','Retiro Almacén']]=0.0
            frame.loc[blocked,'Estado']='PENDIENTE — REVISIÓN OPERATIVA'
            frame.loc[blocked,'Revisión del cálculo']=frame.loc[blocked,'Bloqueo operativo']
            # Total <= 0 no prueba ausencia de ventas: en período acumulado es solo candidato.
            frame['Lectura rotación']=np.where(frame['Ventas'].eq(0)&frame['Existencia'].gt(0),'Neto del período cero · requiere detalle mensual',
                                              np.where(frame['Ventas'].lt(0),'Devoluciones / neto negativo','Con actividad o sin historial'))
            source=selected_sales_rows_v717(site,cut,scope)
            if c.get('supplier') or scope:source=[r for r in source if r.get('Código') in set(inv['Código'])]
            sales_ledger.extend(source)
            statuses.append({'Sede':site,'Inventario':cut,'Historial':'Período guardado','Detalle':str(frame['Período ventas'].iloc[0]) if not frame.empty else '', 'Productos':len(frame)})
        else:
            keys,issues=choose_monthly_keys_v717(site,c['months'],c.get('sources',{}).get(site,{}),scope)
            if issues:
                frame=_pending_inventory_v717(inv,site,cut,'; '.join(issues),c,scope)
                statuses.append({'Sede':site,'Inventario':cut,'Historial':'Incompleto','Detalle':'; '.join(issues),'Productos':len(frame)})
            else:
                try:
                    entries=cached_monthly_sources_v7184(site,tuple(keys),db_version())
                    # Alcances de sede completa y proveedor no deben mezclarse por accidente.
                    frame,comparison=calculate_monthly_site_v717(inv,entries,site,cut,scope,c)
                    comparisons[site]=comparison
                    ledger_mapping=(comparison.get('identity_plan') or {}).get('mapping',{})
                    for e in entries:
                        for r in e['data'].to_dict('records'):
                            r=dict(r,**{'Código original ventas':r['Código'],'Código':ledger_mapping.get(r['Código'],r['Código'])})
                            if (c.get('supplier') or scope) and r['Código'] not in set(inv['Código']):
                                continue
                            sales_ledger.append({'Sede':site,'Código':r['Código'],'Descripción':r['Descripción'],
                              'Ventas':r['Ventas'],'Ventas del período':r['Ventas'],'Desde':e['metadata']['period_start'],
                              'Hasta':e['metadata']['period_end'],'Moneda ventas':e['metadata'].get('currency','Sin moneda'),
                              'Archivo':e['metadata']['filename'],'Archivo de ventas':e['metadata']['filename'],'Fila de ventas':r.get('Fila origen'),
                              'Período ventas':e['metadata']['period_start']+' a '+e['metadata']['period_end'],
                              'Importe neto':r.get('Importe neto'),'Monto bruto':r.get('Monto bruto'),
                              'Descuentos':r.get('Descuentos'),'IVA reportado':r.get('IVA reportado'),
                              'Costo de ventas':r.get('Costo de ventas')})
                    statuses.append({'Sede':site,'Inventario':cut,'Historial':str(len(c['months']))+' meses',
                       'Detalle':c['months'][0]+' a '+c['months'][-1], 'Productos':len(frame)})
                except (ValueError,KeyError) as exc:
                    frame=_pending_inventory_v717(inv,site,cut,str(exc),c,scope)
                    statuses.append({'Sede':site,'Inventario':cut,'Historial':'Revisar','Detalle':str(exc),'Productos':len(frame)})
        frames[site]=frame
    all_data,moves,adjusted=_postprocess_workspace_v717(frames,c)
    if not all_data.empty:
        # Conserva filas vendidas sin inventario sin inventar existencias para ellas.
        all_data.attrs['v7_sales_rows']=json.dumps(sales_ledger,ensure_ascii=False,default=str)
        all_data.attrs['v717_config']=config_json
    alerts=build_alerts(all_data)
    reports=project_report_frames(all_data,moves,alerts) if not all_data.empty else {}
    return {'data':all_data,'transfers':moves,'alerts':alerts,'sites':adjusted,'comparisons':comparisons,
            'status':pd.DataFrame(statuses),'dates':dates_used,'reports':reports,'config':c,
            'signature':hashlib.sha256((str(data_version)+config_json).encode()).hexdigest()}


def selected_sales_rows_v717(site,cut,scope):
    # El detalle original conserva filas sin código, importes y procedencia.
    rows = _sales_rows_for_reports_v7(v7_version(), ((site,cut),), scope)
    return [dict(r, **{'Ventas del período':r.get('Ventas')}) for r in rows]


def workspace_rotation_v717(result):
    """Candidatos, no un certificado de ausencia de todo movimiento físico."""
    data=result['data'].copy()
    if data.empty:return data
    inventory=data.loc[data['Existencia'].gt(0)].copy()
    if result['config']['mode']=='mensual':
        columns=['Unidades '+m for m in result['config']['months']]
        values=inventory.reindex(columns=columns).apply(pd.to_numeric,errors='coerce')
        candidate=values.notna().all(axis=1)&values.eq(0).all(axis=1)
        candidate &= ~inventory.get('Identidad pendiente',pd.Series(False,index=inventory.index)).fillna(True).astype(bool)
    else:
        candidate=inventory['Ventas'].eq(0)&inventory.get('Historial de ventas',pd.Series('',index=inventory.index)).eq('Disponible')
        candidate &= ~inventory.get('Identidad pendiente',pd.Series(False,index=inventory.index)).fillna(True).astype(bool)
    out=inventory.loc[candidate].copy()
    if out.empty:return out
    ledger=json.loads(result['data'].attrs.get('v7_sales_rows','[]'))
    positives={}
    for row in ledger:
        q=pd.to_numeric(row.get('Ventas del período'),errors='coerce')
        if pd.notna(q) and q>0:positives.setdefault(str(row.get('Código','')),set()).add(row.get('Sede'))
    complete_scope=len(result['comparisons'])==len(result['config']['sites']) if result['config']['mode']=='mensual' else False
    all_company=complete_scope and set(result['config']['sites'])==set(SEDES)
    out['Sedes con venta neta positiva']=out['Código'].map(lambda code:', '.join(sorted(positives.get(str(code),set()))))
    out['Lectura entre sedes']=np.where(out['Sedes con venta neta positiva'].ne(''),'Revisar traslado a sede con demanda',
        'Sin venta neta positiva documentada en todas las sedes cargadas' if all_company else 'Sin venta neta positiva en la selección; no concluye toda la empresa')
    out['Validación comercial']='Pendiente: conteo físico, fecha de alta, movimientos brutos, estado, fotos y precio autorizado'
    return out


def _set_route_v717(page,section=None):
    if section is not None:
        field={'Inventario y decisiones':'v717_analysis_tab','Reportes y planillas':'v717_report_tab',
               'Formatos A2':'v717_format_tab','Control y complementos':'v717_control_tab','Datos base':'v717_data_tab'}.get(page)
        if field:st.session_state[field]=section
    st.session_state['nexus_view']=page
    st.rerun()


def workspace_navigation_v717():
    aliases={
       'Carga de datos':('Datos base','Cargar / actualizar'), 'Cargar archivos':('Datos base','Cargar / actualizar'),
       'Cortes Diarios':('Datos base','Cargar / actualizar'), 'Datos Financieros':('Control y complementos','Datos financieros'),
       'Centro de Control':('Control visual',None), 'Inventario':('Inventario y decisiones','Inventario'),
       'Mínimos y Máximos':('Inventario y decisiones','Mínimos y máximos'), 'Compras':('Inventario y decisiones','Compras'),
       'Redistribución':('Inventario y decisiones','Redistribución'), 'Sin Rotación':('Inventario y decisiones','Sin rotación'),
       'Alertas':('Inventario y decisiones','Revisión de datos'), 'Proveedores':('Inventario y decisiones','Inventario'),
       'Centro Visual':('Control visual',None),
       'Reportes':('Reportes y planillas','Informe completo'), 'Planilla A2':('Reportes y planillas','Planilla A2 · seis columnas'),
       'Preparador A2':('Formatos A2','Limpiar Excel A2 antes de guardar'),
       V715_VIEW:('Formatos A2','Comparar archivos mensuales sin cambiar la base'),
       V714_COMPLETE_VIEW:('Formatos A2','Catálogo de proveedor · cruce puntual'),
       'Ranking mensual A2':('Formatos A2','Ranking PDF · cálculo puntual'),
       'Revisar planilla A2':('Formatos A2','Planilla A2 existente · revisar o pasar a Excel'),
       'Reposición por proveedor':('Formatos A2','Reposición por plazo y frecuencia · simulación'),
       'Gestión y ajustes':('Control y complementos','Respaldo y mantenimiento'),
       'Desempeño Integral':('Control y complementos','Análisis financiero'),
       'Cuentas por Cobrar':('Control y complementos','Cuentas por cobrar'),
       'Gestión Visual':('Control y complementos','Tareas'), 'Finanzas':('Control y complementos','Análisis financiero'),
       'Historial':('Datos base','Ver lo guardado'), 'Automatización':('Control y complementos','Webhook operativo'),
       'Guía de uso':('Control y complementos','Guía del flujo')}
    current=st.session_state.get('nexus_view','Inicio')
    if current in aliases:
        page,section=aliases[current]
        field={'Inventario y decisiones':'v717_analysis_tab','Reportes y planillas':'v717_report_tab','Formatos A2':'v717_format_tab',
               'Control y complementos':'v717_control_tab','Datos base':'v717_data_tab','Control visual':'v718_visual_tab'}[page]
        if section is not None:st.session_state[field]=section
        st.session_state['nexus_view']=page;current=page
    if current not in V717_PAGES:
        current='Inicio';st.session_state['nexus_view']=current
    labels=('Inicio · tu base de trabajo','1 · Datos base','◈ Control visual · gerencia','2 · Inventario y decisiones',
            '3 · Reportes y planillas','4 · Formatos A2 especiales','5 · Control y complementos')
    for label,page in zip(labels,V717_PAGES):
        if st.button(label,key='v717_nav_'+page,width='stretch',type='primary' if current==page else 'secondary'):
            _set_route_v717(page)
    st.caption('Carga una vez. El análisis y sus documentos comparten sedes, fuentes y regla. Los formatos puntuales no cambian tu base automáticamente.')
    return current


def _section_v717(label,options,key,default=None):
    if st.session_state.get(key) not in options:st.session_state[key]=default or options[0]
    return st.radio(label,list(options),horizontal=True,key=key)


def render_home_v717():
    st.title('Tu inventario y tus ventas son el punto de partida')
    st.markdown('**Datos base → Control visual / Inventario y decisiones → Reportes y planillas.** Carga el inventario de cada sede y sus meses una vez; después trabaja sobre esa misma base.')
    inventory,months,cuts=registered_multisite_v716()
    st.dataframe(inventory,hide_index=True,width='stretch')
    a,b,c=st.columns(3)
    with a:
        st.subheader('1. Tener los datos')
        st.write('Cargar todas las sedes y comprobar qué inventarios y meses quedaron registrados.')
        if st.button('Cargar o revisar mi base',key='v717_home_data',width='stretch'):_set_route_v717('Datos base')
    with b:
        st.subheader('2. Decidir qué hacer')
        st.write('Ver existencias, elegir la regla de mínimos/máximos y obtener compras, retiros, traslados y candidatos sin rotación.')
        if st.button('Abrir inventario y decisiones',key='v717_home_ops',width='stretch',type='primary'):_set_route_v717('Inventario y decisiones')
    with c:
        st.subheader('3. Preparar la entrega')
        st.write('Descargar el informe completo, órdenes o la planilla A2 original. No volver a cargar los mismos archivos.')
        if st.button('Abrir reportes y planillas',key='v717_home_reports',width='stretch'):_set_route_v717('Reportes y planillas')
    if st.button('Abrir Control visual · números y gráficas para gerencia',key='v718_home_visual',type='primary'):_set_route_v717('Control visual')
    st.info('Los ranking PDF, las comparaciones A2 y las simulaciones por proveedor están juntos en Formatos A2 especiales. Son herramientas puntuales, no otro punto de inicio obligatorio.')
    st.caption('CxC, contactos, imágenes, precios de venta y condiciones de devolución son datos adicionales. Inventario y ventas no permiten inventarlos.')


def render_data_center_v717():
    st.title('1 · Datos base')
    st.write('Aquí se actualizan los datos de las sedes. Las pantallas de resultados no te volverán a pedir el inventario ni los meses.')
    tab=_section_v717('Qué necesitas hacer',('Cargar / actualizar','Ver lo guardado','Marcas y tipos de producto','Catálogos anteriores · avanzado'),'v717_data_tab')
    if tab=='Ver lo guardado':
        render_registered_multisite_v716()
        render_saved_history_v7()
    elif tab=='Marcas y tipos de producto':
        render_classification_center_v718()
    elif tab=='Catálogos anteriores · avanzado':
        st.caption('Proveedor, marca y departamento son clasificaciones. No cambian unidades vendidas ni existencias.')
        render_catalogs_v7()
    else:
        mode=_section_v717('Tipo de entrada',('Inventarios + meses completos · una o varias sedes','Ventas por rango, días o CxC · avanzado'),'v717_load_kind')
        st.caption('Un inventario es una fotografía; cada mes de ventas es un período. Nunca se suman dos inventarios para obtener el stock actual.')
        render_load_center_direct_v78(monthly_multisite=mode.startswith('Inventarios'))
    if st.button('Continuar a inventario y decisiones',key='v717_data_next',type='primary'):
        _set_route_v717('Inventario y decisiones')


def render_context_controls_v717():
    active=workspace_config_v717()
    with st.expander('Sedes, inventarios, meses y regla · cambiar el análisis completo',expanded=not bool(active['sites'])):
        st.caption('Estas decisiones se aplican a todas las vistas y descargas del análisis. Guardarlas no modifica A2 ni los archivos originales.')
        sites=st.multiselect('Sedes participantes',SEDES,default=active['sites'],key='v717_context_sites')
        cols=st.columns(2)
        def select_sites_v717(values):
            st.session_state['v717_context_sites']=list(values)
        cols[0].button('Seleccionar todas las sedes',key='v717_context_all',on_click=select_sites_v717,args=(SEDES,))
        cols[1].button('Limpiar selección',key='v717_context_none',on_click=select_sites_v717,args=([],))
        mode=st.selectbox('Origen del historial',list(V717_SOURCE_MODES),format_func=V717_SOURCE_MODES.get,
                         index=list(V717_SOURCE_MODES).index(active['mode']),key='v717_context_mode')
        policies=list(V717_RULES) if mode=='mensual' else ['cobertura']
        if st.session_state.get('v717_context_policy') not in policies:st.session_state['v717_context_policy']=active['policy'] if active['policy'] in policies else policies[0]
        policy=st.selectbox('Regla de mínimos y máximos de TODO este análisis',policies,format_func=V717_RULES.get,key='v717_context_policy')
        if policy=='dos_mejores':
            st.info('Cada código elige sus dos mejores meses por UNIDADES. Máximo = suma de ambos; mínimo = mitad. Para compras bajo mínimo se usa ese mínimo, no se añade plazo ni seguridad.')
        else:
            st.caption('Promedio × coberturas conserva la política original. Con meses seleccionados se divide por su cantidad; con historial del motor se conserva el divisor y período ya configurados.')
        supplier=active.get('supplier','')
        if supplier:
            st.warning('Filtro heredado de proveedor activo: '+supplier+'. No se mezcla con los filtros nuevos de marca.')
            if st.checkbox('Quitar filtro heredado de proveedor al aplicar',key='v718_remove_legacy_supplier'):supplier=''
        st.caption('Los filtros de marca, departamento y tipo están debajo del contexto. No requieren proveedores.')
        scopes={};cuts={};source_choices={};available=[]
        with st.container(border=True):
            st.caption('Inventario de cada sede y fuentes mensuales · revisar solo si necesitas cambiarlos')
            for site in sites:
                st.markdown('**'+site+'**')
                with db() as con:
                    scope_names=[r[0] for r in con.execute('SELECT DISTINCT supplier_name FROM supplier_inventory_snapshots WHERE site=? ORDER BY supplier_name',(site,))]
                options=['']+scope_names;default_scope=active.get('scopes',{}).get(site,'')
                chosen=st.selectbox('Inventario de '+site,options,index=options.index(default_scope) if default_scope in options else 0,
                       format_func=lambda x:x or 'Inventario completo de la sede',key='v717_scope_'+site)
                scopes[site]=chosen
                if chosen:
                    with db() as con:date_options=[r[0] for r in con.execute('SELECT DISTINCT snapshot_date FROM supplier_inventory_snapshots WHERE site=? AND supplier_key=? ORDER BY snapshot_date DESC',(site,normalize_key(chosen)))]
                else:date_options=list_snapshot_dates(site)
                date_labels=['Último inventario disponible']+date_options
                prev=active.get('cuts',{}).get(site,'') or date_labels[0]
                value=st.selectbox('Fecha de inventario de '+site,date_labels,index=date_labels.index(prev) if prev in date_labels else 0,key='v717_cut_'+site)
                cuts[site]='' if value==date_labels[0] else value
                items=eligible_monthly_sources_v717(site,chosen)
                available.extend(x['month'] for x in items)
                if mode=='mensual':
                    st.caption('Si un mes tiene una sola fuente del motor, se selecciona automáticamente. Fuentes distintas nunca se suman entre sí.')
                    source_choices[site]={}
                    for month in sorted(set(x['month'] for x in items)):
                        candidates=[x for x in items if x['month']==month]
                        if len(candidates)>1:
                            keys=['']+[x['key'] for x in candidates];labels={x['key']:x['source']+' · '+x['scope']+' · '+x['name'] for x in candidates}
                            prior=active.get('sources',{}).get(site,{}).get(month,'')
                            chosen_key=st.selectbox(site+' · '+month,keys,index=keys.index(prior) if prior in keys else 0,
                                format_func=lambda k,labels=labels:labels.get(k,'Automático: priorizar fuente única del motor'),key='v717_src_'+site+month)
                            if chosen_key:source_choices[site][month]=chosen_key
        available=sorted(set(available))
        months=[]
        if mode=='mensual':
            options=[str(p) for p in pd.period_range(available[0],available[-1],freq='M')] if available else []
            defaults=[m for m in active.get('months',[]) if m in options] or options[-6:]
            existing=st.session_state.get('v717_context_months')
            if existing is not None:st.session_state['v717_context_months']=[m for m in existing if m in options]
            months=st.multiselect('Meses comunes para comparar las sedes',options,default=defaults,key='v717_context_months',format_func=month_label_v715)
            if not options:st.warning('No hay meses completos guardados para esta selección. Cárgalos en Datos base o usa el historial del motor.')
        with st.container(border=True):
            st.caption('Coberturas, redondeo y reglas de revisión')
            a,b=st.columns(2)
            low=a.number_input('Cobertura mínima (meses)',min_value=0.1,max_value=12.0,value=float(active['min_coverage']),step=0.1,key='v717_context_low',disabled=policy=='dos_mejores')
            high=b.number_input('Cobertura máxima (meses)',min_value=0.5,max_value=24.0,value=float(active['max_coverage']),step=0.5,key='v717_context_high',disabled=policy=='dos_mejores')
            lead=a.number_input('Plazo de entrega (días)',min_value=0,max_value=180,value=int(active['lead_time_days']),key='v717_context_lead',disabled=policy=='dos_mejores')
            safety=b.number_input('Reserva (días)',min_value=0,max_value=90,value=int(active['safety_days']),key='v717_context_safety',disabled=policy=='dos_mejores')
            hist=a.number_input('Meses solo para historial antiguo SIN fechas',min_value=1,max_value=36,value=int(active['months_history']),key='v717_context_hist')
            round_rule=b.selectbox('Mínimo del método dos mejores',('exact','up'),index=('exact','up').index(active['rounding']),format_func=lambda x:'50% exacto' if x=='exact' else 'Redondear hacia arriba',key='v717_context_round')
            manual=st.checkbox('Respetar límites manuales que ya están guardados por producto',value=active['respect_manual'],key='v717_context_manual',disabled=mode=='periodo')
            complete=st.checkbox('Confirmé que las fuentes mensuales son completas del alcance elegido: un código ausente equivale a cero neto identificado',value=active['complete_reports'],key='v717_context_complete',disabled=mode!='mensual')
            returns=st.checkbox('Revisé las ventas netas negativas y sus devoluciones',value=active['review_returns'],key='v717_context_returns')
            zero=st.checkbox('Autorizar límites cero y sus propuestas de retiro para esta selección',value=active['approve_zero'],key='v717_context_zero')
            st.caption('Sin autorización, los ceros permanecen visibles pero no producen traslados/retiros ni se envían a la planilla validada. Cero neto no acredita que jamás se vendió.')
        draft=dict(active,sites=sites,mode=mode,policy=policy,months=months,scopes=scopes,cuts=cuts,sources=source_choices,
                   supplier=supplier,complete_reports=complete,review_returns=returns,approve_zero=zero,rounding=round_rule,
                   respect_manual=manual if mode=='mensual' else True,min_coverage=low,max_coverage=high,lead_time_days=int(lead),safety_days=int(safety),months_history=int(hist))
        changed=json.dumps(draft,sort_keys=True)!=json.dumps(active,sort_keys=True)
        if changed:st.warning('Hay cambios sin aplicar. Pulsa el botón para actualizar TODAS las vistas y documentos. Las descargas quedan bloqueadas mientras tanto.')
        if st.button('Aplicar selección y recalcular todo',type='primary',key='v717_context_apply'):
            try:save_workspace_config_v717(draft);st.rerun()
            except ValueError as exc:st.error(str(exc))
    return active, changed


def current_workspace_result_v717(apply_product_scope=True):
    config,changed=render_context_controls_v717()
    if changed:
        st.info('Aplica los cambios de arriba antes de consultar o descargar resultados.');return None
    if not config['sites']:
        st.info('Todavía no hay sedes seleccionadas con inventario. Empieza en Datos base.');return None
    try:
        with st.spinner('Preparando el análisis común…'):
            result=calculate_workspace_v717(db_version(),json.dumps(config,ensure_ascii=False,sort_keys=True))
    except (ValueError,KeyError,sqlite3.DatabaseError) as exc:
        st.error('No se pudo preparar la selección: '+str(exc));return None
    st.caption('MISMA BASE PARA TODAS LAS VISTAS · '+', '.join(config['sites'])+' · '+V717_RULES[config['policy']])
    st.dataframe(result['status'],hide_index=True,width='stretch')
    if result['data'].empty:
        st.info('No hay productos para este alcance. No se han borrado datos: revisa sede, fecha y proveedor.');return None
    for identity_site,comparison in result.get('comparisons',{}).items():
        render_identity_review_v7184(comparison.get('identity_plan'),'v7184_workspace_'+safe_slug(identity_site))
    if result.get('config',{}).get('mode')=='periodo':
        for identity_site,frame in result.get('sites',{}).items():
            render_identity_review_v7184(deserialize_identity_plan_v7184(frame.attrs.get('v7184_identity_plan')),'v7184_period_'+safe_slug(identity_site))
    resources=classification_resources_v718(v7_version())
    result=enrich_workspace_v718(result,resources)
    result=render_product_scope_v718(result) if apply_product_scope else filter_workspace_v718(result,V718_FILTER_DEFAULT)
    if result is None:return None
    # Compatibilidad explícita con generadores antiguos que consultan estos globales.
    globals().update(all_df=result['data'],transfers=result['transfers'],alerts=result['alerts'],
                      site_results_adjusted=result['sites'],site_results=result['sites'],dates_used=result['dates'],
                      latest_display=workspace_label_v717(result))
    return result


def workspace_label_v717(result):
    c=result['config'];period=(c['months'][0]+'_'+c['months'][-1]) if c['mode']=='mensual' and c['months'] else 'historial_guardado'
    return period+' · '+V717_RULES[c['policy']]+' · inventarios '+', '.join(sorted(set(result['dates'].values())))+(' · '+result['scope_label'] if result.get('filter_applied') else '')


def render_paged_table_v717(frame,key,columns=None):
    cols=[c for c in (columns or frame.columns) if c in frame]
    count=len(frame)
    st.caption(f'{count:,} filas. La paginación de pantalla no recorta el archivo completo.')
    if count==0:
        st.info('No hay filas en esta selección.');return
    pages=max(1,math.ceil(count/100))
    if int(st.session_state.get('page_'+key,1))>pages:st.session_state['page_'+key]=1
    page=st.number_input('Página',min_value=1,max_value=pages,value=1,step=1,key='page_'+key)
    st.dataframe(frame.iloc[(page-1)*100:page*100][cols],hide_index=True,width='stretch',height=460)


def render_operation_center_v717():
    st.title('2 · Inventario y decisiones')
    result=current_workspace_result_v717()
    if result is None:return
    data=result['data'];c=result['config']
    tab=_section_v717('Ver sobre la misma base',V717_ANALYSIS,'v717_analysis_tab')
    if tab=='Resumen':
        a,b,d,e=st.columns(4)
        a.metric('Productos / sede',len(data));b.metric('Con revisión pendiente',int(data['Bloqueo operativo'].ne('').sum()))
        d.metric('Unidades por comprar',_quantity_text_v73(data['Compra Ajustada'].sum()));e.metric('Traslados propuestos',len(result['transfers']))
        st.dataframe(currency_summary_v714(data),hide_index=True,width='stretch')
        st.markdown('**El orden de decisión:** revisar datos → mínimos/máximos → redistribuir → comprar lo que falta → gestionar exceso y sin rotación → preparar documentos.')
        st.caption('Trasladar mercancía entre sedes no equivale a venderla ni a recuperar caja. Las cantidades son propuestas; confirma stock físico, capacidad de recepción y costos antes de ejecutarlas.')
    elif tab=='Mínimos y máximos':
        monthcols=['Unidades '+m for m in c['months']] if c['mode']=='mensual' else []
        columns=['Sede','Código','Descripción','Existencia']+monthcols+['Mes mayor 1','Unidades mayor 1','Mes mayor 2','Unidades mayor 2',
                 'Stock Mínimo','Stock Máximo','Punto de Reorden','Política de stock','Bloqueo operativo']
        render_paged_table_v717(data,'limits',columns)
        st.caption('Máximo − existencia (A pedir de la planilla) no es lo mismo que compra bajo punto de reorden. La compra neta descuenta los traslados recibidos.')
    elif tab=='Redistribución':
        st.caption('Sólo entre las sedes seleccionadas arriba. Cada unidad se descuenta una vez del excedente de origen. No se proponen movimientos de productos bloqueados.')
        render_paged_table_v717(result['transfers'],'moves')
    elif tab=='Compras':
        render_paged_table_v717(data.loc[data['Compra Ajustada'].gt(0)],'buys',
            ['Sede','Código','Descripción','Existencia','Stock Mínimo','Stock Máximo','Compra Sugerida','Transferencias Recibidas','Compra Ajustada','Costo','Moneda inventario','Costo Compra Estimada ($)'])
    elif tab=='Sobrestock y retiros':
        render_paged_table_v717(data.loc[data['Retiro Almacén'].gt(0)],'excess',
             ['Sede','Código','Descripción','Existencia','Stock Máximo','Retiro Almacén','Transferencias Enviadas','Retiro neto','Moneda inventario','Capital Inmovilizado ($)'])
    elif tab=='Sin rotación':
        st.warning('Este listado identifica candidatos sin ventas NETAS en el período cargado. No prueba ausencia absoluta de ventas, disponibilidad durante todo el período ni falta de movimientos físicos. Revisa facturas/devoluciones, fecha de alta y conteo antes de promocionar o devolver.')
        candidates=workspace_rotation_v717(result)
        render_paged_table_v717(candidates,'no_rotation',['Sede','Código','Descripción','Departamento','Marca','Tipo de producto','Existencia','Período ventas','Lectura rotación','Sedes con venta neta positiva','Lectura entre sedes','Bloqueo operativo'])
        if not candidates.empty:
            fields=[x for x in ['Sede','Código','Descripción','Departamento','Marca','Tipo de producto','Existencia','Período ventas','Lectura entre sedes','Validación comercial'] if x in candidates]
            st.download_button('Descargar candidatos para validar el portafolio · CSV',export_csv_bytes(candidates[fields]),
                'Candidatos_portafolio_pendientes.csv','text/csv',key='v717_candidates_download',on_click='ignore')
    elif tab=='Revisión de datos':
        render_paged_table_v717(result['alerts'],'alerts')
        if result['comparisons']:
            missing=[dict(r,Sede=s) for s,res in result['comparisons'].items() for r in res['unidentified'].to_dict('records')]
            if missing:
                st.subheader('Ventas sin código · no se asignaron por parecido')
                render_paged_table_v717(pd.DataFrame(missing),'no_code')
    else:
        render_paged_table_v717(data,'inventory',['Sede','Código','Descripción','Departamento','Marca','Tipo de producto','Existencia','Ventas','Demanda Mensual','Stock Mínimo','Stock Máximo','Estado','Acción','Bloqueo operativo'])
    if st.button('Preparar documentos de esta misma selección',type='primary',key='v717_ops_exports'):
        _set_route_v717('Reportes y planillas')


def render_shared_planilla_v717(result):
    """Sin otro cargador: solo el resultado común y la plantilla incorporada."""
    data=result['data'];sites=sorted(data['Sede'].unique())
    if result.get('selection',{}).get('include_suggestions'):
        if not st.checkbox('Revisé la selección que incluye marcas sugeridas antes de emitir la planilla',key='v718_plan_suggestions_'+result['signature'][:12]):
            st.info('Confirma las relaciones en Datos base o revisa expresamente la selección.');return
    site=st.selectbox('Sede de esta planilla',sites,key='v717_plan_site')
    source=data.loc[data['Sede'].eq(site)].copy()
    eligible=source['Bloqueo operativo'].eq('') & source['Stock Mínimo'].notna() & source['Stock Máximo'].notna() & source['Existencia'].ge(0)
    valid=source.loc[eligible].copy()
    st.caption(f'{len(source)} productos del alcance · {len(valid)} seleccionables · {int((~eligible).sum())} pendientes. Ningún pendiente desaparece del informe completo.')
    with st.expander('Ver los códigos que no se enviarían a la planilla'):
        st.dataframe(source.loc[~eligible,['Código','Descripción','Stock Mínimo','Stock Máximo','Bloqueo operativo']],hide_index=True,width='stretch')
    if valid.empty:
        st.info('No hay productos validados para esta sede. Revisa los bloqueos en Inventario y decisiones.');return
    codes=valid['Código'].tolist()
    all_codes=st.checkbox('Incluir todos los productos validados de esta sede',value=True,key='v717_plan_all')
    selected=codes if all_codes else st.multiselect('Códigos incluidos',codes,key='v717_plan_codes')
    chosen=valid.loc[valid['Código'].isin(selected)].copy()
    plan=chosen.rename(columns={'Stock Mínimo':'Mínimo','Stock Máximo':'Máximo'})
    plan['A pedir']=(plan['Máximo']-plan['Existencia']).clip(lower=0)
    plan=plan[V714_PLAN_COLUMNS]
    title=st.text_input('Razón social / título de la sede',value='MAKROPETROL, C.A.' if site=='Matriz Makropetrol' else site.upper(),key='v717_plan_title_'+site)
    group=st.text_input('Grupo / departamento que se imprime',value=result.get('scope_label') or 'Inventario seleccionado',key='v717_plan_group_'+result['signature'][:12])
    meta={'Sede':site,'Título encabezado':title,'Departamento encabezado':group,'Marca':'','Proveedor':result['config'].get('supplier',''),
          'Existencia para planilla':'NEXUS','Origen de los límites':V717_RULES[result['config']['policy']],
          'Versión NEXUS':APP_VERSION,'Ajustar paginación':True,'Factor libre':workspace_label_v717(result),
          'Dirección línea 1':'','Dirección línea 2':'','Teléfono encabezado':''}
    render_paged_table_v717(plan,'planilla')
    st.info('Esta planilla conserva seis columnas. A pedir completa al máximo sin descontar traslados: para la compra ajustada utiliza Órdenes y movimientos. No es una orden ejecutada en A2.')
    signature=reconciliation_fingerprint_v714([result['signature'],site,selected,meta])
    if st.session_state.get('v717_plan_exports',{}).get('signature')!=signature:st.session_state.pop('v717_plan_exports',None)
    if st.button('Preparar planilla A2 · Excel y PDF',key='v717_plan_prepare',type='primary',disabled=plan.empty or not title.strip() or not group.strip()):
        payload={'signature':signature,'files':{}};meta.update(_mm_generation_metadata_v711())
        for kind,builder in [('xlsx',lambda:build_minmax_planilla_excel_v713(plan,meta,builtin_a2_template_v712())),
                              ('pdf',lambda:build_minmax_original_pdf_v710(builtin_a2_template_v712(),plan,meta))]:
            try:payload['files'][kind]=builder()
            except Exception as exc:st.error(kind.upper()+': '+str(exc))
        st.session_state['v717_plan_exports']=payload
    for kind,raw in st.session_state.get('v717_plan_exports',{}).get('files',{}).items():
        if raw:st.download_button('Descargar planilla '+kind.upper(),raw,'Planilla_A2_'+safe_slug(site+'_'+result.get('scope_label',''))+'.'+kind,
                    DOC_MIME_XLSX if kind=='xlsx' else DOC_MIME_PDF,key='v717_plan_dl_'+kind,on_click='ignore')


def render_shared_documents_v717(result):
    data=result['data'];moves=result['transfers'];alerts=result['alerts'];label=max(result['dates'].values(),default='sin cortes')
    kind=st.selectbox('Documento',('Compra neta por sede','Retiro neto por sede','Redistribución del alcance','Alertas por sede'),key='v717_doc_kind')
    site=st.selectbox('Sede del documento',sorted(data['Sede'].unique()),key='v717_doc_site',disabled=kind=='Redistribución del alcance')
    export=st.selectbox('Formato de entrega',('Excel','PDF','HTML imprimible','CSV'),key='v717_doc_format')
    mapping={'Compra neta por sede':'purchase','Retiro neto por sede':'withdrawal','Redistribución del alcance':'redistribution','Alertas por sede':'alerts'}
    doc_kind=mapping[kind]
    src=moves if doc_kind=='redistribution' else alerts if doc_kind=='alerts' else data
    prepared=_doc_prepare_frame(src,doc_kind,None if doc_kind=='redistribution' else site)
    render_paged_table_v717(prepared,'document')
    st.caption('La sede de impresión no vuelve a calcular el plan: los traslados y la compra neta son los de la selección común de arriba. Son propuestas, no autorizaciones de despacho.')
    key=hashlib.sha256((result['signature']+kind+site+export).encode()).hexdigest()
    if st.session_state.get('v717_doc_ready',{}).get('key')!=key:st.session_state.pop('v717_doc_ready',None)
    if st.button('Preparar documento',key='v717_doc_prepare',disabled=prepared.empty):
        try:
            if export=='Excel':
                raw=build_purchase_excel(data,site,label) if doc_kind=='purchase' else export_xlsx_bytes(prepared,kind,warehouse_report=True)
                ext,mime='xlsx',DOC_MIME_XLSX
            elif export=='PDF':
                if doc_kind=='purchase':raw=build_purchase_pdf(data,site,label)
                elif doc_kind=='withdrawal':raw=build_withdrawal_pdf(data,site,label)
                elif doc_kind=='alerts':raw=build_alerts_pdf(alerts,site,label)
                else:raw=build_redistribution_pdf(moves,label)
                ext,mime='pdf',DOC_MIME_PDF
            elif export=='HTML imprimible':
                raw=build_operational_html(doc_kind,src,None if doc_kind=='redistribution' else site,label,kind);ext,mime='html',DOC_MIME_HTML
            else:raw=export_csv_bytes(prepared,warehouse_report=True);ext,mime='csv','text/csv'
            if not raw:raise ValueError('No se generó el archivo; revisa las dependencias del formato.')
            st.session_state['v717_doc_ready']={'key':key,'bytes':raw,'ext':ext,'mime':mime}
        except Exception as exc:st.error('No se generó este documento: '+str(exc))
    ready=st.session_state.get('v717_doc_ready')
    if ready and ready['key']==key:
        st.download_button('Descargar '+kind,ready['bytes'],safe_slug(kind+'_'+site+'_'+result.get('scope_label',''))+'.'+ready['ext'],ready['mime'],key='v717_doc_download',on_click='ignore')


def render_export_center_v717():
    st.title('3 · Reportes y planillas')
    result=current_workspace_result_v717()
    if result is None:return
    st.caption('Los filtros de marca, departamento, familia y código de arriba se aplican a TODOS los formatos. La clasificación se conserva en un anexo; la planilla A2 sigue en seis columnas.')
