def init_visual_catalog_v718():
    """Migración aditiva; el catálogo es vocabulario, nunca membresía de SKU."""
    with db() as con:
        present=con.execute("SELECT 1 FROM sqlite_master WHERE name='v718_product_labels'").fetchone()
        has_data=con.execute('SELECT 1 FROM inventory_snapshots UNION ALL SELECT 1 FROM supplier_inventory_snapshots LIMIT 1').fetchone()
    if not present and has_data:
        path=DB_PATH.with_name('nexus_pre_718_'+datetime.now().strftime('%Y%m%d_%H%M%S_%f')+'.db')
        path.write_bytes(backup_database_bytes())
    with db() as con:
        con.executescript('''
        CREATE TABLE IF NOT EXISTS v718_department_catalog (
            origin TEXT NOT NULL,code TEXT NOT NULL,name TEXT NOT NULL,active TEXT,classification TEXT,
            filename TEXT,sha256 TEXT,row_no INTEGER,PRIMARY KEY(origin,name));
        CREATE TABLE IF NOT EXISTS v718_catalog_scopes (site TEXT PRIMARY KEY,origin TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS v718_product_labels (
            site TEXT NOT NULL,code TEXT NOT NULL,description TEXT NOT NULL,
            department TEXT NOT NULL,brand TEXT NOT NULL,family TEXT NOT NULL,ptype TEXT NOT NULL,
            evidence TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(site,code));
        CREATE TABLE IF NOT EXISTS v718_classification_audit (
            id INTEGER PRIMARY KEY AUTOINCREMENT,updated_at TEXT NOT NULL,site TEXT NOT NULL,code TEXT NOT NULL,
            before_json TEXT NOT NULL,after_json TEXT NOT NULL,reason TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS v718_alias_rules (
            term TEXT PRIMARY KEY,brand TEXT NOT NULL,department TEXT NOT NULL,
            enabled INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
        ''')
        for rec in V718_REFERENCE_DEPARTMENTS:
            con.execute('INSERT OR IGNORE INTO v718_department_catalog VALUES (?,?,?,?,?,?,?,?)',
                (V718_CATALOG_SOURCE,rec['code'],rec['name'],rec['active'],rec['classification'],
                 V718_CATALOG_FILE,V718_CATALOG_SHA,rec['row']))


def _label_text_v718(value):
    if value is None:return ''
    try:
        if pd.isna(value):return ''
    except (ValueError,TypeError):return ''
    text=str(value).strip()
    return '' if normalize_key(text) in {'nan','none','n d','sin asignar','sin dato','no informado'} else text


def _brand_from_department_v718(name):
    """Sugerencia semántica de catálogo; grupos genéricos no se vuelven marcas."""
    text=_label_text_v718(name);key=normalize_key(text)
    if not text or key in V718_GENERIC_DEPARTMENTS:return ''
    if key.startswith('filtros '):return re.sub(r'^FILTROS\s+','',text,flags=re.I).strip()
    if key.endswith(' filtros'):return re.sub(r'\s+FILTROS$','',text,flags=re.I).strip()
    if key=='cascos edge':return 'EDGE'
    return text


@st.cache_data(show_spinner=False,max_entries=6)
def classification_resources_v718(version):
    with db() as con:
        catalog=pd.read_sql_query('SELECT origin,code,name,active,classification,filename,row_no FROM v718_department_catalog',con)
        legacy=pd.read_sql_query("SELECT 'Catálogo NEXUS anterior' AS origin,code,name,active,classification,'Base NEXUS' AS filename,0 AS row_no FROM v7_catalog WHERE kind='departamentos'",con)
        labels=pd.read_sql_query('SELECT * FROM v718_product_labels',con)
        aliases=pd.read_sql_query('SELECT * FROM v718_alias_rules WHERE enabled=1',con)
        scopes=dict(con.execute('SELECT site,origin FROM v718_catalog_scopes').fetchall())
    full=pd.concat([catalog,legacy],ignore_index=True).drop_duplicates(['origin','name'])
    full['brand_hint']=full['name'].map(_brand_from_department_v718)
    return {'catalog':full,'labels':labels,'aliases':aliases,'scopes':scopes}


def detect_product_type_v718(description):
    """Detección explicable; prueba familia ANTES del fluido/aplicación."""
    text=normalize_key(description)
    if not text:return 'Sin clasificar','Sin clasificar','Sin descripción'
    patterns=[
        (r'\b(?:kit|juego)\b.*\bfiltros?\b','Filtros','Kit de filtros'),
        (r'\b(?:porta filtro|portafiltro|base de filtro|turbina separador)\b','Accesorios de filtración','Portafiltro / separador'),
        (r'\bfiltros?\b.*\b(?:cabina|habitaculo|polen)\b','Filtros','Filtro de cabina'),
        (r'\bfiltros?\s+(?:de\s+)?(?:combustible|comb|separador|diesel|gasolina)\b','Filtros','Filtro de combustible / separador'),
        (r'\bfiltros?\b.*\baire\b','Filtros','Filtro de aire'),
        (r'\bfiltros?\b.*\b(?:hidraulico|hidraulica)\b','Filtros','Filtro hidráulico'),
        (r'\bfiltros?\b.*\baceite\b','Filtros','Filtro de aceite'),
        (r'\bfiltros?\b','Filtros','Filtro · subtipo por revisar'),
        (r'\b(?:pastillas?|bandas?|discos?)\b.*\bfrenos?\b','Frenos','Pastillas / bandas / discos'),
        (r'\bliquido\b.*\bfrenos?\b','Fluidos','Líquido de frenos'),
        (r'\b(?:refrigerante|anticongelante)\b','Fluidos','Refrigerante'),
        (r'\b(?:aceite|lubricante)\b','Lubricantes','Aceite / lubricante'),
        (r'\bgrasa\b','Lubricantes','Grasa'),
        (r'\bbaterias?\b','Electricidad','Batería'),
        (r'\bbujias?\b','Encendido','Bujía'),
        (r'\blimpiaparabrisas?\b','Accesorios','Limpiaparabrisas'),
        (r'\b(?:bombillo|led|faro)\b','Iluminación','Bombillo / iluminación'),
        (r'\bcascos?\b','Protección','Casco'),
        (r'\b(?:silicon|pegamento|adhesivo|sellador)\b','Químicos','Adhesivo / sellador'),
        (r'\b(?:aditivo|limpiador|desengrasante)\b','Químicos','Aditivo / limpiador'),
    ]
    for pattern,family,ptype in patterns:
        if re.search(pattern,text):return family,ptype,'Regla de texto: '+pattern
    return 'Sin clasificar','Sin clasificar','No hubo una regla de tipo aplicable'


def classify_products_v718(frame,resources):
    """Original > asignación aprobada > sugerencias. No normaliza claves SKU."""
    data=frame.copy().reset_index(drop=True)
    if 'Código' not in data:data['Código']=pd.Series(dtype=str)
    for c in ['Descripción','Sede','Departamento','Marca']:
        data[c]=data.get(c,pd.Series('',index=data.index)).astype(object).map(_label_text_v718)
    data['Departamento original']=data['Departamento'];data['Marca original']=data['Marca']
    cats=resources['catalog'].to_dict('records')
    by_name={}
    for rec in cats:by_name.setdefault(normalize_key(rec['name']),[]).append(rec)
    aliases={}
    for rec in cats:
        brand=rec['brand_hint']
        if brand and normalize_key(brand) not in {'toyota','f1','sq'}:
            aliases.setdefault(normalize_key(brand),set()).add((brand,rec['name']))
    for rec in resources['aliases'].to_dict('records'):
        aliases.setdefault(normalize_key(rec['term']),set()).add((rec['brand'],rec['department']))
    label_map={(str(r['site']),str(r['code'])):r for r in resources['labels'].to_dict('records')}
    output=[]
    for rec in data.to_dict('records'):
        dept,brand=rec['Departamento'],rec['Marca'];description=rec['Descripción']
        family,ptype,type_evidence=detect_product_type_v718(description)
        state='Sin clasificar';source='';reason='';sdept='';sbrand=''
        override=label_map.get((rec['Sede'],str(rec['Código'])))
        matching=[]
        if dept:
            matching=by_name.get(normalize_key(dept),[])
            if not matching:
                # Los códigos de departamentos dependen del catálogo/sede.
                origin=resources['scopes'].get(rec['Sede'],'')
                matching=[c for c in cats if c['origin']==origin and _label_text_v718(c['code'])==re.sub(r'\.0$','',dept)] if origin else []
                names={c['name'] for c in matching}
                if len(names)==1:dept=next(iter(names))
                elif re.fullmatch(r'\d+(?:\.0)?',dept):reason='Departamento numérico sin catálogo confirmado para esta sede'
        if matching:
            hints={c['brand_hint'] for c in matching if c['brand_hint']}
            if not brand and len(hints)==1:brand=next(iter(hints))
        if dept or brand:
            state='Dato de origen / regla previa';source='A2 o clasificación previamente confirmada'
        if override:
            if normalize_key(override['description'])==normalize_key(description):
                dept,brand=override['department'],override['brand']
                family=override['family'] or family;ptype=override['ptype'] or ptype
                state='Confirmada por usuario';source='Asignación por sede y código'
                reason=override['evidence'];type_evidence='Confirmación por código'
            else:
                state='Revisar cambio de descripción';source='Asignación previa no aplicada'
                reason='Cambió la descripción del código desde su última confirmación'
        if not brand and state!='Confirmada por usuario':
            text=normalize_key(description);hits={}
            for term,targets in aliases.items():
                found=re.search(r'(?<!\w)'+re.escape(term)+r'(?!\w)',text)
                if not found:continue
                prefix=text[:found.start()].strip()
                # Equivalencias/aplicaciones NO acreditan fabricante.
                if re.search(r'(?:equivalente|equivalencia|reemplaza|sustituye|compatible|tipo|ref|referencia|eq|para)\s*$',prefix):continue
                for target,department in targets:hits.setdefault(target,[]).append((term,department))
            if len(hits)==1:
                sbrand=next(iter(hits));departments={x[1] for x in hits[sbrand] if x[1]}
                sdept=dept or (next(iter(departments)) if len(departments)==1 else '')
                if state!='Revisar cambio de descripción':state='Sugerida por descripción'
                source=source or 'Coincidencia literal de marca'
                reason=(reason+' | ' if reason else '')+'Texto reconocido: '+', '.join(sorted({x[0] for x in hits[sbrand]}))+'; confirmar fabricante'
            elif len(hits)>1:
                if state!='Revisar cambio de descripción':state='Ambigua · varias marcas'
                reason='Coinciden: '+', '.join(sorted(hits))+'. No se asigna una al azar.'
            elif not brand and not dept:
                reason=reason or 'No hay marca explícita ni evidencia suficiente en la descripción'
        if dept and not brand and normalize_key(dept) in V718_GENERIC_DEPARTMENTS:
            reason=(reason+' | ' if reason else '')+'Departamento genérico: no equivale a una marca'
        output.append({'Departamento':dept,'Marca':brand,'Familia producto':family,'Tipo de producto':ptype,
            'Departamento sugerido':sdept,'Marca sugerida':sbrand,'Estado clasificación':state,
            'Fuente clasificación':source,'Motivo clasificación':reason,'Origen tipo':type_evidence})
    for col in V718_LABEL_COLUMNS:data[col]=[r[col] for r in output]
    return data


def save_product_labels_v718(rows,reason='Confirmación de clasificación'):
    records=[]
    for row in rows:
        site=_label_text_v718(row.get('Sede'));code=_label_text_v718(row.get('Código'))
        if site not in SEDES or not code:raise ValueError('Cada asignación requiere sede válida y código exacto.')
        department=_label_text_v718(row.get('Departamento'));brand=_label_text_v718(row.get('Marca'))
        if not department and not brand:raise ValueError('Confirma una marca o departamento; no se guarda una clasificación vacía.')
        records.append((site,code,_label_text_v718(row.get('Descripción')),department,brand,
            _label_text_v718(row.get('Familia producto')),_label_text_v718(row.get('Tipo de producto')),str(reason),datetime.now().isoformat(timespec='microseconds')))
    with db() as con:
        for row in records:
            previous=con.execute('SELECT * FROM v718_product_labels WHERE site=? AND code=?',row[:2]).fetchone()
            con.execute('INSERT OR REPLACE INTO v718_product_labels VALUES (?,?,?,?,?,?,?,?,?)',row)
            con.execute('INSERT INTO v718_classification_audit(updated_at,site,code,before_json,after_json,reason) VALUES (?,?,?,?,?,?)',
                 (row[-1],row[0],row[1],json.dumps(previous,ensure_ascii=False),json.dumps(row,ensure_ascii=False),reason))
        touch_v7(con)
    st.cache_data.clear()
    return len(records)


def remove_product_label_v718(site,code):
    with db() as con:
        previous=con.execute('SELECT * FROM v718_product_labels WHERE site=? AND code=?',(site,code)).fetchone()
        con.execute('DELETE FROM v718_product_labels WHERE site=? AND code=?',(site,code))
        con.execute('INSERT INTO v718_classification_audit(updated_at,site,code,before_json,after_json,reason) VALUES (?,?,?,?,?,?)',
            (datetime.now().isoformat(timespec='microseconds'),site,code,json.dumps(previous,ensure_ascii=False),'null','Retirar asignación manual'))
        touch_v7(con)
    st.cache_data.clear()


@st.cache_data(show_spinner=False,max_entries=3)
def enrich_workspace_v718(result,resources):
    """Sólo clasificación. No se vuelven a calcular los límites ni transferencias."""
    output=dict(result)
    output['data']=classify_products_v718(result['data'],resources)
    output['data'].attrs=dict(result['data'].attrs)
    ledger=json.loads(result['data'].attrs.get('v7_sales_rows','[]'))
    if ledger:
        sales=classify_products_v718(pd.DataFrame(ledger),resources)
        # Priorizar la relación del inventario de la misma sede/código.
        lookup={(str(r['Sede']),str(r['Código'])):r for r in output['data'].to_dict('records')}
        for i,row in sales.iterrows():
            matched=lookup.get((str(row['Sede']),str(row['Código'])))
            if matched:
                for col in V718_LABEL_COLUMNS:sales.at[i,col]=matched[col]
        output['data'].attrs['v7_sales_rows']=sales.to_json(orient='records',force_ascii=False)
    else:sales=pd.DataFrame(columns=['Sede','Código','Descripción']+V718_LABEL_COLUMNS)
    parts=[output['data'][['Sede','Código','Descripción']+V718_LABEL_COLUMNS],sales[['Sede','Código','Descripción']+V718_LABEL_COLUMNS]]
    universe=pd.concat(parts,ignore_index=True).drop_duplicates(['Sede','Código'])
    universe=universe.loc[universe['Código'].map(_label_text_v718).ne('')].reset_index(drop=True)
    output['classification_universe']=universe
    known=universe.loc[universe['Marca'].map(_label_text_v718).ne('')]
    differences=known.groupby('Código',observed=True)['Marca'].agg(lambda v:len(set(v.map(normalize_key))))
    output['classification_conflicts']=sorted(differences[differences.gt(1)].index.astype(str))
    output['classification_resources_version']=v7_version()
    return output


def _effective_labels_v718(universe,include_suggestions=False):
    frame=universe.copy()
    for col,suggested in [('Departamento','Departamento sugerido'),('Marca','Marca sugerida')]:
        actual=frame[col].map(_label_text_v718)
        proposed=frame[suggested].map(_label_text_v718) if include_suggestions else pd.Series('',index=frame.index)
        frame[col]=actual.where(actual.ne(''),proposed).replace('','Sin clasificar')
    return frame


def product_filter_codes_v718(universe,selection):
    frame=_effective_labels_v718(universe,selection.get('include_suggestions',False))
    mask=pd.Series(True,index=frame.index)
    for key,col in [('departments','Departamento'),('brands','Marca'),('families','Familia producto'),('types','Tipo de producto'),('codes','Código')]:
        chosen=selection.get(key,[])
        if chosen:mask &= frame[col].astype(str).isin(chosen)
    query=normalize_key(selection.get('query',''))
    for term in query.split():
        text=(frame['Código'].astype(str)+' '+frame['Descripción'].astype(str)).map(normalize_key)
        mask &= text.str.contains(term,regex=False)
    chosen=set(frame.loc[mask,'Código'].astype(str))
    if selection.get('brands') or selection.get('departments'):
        known=universe.loc[universe['Marca'].map(_label_text_v718).ne('')]
        differences=known.groupby('Código',observed=True)['Marca'].agg(lambda v:len(set(v.map(normalize_key))))
        conflicts=set(differences[differences.gt(1)].index.astype(str))
        chosen-=conflicts
    return chosen


def filter_workspace_v718(result,selection):
    """Selecciona SKU completos en todas las sedes del plan; no recalcula rutas."""
    active=any(selection.get(x) for x in ['departments','brands','families','types','codes','query'])
    codes=product_filter_codes_v718(result['classification_universe'],selection)
    out=dict(result);data=result['data']
    out['data']=data.loc[data['Código'].astype(str).isin(codes)].copy() if active else data.copy()
    ledger=json.loads(data.attrs.get('v7_sales_rows','[]'))
    selected=[r for r in ledger if not active or str(r.get('Código','')) in codes]
    out['data'].attrs=dict(data.attrs);out['data'].attrs['v7_sales_rows']=json.dumps(selected,ensure_ascii=False,default=str)
    out['transfers']=result['transfers'].loc[result['transfers']['Código'].astype(str).isin(codes)].copy() if active and not result['transfers'].empty else result['transfers'].copy()
    out['alerts']=result['alerts'].loc[result['alerts']['Código'].astype(str).isin(codes)].copy() if active and not result['alerts'].empty else result['alerts'].copy()
    out['sites']={site:part.loc[part['Código'].astype(str).isin(codes)].copy() if active else part.copy() for site,part in result['sites'].items()}
    out['comparisons']={site:subset_monthly_result_v715(comp,codes) if active else comp for site,comp in result['comparisons'].items()}
    if active:
        for comp in out['comparisons'].values():
            for field in ['evidence']:
                evidence=comp.get(field)
                if isinstance(evidence,pd.DataFrame) and 'Código' in evidence:
                    comp[field]=evidence.loc[evidence['Código'].astype(str).isin(codes)].copy()
    out['selection']=dict(selection);out['filtered_codes']=sorted(codes)
    out['filter_applied']=active;out['unfiltered_products']=len(result['data'])
    out['excluded_sales_rows']=len(ledger)-len(selected)
    label=[]
    for key,name in [('departments','Depto'),('brands','Marca'),('families','Familia'),('types','Tipo'),('codes','Códigos')]:
        if selection.get(key):label.append(name+': '+', '.join(selection[key][:8])+('…' if len(selection[key])>8 else ''))
    if selection.get('query'):label.append('Buscar: '+selection['query'])
    out['scope_label']=' · '.join(label) or 'Todos los productos de las sedes seleccionadas'
    out['signature']=reconciliation_fingerprint_v714([result['signature'],result.get('classification_resources_version',''),selection])
    out['data'].attrs['v718_scope']=out['scope_label']
    if not out['data'].empty:
        reports=project_report_frames(out['data'],out['transfers'],out['alerts'])
        # Mantener seis columnas A2 aparte; la clasificación va en el anexo.
        ids=['Sede','Código','Descripción'];cols=ids+V718_LABEL_COLUMNS
        reports['Clasificación']=out['data'][cols].rename(columns={'Departamento':'Departamento asignado','Marca':'Marca asignada'}).copy()
        reports['Alcance del informe']=pd.DataFrame([
            {'Campo':'Selección de productos','Valor':out['scope_label']},
            {'Campo':'Sedes participantes','Valor':', '.join(out['config']['sites'])},
            {'Campo':'Regla de stock','Valor':V717_RULES[out['config']['policy']]},
            {'Campo':'Incluye marcas sugeridas','Valor':'Sí · revisar anexo' if selection.get('include_suggestions') else 'No'},
            {'Campo':'Filas de ventas excluidas por alcance','Valor':str(out['excluded_sales_rows'])},
            {'Campo':'Clasificación pendiente','Valor':'Sin clasificar no equivale a ausencia de productos de la marca.'},
        ])
        inv=reports.get('Inventario',pd.DataFrame())
        candidates=workspace_rotation_v717(out)
        wanted=set(zip(candidates.get('Sede',[]),candidates.get('Código',[])))
        mask=[(r.Sede,r.Código) in wanted for r in inv[['Sede','Código']].itertuples(index=False)]
        reports['Sin rotación']=inv.loc[mask].copy()
        reports['Mínimos y máximos']=inv.copy()
        out['reports']=reports
    else:out['reports']={}
    return out


def render_product_scope_v718(result):
    """Una selección persistente de sesión para visual, operaciones y descargas."""
    universe=result['classification_universe']
    active=dict(V718_FILTER_DEFAULT,**st.session_state.get('v718_product_selection',{}))
    with st.expander('Marca, departamento y productos · filtrar todas las vistas y descargas',expanded=any(active.get(k) for k in ['brands','departments','query','codes'])):
        st.caption('El catálogo de departamentos es vocabulario, no una lista de productos. Las sugerencias de descripción no se confirman automáticamente. Proveedores no participan en este filtro.')
        k='v718_scope_'
        # Rehidratar controles al cambiar de página: Streamlit puede limpiar widgets ocultos.
        for key in V718_FILTER_DEFAULT:
            if k+key not in st.session_state:st.session_state[k+key]=active[key]
        include=st.checkbox('Incluir sugerencias de marca sin confirmar · para exploración',key=k+'include_suggestions')
        effective=_effective_labels_v718(universe,include)
        cols=st.columns(2);draft={'include_suggestions':include}
        fields=[('departments','Departamento','Departamento A2'),('brands','Marca','Marca del producto'),('families','Familia producto','Familia de productos'),('types','Tipo de producto','Tipo de producto')]
        for i,(key,col,title) in enumerate(fields):
            options=sorted(set(effective[col].dropna().astype(str)))
            # Conservar selecciones no disponibles para producir cero filas, NO ampliar a todos.
            options=sorted(set(options)|set(active.get(key,[]))|set(st.session_state.get(k+key,[])))
            draft[key]=cols[i%2].multiselect(title,options,key=k+key)
        draft['query']=st.text_input('Buscar producto por código o palabras de la descripción',key=k+'query')
        code_options=sorted(set(universe['Código'].astype(str))|set(active.get('codes',[])))
        draft['codes']=st.multiselect('Códigos específicos · dejar vacío incluye los que cumplen los filtros',code_options,key=k+'codes')
        n=len(product_filter_codes_v718(universe,draft))
        st.caption(f'{n:,} códigos coinciden. Los mismos códigos se conservan en TODAS las sedes participantes para no romper el plan de traslado. Sin clasificar sigue siendo una opción visible.')
        changed=reconciliation_fingerprint_v714(active)!=reconciliation_fingerprint_v714(draft)
        left,right=st.columns(2)
        if left.button('Aplicar filtro de productos',key='v718_scope_apply',type='primary'):
            st.session_state['v718_product_selection']=dict(draft);st.rerun()
        def clear_scope():
            st.session_state['v718_product_selection']=dict(V718_FILTER_DEFAULT)
            for key,value in V718_FILTER_DEFAULT.items():st.session_state[k+key]=value
        right.button('Ver todos los productos',key='v718_scope_reset',on_click=clear_scope)
        if changed:
            st.warning('Hay filtros sin aplicar. Se bloquean las descargas anteriores hasta aplicar o limpiar la selección.');return None
        if include:st.warning('Incluyes sugerencias no confirmadas. El anexo de clasificación identifica su origen. Revisa antes de una entrega oficial.')
    out=filter_workspace_v718(result,active)
    conflicts=result.get('classification_conflicts',[])
    if conflicts:st.warning(f'{len(conflicts)} códigos tienen marcas contradictorias entre sedes. Se excluyen del filtro por marca/departamento hasta revisar: '+', '.join(conflicts[:20]))
    st.info('ALCANCE ACTIVO · '+out['scope_label'])
    total=len(result['data']);pending=int(result['data']['Marca'].map(_label_text_v718).eq('').sum())
    st.caption(f'{len(out["data"]):,} de {total:,} productos/sede visibles. En la base de este análisis: {pending:,} sin marca confirmada. Aplicar una marca NO clasifica los pendientes ni demuestra que no existan más productos de esa marca.')
    if out['data'].empty:st.warning('No hay inventario para este filtro. No se recupera el reporte sin filtrar ni se ofrece una descarga anterior.');return None
    return out


def _visual_number_v718(frame,column,default=np.nan):
    return pd.to_numeric(frame.get(column,pd.Series(default,index=frame.index)),errors='coerce').replace([np.inf,-np.inf],np.nan)


def visual_inventory_v718(result):
    """Valoración positiva a costo. Exceso y sin venta neta se solapan: no sumar."""
    data=result['data'].copy().reset_index(drop=True)
    stock=_visual_number_v718(data,'Existencia');cost=_visual_number_v718(data,'Costo')
    cost=cost.where(cost.ge(0));maxstock=_visual_number_v718(data,'Stock Máximo')
    maximum_valid=maxstock.notna()&maxstock.ge(0)
    positive=stock.clip(lower=0)
    value=_visual_number_v718(data,'Valor Inventario ($)').where(stock.ge(0))
    value=value.fillna(positive*cost);value=value.where(value.ge(0))
    data['Valor existencias positivas']=value.where(stock.gt(0),0.0).where(stock.notna())
    data['Valor existencias positivas']=data['Valor existencias positivas'].where(stock.ge(0))
    excess=(stock-maxstock).clip(lower=0).where(maximum_valid&stock.ge(0))
    # Exposición económica, aunque todavía esté bloqueada la autorización de retiro.
    data['Exceso físico estimado']=excess
    data['Valor exceso bruto']=(excess*cost).where(excess.ne(0),0.0)
    candidates=workspace_rotation_v717(result)
    no_net=set(zip(candidates.get('Sede',[]),candidates.get('Código',[])))
    mask=pd.Series([(r['Sede'],r['Código']) in no_net for r in data.to_dict('records')],index=data.index)
    data['Candidato sin venta neta']=mask
    if result['config'].get('mode')=='mensual':
        month_cols=['Unidades '+mo for mo in result['config'].get('months',[])]
        rotation_known=data.reindex(columns=month_cols).apply(pd.to_numeric,errors='coerce').notna().all(axis=1) if month_cols else pd.Series(False,index=data.index)
        rotation_known &= ~data.get('Identidad pendiente',pd.Series(False,index=data.index)).fillna(True).astype(bool)
    else:
        rotation_known=data.get('Historial de ventas',pd.Series('',index=data.index)).eq('Disponible') & _visual_number_v718(data,'Ventas').notna()
    data['Valor sin venta neta']=data['Valor existencias positivas'].where(mask,0.0).where(rotation_known|stock.eq(0))
    data['Valor a revisar sin duplicar']=data['Valor exceso bruto'].where(~mask,data['Valor sin venta neta'])
    data['Valor solapado']=data['Valor exceso bruto'].where(mask,0.0)
    purchases=_visual_number_v718(data,'Compra Ajustada')
    data['Presupuesto compra neta']=(purchases*cost).where(purchases.ne(0),0.0)
    pending=_visual_number_v718(data,'Retiro neto')
    data['Valor retiro neto']=(pending*cost).where(pending.ne(0),0.0)
    money=data.get('Moneda inventario',pd.Series('',index=data.index)).map(_label_text_v718)
    data['Moneda análisis']=money.where(money.isin(FIN_CURRENCIES),'Sin moneda')
    for col in ['Marca','Departamento']:
        proposed=col+' sugerido';actual=data[col].map(_label_text_v718)
        if result.get('selection',{}).get('include_suggestions'):
            actual=actual.where(actual.ne(''),data[proposed].map(lambda x:str(x)+' · sugerida' if x else ''))
        data[col+' visual']=actual.replace('','Sin clasificar')
    return data


def visual_metric_v718(frame,column,currency):
    if currency not in FIN_CURRENCIES:
        return {'value':np.nan,'known':0,'missing':len(frame),'rows':len(frame),'label':'Moneda pendiente'}
    values=_visual_number_v718(frame,column)
    missing=int(values.isna().sum());known=int(values.notna().sum())
    amount=float(values.sum(min_count=1)) if len(frame) else 0.0
    return {'value':amount,'known':known,'missing':missing,'rows':len(frame),
        'label':f'PARCIAL · {missing} sin valorar/evaluar' if missing else 'Cobertura completa en la selección'}


def visual_groups_v718(frame,field,column,currency):
    out=[]
    for name,part in frame.groupby(field,dropna=False,observed=True,sort=True):
        metric=visual_metric_v718(part,column,currency)
        out.append({field:str(name),column:metric['value'],'Sin valorar/evaluar':metric['missing'],
                    'Productos/sede':len(part),'Cobertura':metric['label']})
    return pd.DataFrame(out,columns=[field,column,'Sin valorar/evaluar','Productos/sede','Cobertura'])


def visual_months_v718(result):
    rows=json.loads(result['data'].attrs.get('v7_sales_rows','[]'))
    records=[]
    for row in rows:
        start=_label_text_v718(row.get('Desde'));end=_label_text_v718(row.get('Hasta'))
        if not start or not end or start[:7]!=end[:7]:continue
        try:
            first=date.fromisoformat(start);last=date.fromisoformat(end)
            import calendar
            if first.day!=1 or last.day!=calendar.monthrange(last.year,last.month)[1]:continue
        except ValueError:continue
        records.append({'Mes':start[:7],'Sede':row.get('Sede'),'Código':row.get('Código'),
             'Unidades':pd.to_numeric(row.get('Ventas del período',row.get('Ventas')),errors='coerce'),
             'Ventas netas':pd.to_numeric(row.get('Importe neto'),errors='coerce'),
             'Moneda ventas':_label_text_v718(row.get('Moneda ventas')) or 'Sin moneda'})
    if not records:return pd.DataFrame(columns=['Mes','Sede','Unidades','Ventas netas','Moneda ventas','Filas sin importe'])
    data=pd.DataFrame(records);output=[]
    for (month,site,currency),part in data.groupby(['Mes','Sede','Moneda ventas'],dropna=False,observed=True):
        vals=part['Ventas netas'];miss=int(vals.isna().sum())
        output.append({'Mes':month,'Sede':site,'Unidades':part['Unidades'].sum(min_count=1),
                      'Ventas netas':vals.sum(min_count=1) if currency in FIN_CURRENCIES else np.nan,
                      'Moneda ventas':currency,'Filas sin importe':miss})
    return pd.DataFrame(output).sort_values(['Mes','Sede','Moneda ventas'])


def build_visual_figures_v718(result,currency,top_n=15):
    all_data=visual_inventory_v718(result)
    data=all_data.loc[all_data['Moneda análisis'].eq(currency)].copy()
    figures=[];tables={}
    for field,value,title in [
      ('Sede','Valor existencias positivas','Inventario a costo por sede'),
      ('Marca visual','Valor a revisar sin duplicar','Capital a revisar por marca · sin duplicar'),
      ('Departamento visual','Valor sin venta neta','Sin venta neta por departamento · valor conocido'),
    ]:
        group=visual_groups_v718(data,field,value,currency)
        tables[title]=group
        known=group.loc[group[value].notna()].sort_values(value,ascending=False).head(top_n).sort_values(value)
        if not known.empty and known[value].gt(0).any():
            fig=px.bar(known,x=value,y=field,orientation='h',title=title+' · '+currency,
                        hover_data=['Sin valorar/evaluar','Cobertura'],color_discrete_sequence=[NEXUS_BLUE])
            fig.update_layout(yaxis_title=None,xaxis_title=currency+' · valores conocidos')
            figures.append((title,chart_layout(fig,max(330,min(600,len(known)*30+90)))))
    states=all_data.groupby('Estado',observed=True).size().rename('Productos/sede').reset_index()
    if not states.empty:
        fig=px.pie(states,names='Estado',values='Productos/sede',hole=.64,title='Estado del inventario · toda la selección')
        figures.append(('Estado del inventario',chart_layout(fig,360)))
    top=data.loc[data['Valor a revisar sin duplicar'].gt(0)].sort_values('Valor a revisar sin duplicar',ascending=False).head(top_n).copy()
    if currency not in FIN_CURRENCIES:top=top.iloc[:0].copy()
    if not top.empty:
        top['Producto']=top['Código'].astype(str)+' · '+top['Sede'].astype(str)
        figures.append(('Productos prioritarios',chart_layout(px.bar(top.sort_values('Valor a revisar sin duplicar'),
            x='Valor a revisar sin duplicar',y='Producto',orientation='h',title='Productos que concentran capital a revisar · '+currency,
            hover_data=['Descripción','Marca visual','Existencia','Stock Máximo','Bloqueo operativo'],color_discrete_sequence=[NEXUS_ORANGE]),max(360,min(700,len(top)*30+70)))))
    pareto=data.loc[data['Valor existencias positivas'].gt(0)].sort_values('Valor existencias positivas',ascending=False).copy()
    if not pareto.empty and currency in FIN_CURRENCIES:
        pareto['Orden']=np.arange(1,len(pareto)+1)
        pareto['Acumulado conocido (%)']=pareto['Valor existencias positivas'].cumsum()/pareto['Valor existencias positivas'].sum()*100
        fig=px.line(pareto,x='Orden',y='Acumulado conocido (%)',title='Concentración del inventario · valores conocidos '+currency,
                    hover_data=['Código','Sede','Valor existencias positivas'])
        fig.add_hline(y=80,line_dash='dot',annotation_text='Referencia 80%')
        figures.append(('Concentración del inventario',chart_layout(fig,350)))
    scatter=all_data.loc[_visual_number_v718(all_data,'Demanda Mensual').gt(0)&_visual_number_v718(all_data,'Existencia').ge(0)].copy()
    if not scatter.empty:
        # Puntos por sede/código; no se afirma que un mes futuro repetirá la demanda.
        figures.append(('Existencia y demanda',chart_layout(px.scatter(scatter,x='Demanda Mensual',y='Existencia',color='Estado',
            hover_data=['Código','Sede','Stock Mínimo','Stock Máximo'],title='Existencia frente a demanda mensual · unidades'),390)))
    monthly=visual_months_v718(result)
    tables['Ventas mensuales']=monthly
    if not monthly.empty:
        units=monthly.groupby(['Mes','Sede'],as_index=False)['Unidades'].sum(min_count=1)
        figures.append(('Evolución de unidades',chart_layout(px.line(units,x='Mes',y='Unidades',color='Sede',markers=True,
             title='Ventas netas en unidades · meses completos identificados'),350)))
        monetary=monthly.loc[monthly['Moneda ventas'].eq(currency)&monthly['Ventas netas'].notna()]
        if not monetary.empty:
            figures.append(('Evolución de ventas en dinero',chart_layout(px.bar(monetary,x='Mes',y='Ventas netas',color='Sede',barmode='group',
                hover_data=['Filas sin importe'],title='Ventas netas conocidas · '+currency),350)))
    moves=result['transfers']
    if not moves.empty:
        routes=moves.groupby(['Origen','Destino'],as_index=False)['Unidades Sugeridas'].sum()
        names=sorted(set(routes['Origen'])|set(routes['Destino']));pos={name:i for i,name in enumerate(names)}
        figure=go.Figure(go.Sankey(node={'label':names,'pad':24,'thickness':18},link={
             'source':[pos[x] for x in routes['Origen']],'target':[pos[x] for x in routes['Destino']],
             'value':routes['Unidades Sugeridas'].tolist()}))
        figure.update_layout(title='Redistribución propuesta · unidades, no dinero cobrado')
        figures.append(('Mapa de redistribución',chart_layout(figure,380)))
        tables['Rutas']=routes
    tables['Prioridades']=top
    return figures,tables,all_data


def build_visual_html_v718(result,currency,top_n=15):
    figures,tables,full=build_visual_figures_v718(result,currency,top_n)
    selected=full.loc[full['Moneda análisis'].eq(currency)]
    headings=[('Inventario a costo','Valor existencias positivas'),('Sin venta neta','Valor sin venta neta'),
         ('Exceso bruto','Valor exceso bruto'),('Capital a revisar · sin duplicar','Valor a revisar sin duplicar'),
         ('Compra neta propuesta','Presupuesto compra neta'),('Retiro neto propuesto','Valor retiro neto')]
    cards=''
    for name,field in headings:
        m=visual_metric_v718(selected,field,currency)
        cards+='<article><small>'+escape(name)+'</small><strong>'+escape(_doc_amount_v714(m['value']))+' '+escape(currency)+'</strong><small>'+escape(m['label'])+'</small></article>'
    charts=[]
    for i,(name,fig) in enumerate(figures):
        charts.append('<section>'+pio.to_html(fig,full_html=False,include_plotlyjs=True if i==0 else False,
            config={'responsive':True,'displaylogo':False})+'</section>')
    details=result['data'].reindex(columns=['Sede','Código','Descripción','Departamento','Marca','Tipo de producto',
        'Existencia','Stock Mínimo','Stock Máximo','Compra Ajustada','Retiro neto','Estado','Acción','Bloqueo operativo'])
    text=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
    <title>NEXUS · Control visual</title><style>
    body{{margin:0;background:#f3f7f8;color:#193a47;font:14px Arial,sans-serif}}main{{max-width:1450px;margin:auto;padding:26px}}
    header{{padding:28px;background:#153d48;color:white;border-radius:18px}}h1{{margin:0 0 12px}}.cards{{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}}
    article,section{{background:white;border:1px solid #d6e4e7;border-radius:14px;padding:18px;margin-bottom:14px}}strong{{display:block;font-size:26px;margin:12px 0}}small{{display:block;line-height:1.6}}.note{{padding:14px;background:#fff3d8;border-radius:12px}}
    table{{border-collapse:collapse;width:100%;font-size:12px}}th,td{{padding:9px;border-bottom:1px solid #d6e4e7;text-align:left}}th{{background:#e6f1f0}}.scroll{{overflow:auto;max-height:700px}}
    @media(max-width:800px){{.cards{{grid-template-columns:1fr}}main{{padding:12px}}}}
    </style></head><body><main><header><h1>MAKROPETROL NEXUS · Control visual</h1>
    <p>{escape(result.get('scope_label','Todos los productos'))}</p><p>{escape(workspace_label_v717(result))}</p>
    <small>Generado {datetime.now():%d/%m/%Y %H:%M} · NEXUS {APP_VERSION}</small></header>
    <div class="cards">{cards}</div><p class="note">Sin venta neta y exceso pueden solaparse: no sumar ambos. Capital a revisar usa la unión sin duplicar.
    Valores a costo, no ingresos garantizados. Cada moneda se analiza por separado; no se convierten importes.
    Un candidato sin neto no prueba ausencia de movimientos. Gráficos limitados a los primeros {top_n} grupos/productos cuando corresponde; la tabla conserva todas las filas seleccionadas.</p>
    {''.join(charts)}<section><h2>Inventario y decisiones · {len(details)} filas</h2><div class="scroll">{details.to_html(index=False,escape=True,na_rep='N/D')}</div></section>
    <section><h2>Clasificación y procedencia</h2><div class="scroll">{result['data'][['Sede','Código']+V718_LABEL_COLUMNS].to_html(index=False,escape=True)}</div></section>
    <small>Documento de revisión. No crea pedidos, transferencias ni cambios en A2. Proveedores no forman parte del filtro de esta vista.</small></main></body></html>'''
    return text.encode('utf-8')


def build_visual_pdf_v718(result,currency,top_n=12):
    """PDF con gráficos vectoriales simples: no requiere Kaleido ni navegador."""
    if not HAS_PDF:raise ValueError('La descarga PDF requiere fpdf2.')
    full=visual_inventory_v718(result);data=full.loc[full['Moneda análisis'].eq(currency)]
    pdf=FPDF();pdf.set_auto_page_break(auto=True,margin=15)
    def line(text,size=10,bold=False):
        pdf.set_x(12);pdf.set_font('Helvetica','B' if bold else '',size)
        pdf.multi_cell(186,5,_doc_safe_text(text))
    def page(title):
        pdf.add_page();pdf.set_fill_color(21,61,72);pdf.rect(0,0,210,24,'F')
        pdf.set_text_color(255,255,255);pdf.set_xy(12,7);pdf.set_font('Helvetica','B',14)
        pdf.cell(185,8,_doc_safe_text('NEXUS · '+title));pdf.set_text_color(25,50,62);pdf.set_y(30)
    page('Control visual gerencial')
    line(result.get('scope_label','Todos los productos'),11,True)
    line(workspace_label_v717(result),8)
    line('Moneda: '+currency+' · valores a costo. Generado '+datetime.now().strftime('%d/%m/%Y %H:%M'),8)
    pdf.ln(3)
    for name,col in [('Inventario positivo a costo','Valor existencias positivas'),('Sin venta neta documentada','Valor sin venta neta'),
          ('Exceso bruto sobre el máximo','Valor exceso bruto'),('Capital a revisar SIN DUPLICAR','Valor a revisar sin duplicar'),
          ('Compra neta propuesta','Presupuesto compra neta'),('Retiro neto propuesto','Valor retiro neto')]:
        m=visual_metric_v718(data,col,currency)
        line(name+': '+_doc_amount_v714(m['value'])+' '+currency,12,True);line(m['label'],8);pdf.ln(2)
    line('No sumar sin venta neta y exceso: pueden ser los mismos productos. La unión evita ese doble conteo. No es dinero disponible ni una previsión de cobro.',9)
    line('Faltantes de costo, moneda o límites se muestran como parcial/N/D. Saldos negativos se revisan aparte.',9)
    line('Unidades por comprar: '+_quantity_text_v73(result['data']['Compra Ajustada'].sum())+' · Rutas propuestas: '+str(len(result['transfers'])),10,True)
    for field,col,title in [('Sede','Valor existencias positivas','Inventario por sede'),('Marca visual','Valor a revisar sin duplicar','Capital a revisar por marca')]:
        page(title)
        group=visual_groups_v718(data,field,col,currency);known=group.loc[group[col].notna()].sort_values(col,ascending=False).head(top_n)
        line(result.get('scope_label','Todos')+' · '+currency,8)
        line('Primeros '+str(top_n)+' grupos; valores conocidos. La ausencia de datos no equivale a cero.',8)
        top=float(known[col].max()) if len(known) else 0
        for r in known.to_dict('records'):
            if pdf.get_y()>260:page(title+' · continuación')
            line(str(r[field])+(' · PARCIAL' if r['Sin valorar/evaluar'] else ''),10,True)
            y=pdf.get_y();width=126*max(0,float(r[col]))/top if top>0 else 0
            pdf.set_fill_color(30,126,120);pdf.rect(12,y+1,width,5,'F')
            pdf.set_xy(143,y);pdf.set_font('Helvetica','',9);pdf.cell(54,7,_doc_safe_text(_doc_amount_v714(r[col])+' '+currency),align='R');pdf.set_y(y+12)
        if known.empty:line('No hay valores monetarios conocidos para esta moneda. Revisa costos y moneda.',11)
    page('Prioridades e inventario')
    line('Listado reducido para gerencia; el informe Excel/HTML conserva todas las filas del alcance.',8)
    top=data.loc[data['Valor a revisar sin duplicar'].gt(0)].sort_values('Valor a revisar sin duplicar',ascending=False).head(top_n)
    if currency not in FIN_CURRENCIES:top=top.iloc[:0].copy()
    for r in top.to_dict('records'):
        if pdf.get_y()>244:page('Prioridades · continuación')
        line(str(r['Código'])+' · '+str(r['Sede'])+' · '+_doc_amount_v714(r['Valor a revisar sin duplicar'])+' '+currency,10,True)
        line(str(r['Descripción']),8)
        line('Existencia '+_quantity_text_v73(r['Existencia'])+' · Mín '+_quantity_text_v73(r['Stock Mínimo'])+' · Máx '+_quantity_text_v73(r['Stock Máximo']),8)
        line('Acción: '+str(r['Acción'])+' · '+str(r.get('Bloqueo operativo','')),8);pdf.ln(2)
    if top.empty:line('Sin prioridades monetarias calculables en esta selección. No significa que los datos pendientes estén resueltos.',10)
    return pdf_output_bytes_v714(pdf)


