def read_code_list_v718(raw,filename):
    """Sólo identidades: admite Código/Descripción sin cantidades ni precios."""
    if len(raw)>32*1024*1024:raise ValueError('La relación supera 32 MB.')
    grid=read_a2_grid(raw,filename)
    header=None;column=None
    for i,row in enumerate(grid.head(100).values.tolist()):
        for j,value in enumerate(row):
            if normalize_key(_label_text_v718(value)) in {'codigo','cod','sku','codigo producto','codigo de producto'}:
                header=i;column=j;break
        if header is not None:break
    if header is None:raise ValueError('No hay columna Código/SKU identificable en las primeras 100 filas.')
    result=set()
    for row in grid.iloc[header+1:].values.tolist():
        code=code_key_v714(row[column])
        if code and normalize_key(code) not in {'codigo','cod','sku','total','total general'}:
            result.add(code)
    if not result:raise ValueError('La lista no contiene códigos.')
    return result


